-- 제주시(50110) / 태안군(44825) TourAPI 실데이터 place 적재
-- 원본: data/제주_제주시_TourAPI_실데이터.csv, data/충남_태안군_천안시_TourAPI_실데이터.csv
-- (주의) 충남 CSV는 파일명에 '천안시'가 포함되어 있으나 실제 데이터는 전부 태안군(44825)이며 천안시(44131) 행은 없음.
-- place.(source_provider,source_place_id) UNIQUE 제약 기준으로 ON DUPLICATE KEY UPDATE 하므로 여러 번 실행해도 안전함.
-- region_id는 하드코딩하지 않고 region_code로 매번 JOIN해서 찾는다 (제주시/태안군 region은 이미 DB에 존재).
USE smart_travel_db;
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

DROP TEMPORARY TABLE IF EXISTS place_seed_stage;
CREATE TEMPORARY TABLE place_seed_stage (
  region_code VARCHAR(30) NOT NULL,
  source_provider VARCHAR(30) NOT NULL,
  source_place_id VARCHAR(100) NOT NULL,
  place_type VARCHAR(30) NOT NULL,
  name VARCHAR(200) NOT NULL,
  description TEXT NULL,
  address VARCHAR(300) NULL,
  address_detail VARCHAR(200) NULL,
  latitude DECIMAL(10,7) NULL,
  longitude DECIMAL(10,7) NULL,
  phone VARCHAR(30) NULL,
  homepage_url VARCHAR(1000) NULL,
  opening_hours TEXT NULL,
  closed_days VARCHAR(500) NULL,
  recommended_minutes INT NULL,
  is_market TINYINT(1) NULL,
  source_modified_at DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO place_seed_stage (region_code, source_provider, source_place_id, place_type, name, description, address, address_detail, latitude, longitude, phone, homepage_url, opening_hours, closed_days, recommended_minutes, is_market, source_modified_at) VALUES
('50110','KTO_TOURAPI','128641','ATTRACTION','제주목 관아','조선시대 제주지방 통치의 중심지였던 제주목 관아[濟州牧 官衙]는 지금의 관덕정을 포함하는 주변 일대에 분포해 있었으며, 이미 탐라국시대부터 성주청 등 주요 관아 시설이 있었던 곳으로 추정되고 있다. 관아 시설은 1434년 관청의 화재로 건물이 모두 불타 없어진 뒤 바로 역사를 시작하여 그다음 해인 1435년에 골격이 이루어졌으며, 조선시대 내내 중. 개축이 이루어졌다. 그러나 제주목 관아는 일제강점기 때 집중적으로 훼철되어 관덕정을 빼고는 그 흔적을 볼 수가 없었다. 제주시에서는 탐라국 이래 조선시대에 이르기까지 제주의 정치·행정·문화의 중심지 역할을 해왔던 제주목 관아를 원래의 양식으로 복구하고자, 1991년부터 1998년까지 4차례 발굴 조사를 마친 결과, 탐라시대부터 조선시대에 이르기까지의 여러 문화층과 함께 문헌상에 나타난 중심 건물인 홍화각[弘化閣], 연희각[延曦閣], 우연당[友蓮堂], 귤림당[橘林堂]등의 건물터와 유구[遺構]가 확인되고 유물[遺物]도 출토되었다. 1993년 3월 30일에 제주목 관아지 일대가 국가 사적으로 지정되었고, 발굴 과정에서 확인된 초단. 기단석 등을 토대로 하고, 『탐라순력도[耽羅巡歷圖]』와 『탐라방영총람[耽羅防營總覽]』 등 당대의 문헌 및 향토사학가·전문가 등의 고증과 자문을 거쳐 관아지 복원 기본 설계를 완료, 2002년 12월에 복원을 완료하였다.','제주특별자치도 제주시 관덕로 25',NULL,33.5136724909,126.5220519585,NULL,NULL,'[일반 개장] - 09:00~18:00 [야간 개장] - 수요일~일요일 18:00~21:00','연중무휴',90,0,'2026-11-16 17:59:03'),
('50110','KTO_TOURAPI','2714241','ATTRACTION','아르떼뮤지엄 제주','국내 최대 규모의 몰입형 미디어아트 전시관인 아르떼뮤지엄 제주는 제주 애월의 옛 공장을 업사이클링 해 탄생한 공간이다. 단순한 재활용을 넘어 디자인과 활용성을 더해 새로운 가치를 만들어냈으며 제주 섬의 정서를 빛과 소리, 향기로 풀어내 감각적으로 경험할 수 있다.
코엑스 ‘WAVE’ 작품으로 잘 알려진 디스트릭트가 선보인 이 전시관은 스피커 제조 공장으로 사용되던 약 1,400평 규모의 공간과 최대 10m에 이르는 높은 층고를 활용해 압도적인 몰입감을 선사한다. 내부에서는 빛과 소리가 어우러진 16개의 다채로운 미디어아트 전시가 펼쳐진다. 빠르게 소비하는 관광보다 경험과 감정을 중시하는 여행 트렌드와 맞물려 주목받고 있다.','제주특별자치도 제주시 애월읍 어림비로 478',NULL,33.3966944006,126.3449766448,NULL,'https://kr.artemuseum.com','10:00~20:00 (입장 마감 19:00)','연중무휴',90,0,'2026-11-16 17:58:32'),
('50110','KTO_TOURAPI','665594','ATTRACTION','더마파크','더마파크는 말을 주제로 한 테마공원으로 승마 체험과 기마공연 등 다양한 말 문화를 경험할 수 있는 곳이다. 제주 말의 역사와 문화를 바탕으로 한 공연 프로그램을 운영하고 있으며, 박진감 넘치는 기마공연을 통해 색다른 볼거리를 제공한다. 또한 승마 체험과 다양한 부대시설을 갖추고 있어 가족 단위 관광객부터 말 문화에 관심 있는 방문객까지 폭넓게 찾고 있다.','제주특별자치도 제주시 한림읍 월림7길 155',NULL,33.3549226516,126.2430787305,NULL,'http://www.mapark.co.kr','[카트/승마]- 09:00~17:00 - 입장 마감 16:30[공연]- 10:30~17:30※ 자세한 사항은 홈페이지 참조','연중무휴',90,0,'2026-11-16 17:50:28'),
('50110','KTO_TOURAPI','126460','ATTRACTION','관덕정(제주)','제주도 내에서 오래된 건축물 중의 하나인 보물 관덕정은 조선 시대 세종 30년(1448)에 목사 신숙청이 사졸들을 훈련하고 상무 정신을 함양할 목적으로 이 건물을 세웠다. 관덕정이란 이름은 [사이관덕]이란 문구에서 나온 것으로 활을 쏘는 것은 평화 시에는 심신을 연마하고 유사시에는 나라를 지키는 까닭에 이를 보는 것은 덕행으로 태어난 곳이다. 대들보에는 십장생도, 적벽대첩도, 대수렵도 등의 격조 높은 벽화가 그려져 있고, 편액은 안평대군의 친필로 전해오고 있다.','제주특별자치도 제주시 관덕로 19',NULL,33.5132642036,126.5219575322,NULL,NULL,'09:00~18:00','연중무휴',90,0,'2026-11-16 17:19:04'),
('50110','KTO_TOURAPI','126455','ATTRACTION','한림공원','제주 한림공원은 1971년 창업인 송봉규 선생이 10만여 평의 황무지 모래밭에 야자수 씨앗을 파종하여 육묘함으로써 탄생하게 된 비경지대이다. 협재, 금릉 해수욕장의 비경과 아름다운 비양도의 경관을 마주하고 있는 제주도내 최고의 관광명소로 손꼽히고 있다. 10만여 평의 대지에 하늘로 우뚝 뻗은 야자수군락과 울창한 송림으로 둘러싸인 한림공원은 다양한 종류의 꽃과 나무가 사계절 아름다운 경관을 연출하며, 남국의 정취가 물씬 풍기는 야자수길, 분재와 돌을 소재로 하여 구성된 제주석분재원, 제주의 옛 모습을 재현한 재암민속마을 등 다양한 볼거리를 함께 갖추고 있다. 환상적인 9가지 다양한 테마가 펼쳐지는 한림공원은 장쩌민 중국 전 국가주석과 나까소네 전 일본수상을 비롯한 세계 각국의 저명인사들이 방문한 곳으로, 국내외 관광객이 찾는 세계적인 관광명소이다.','제주특별자치도 제주시 한림읍 한림로 300',NULL,33.3886353694,126.2415447847,NULL,'https://hallimpark.com/','- 2월~5월 09:00~17:00- 6월~8월 09:00~17:30- 9월~10월 09:00~17:00- 11월~1월 09:00~16:30','연중무휴',90,0,'2026-11-16 17:18:08'),
('50110','KTO_TOURAPI','2414812','ATTRACTION','신산공원','신산공원은 제주 시민들이 애용하는 도심 속 공원 중 한 곳이다. 신산공원 중심에는 올림픽 성화의 국내 도착을 기념하는 기념물이 세워져 있어 88 서울올림픽을 상징하는 공원이기도 하다. 또한, 1995년 10월에 광복 50주년 기념으로 제주 문물을 담은 총 1,250점의 95 제주타임캡슐을 매설한 뜻깊은 장소이다. 공원 내에는 제주 4·3 해원 방사탑과 6·25 참전 기념탑 등 역사적으로 의미 있는 다양한 조형물이 자리하고 있다. 신산공원은 넓은 잔디밭과 단풍나무를 비롯하여 예쁜 꽃밭과 나무들이 어우러진 도심 속에 있는 시민들의 휴식 공간이다. 특히, 봄에는 벚꽃들이 흩날려 아름답다. 신산공원에는 게이트볼장, 배드민턴장, 족구장 등의 시설이 있고 아이들을 위한 놀이터도 있어 가족이 함께 모여 즐거운 시간을 보내기 좋은 공간이다. 또한, 신산공원 근처에는 국수문화거리, 삼성혈, 민속자연사박물관 등의 관광명소가 있다.','제주특별자치도 제주시 신산로 92-12',NULL,33.5052486604,126.5337788377,NULL,'http://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-11-16 17:15:55'),
('50110','KTO_TOURAPI','127490','ATTRACTION','협재해수욕장','협재해수욕장은 제주시 서쪽의 한림공원에 인접해 있다. 조개껍질 가루가 많이 섞인 백사장과 앞바다에 떠 있는 비양도, 코발트 빛깔의 아름다운 바다와 울창한 소나무 숲이 한데 어우러진 풍광이 매우 아름답다. 수심이 얕고 경사가 완만하여 가족 단위의 해수욕장으로 적합하다. 이 해수욕장의 남서쪽 해안은 금릉해수욕장과 이어져 있는데, 주민들은 두 해변을 합쳐 협재해수욕장이라고도 부른다. 해수욕장 내에는 탈의실, 샤워실, 휴게소, 식수대, 화장실 등 각종 편의시설이 있어 이용하기에도 편리하다. 또 해수욕장 주변에는 짙은 송림이 있어 야영과 산림욕을 즐길 수 있고, 전복과 소라가 많이 잡히기 때문에 싱싱한 해산물을 마음껏 맛볼 수 있다. 멀지 않은 곳에는 한림공원과 협재굴, 명월대, 황룡사, 영각사 등이 있어 해수욕과 함께 주변을 둘러볼 수 있으며 특히 해수욕장 정면에 보이는 비양도의 모습은 맑고 깨끗한 해수와 어울려 아름다운 풍광을 연출하며 이곳에서 바라보는 낙조 또한 아름답다. 

◎ 한류의 매력을 만나는 여행 정보
시원한 파도 소리, 에메랄드빛 바다, 백사장 옆 검은 현무암 위에서 반갑게 손을 흔드는 세븐틴이 있다. 세븐틴이 팬인 캐럿에게 보내는 노래 엔 예쁜 사랑이 담겨 있다. 협재해수욕장은 수심이 얕아 수영을 못 하는 사람들도 물놀이하기 좋고, 옆쪽으로 야자수, 소나무 숲, 잔디가 있어 산책하거나 캠핑하기에도 적합하다.','제주특별자치도 제주시 한림읍 한림로 329-10',NULL,33.3937458521,126.2394309781,NULL,'http://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-11-16 17:15:09'),
('50110','KTO_TOURAPI','2948051','ATTRACTION','산양큰엉곶','산양큰엉곶은 곶자왈 지대로서 제주 4대 곶자왈중 한경-안덕 곶자왈에 속해 있으며 평지가 아닌 숲을 뜻하고 크게 달구지길과 숲길로 나누어져 있다. 달구지길은 남녀노소뿐만 아니라 휠체어 및 유모차로도 탐방이 가능하며 동화 속 숲 속의 작은 마을을 구현하여 마녀의 집, 공주의 집, 난쟁이의 집, 숲 속의 기찻길, 새 둥지와 같은 포토존이 많이 있으며 소와 말이 달구지를 끌고 가는 제주의 옛 모습을 볼 수 있다. 숲길 탐방로는 곶자왈의 원시림을 깊이 즐길 수 있으며 총 3.5km의 길로 다양한 식생과 독특한 생태계가 형성되어 있다. 
3.5km에 달하는 생태숲길은 마치 동화나라로 초대받은 기분이 든다. 박공지붕의 통나무집, 조릿대로 엮은 집채만 한 새 둥지, 다람쥐 바퀴 모양의 그네, 곶자왈 속 작은 기찻길 등 자연과 하나 된 포토존에 눈을 뗄 수 없다. 달구지길은 나무로 둘러싸인 숲길을 유모차와 휠체어도 다닐 수 있는 무장애 길이다. 걷다가 만나는 소달구지와 말달구지는 산양큰엉곶만의 매력이다. 책에서만 만나던 황소와 제주 조랑말을 직접 눈앞에서 볼 수 있음에 아이들은 반가워한다. 소달구지와 말달구지는 직접 탑승하고 체험할 수 있으며 먹이 주기와 꽃 팔지 만들기, 키즈 가드닝, 식물 옮겨심기 등 체험학습도 다양하게 진행 중이다. 숲길 탐방로는 원시림을 깊이 즐기고 싶은 올레객에게 안성맞춤이다. 한 사람씩 걸을 수 있는 호젓한 숲길은 자연 친화적으로 정비되어 있어 오롯이 자연을 느끼며 감성적 그리움에 빠져들기 좋다. 계절마다 다른 식물과 꽃들이 각각의 향기로 코끝을 자극하는 곳이다. 화산 활동으로 인한 다양한 식생과 독특한 생태계는 제주에서만 볼 수 있는 풍경이다. 숯을 생산했던 숯가마터와 4.3 당시 마을 사람들이 피신했던 궤(굴)도 볼 수 있어 제주의 아픔까지 느낄 수 있는 숲길이다.','제주특별자치도 제주시 한경면 청수리','청수리 956-6',33.2906996816,126.2502989388,NULL,'https://www.instagram.com/sanyang_keunkot/','09:30~18:00 (입장마감 17:00)','연중무휴',90,0,'2026-11-16 17:14:26'),
('50110','KTO_TOURAPI','2472824','ATTRACTION','넥슨뮤지엄','넥슨뮤지엄은 컴퓨터와 게임의 역사를 조명하던 넥슨컴퓨터박물관에서 한 걸음 더 나아가, 게임을 하나의 문화로 바라보며 플레이어의 경험과 추억을 함께 나누는 체험형 공간이다. 컴퓨터와 하드웨어 중심의 전시를 넘어 게임을 통해 형성된 플레이어들의 기억과 관계, 다양한 플레이 경험을 담아낸다. 넥슨 ID 또는 게스트로 로그인한 뒤 입장카드를 연동하면 자신의 게임 플레이 기록과 연계된 맞춤형 전시를 경험할 수 있다. 게임을 즐겼던 순간과 그 안에 담긴 추억을 되돌아보고, 게임이 지닌 문화적 가치와 즐거움을 직접 체험할 수 있는 곳이다.','제주특별자치도 제주시 1100로 3198-8','(노형동)',33.4721323038,126.4857590608,NULL,'https://www.nexonmuseum.org','10:00~18:00 (입장 마감 17:30)','매주 월요일 / 설·추석 당일',90,0,'2026-11-16 17:14:00'),
('50110','KTO_TOURAPI','1925362','ATTRACTION','어영공원','어영공원은 제주도 용담해안도로를 따라 길게 만들어진 공원이다. 각종 조명시설을 설치해 해가 지면 어영공원의 야경을 감상하기 좋아 많은 관광객이 찾고 있다. 또한, 제주 올레 17코스에 속한 공원으로 올레꾼들의 발걸음이 끊이지 않고 있다. 낮에도 탁트인 전경과 바로 눈 앞에 펼쳐진 바다, 시원한 바닷바람으로 사람들을 붙잡는다. 어영공원에서는 시원한 풍경과 함께 시도 즐길 수 있다. 공원에 설치된 벤치와 바다 쪽의 방호벽에 유명인들의 시가 이어져 있으며 시와 함께 잔잔한 여운을 남기는 벽화가 그려져 있다. 방호벽 위로 어패류 조형물이 세워져 있어, 이것 또한 볼거리이다. 로렐라이 요정상도 눈에 띈다. 독일의 로렐라이시와 제주시가 우정의 상징으로 각각 로렐라이 요정상과 돌하르방을 교환하여 이곳에 세워졌다고 한다.','제주특별자치도 제주시 서해안로 451 (용담삼동)',NULL,33.5183452018,126.4875582636,NULL,'http://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-11-16 17:13:34'),
('50110','KTO_TOURAPI','745313','ATTRACTION','제주별빛누리공원','제주별빛누리공원은 천체탐구와 천문학습의 장으로 활용되고 있는 최첨단천문우주 과학시설이다. 21세기의 주역인 청소년들에게 무한한 꿈과 희망을 심어줄 과학문화 공간이다. 내부에는 삼차원 입체영상을 모션시뮬레이터에 탑승하여 현실감 있게 관람할 수 있는 4D영상관, 반구모양의 돔 스크린으로 우주에 대한 영상물과 사계절 별자리를 감상할 수 있는 천체투영실, 태양계 전시물, 행성 체중계, 디지털 망원경, 우주쓰레기 제거 게임, 포토존 등 다양한 볼거리와 체험이 있는 전시실 등이 있다. 또한, 구름 없이 맑은 날, 야간에만 운영하는 관측실은 주관측실과 보조관측실로 나뉘어 있다. 주관측실에서는 600㎜ 리치크리티앙 반사망원경을 통하여 희미한 천체를 더 밝게 접할 수 있으며, 보조관측실에서는 천체 망원경을 이용하여 다양한 천체를 관측할 수 있다. 이 외에 야외광장에는 태양계 광장과 해시계가 조성되어 있어 관람객들이 다양한 체험을 할 수 있는 공간으로 만들어졌다.','제주특별자치도 제주시 선돌목동길 60 (오등동)',NULL,33.4445760547,126.5491861429,NULL,'http://www.jejusi.go.kr/star/','[하절기(4월~9월)]15:00~23:00[동절기(10월~3월)]14:00~22:00※ 마감 1시간 30분 전까지 입장 가능','매주 월요일 / 신정 / 설 당일 / 추석 당일(단, 월요일이 공휴일인 경우 그 공휴일 다음의 첫번째 평일)',90,0,'2026-11-16 17:13:08'),
('50110','KTO_TOURAPI','126444','ATTRACTION','차귀도','차귀도는 제주시 한경면 고산리에 딸린 섬으로 사람이 살지 않으며 제주의 무인도 가운데 가장 크다. 고산리에서 해안 쪽으로 약 2㎞ 떨어진 자구내마을에서 배를 타고 10여 분 가면 차귀도가 나온다. 죽도, 지실이섬, 와도의 세 섬과 작은 부속섬을 거느리고 있다. 섬에는 시누대·들가시나무·곰솔·돈나무 등 13종의 수목과 양치식물인 도깨비고비, 제주특별자치도에서만 사는 해녀콩을 비롯한 갯쑥부쟁이·천무동 등 62종의 초본류 등 총 82종의 식물이 자란다. 주변 바다는 수심이 깊고 참돔·돌돔·혹돔·벤자리·자바리 등 어족이 풍부하며 바닷바람에 말린 화살오징어로도 유명하다. 차귀도라는 이름은 섬에 내려오는 전설에서 유래했다. 옛날 중국 송나라 푸저우 사람 호종단이 이 섬에서 중국에 대항할 큰 인물이 나타날 것이라고 하여 섬의 지맥과 수맥을 모두 끊은 뒤 고산 앞바다로 돌아가는 길에 날쌘 매를 만났는데 매가 돛대 위에 앉자 별안간 돌풍이 일어 배가 가라앉았다. 이 매가 바로 한라산의 수호신이고 지맥을 끊은 호종단이 돌아가는 것을 막았다고 하여 대섬과 지실이섬을 합쳐서 차귀도라 불렀다는 것이다.','제주특별자치도 제주시 한경면 고락로 200-52',NULL,33.3116,126.1485,NULL,'https://www.visitjeju.net/kr/','상시 개방','연중무휴',90,0,'2026-11-16 11:19:00'),
('50110','KTO_TOURAPI','126456','ATTRACTION','관음사(제주)','한라산 650m 기슭에 자리한 대한불교 조계종 제23교구 본사 관음사는 제주의 30여 사찰을 관장하는 제주불교의 중심이다. 그 힘의 근원은 제주의 불교역사에서 찾을 수 있다. 제주의 여러 신화, 전설, 민담을 통해 괴남절(제주 방언으로 관음사), 개남절, 동괴남절, 은중절이라고 전해지며 고려 성종 때 지리서인 에 관음사의 기록이 남아있고, 조선시대에도 존재했던 것으로 알려져 있다.
조선이 유교를 숭상하여 1702년 이형상 목사에 의해 제주 지역 사찰이 전부 훼철되고 관음사도 사라지게 되었다. 200년의 명맥불교를 유지하다가 1908년 안봉려관 스님에 의해 중창되었다. 스님은 지역의 반대에 부딪히면서도 해월굴에서 3년간 관음기도를 드리며 법당과 요사를 완공했다. 뒤이어 통영 영화사 등지에서 불상과 탱화를 모셔 와 사찰의 모습을 갖추게 되었다. 절의 외형을 갖추는 불사가 일단락되자, 제주 중심지인 중앙로에 시내 포교당인 대각사를 세워 제주 도민과 함께 호흡하는 적극적인 포교활동을 펼쳤다. 이에 따라 오랜 시간 맥이 끊겼던 제주의 불교가 관음사를 중심으로 살아나기 시작했다. 그러나 1939년 불이나 대웅전 등이 모두 불타 없어졌고, 이어 1948년 제주 4·3사건 당시 관음사의 위치가 전략적 요충지였기 때문에 토벌대와 입산 무장대가 관음사를 중심으로 서로 첨예하게 대치하는 과정에서 모든 전각이 소실되었다.
한라산이 입산 금지가 풀리면서 지난 1969년부터 대웅전을 시작으로 선방, 영산전, 해월각, 사천왕문, 일주문, 종각 등을 다시 지어 지금의 모습을 갖게 됐다. 관음사에서는 템플스테이 체험이 이루어지고 있으며 교원 직무연수교육, 달빛 동동(걷기 치유 명상), 토요 명상여행, 행복 명상&힐링, 만다라 체험 등을 운영하고 있다.

◎ 한류의 매력을 만나는 여행 정보 - 드라마 
우영우 일행이 제주행을 떠난 이유는 황지사라는 이름의 사찰에 엮인 사건 때문이었다. 그런데 이 사찰, 예뻐도 너무 예뻐 많은 시청자가 촬영지를 궁금해했는데 이곳의 실제 이름은 ‘관음사’이다. ‘관음사’는 제주의 30여 사찰을 관장하는 제주 불교의 중심이 되는 사찰이다. 연등이 걸려 있는 하늘부터 마음을 정화하는 사찰, 해월궁 등 볼거리가 많은 장소이다.','제주특별자치도 제주시 산록북로 660',NULL,33.4237307637,126.558131212,NULL,'http://www.jejugwaneumsa.or.kr','09:00~18:00','연중무휴',90,0,'2026-11-16 01:30:04'),
('50110','KTO_TOURAPI','2606298','ATTRACTION','성이시돌목장','성이시돌목장은 아일랜드인 맥글린치(한국명 임피제) 신부님이 1954년 제주 한림지역에 부임하면서 가난한 지역민을 돕기 위한 가축은행을 열면서 시작되었다. 1961년 정식으로 중앙 실습 목장을 열고 축산업 교육과 함께 양돈, 면양, 비육우 및 낙농사업을 펼쳤으며 현재는 경주마와 젖소를 주로 사육하여 유수의 경주마와 유기농 우유를 생산하여 그 수익을 여러 복지사업에 사용하고 있다. 넓은 초지와 오랜 역사를 상징하는 ‘테쉬폰’ 등 근대건축물이 어우러져 이국적인 풍광을 즐길 수 있고, 목장의 우유를 이용한 카페와 신앙을 주제로 한 산책로와 공원 등을 방문할 수 있다.','제주특별자치도 제주시 한림읍 산록남로 53',NULL,33.3501384186,126.3267349447,NULL,'https://www.visitjeju.net','상시 개방 (카페 우유부단 10:00~18:00)','연중무휴(단, 카페 우유부단 공휴일 휴무)',90,0,'2026-11-15 01:30:00'),
('50110','KTO_TOURAPI','2704353','ATTRACTION','신비의도로','신비의 도로 혹은 도깨비 도로로 불리는 이곳은 내리막길에 차를 세워두면 아래로 내려가야 하는 차가 내려가지 않고 오히려 오르막 쪽으로 뒷걸음치는 기이한 곳이다. 사실 이는 오르막길이 보이는 쪽이 경사 3도가량의 내리막 길이어서 단순 착시 현상에 의해 올라가는 것처럼 보이는 것이다. 이러한 현상 때문에 입소문을 탄 신비의도로는 관광 명소가 되어 점점 많은 이들이 방문을 하는 추세로 현재 이로 인한 사고를 방지하기 위해 각종 안전시설들이 추가되고 있고 조만간 신비의도로를 기점으로 관광 공원이 생겨날 전망이다.

(출처 : 제주 문화관광 홈페이지)','제주특별자치도 제주시 1100로 2894-63 (노형동)',NULL,33.4512882139,126.4875009879,NULL,'https://www.visitjeju.net/kr/','상시 개방','연중무휴',90,0,'2026-11-15 01:30:00'),
('50110','KTO_TOURAPI','2765252','ATTRACTION','새미은총의동산','새미 은총의 동산은 예수님의 탄생부터 최후의 만찬까지 12개의 주요 사건을 표현한 ‘예수님 생애 공원’과 ‘삼위일체 대성당\'이 있는 곳으로, 천주교 제주교구의 성지 순례 장소다. 전체 면적은 약 264,000㎡에 달하며 언제든 신자들이 찾아와 기도할 수 있도록 24시간 개방하고 있다. 또, 성 이시돌 목장 뒤를 순례지로 개발해 넓은 동산과 연못, 성모상과 대형 십자가 등을 볼 수 있게 했다. 야외에서는 동시에 약 5천여 명이 함께 야외 미사를 보거나, 각종 공연이나 행사 공간으로 사용할 수 있다. 최근 많은 사람들이 찾는 여행지로 각광받고 있으며 다양한 조형물과 산책로, 넓은 들판이 있어 종교인이 아니어도 힐링할 수 있는 곳이다.','제주특별자치도 제주시 한림읍 새미소길 15',NULL,33.3482746995,126.3237602632,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-11-15 01:30:00'),
('50110','KTO_TOURAPI','591798','ATTRACTION','하고수동해변','제주도 동쪽 끝 성산포에서 북동쪽 해상에 위치한 화산섬 우도의 하고수동해변은 중앙에 노출된 암석 해안에 의해 둘로 분리된다. 해변의 총길이는 약 400m 정도이며, 동쪽에서 약 100m 되는 지점과 200m~300m 지점에는 현무암초가 노출되어 있고, 배후에는 사구 층이 발달되어 있다. 연안류에 의해 운반되는 물질들이 집적되어 형성된 해변이다. 1970년대까지 후릿그물을 이용한 멸치잡이가 이루어졌다. 
모래가 부드럽고 수심이 얕아 어린이를 동반한 가족 단위 피서객이 이용하기에 좋다. 해변 주변으로 민박집과 식당들이 있으며 탈의장, 화장실 등 편의 시설이 있다. 70대 해녀를 모티브로 한 해녀상이 중앙에 있어 눈길을 끈다. 여름밤에는 고기잡이 선박들이 밝힌 불빛들이 환하다.','제주특별자치도 제주시 우도면 연평리',NULL,33.5142433685,126.9574420445,NULL,'https://visitjeju.net/','상시 개방','연중무휴',90,0,'2026-11-11 08:48:03'),
('50110','KTO_TOURAPI','591866','ATTRACTION','금능해수욕장','제주시 한림읍에 위치한 금능해수욕장은 서쪽의 인기 명소인 협재해수욕장과 바로 이어져 있다. 파란 물감을 풀어놓은 것 같은 바다부터 생김새가 귀여운 비양도, 촉감이 보슬거리는 모래사장까지 이웃한 해변과 비슷한 풍경을 품고 있지만 그보다 사람이 붐비지 않아 여유로운 것이 매력이다. 주차장과 해변이 바로 연결되어 있어 짐을 옮길 때도 부담이 없다. 새로 신축된 샤워실은 온수 샤워가 가능해 편리함을 갖췄다. 이곳을 방문할 땐 물이 빠지는 간조 시간에 맞춰 가기를 추천한다. 바닷물이 멀리까지 빠지면 넓고 고운 모래사장이 드러난다. 곳곳에 수심이 얕고 어린아이도 놀기 좋은 천연 풀장이 만들어진다. 빠져나간 바닷물이 남겨 놓은 해조류나 작은 보말 등은 자연스럽게 아이들의 장난감이 된다. 덕분에 아무런 준비 없이 찾아도 재미있게 즐길 수 있다. 단, 해변 입구에 작게 부서진 조개껍질이 모래와 섞여 있어 되도록 물놀이용 신발 착용을 권한다. 

(출처 : 비짓제주 홈페이지)','제주특별자치도 제주시 한림읍 금능길 119-10',NULL,33.3903137402,126.2360240519,NULL,'http://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-11-11 08:48:03'),
('50110','KTO_TOURAPI','598187','ATTRACTION','선녀와나무꾼','제주 조천읍 선흘리에 위치한 선녀와 나무꾼은 옛 추억을 회상할 수 있는 실내 테마 공원이다. 옛 서울역의 모습을 재현한 건물로 들어서면 다양한 테마의 건물 모형과 옛날 물건들이 전시되어 있다. 옛 장터의 모습을 재현한 거리와 고고장, 다방, 만화방 등 옛 도심, 달동네 등의 풍경을 보며 그 시절을 살아온 세대는 추억에 잠기고, 그 시절을 경험하지 못한 세대는 부모님이 살아온 삶의 모습을 짐작할 수 있다. 추억의 영화 마을에서는 옛 영화를 하루 종일 상영하고 있어 이를 무료로 관람할 수 있다. 옛 학교를 재현한 공간에서는 옛 교복을 입고 기념사진을 남기는 특별한 경험을 할 수 있어 남녀노소 모두에게 반응이 좋다. 그 밖에 닥종이 인형이 테마별로 전시된 공간과 농기구 등 민속용품이 전시된 농업박물관 등 볼거리가 끝이 없다. 굴렁쇠, 팽이, 고무줄놀이 등 추억의 놀이를 체험할 수 있는 체험관도 있고, 꿩, 토끼 닭 등을 볼 수 있는 작은 공간과 도깨비가 있는 공포의 집에서도 특별한 추억을 만들 수 있다. 실내에 조성되어 있어 날씨와 관계없이 즐길 수 있는 테마공원인 이곳은 옛 추억을 떠올리고 싶은 사람들과 새로운 추억을 쌓고 싶은 사람 모두 즐거운 시간을 보낼 수 있는 여행지이다.','제주특별자치도 제주시 조천읍 선교로 267',NULL,33.4796207867,126.7026849679,NULL,'https://www.namuggun.net/','09:00~18:00(입장마감 17:00)※ 당일 상황 및 기상에 따라 변동될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-11-11 08:48:03'),
('50110','KTO_TOURAPI','660972','ATTRACTION','하도리 철새도래지','제주시 구좌읍 하도리에 있는 철새도래지로 바다와 인접하고 영양분이 풍부한 먹잇감과 습지식물이 많아 철새들이 월동하기에 최적의 지역으로 알려진 곳이다. 천연기념물로 지정돼 있고 세계적으로 1,600여 마리 정도만 남아있다는 저어새를 비롯해 천연기념물인 고니, 매, 황조롱이 등과 환경부 멸종위기야생동물인 물수리 등이 관찰되고 있다. 매년 30종에 이르는 철새들이 날아온다. 하도리 지미봉 기슭은 해안에 하굿둑을 축조해 저수지를 만들어 먹이가 풍부하고 둥지를 틀 수 있는 곳이 많이 있다. 망원경이 설치되어 있는 탐조대에서는 철새들의 모습을 관찰할 수 있다. 특히 이 지역은 둑을 축조하며 만든 다리의 경치가 일품이라 드라이브 코스로도 주목받고 있다.','제주특별자치도 제주시 구좌읍 하도리 53-2',NULL,33.504012,126.891953,NULL,'https://www.visitjeju.net/kr','상시 개방','연중무휴',90,0,'2026-11-11 08:48:03'),
('50110','KTO_TOURAPI','745449','ATTRACTION','다희연','제주도 제주시 조천읍 선흘리 일대 6만 평 대지에 자리 잡은 다희연은 국내 최고 수준의 친환경 녹차를 생산하는 다원이다. 제주도는 연평균 온도가 섭씨 16도를 유지해야 하고, 뿌리가 쉽게 썩어 물이 잘 빠지는 녹차 재배의 최적의 조건을 갖추고 있다. 에버그린루체 야외 정원은 화산이 폭발하면서 흘러내린 용암에 의해 생성된 조그만 동굴들을 활용한 곳이다. 동굴 연못과 동굴 다리 그리고 제주 자생수와 야생화 등이 어우러져 있다. 이브홀은 동굴 천정이 뚫린 부분에 있다. 사방에 동공들이 뚫려 있는데 가장 긴 것은 30여 미터까지 된다. 여기에는 박쥐도 서식하고 있어 운이 좋으면 직접 볼 수도 있다. 이브홀은 터널 같은 동굴을 통과하여야 들어갈 수 있다. 경덕원 정상부(그린루체)와 입구(이브홀)에 각각 자리한 두 곳의 동굴 카페에서는 천연 녹차 발효 빵, 녹차 쿠키, 녹차 머핀, 녹차라떼, 천연 녹차 발효즙 카테킹 등이 판매되고 있다.','제주특별자치도 제주시 조천읍 선교로 266-4',NULL,33.4789497557,126.7006524863,NULL,NULL,'09:00~18:00※ 방문 전 입장시간 문의 요망','연중무휴',90,0,'2026-11-11 08:48:03'),
('50110','KTO_TOURAPI','802844','ATTRACTION','한라생태숲','한라생태숲은 1970년대 초부터 1995년까지 개인에게 대부돼 마소의 방목지로 사용했던 곳이었다. 제주 식물의 보고에 걸맞은 산림생물 난대, 온대, 한대 식물 등 다양한 식물상을 조화롭게 설계하여 식재 생태복원시켰으며, 곶자왈 지대, 천연림 지역을 유전자원 보전지역으로 관리하고 있다. 또한 한라생태숲은 시험연구림으로서의 기능도 갖추고 있어 제주도의 온·난대 수종 및 한라산 고산대 희귀수종에 대한 유전자 보전 연구와 한라산의 훼손지 복구를 위한 식물증식 및 내한성 적응시험림의 역할도 수행하고 있다. 한라생태숲은 훼손되어 방치되었던 야초지를 원래의 숲으로 복원 조성한 곳으로 산림트래킹과 함께 자연생태계의 다양한 모습을 즐길 수 있다. 한라산에 서식하는 동물을 만날 수 있으며, 특히 난대성식물에서부터 한라산 고산식물까지 모두 볼 수 있다. 생태로, 전망대, 양묘하우스, 테마별 산책로, 유전자보존 조직배양실 등 기반시설과 단풍나무숲, 벚나무숲, 구상나무숲, 참꽃나무숲 등 13개의 테마숲, 생태숲 전체의 축소판인 암석원이 중앙에 조성되어 숲다운 숲의 면모를 보여주고 있다.','제주특별자치도 제주시 516로 2596',NULL,33.4319110107,126.5982189668,NULL,'https://www.jeju.go.kr/hallaecoforest','[하절기(3~10월)]- 09:00~18:00 (입장 마감 17:00)[동절기(11~2월)]- 09:00~17:00 (입장 마감 16:00)','연중무휴',90,0,'2026-11-11 08:48:03'),
('50110','KTO_TOURAPI','3371999','ATTRACTION','제주동화마을','제주다운 개방형 공원을 표방하는 제주동화마을은 제주 동부 오름 군락 중심부인 구좌읍 송당리에 자리 잡고 있으며, 약 3만 평의 부지에 수백 년 수령의 팽나무, 조록 나무, 배롱나무 등 제주의 나무와 수십만 년 전 화산활동을 통해 형성된 S급의 자연석 5천 점을 기본 재료로 공원을 조성하였다. 문화유산급 동자석, 문관석, 촛대석을 비롯해 상석류 200여 점을 수집하여 전시하였고 옛 문헌과 자료의 고증을 통하여 다양한 형태의 동자석 복원을 시도하고 있다.
향기체험관을 통해 농어촌 체험학습관을 시설하였고, 제이팜정육식당, 미스터밀크(성이시돌목장), 송당산들네식당(향토음식점) 등 제주의 맛을 맛볼 수 있는 음식점들은 물론, 관광지로서의 역할로 공원의 전경을 볼 수 있는 스타벅스, 파리바게뜨, 지브리공식 코리코카페, 지브리공식 도토리숲 등이 있다. 감성 소품과 편의점 물품을 판매하는 제스코 관광마트는 제주위미농협직판장, 성산포수협직판장, 제주시산림조합을 통한 제주 특산품 판매를 하고 있으며, 동시에 제주농촌관광 활성화를 위해 제주농촌 융복합산업 6차 산업 인증사업자들의 상품이 많은 비중을 차지하고 있어 제주관광 상품 및 제주 굿즈의 대부분을 한 곳에서 쇼핑할 수 있는 장소라 할 수 있다.','제주특별자치도 제주시 구좌읍 비자림로 1191',NULL,33.4354329703,126.7320377305,NULL,'https://jejudonghwa.com/','09:00~20:00','연중무휴',90,0,'2026-11-11 08:48:03'),
('50110','KTO_TOURAPI','3396532','ATTRACTION','안의울림','안의울림은 마음과 몸의 고요를 위한 쉼, 깊은 이완을 위한 소규모그룹 싱잉볼 사운드힐링세션과 프라이빗 힐링프로그램이 준비되어 있는 곳이다. 히말라야싱잉볼의 잔잔하고 깊은 울림의 사운드와 진동 안에서 이완하고 휴식을 경험할 수 있다. 스트레스완화 이완, 힐링, 에너지 균형을 위한 프로그램등이 준비되어 있다.','제주특별자치도 제주시 애월읍 애월북서길 15',NULL,33.4653530933,126.3119865763,NULL,'https://www.instagram.com/jejusingingbowl','06:00~22:00','연중무휴',90,0,'2026-11-11 08:48:03'),
('50110','KTO_TOURAPI','4139039','ATTRACTION','토토아뜰리에','토토아뜰리에는 셀프쿠킹 체험을 할 수 있는 카페 겸 요리체험 공간이다. 성인을 위한 쿠킹 랩과 아이를 위한 쿠킹 랩이 따로 운영되고 있어 아이와 성인 모두가 즐겁게 체험을 할 수 있는 곳이다. 또한 자체적으로 텃밭을 가꾸고 있어 이곳의 식재료를 이용해 음식을 만들어볼 수 있다. 치킨, 라자냐, 쿠키, 베이킹 등 다양한 음식 체험 활동을 할 수 있다. 쿠킹 체험을 할 수 있는 공간과 함께 카페도 운영하고 있어 여유롭게 티타임을 즐기기에도 좋다. 건물의 벽면이 모두 통유리로 되어있어 밖의 전경을 바라보며 여유로운 시간을 가질 수 있다. 카페 밖에는 아이들이 뛰어놀 수 있는 공간이 있어 가족과 함께 가기 좋다. 요리하는 모습을 전담 포토그래퍼가 촬영해 준다.','제주특별자치도 제주시 애월읍 고성북길 112-4',NULL,33.4700264921,126.4134386065,NULL,'https://www.instagram.com/thankstoto_atelier','10:00~18:00 (휴게시간 12:20~13:00)','매주 월요일',90,0,'2026-11-11 08:48:03'),
('50110','KTO_TOURAPI','125445','ATTRACTION','생각하는 정원','생각하는 정원은 자연 속에서 자기 자신을 만나고, 삶을 다시 돌아볼 수 있는 정원이다. 단순히 아름다운 정원을 감상하는 관광지가 아니다. 천천히 걷고, 머물고, 자연과 함께하는 시간 속에서 자신만의 질문과 답을 발견하는 곳이다. 이 정원은 한 사람이 60년 동안 포기하지 않고 자연과 함께 가꾸어 온 삶의 기록 위에 세워졌다. 그래서 이곳의 사유는 이론이 아니라 삶에서 태어나, 정원에서 발견되고, 다시 삶으로 이어진다. 자연을 통해 자기 자신을 만나고, 자신의 삶을 성찰하며, 다시 일상으로 나아갈 힘을 얻도록 도우려 한다. 때문에 아름다운 정원을 넘어, 사람을 자기 자신에게 돌아오게 하는 살아있는 문화유산을 지향한다.','제주특별자치도 제주시 한경면 녹차분재로 675','(한경면)',33.3253707254,126.2551643784,NULL,'http://www.spiritedgarden.com','09:00~18:00','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','126448','ATTRACTION','이호테우해변','이호테우해변(이호해수욕장)은 조랑말 등대로 제주도 사진을 찍기 좋은 곳으로 붉은 조랑말과 흰색 조랑말은 극명하게 대조되는 색감이 이국적인 풍경을 선사한다. 또한, 제주 시내에서 가장 가까이 있어 교통이 편리하고, 편의시설도 잘 갖추어져 있다. 백사장의 경사가 완만하여 많은 피서객들이 찾으며 특히 야영하기에 안성맞춤인 소나무 숲이 형성되어 있다. 해수면이 가장 낮아지는 간조에는 끝없이 넓은 백사장과 함께 원담의 모습도 볼 수 있다. 원담은 밀물과 썰물의 차이를 이용해 고기를 잡는 제주의 전통 고기잡이 방식 중 하나로, 이호테우해변(이호해수욕장)에는 그 공간을 복원시켜 놓은 이호 모살원이 있다.','제주특별자치도 제주시 도리로','(이호일동)',33.4973871738,126.4531448539,NULL,'http://www.visitjeju.net','상시 개방','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','126451','ATTRACTION','함덕해수욕장 (함덕 서우봉 해변)','제주올레 19코스를 걷다 보면 에메랄드빛 보석을 품고 있는 함덕해수욕장을 만날 수 있다. 제주시 조천읍 함덕리에 자리한 함덕해수욕장은 해수욕장 바로 옆에 우뚝 선 오름(서우봉) 덕분에 ‘함덕서 우봉해변’이라고도 불린다. 제주공항에서 불과 20㎞ 떨어졌지만, 이곳에 도착하는 순간 다른 나라에 온 것 같은 기분이 든다. 입구부터 환영해 주는 키 큰 야자수들, 하얀 모래와 대조를 이루는 에메랄드빛 바다, 모래와 미역마저 투명하게 비춰주는 맑은 물과 하얀 파도가 그러하다. 제주도 수많은 해수욕장 중에서도, 바다색이 가장 예쁜 3곳을 꼽는다면 단연 협재, 김녕, 그리고 함덕해수욕장이다. 물이 맑고 수심이 얕아서 가족단위 피서지로도 좋다. 해수욕장 서쪽은 구름다리로 연결되어 있어 바다 위를 걷는 듯한 경험을 할 수 있다. 피크닉 하기 좋은 잔디밭, 밤에도 안심하고 바다를 즐길 수 있는 산책로가 매력이어서 사계절 찾는 이들의 발길이 끊이지 않는다. 특히 여름에는 야간개장도 하고 있어 제주의 푸른 밤을 바다에서 즐길 수 있다. 바로 옆에 자리한 서우봉은 봄이 되면 노란 유채꽃으로 여름엔 초록빛으로 계절마다 그림 같은 풍경을 선사한다. 서우봉에 오르면 함덕해수욕장을 한눈에 담을 수 있는 호사를 누릴 수 있다. 날씨가 좋으면 한라산과 동쪽 오름들도 내려다볼 수 있는 최고의 전망 포인트이다.','제주특별자치도 제주시 조천읍 조함해안로 519-10',NULL,33.543868551,126.6683432124,NULL,'http://www.visitjeju.net/','상시 개방
※ 해수욕장 개장기간에는 변동 가능성 있음','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','126452','ATTRACTION','만장굴 (제주도 국가지질공원)','제주시 구좌읍 김녕리에 위치하는 만장굴은 전체길이 약 7,400 m, 최대 높이 약 25 m, 최대 폭 약 18m로서 제주 세계자연유산의 한 부분인 거문오름용암동굴계(황상구 외, 2005)에 속하는 용암동굴이다. 특히 주 통로는 폭이 18m, 높이가 23m에 이르는 세계적으로도 큰 규모의 동굴이다. 전 세계에는 많은 용암동굴이 분포하지만 만장굴과 같이 수십만 년 전에 형성된 동굴로서 내부의 형태와 지형이 잘 보존되어 있는 용암동굴은 드물어서 학술적, 보전적 가치가 매우 크다. 만장굴은 동굴 중간 부분의 천장이 함몰되어 3개의 입구가 형성되어 있는데, 현재 일반인이 출입할 수 있는 입구는 제2입구이며, 1㎞만 탐방이 가능하다. 만장굴 내에는 용암종류, 용암석순, 용암유석, 용암유선, 용암선반, 용암표석 등의 다양한 용암동굴생성물이 발달하며, 특히 개방구간 끝에서 볼 수 있는 약 7.6m 높이의 용암석주는 세계에서 가장 큰 규모로 알려져 있다.

(출처 : 제주도세계지질공원)','제주특별자치도 제주시 구좌읍 만장굴길 182','(구좌읍)',33.5280164989,126.7706646226,NULL,NULL,'09:00~18:00 (입장 마감 17:00)','매월 첫째 수요일',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','126454','ATTRACTION','사라봉공원','사라봉 공원은 제주시 동문로터리에서 있는 낮은 동산이다. 사라봉 전체를 공원으로 조성하여 제주 시민들의 산책이나 운동 장소로 이용될 뿐만 아니라, 사라봉을 오르는 관광객들에게도 오름을 오르는 즐거움을 더하고 있다. 사봉낙조는 사라봉에서 바라보는 해넘이를 말하는데, 이곳에서 볼 수 있는 사봉낙조는 영주(제주도의 옛 명칭) 10경의 하나로 성산일출과 대조가 될만하다. 북쪽으로는 바다를 끼고 남쪽으로는 한라산을 바라보고 있는 이곳은 제주시민은 물론 관광객도 즐겨 찾는다. 사라봉입구 버스 정류장에서 공원으로 가는 길에 모충사가 있고 사라봉 동쪽에는 패러글라이딩 활공장이 있는 별도봉이 들어앉았다. 기슭에 우당도서관이 있는데 이곳에서부터 사라봉 뒤편을 돌아 제주항을 거친 다음 탑동까지 가는 코스는 이름난 드라이브 코스이다. 오후에 운동 겸 산책 겸 사라봉을 오르면서 바다로 지는 일몰도 감상하고, 시내에 하나 둘 들어오는 불빛을 바라보면, 자연과 도시의 아름다움을 한 번에 느낄 수 있다. 도시의 불빛뿐만 아니라, 항구 쪽에서 밝혀지는 불빛들은 바닷가에서만 만날 수 있는 또 다른 아름다움을 선사한다.','제주특별자치도 제주시 사라봉길 75 (건입동)',NULL,33.5160073749,126.5461911127,NULL,'http://www.visitjeju.net','상시 개방','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','126459','ATTRACTION','모충사','모충사는 제주특별자치도 제주시 건입동 사라봉 공원에 자리한 사당으로, 제주 의병항쟁과 항일운동에 참여한 인물들, 그리고 나눔과 구휼을 실천한 김만덕을 기리기 위해 조성되었다. 제주 내외 도민의 성금으로 건립되었으며, ‘충절을 사모한다’는 뜻을 담아 모충사라 이름 지었다.
경내에는 제주 의병항쟁기념탑과 순국지사 조봉호 기념비, 김만덕을 기리는 기념 시설이 있다. 의병항쟁기념탑은 1909년 제주 의병항쟁에 참여한 인물들의 뜻을 기리는 시설이며, 조봉호 기념비는 독립운동에 참여한 조봉호 지사를 추모하기 위해 세워졌다. 김만덕은 조선 후기 제주에 흉년이 들었을 때 재산을 나누어 주민들을 구휼한 인물로 알려져 있다.
모충사는 제주의 역사와 인물들의 삶을 되새길 수 있는 곳으로, 숲길이 아름답게 정돈되어 있다. 마을 주민과 관광객이 제주의 역사를 돌아보며 쉬어갈 수 있는 산책코스로 인근 사라봉 공원 산책과 함께 둘러보기 좋다.','제주특별자치도 제주시 건입동','1427-13',33.516113,126.545509,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','126461','ATTRACTION','산천단곰솔','제주시의 곰솔은 제주시에서 서귀포시로 향하는 제1횡단도로를 따라 8㎞ 정도 가면 나타나는 산천단이라는 곳에 군락을 이룬다. 원래 이곳에는 곰솔이 9그루 있었는데, 1965년 벼락을 맞아 1그루가 고사하고 8그루만 남아 있다. 높이는 21∼30m로 4그루가 30m, 3그루가 25m이며 가슴 높이 둘레는 3.4∼6m, 수관 너비는 12∼24m이다. 수령은 500∼600년으로 추정된다. 현재까지 알려진 제주도의 수목 중에서는 가장 크며, 생육 상태는 대체로 양호한 편이나 몇 그루는 풍해로 가지들이 한쪽으로 치우쳐 생장하고 있다. 이들 곰솔 틈에서는 예덕나무, 팽나무, 쥐똥나무, 뽕나무 등이 자란다.','제주특별자치도 제주시 516로 3041-24','(아라일동)',33.4476390382,126.5547476479,NULL,'http://www.visitjeju.net/','[하절기]- 08:30~18:00[동절기]- 09:00~17:30','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','126472','ATTRACTION','비자림','천연기념물로 지정보호하고 있는 비자림은 448,165㎡의 면적에 500~800년생 비자나무 2,800여 그루가 밀집하여 자생되고 있다. 나무의 높이는 7~14m, 직경은 50∼110㎝, 그리고 수관폭은 10~15m에 이르는 거목들이 군집한 세계적으로 보기 드문 비자나무 숲이다. 예부터 비자나무 열매인 비자는 구충제로 많이 쓰였고, 나무는 재질이 좋아 고급가구나 바둑판을 만드는 데 사용되어 왔다. 
비자림은 나도풍란, 풍란, 콩짜개란, 흑난초, 비자란 등 희귀한 난과식물의 자생지이기도 하다. 녹음이 짙은 울창한 비자나무 숲 속의 삼림욕은 혈관을 유연하게 하고 정신적, 신체적 피로해소와 인체의 리듬을 되찾는 자연 건강 휴양효과가 있다. 또한 주변에는 자태가 아름다운 기생화산인 월랑봉, 아부오름, 용눈이오름 등이 있어 빼어난 자연경관을 자랑하고 있을 뿐만 아니라 가벼운 등산이나 운동을 하는데 안성맞춤인 코스이며, 특히 영화 촬영지로서 매우 각광을 받고 있다.','제주특별자치도 제주시 구좌읍 비자숲길 55',NULL,33.4862219608,126.8074760594,NULL,'https://www.visitjeju.net/kr','09:00~18:00 (입장 마감 17:00)','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','126473','ATTRACTION','연화못(하가못)','연꽃이 많은 연못이라는 뜻으로 지어진 연화못은 제주 유명한 명소인 더럭분교 인근에 있다. 넓이가 3,780여 평으로 봉천수에 의한 연못으로는 제주도에서 가장 넓으며 마을 안에 위치하고 있어 농업용수로 이용할 뿐만 아니라 연꽃, 수련, 소리쟁이, 쇠무릎 등과 각종 수생 식물을 비롯하여 어류 등 다양한 종이 서식하고 있다.','제주특별자치도 제주시 애월읍 하가로',NULL,33.454715462,126.3475084329,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','126474','ATTRACTION','산굼부리','산굼부리는 천연기념물로 둘레가 2㎞가 넘는 화구이다. 제주도에는 360여 개의 기생화산이 분포되어 있지만 이곳 산굼부리를 제외한 다른 화산은 모두 대접을 엎어놓은 듯한 분화구의 형태이고, 산굼부리 분화구만은 제주도에서 유일하게 용암이나 화산재의 분출 없이 폭발이 일어나 그곳에 있던 암석을 날려 그 구멍만이 남게 된 것이다. 이러한 화산을 마르(Maar)라고 부르는데 한국에는 하나밖에 없는 세계적으로도 아주 희귀한 화산이다.

특히, 산굼부리 밑바닥에는 틈이 많아서 물이 모두 스며들기 때문에 이 화구 안에는 식물의 생태계가 특이하게 분포되어 있다. 분화구의 내부높이에 따라 온대와 난대지역이 형성되어 있고 태양이 비치는 일사량과 일조시간에 따라 다양한 분포를 이루고 있다. 즉, 햇볕이 잘 드는 북쪽벼랑은 난대지역을 이뤄서 붉가시나무를 비롯해서 후박나무, 구실잣밤나무, 센달나무 등 상록활엽수군이 형성되어 있으며, 그 아래층에는 금새우란과 같은 희귀 식물과 자금우, 겨울딸기 등이 분포되어 있다. 또한, 햇볕이 잘 들지 않는 남쪽벼랑에는 북쪽과는 판이한 분포를 이루는 상수리나무를 비롯하여 졸창나무, 산딸나무, 단풍나무, 곰솔등 온대성낙엽수 군락이 진을 치고 있다.

뿐만 아니라, 다른 곳에서는 보기 힘든 왕쥐똥나무군락을 비롯해서 상산 군락, 제주조릿대군락, 복수초군락, 변산바람꽃군락등이 매우 화려하고 완벽하게 보존되어 있음은 학술적으로도 연구 가치가 매우 높게 평가되고 있다. 그리고 노루와 오소리 등의 포유류를 비롯하여 조류, 파충류 등 야생동물들의 서식처로도 유명하다. 봄에는 분화구 밑바닥에서 구름이 형성돼서 위로 올라가는 모양이 신비에 가까우며, 쑥부쟁이를 비롯한 무룻과 용담, 물매화 등 천연색 꽃과 더불어 이 산굼부리에는 일 년 사시사철 관광객들에게 신비와 아름다움을 보여준다.','제주특별자치도 제주시 조천읍 비자림로 768',NULL,33.4322819348,126.6928046167,NULL,'http://sangumburi.net','[3~6월 / 9~10월]- 09:00~18:40 (입장마감 18:00)
[7~8월 / 11월~2월]- 09:00~17:40 (입장마감 17:00)
※ 마감시간은 기후 및 날씨에 따라 변경될 수 있음','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','127046','ATTRACTION','김녕미로공원','제주도 제주시의 만장굴과 김녕사굴 사이에 유명한 관광지인 제주 김녕미로공원이 있다. 키 큰 나무 사이로 샛길이 만들어져 한번 들어가면 방향감각을 잃게 되어 어디로 나와야 할지 헷갈리게 하는 매력의 우리나라 최초 미로공원이다. 제주대학교에서 퇴직한 미국인 더스틴(F.H. Dustin) 교수가 세계적으로 유명한 영국의 미로 디자이너 에드린 피셔(Adrian Flsher Minotaur Maze Designs)와 함께 국제 전화, 국제 우편을 주고받으며 1983년부터 약 3년에 걸쳐 기본 디자인 작업을 마무리하였다. 그 후 1987년 처음으로 랠란디 나무를 산목 후 8년 동안 나무를 가꾸면서 1995년부터 운영을 시작했다. 
김녕미로공원의 수벽을 리우고 있는 나무는 랠란디나무는 사계절 푸른 상록수로서 향기는 사람의 정신을 맑게 해 주고 심리적 압박감을 완화시켜 주는 효과를 지니고 있다. 미로의 붉은빛이 감도는 바닥은 제주 천연 화산석이 송이이며 오염된 공기를 정화시키고 인체의 혈액 순환을 촉진시키는 효과를 지니고 있다. 
미로공원뿐만 아니라 다양한 포토존, 아이들과 놀 수 있는 놀이터, 미로공원에서 자라고 있는 고양이들에게 사료를 주는 등의 체험 프로그램을 진행하고 있어 가족 단위의 관광객들이 많이 방문한다.','제주특별자치도 제주시 구좌읍 만장굴길 122',NULL,33.5362933352,126.7720254157,NULL,'http://www.jejumaze.com','09:00~18:30 (입장 마감 17:30)※ 계절별로 상이하니 자세한 시간은 매표소 문의','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','127479','ATTRACTION','제주절물자연휴양림','제주절물자연휴양림은 삼나무가 주종을 이루는 힐링명소이다. 절물은 근처에 약효가 좋은 물이 난다고 하여 유래된 이름이며, 이전에 가뭄 때도 물이 마르지 않아 주민들이 식수로 이용했다고 할 정도로 수량이 풍부하다. 특히 신경통과 위장병에 특효가 있다고 하며, 제주도와 제주시에서 정기적으로 수질 검사를 진행하고 있다. 휴양림에 주 수종을 이루고 있는 삼나무는 60년대 중반부터 잡목을 제거하고 식재한 것이다. 삼나무 우량조림지는 자연휴양림으로 개발되면서 전국에서 가장 많은 사람이 방문하는 유명한 산림 휴식공간을 제공하고 있다. 휴양림 내에는 산책로, 약수터, 폭포, 연못, 잔디광장, 목공예체험장, 운동시설, 어린이 놀이시설, 숙박시설 등 다양한 시설이 갖추어져 있어 편안한 한 때를 보낼 수 있으며, 산책로는 비교적 완만하고 경사가 낮고 계단이 없어 노약자나 어린이, 장애인도 편하게 이용할 수 있다. 또 휴양림 내에는 다양한 동식물이 서식하고 있다. 휴양림 근처에는 기생화산인 절물오름이 있으며, 이곳 정상에는 전망대가 있어 말발굽형 분화구를 볼 수 있다. 날씨가 좋은 날이면 동쪽으로 성산일출봉이, 서쪽으로는 제주에서 제일 큰 하천인 무수천이, 북쪽으로는 제주시를 한눈에 조망할 수 있다.','제주특별자치도 제주시 명림로 584',NULL,33.440046609,126.6252023847,NULL,'https://www.foresttrip.go.kr','[3월~10월] 07:00~18:00 [11월~2월] 07:00~17:00','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','127514','ATTRACTION','한라수목원','제주시 연동 1100로 변, 광이오름 기슭에 위치한 한라수목원은 제주 자생 수종과 아열대 식물을 한눈에 볼 수 있는 수목원이다. 2000년 환경부로부터 멸종위기 야생생물의 \'서식지외보전기관\'으로 지정되었으며, 멸종위기 식물인 나도풍란, 한란, 파초일엽, 갯대추 등 보호 대상 식물을 포함해 총 1,321종(목본류 530종, 초본류 791종), 10만여 본의 식물을 보존·전시하고 있다. 제주 자생식물의 유전자원 보존과 연구는 물론, 방문객에게는 청정한 자연 속 휴식과 생태 체험의 기회를 제공하는 대표 관광명소이다.

◎ 한류의 매력을 만나는 여행 정보 - 예능 
제주살이의 상징이 된 효리네 민박 촬영지로 제주의 자생 수종과 아열대 식물 등 1,100여 종의 식물이 식재, 전시되어 있는 수목원이다. 멸종 위기종과 희귀한 식물도 많지만 가볍게 산책하며 힐링하기 좋다. 5만 평의 산림욕장은 관광객과 제주도민에게 도심 속 숲과 같은 휴식 공간이 되어준다. 야외 산책로는 오후 11시까지 관람 가능해 밤 산책을 하기에도 좋다.','제주특별자치도 제주시 수목원길 72 (연동)',NULL,33.469586747,126.4932439937,NULL,'https://www.jeju.go.kr/sumokwon/','[야외전시원 및 산책로]- 상시 개방[야외 산책로]- 09:00~23:00[실내시설]- 3월~11월 09:00~18:00- 12월~2월 09:00~17:00','[야외전시원 및 산책로]연중무휴[실내시설]설·추석 당일',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','127744','ATTRACTION','제주 삼성혈','국가지정문화유산인 사적으로 지정되어 있는 삼성혈은 탐라국 시조에 대한 제의가 이루어지는 장소이다. 태초에 탐라를 창건한 고을나, 양을나, 부을나 삼신이 이곳에서 동시에 태어나 수렵생활을 하다가 소, 말, 오곡의 종자를 가지고 온 벽랑국의 세 공주를 맞이하면서부터 농경생활이 비롯되었으며 탐라왕국으로 발전하였다고 전한다. 특히, 이 세 개의 지혈은 주위가 수백 년 된 고목으로 둘러싸여 있으며 모든 나뭇가지들이 혈을 향하여 경배하듯이 신비한 자태를 취하고 있다. 또한 아무리 비가 많이 오거나 눈이 내려도 일 년 내내 고이거나 쌓이는 일이 없는 성혈로서 이곳을 찾는 방문객들의 놀라움을 자아낸다. 조선 중종 21년(1526) 목사 이수동이 처음 표단과 홍문을 세우고 담장을 쌓아 춘·추봉제를 하기 시작한 이래 역대 목사에 의하여 성역화 사업이 이루어졌고 현재에도 매년 춘·추대제(4월 10일, 10월 10일) 및 건시대제(12월 10일)를 지내고 있다.','제주특별자치도 제주시 삼성로 22','(이도일동)',33.5041459335,126.5289459792,NULL,NULL,'09:00~18:00 (매표 마감 17:30)※ 1월 1일 / 설·추석 10:00 개장','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','127860','ATTRACTION','금능석물원','똑같이 생긴 하르방만 본 여행객들에게 제주 석물의 진수를 감상할 수 있게 하는 곳이 바로 금능석물원이다. 금능석물원은 40여 년을 돌하르방 제작에 힘쓴 장공익 명장이 조성한 공원이다. 돌하르방을 비롯해 해녀상, 동자상, 물허벅을 지고 아이를 돌보는 어머니상 등 제주 지역의 전설을 돌로 표현한 작품, 제주의 생활, 민속, 문화를 상징하는 조각품들이 전시되어 있다. 세계 여러 나라의 대통령과 총리, 지도자들이 제주도를 방문했을 때 선물했던 돌하르방 모형도 함께 전시해 놓았다. 금능석물원의 전체적인 분위기를 주도하는 불교적인 색채가 묻어나는 석불들도 볼 수 있다. 금릉석물원 내에는 정녀굴과 조롱굴 2개의 동굴이 있으며 굴 안에는 불공을 드릴 수 있는 암자가 있다.','제주특별자치도 제주시 한림읍 한림로 176',NULL,33.3854605055,126.2267379009,NULL,'https://www.ok114.co.kr/0647962174','매일 08:30~17:30','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','127870','ATTRACTION','곽지해수욕장','제주시에 위치한 곽지해수욕장은 입지가 좋아 주변에 청소년 수련장이 설치되고 단체 피서객이 많이 찾는 제주 명소이다. 곽지리는 선사시대의 패총이 발견되었을 정도로 유서 깊은 마을이다. 지금의 곽지해수욕장은 옛날에 마을이 들어서 있던 곳이었으나, 어느 날 갑자기 모래에 파묻혔다는 전설이 전해온다. 곽지해수욕장 끝머리에는 과물노천탕이 있다. 과물은 한라산에서 흘러내리기 시작한 물이 땅속으로 스며들어 100리를 내려와 곽오름을 배경으로 바다에서 솟는 달콤한 물이라는 뜻이다. 과물노천탕은 남탕과 여탕으로 나뉘어 있고 해수욕장에서 놀고 난 후 바닷물을 씻어내기에 안성맞춤이다.','제주특별자치도 제주시 애월읍 곽지리 1565',NULL,33.4485059408,126.3030937715,NULL,'http://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','128049','ATTRACTION','제주 센트럴파크','제주 센트럴파크는 태고의 신비를 그대로 간직한 한라산을 중심으로 둘러싼 중산간에 위치하여 있다. 1만 5천 평 규모의 사계절 형형색색의 아름다운 경관 속에 에펠탑, 자유의 여신상, 콜로세움 등 전 세계의 유명 건축 조형물 미니어처와 캐릭터 조형물, 그리고 세계 위인상과 인물상이 전시되어 있다. 이곳은 세계문화유산의 나라, 세계 위인의 나라, 환상과 동화의 나라, 공룡의 나라, 레이싱카트장 등 5개의 이색 테마로 이루어져 있다. 특별한 제주 속 세계여행지로 각광받고 있는 제주 센트럴파크는 문화예술에 대한 경험의 폭을 넓히는 창의적인 공간이자 국내 최초 야외 전동 고카트장에서 안전하게 드라이빙을 즐길 수 있는, 관람과 체험을 동시에 만족하는 복합문화공간이다. 근처에 에코랜드 테마파크와 산굼부리분화구가 있어 연계해서 방문하는 것도 좋다.','제주특별자치도 제주시 조천읍 비자림로 606',NULL,33.433195423,126.6745535129,NULL,'https://www.instagram.com/jejucentralpark','09:00~18:00 (입장 마감 17:00) (카트 마감 16:30)','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','128050','ATTRACTION','제주 항파두리 항몽 유적','제주 항파두리 항몽 유적은 몽골의 침입 때 조국을 지키고자 궐기한 삼별초가 최후까지 항전한 유서 깊은 곳으로, 사적으로 지정되어 있다. 전시관과 기념비, 토성이 남아 있으며 주변에는 김통정 장군이 뛰어내린 발자국에서 솟아나는 물이라고 전해지는 장수물이 있다. 삼별초는 고려군의 정예 별동 부대로서 고려 조정이 몽골군과 강화 조약을 맺자 이에 반대하여 끝까지 반몽항쟁을 계속하였는데, 전라도 진도로 근거지를 옮겼다가 그곳에서 크게 패하자 이곳 제주도로 건너와 항파두성을 쌓고 몽골군과 대결한 끝에 1273년 4월 몽골 세력에 의해 전원이 순의 했다. 삼별초의 독자적인 무력 항몽은 외세의 침략으로부터 조국을 수호하려는 호국 충정이 담겨 있으며 오늘날까지 우리에게 교훈을 일깨워준다.','제주특별자치도 제주시 애월읍 항파두리로 50',NULL,33.4523056089,126.4089499911,NULL,'https://www.jeju.go.kr/hangpadori/','09:00~18:00 (입장 마감 17:30)','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','128556','ATTRACTION','제주러브랜드','국내 유일의 성(性)을 주제로 한 테마조각공원 제주러브랜드. 홍익대 미대 조소과 출신의 신인, 중견 작가 20여 명이 2년여의 제작기간을 거쳐 2004년 11월 16일 드디어 국내 최초로 성테마 조각공원이 문을 열었다. 39,667m²(12,000평)의 대지 위에 야외 조각작품 100여 점과 실내 미술관에 40여 점의 조각품이 전시되어 있으며 공원 전체가 거대한 랜드아트(대지미술)로 작품화되어 있다. 제주도 유일의 야간 관광지로 관람시간은 오전 9시부터 밤 12시까지 일 년 365일 관람객들을 맞이하고 있으며 관람 소요시간은 주간 30분, 야간 40분이 소요된다. 공원 내에 유리돔 레스토랑과 노천카페, 아트샵도 있어 볼거리, 먹거리, 살 거리와 함께 촉각체험작품을 직접 작동해 보면 색다른 즐거움을 맛볼 수 있는 곳이다. 즐거움과 해학으로 가득 찬 조각공원 제주러브랜드는 휴식과 관광, 에로티시즘이 가미된 새로운 볼거리를 제공하며, 외설이 아닌 예술의 공간으로 성을 아름답고 개방된 곳에서 만날 수 있다.','제주특별자치도 제주시 1100로 2894-72','(연동)',33.4520763477,126.4883787181,NULL,NULL,'09:30~20:00','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','128777','ATTRACTION','돌하르방미술관','돌하르방미술관은 제주시 조천읍에 위치한 미술관이다. 이곳은 제주 토박이 김남흥 원장이 15년 이상의 세월 동안 개인의 힘으로 일구어온 생명과 평화의 공원이자 문화와 예술을 담은 공원이다. 도 내외에 흩어져 있는 48기의 돌하르방을 원형 그대로 재현해 전시하고 있을 뿐만 아니라 현대적인 해석으로 탄생한 다양한 형태의 돌하르방과 250여 개의 조형물들을 공원 곳곳에서 야외 전시하고 있다. 또, 곶자왈 산책길에서는 각종 양치식물과 청미래덩굴, 자귀나무, 꾸지뽕나무 등 다양한 수목을 관찰할 수 있어 살아 숨 쉬는 자연을 그대로 접할 수 있다.','제주특별자치도 제주시 조천읍 북촌서1길 70',NULL,33.5395721737,126.689646886,NULL,'https://www.visitjeju.net','[하절기(4월~10월)]09:00~18:00 (입장 마감 17:30)[동절기(11월~3월)]09:00~17:00 (입장 마감 16:30)','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','129400','ATTRACTION','김녕해수욕장','하늘에서 바라본 모습이 한문 평(平) 자를 이룬 모양을 하고 있어 김녕이라고 불리는 김녕마을에 있는 해수욕장이다. 거대한 너럭바위 용암 위에 모래가 쌓여 만들어졌으며, 김녕성세기해변이라고도 불리는데 외세의 침략을 막기 위한 작은 성이라는 뜻이 담겨 있다. 하얀 모래에 부서지는 파도들이 시원한 소리를 내고, 코발트빛 바다 풍경이 제주 자연의 아름다움을 새삼 느끼게 해주는 곳이다. 해변가를 걷다 보면 제주의 바람으로 돌아가는 김녕풍력발전기들을 관찰할 수 있다. 인근에는 갓돔과 노래미돔이 잘 잡히는 갯바위 낚시터가 낚시꾼들에게 인기 명소이며, 용천동굴, 당처물동굴, 만장굴 등 다양한 굴이 근처에 위치해 있어 여름에 시원하게 피서를 즐길 수 있다. 김녕해수욕장은 특이한 지형으로 인해 지질트레일도 조성이 되어 있는데, 지질트레일은 유네스코 세계지질공원을 활용해 각 지역의 지질자원과 마을의 역사 및 문화와 어울려진 도보길이다.','제주특별자치도 제주시 구좌읍 구좌해안로 237',NULL,33.5572081368,126.7365512139,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','129401','ATTRACTION','삼양해수욕장','삼양해수욕장은 관광객들에게 잘 알려지지 않은 해변이다. 상대적으로 소박하며, 물이 깨끗하고 고운 모래가 특징이다. 특히 화산암편과 규산염광물이 많은 세립질 모래로 이루어져 있어 반짝이는 검은 모래가 특색이라 바다와 모래를 배경으로 사진을 찍으면 인생사진을 건질 수 있는 해수욕장이다. 이 모래는 태양열에 뜨거워졌을 때 그 안에 몸을 파묻고 찜질을 하면 신경통 및 관절염에 좋다고 알려지고 있어, 매년 여름이면 뜨거운 모래를 덮고 찜질하는 관광객들의 모습을 심심찮게 볼 수 있다.','제주특별자치도 제주시 삼양이동',NULL,33.5254971286,126.5852430307,NULL,'http://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','129455','ATTRACTION','제주 삼양동 유적','제주 삼양동 유적은 청동기부터 초기 철기시대의 해안평탄대지에 많은 사람들이 모여 큰 마을을 이루고 살았던 마을 유적이다. 이 마을 안에는 크고 작은 집터, 창고, 저장공, 야외 토기요지, 마을 공간을 구획한 돌담과 배수로, 폐기장, 조개무지, 고인돌 등이 확인되었다. 발굴조사에서 확인된 집터는 원형주거지, 장방형주거지, 부정형주거지, 창고지 등이다. 원형주거지가 가장 많이 확인되었으며 대부분 한국 본토의 이른바 ‘송국리형 주거지’의 형태를 취하고 있다. 이 유적지에서 출토된 옥제품 등으로 보아 당시 삼양 동선사인들은 ‘삼국지’ 등의 기록처럼 중국, 일본 등과의 교역을 통해 축적된 부를 토대로 탐라국의 기틀을 다진 것으로 짐작된다. 삼양동 유적이 한국 본토나 일본의 야요이시대 주거지와 다른 특징적 요소는 집터 유구 자체가 완전한 정형성으로 작은 광장이 배치되어 있고 그 주위로 원형 움집 다수가 둥그렇게 들어서 있는 ‘단위주거군’의 정형성을 보이고 있다. 이러한 유적의 중요성 때문에 삼양동 마을 유적은 1999년 11월 16일에 국가사적지로 지정되었고, 지난 2004년 4월 전시관 2동, 선사 움집 14동 등이 복원 완료되어 문화관광자원으로 활용되고 있다.','제주특별자치도 제주시 선사로2길 13',NULL,33.5232668738,126.5877845121,NULL,'http://www.jeju.go.kr/samyang/index.htm','09:00~18:00','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','129619','ATTRACTION','협재동굴','협재동굴은 제주도의 대표적인 용암동굴이며 황금굴, 소천굴과 함께 제주도용암동굴지대를 이룬다. 용암동굴이자 석회동굴의 특징이 복합된 2차원적인 동굴이라는 점이 특이하며, 그 일대가 모래와 조개껍데기가 섞여 있는 패사층으로 되어 있다. 동굴 내부에는 천장에서 뻗어 나온 석종과 마치 바닥으로부터 솟구쳐 나온 듯이 보이는 석순 등이 신비로운 광경을 연출하며, 석종과 석순이 만나 하나의 기둥을 이루는 종유석이 기이하면서 아름답다. 동굴 벽면에는 석회분이 덮여있어 마치 하나의 거대한 벽화가 새겨져 있는 듯 웅장한 모습이다. 동굴 내부의 온도는 연중 내내 17~18℃를 유지하여 한여름의 이색적인 피서지가 되며, 한겨울에는 따뜻한 온도로 추위를 피할 수 있어 사계절 관광객에게 인기가 있다. 협재동굴은 천연기념물로 지정되어 있고, 페루의 돌소금동굴, 유고의 해중석회동굴과 더불에 세계 3대 불가사의 동굴로 꼽힐 만큼 유명한 곳이다.','제주특별자치도 제주시 한림읍 한림로 300','(한림읍)',33.3882575819,126.2381395546,NULL,'https://www.visitjeju.net/kr/','[3월~10월] 08:30~17:30[6월~8월] 09:00~18:00[11월~2월] 09:00~16:30※ 계절별 일몰시간에 따라 변동가능','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','129620','ATTRACTION','쌍용굴(한림공원)','쌍용굴(쌍룡굴)은 황금굴, 소천굴, 만장굴과 더불어 제주도의 대표적인 용암동굴이다. 동굴의 길이는 약 400m, 너비 6m, 높이는 3m 정도의 규모이며, 250만 년 전 한라산 일대의 화산이 폭발하면서 협재굴과 함께 생성되었다. 용암동굴이자 석회동굴의 특징이 복합된 2차원적인 동굴이라는 점이 특이하며, 그 일대가 모래와 조개껍질이 섞여 있는 패사층으로 되어 있다. 
쌍용굴은 좌우 양쪽으로 나뉘어 있으며 마치 용 두 마리가 굴 내부에 있다가 밖으로 빠져나간 듯한 모양을 하고 있다 해서 쌍용굴이라고 이름이 지어졌다. 쌍용굴의 제2입구와 협재굴의 끝부분이 인접해 있어 두 동굴은 원래 하나였다가 내부 함몰로 인해 나뉜 것으로 추정되고 있다. 협재굴과 마찬가지로 천연기념물로 지정되어 있다. 
동굴 내부에는 석회동굴의 특징인 석순과 종유석이 곳곳에 기둥처럼 즐비해 있어 신비한 광경을 연출한다. 동굴 벽면에는 석회분이 덮여있어 마치 하나의 거대한 벽화가 새겨져 있는 듯 웅장한 모습을 보인다. 동굴 내부의 온도는 연중 내내 17~18℃를 유지하여 한여름의 이색적인 피서지로 주목을 받고 있고, 한겨울에는 따뜻한 온도로 추위를 피할 수 있어 사계절 사람이 찾는 관광명소이다.','제주특별자치도 제주시 한림읍 한림로 300',NULL,33.3878715739,126.2418253313,NULL,'http://www.hallimpark.co.kr','[2월~5월]09:00~17:00[6월~8월]09:00~17:30[9월~10월]09:00~17:00[11월~1월]09:00~16:30※ 계절별 일몰시간에 따라 변동 가능','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','228853','ATTRACTION','용두암','제주공항 인근의 북쪽 바닷가에 있는 용두암은 오랜 세월에 걸쳐 파도와 바람에 씻겨 빚어진 모양이 용의 머리와 닮았다 하여 용두암이라 불린다. 전설에 의하면 용 한 마리가 한라산 신령의 옥구슬을 훔쳐 달아나자 화가 난 한라산 신령이 활을 쏘아 용을 바닷가에 떨어뜨려 몸은 바닷물에 잠기게 하고 머리는 하늘로 향하게 하여 그대로 굳게 했다고 전해진다. 또 다른 전설은 용이 되어 하늘로 올라가는 것이 소원이던 한 마리의 백마가 장수의 손에 잡힌 후, 그 자리에서 바위로 굳어졌다는 전설이 있다.용두암에서 도두항까지 이어지는 용담-도두 해안도로에는 다양한 카페와 맛집이 있어 눈과 입이 즐거운 드라이브도 즐길 수 있다. 제주의 명물로 떠오른 카페촌에서 차를 한잔하고 바닷길을 따라가다 보면 이호 해수욕장과 하귀해변, 애월읍으로 이어진다. 애월읍에서 용두암에 이르는 북제주의 해안도로는 제주 사람들이 가장 많이 찾는 데이트 코스이다.','제주특별자치도 제주시 용두암길 15 (용담이동)',NULL,33.5147526573,126.5124978463,NULL,'http://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','250412','ATTRACTION','용두암해수랜드','용두암해수랜드는 제주시 해안도로와 용두암 인근에 있는 사우나이다. 야자수로 조경을 둘러 남국의 정취가 물씬 풍기는 해수랜드는 넓은 규모의 사우나 종합시설과 정원 내 전통불한증막, 대형폭포, 이벤트 광장인 낙원의 쉼터, 주차장 등의 시설을 갖춘 대형 목욕 업장이다. 단순히 몸을 씻어내는 목욕이 아니라 휴식과 즐거움이 있는 여가공간을 만들어가고 있다. 각종 미네랄이 풍부한 청정 바닷물을 이용하는 해수사우나와 찜질방에서 피로를 풀 수 있고, 해수랜드에서 내려다보이는 바닷가 절경이 몸과 마음을 즐겁게 한다.','제주특별자치도 제주시 서해안로 630',NULL,33.5158275149,126.5045563152,NULL,NULL,'- 기본 05:00~22:00 - 건식사우나 05:00~22:00 - 게르마늄방 05:00~20:00','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','1146121','ATTRACTION','에코랜드테마파크','에코랜드테마파크는 1800년대 증기 기관차인 볼드윈 기종을 모델화하여 영국에서 수제품으로 제작된 링컨 기차를 타고 3만 평의 곶자왈 원시림을 체험하는 테마파크이다. 에코랜드테마파크가 위치한 곳은 교래 곶자왈로 지하수 함양은 물론, 보온, 보습 효과가 높아 북방한계 식물과 남방한계 식물이 공존하는 신비의 숲이다. 용암의 바위 위에 처절하고 치열한 생명의 힘으로 바위를 덮고 하늘을 막아 동식물의 낙원으로 만든 숲의 위대함을 느낄 수 있으며, 4.5㎞의 기차여행을 즐기는 동안 신비의 숲 곶자왈에서 서식하는 곤충과 동물 그리고 다양한 식물을 체험할 수 있어 자연이 우리에게 주는 무한한 혜택을 학습할 수 있는 공간이다.
에코랜드테마파크는 자연의 섭리를 어기지 않고 풀 한 포기도 소중히 여기며 인간과 자연을 하나로 이어주는 다리가 되고자 한다. 돌과 바위의 화산 땅에 뿌리를 길게게 바위틈으로 내리고 한줄기 빛을 찾기 위해 가지를 하늘로 뻗어 질긴 생명력을 이어가는 나무를 보며 자연의 위대함을 배웠다. 그 위대함을 표현하기에 아직 표현력이 부족하지만 자연과 인간의 공존이라는 대명제를 향하여 멈추지 않고 달려갈 것이다.','제주특별자치도 제주시 조천읍 번영로 1278-169',NULL,33.4553485145,126.6688527655,NULL,NULL,'- 파크 운영시간 08:30~19:30- 스카이파크 09:30~17:20- 백조보트 10:00~17:00- 풋티풋티 족욕카페 09:30~17:00','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','1329201','ATTRACTION','메이즈랜드','메이즈랜드는 최장을 자랑하는 석축미로를 보유한 제주의 종합테마파크로 제주의 명물인 돌, 바람, 여자를 뜻하는 삼다(三多)를 테마로 하여 조성됐다. 현무암과 송이석으로 만든 돌미로에서는 원적외선과 음이온을, 미측백나무로 만든 바람미로에서는 피톤치드를 누릴 수 있다. 미로퍼즐박물관에서는 체험을 통해 학생들이 과학적, 수리적 능력을 배양할 수 있으며 미로의 기원 설화와 14세기부터 현재까지의 미로와 관련된 유물을 관람할 수 있는 공간을 제공한다. 애지앙길과 야외에는 석공명장 장공익 선생의 제주 설화와 전설이 깃든 해학적인 석상들도 만날 수 있다.','제주특별자치도 제주시 구좌읍 비자림로 2134-47',NULL,33.4887187821,126.8006766329,NULL,'http://www.mazeland.co.kr','- 09:00~18:00- 매표 마감 17:00※ 계절별로 이용시간이 상이하므로 자세한 이용시간은 공식 홈페이지 참조','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','1621077','ATTRACTION','세화해수욕장','제주올레 20코스를 걷다 보면 세화민속오일장과 해녀박물관 사이에 작은 해변인 세화해수욕장을 만날 수 있다. 구좌읍 세화리에 위치한 이 해변은 정식 해수욕장도 아니고 규모도 크지 않지만, 맑고 파란 바다를 선물해 준다. 물이 빠지면 드러나는 하얀 모래와 검은 현무암이 에메랄드빛 바다와 아름다운 조화를 이루는 곳이다. 제주의 많은 해변 중에서도 작은 세화해수욕장이 널리 알려진 것은 벨롱장과 세화민속오일장 덕분이다. 동부지역에서 가장 규모가 큰 오일장이자 바닷가 바로 옆에서 열리는 이 오일장엔 매 5일마다 도민들의 삶을 엿볼 수 있는 풍경이 펼쳐진다.','제주특별자치도 제주시 구좌읍 세화길','(구좌읍)',33.525289,126.861237,NULL,'https://www.visitjeju.net/kr','상시 개방','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','1621118','ATTRACTION','제주해녀항일운동기념탑','제주해녀항일운동기념탑은 제주해녀항일운동의 흔적과 저항 정신을 기리고 있는 곳이다. 제주해녀항일운동은 1932년 1월 제주시 구좌읍과 성산읍, 우도면 일대에서 일제의 식민지 수탈 정책과 민족적 차별에 항거한 국내 최대 규모의 항일운동이다. 이 운동은 여성들이 주도한 유일한 여성항일운동으로 그 의의가 매우 크다고 할 수 있다. 제주해녀항일운동기념탑은 당시 항일운동에 참여했던 해녀들의 2차 집결지인 이곳에 해녀 항일 운동 정신을 기리고자 조성하였다. 선열들의 자주독립 정신을 바탕으로 후세들에게 올바른 역사의식과 애국, 애향정신 함양을 위한 교육장으로 활용되고 있다.','제주특별자치도 제주시 구좌읍 해녀박물관길 26',NULL,33.5224714401,126.863978306,NULL,'http://www.jeju.go.kr',NULL,NULL,90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','1672315','ATTRACTION','제주 노루생태관찰원','제주 노루생태관찰원은 2007년 8월 3일 개장하였다. 각종 동식물이 자연 그대로 보존된 52㏊의 공간에 오름에서 자유롭게 뛰노는 노루를 관찰할 수 있는 숲길 관찰로와 관람객이 가까이에서 직접 노루를 만져보고 먹이 주기 체험을 할 수 있는 상시관찰원이 조성되어 있다. 전시관에는 제주의 다양한 동식물과 한라산의 식생분포 등 제주의 자연에 대한 동물 이야기관과 노루의 특징, 역사 속에 나오는 노루의 기록 등 노루에 대한 지식을 제공하는 노루의 생태관, 노루의 생태와 생활상을 영상으로 보여주는 노루이야기 영상관이 있다. 천혜의 자연환경을 바탕으로 제주의 상징인 노루를 직접 관찰하고 휴식을 취하면서 노루에 대한 지식을 얻을 수 있는 노루생태관찰원은 자연학습과 생태체험을 동시에 즐길 수 있는 우리들의 공간이다. 거친 오름 중턱을 따라 조성된 숲길 관찰로는 온 가족이 쉽게 이용할 수 있는 트래킹 코스로 약 40분이 소요되며 탁 트인 전망과 함께 자연 속의 휴식공간을 제공한다. 노루생태관찰원에서는 노루먹이 주기 체험과 나무를 이용한 노루 만들기 체험 등을 진행하고 있다.','제주특별자치도 제주시 명림로 520',NULL,33.4444239001,126.6266077095,NULL,'https://www.visitjeju.net','09:00~18:00','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','1907801','ATTRACTION','제주4·3평화공원','제주 4·3 평화공원은 4·3 사건으로 인한 제주도 민간인 학살과 처절한 삶을 기억하고 추념하며, 화해와 상생의 미래를 열어가기 위한 평화 인권기념공원이다. 제주 4·3 평화공원 조성사업은 제주 4·3 사건에 대한 공동체적 보상의 하나로 이루어졌으며, 4·3 특별법 공포(2000), 공원부지 매입, 조성기본계획 연구 용역, 현상공모, 건축공사, 전시물 제작 및 설치 등이 이어져 2008년 3월 28일 개관하게 되었다. 
공원 안에는 제주 4·3 평화기념관, 위령제단, 위령탑, 봉안관 등이 이곳을 지키고 있다. 위령제단은 연중 4·3 희생자에 대해 참배를 진행하는 곳이며, 그들을 모시고 있는 위패봉안실이 따로 마련되어 있다. 봉안관은 4·3 유해발굴 사업 시기에 발굴된 유해를 봉안하는 장소로 현재 380기가 안치되어 있다. 각 명비원에는 희생자의 성명과 성별, 당시 연령 등을 기록해 두었다. 
제주 4·3 평화기념관에는 총 6개의 특별 전시관이 있다. 제1관에서는 주민들의 피신처로 활용되었다는 천연동굴을 주제로 한 역사관이 있으며, 제2관에서는 해방과 좌절이라는 주제로 해방 후 3·1절 기념행사에서 사망한 6명의 민간인의 이야기를 담아내고 있다. 제3관에서는 무장봉기와 분단 거부라는 주제로 1948년 4월 3일에 일어난 무장봉기에 대한 이야기가 있고, 제4관에서는 학살에 관한 내용을 다루고 있다. 마지막으로 5관과 6관에서는 진상 규명 운동으로 상처를 극복해 내는 과정과 관람 후의 소감문이 걸려 있다.','제주특별자치도 제주시 명림로 430',NULL,33.4498231292,126.6177472981,NULL,'https://jeju43peace.or.kr/','[야외 공원]- 상시개방[4·3 평화 기념관]- 09:00~18:00 - 입장 마감 17:00','[야외 공원]- 연중무휴[4·3 평화 기념관]- 매월 첫째, 셋째 월요일 (단, 공휴일(대체공휴일)인 경우 그 다음의 첫 번째 비공휴일)',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','1918639','ATTRACTION','월정리해변(월정리해수욕장)','제주도의 동쪽에 있는 마을인 월정리는 달이 머문다는 뜻의 이름을 가진 서정적인 풍경의 마을이다. 아름다운 에메랄드빛 바다가 한 폭의 그림처럼 펼쳐져 있고, 그 위에는 밝은 달이 비친다. 풍경화처럼 아름다운 월정리 해변을 방문한 여행객들은 저마다 다양한 방법으로 해변의 경치를 만끽한다. 특히 수심이 얕은 편이기 때문에 아이를 동반한 가족들이 물놀이를 즐기기 좋다. 월정리의 아름다운 풍광이 여행객들 사이에서 점점 유명해질수록 월정리의 해변을 방문하는 사람들이 더욱 늘어났고, 그에 맞춰 다양한 식당과 카페, 숙박시설 등이 많이 들어서 있다. 몇몇 카페는 사람들이 바다를 보며 쉬어갈 수 있도록 의자를 두었는데, 이 의자에 앉아 찍은 사진이 유명해지면서 하나의 포토 스폿이 되기도 했다. 월정리엔 카메라를 들고 제주도 여행의 추억을 담는 사람들의 모습을 쉽게 볼 수 있다. 그 밖에 서핑, 스노클링, 카약 등 다양한 수상 레포츠를 즐기며 보다 더 역동적으로 해변에서의 즐거움을 만끽하는 사람들도 있다. 월정리 해변은 일정한 높이의 파도가 지속해서 들어오기 때문에 서핑을 하기 좋아 서퍼들이 즐겨 찾는다. 제주도 올레길 20코스 [김녕-하도 올레]와 [김녕-월정 지질 트레일 코스]의 일부여서, 뚜벅이 여행객들이 걷다가 바다의 아름다운 풍경과 시원한 바다 내음을 맡으며 쉴 수 있는 아름다운 해변이다.','제주특별자치도 제주시 구좌읍 해맞이해안로 485',NULL,33.5550461413,126.7982299577,NULL,'http://www.visitjeju.net','[해변] - 상시 개방 [해수욕장] - 주간 개장 10:00~19:00 - 야간 개장 10:00~20:00','연중무휴※ 수영 개장 시기는 전화 문의 바람',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2027184','ATTRACTION','금룡사(제주)','제주 금룡사는 1930년 김연화 보살님에 의해 설립된 염불당이 그 창사의 시초가 되었다. 청춘고혼(靑春孤魂)이 된 동생 덕암(德庵)의 넋을 기리며 오십 년 남짓 지낸 세월에 염불당 및 요사체가 폐허 지경까지 왔을 때, 자재 현도(自在賢途) 스님을 만나 인연이 되어 1975년 대웅전 건립을 기점으로 사찰로 면모를 일신했다. 대웅전에는 석가모니를 주불로 모시고 관음대세지보살이 좌우에 협시하고 있다. 법당에는 총 7축의 탱화작품이 있는데 (후불탱화, 신중탱화, 칠성탱화, 독성탱화, 산신탱화, 지장탱화, 영단탱화), 이 작품은 석정 스님이 1979년에 완성하였다.

(출처 : 제주 문화관광 홈페이지)','제주특별자치도 제주시 구좌읍 김녕로 148-11',NULL,33.5539409808,126.7535878318,NULL,'https://www.visitjeju.net','상시 개방','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2479639','ATTRACTION','제주불빛정원','제주불빛정원은 2017년 개장한 이래 제주관광공사에서 선정한 제주야간관광 10선에 선정되는 등 아름다운 제주도의 밤을 가족과 친구들과 보낼 수 있는 야간 축제 관광지로써 발전해 왔다. LED조명과 아름다운 조형물을 기획하고 설치하는 기술을 토대로 아름다운 추억과 감성을 느낄 수 있도록 끊임없이 연구하고 있다. 제주도의 야간관광을 활성화하여 제주도를 방문하는 관광객들에게 더욱 알찬 관광의 기회를 제공하고 지역사회에 기여하고 있다.','제주특별자치도 제주시 애월읍 평화로 2346',NULL,33.4221,126.4093,NULL,'https://jejulightgarden.cafe24.com','17:00~24:00 (입장 마감 23:00)※ 악천후 시 조기폐장 가능','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2633955','ATTRACTION','서프라이즈 테마파크','서프라이즈테마파크는 문화예술계에서 주목하고 있는 재활용 소재를 활용한 장인정신의 숨결과 혼이 깃든 신비로운 정크아트 (Junk Art 폐품으로 만든 입체 예술작품)를 만나볼 수 있는 곳이다. 재활용 소재로 만들었으나 디테일과 크기는 그 어떤 작품 못지않은 정교함과 웅장함을 자랑한다. ‘SBS 세상에 이런 일이’에 방영된 깜짝 놀랄만한 세계 수준의 예술작품을 생동감 있게 구현한 영화 속 히어로들 그리고 애니메이션 주인공들과 함께 가까이에서 만날 수 있다. 다양한 크기와 형태로 작품화된 캐릭터를 통해 그들을 직접 만나고 체험해 봄으로써 흥미와 감동으로 아 동과 청소년들의 꿈을 키우고 용기와 진취적 기상을 심어줄 수 있는 계기가 될 것이다. 50,000여 평의 넓은 대지 위에 펼쳐진 500여 점의 작품과 주변 풍경의 파노라마는 전 지역이 포토존으 로 활용될 수 있어서 가족 단위의 나들이를 통해 추억의 시간을 간직할 수 있으며, 곶자왈둘레길 생태체 험 산책을 통해 삼림욕을 함으로써 웰빙을 구가할 수 있다. 또한 단체 학생들의 체험 활동을 통해 꿈과 끼를 키우는 감성 교육의 장으로 활용될 수 있다.','제주특별자치도 제주시 조천읍 남조로 2243',NULL,33.4651859042,126.6595930576,NULL,'http://surprisethemepark.com','09:00~18:00 (입장 마감 17:00)','연중무휴※ 우천, 강설, 태풍 등 기상 상황에 따라 운영시간 및 휴무일이 변경될 수 있음',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2674014','ATTRACTION','비체올린','자연 위에 조성했다는 의미의 ‘햇빛에 올려 놓은’ 이란 뜻인 비체올린은 제주시 서쪽 중산간에 위치한 가족 놀이공원이다. 카약 뿐만 아니라 전국 최초의 드리프트 전용 카트를 체험할 수 있는 ‘트라익 파크’ 뿐만 아니라 5월에서 7월 사이에는 능소화, 수국, 버베나로 대표되는 여름꽃&능소화 축제가 열리고 겨울에는 애기동백과 홍매화가 시선을 강탈한다. 소소한 재미가 있는 미로 공원 및 곶자왈 숲속 산책 등 여유로움과 액티비티를 동시에 즐길 수 있는 복합적인 테마공원이다.
비체올린의 또 다른 자랑인 공원은 1㎞에 이르는 넉넉한 능소화 정원을 자랑하며 초여름에는 능소화 축제와 함께 수국, 버베나 등 다양한 꽃들이 아름다운 풍경을 연출한다. 여름 꽃들이 제공하는 아름다움은 말로 표현하기 어려울 정도이다. 바다나 계곡이 아닌 제주의 자연에서 느낄 수 있는 힐링 체험은 동행자와 함께 정글을 걷다 강을 건넌 듯한 기분을 느낄 수 있으며 공원 산책은 더욱 특별한 경험을 선사한다. 항상 새로움을 추구하는 비체올린은 자주 변화를 주기 때문에 방문객들은 매년 이곳을 찾아 기대와 궁금증을 가지며 새로운 경험을 누릴 수 있다.

(출처 : 비짓제주)','제주특별자치도 제주시 한경면 판조로 253-6',NULL,33.3494256777,126.2182283881,NULL,'http://www.vicheollin.com/index.php','- 하절기 08:40~18:00- 동절기 08:40~17:30※ 운영시간은 현장상황에 따라 변경될 수 있음','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2704412','ATTRACTION','아침미소목장','제주공항 부근에 위치해 접근성이 뛰어난 아침미소목장은 지난 1978년 설립되어 많은 젖소들을 건강하게 길러내고 2008년 낙농체험목장으로 선정되어 친환경 목장으로 인정되었다. 무료로 입장이 가능해 부담 없이 방문하기 좋은 이곳은 한라산을 배경으로 펼쳐진 푸른 초원의 아름다운 풍경을 품으며 전통놀이와 자연 친화적 놀이터가 마련되어 있어 온 가족이 함께 즐길 수 있다. 맑고 푸른 자연속에서 송아지에게 우유를 직접 먹여주며 생명의 소중함을 배우고 동물의 체온을 직접 느낄 수 있는 기회가 될 것이다.','제주특별자치도 제주시 첨단동길 160-30',NULL,33.4532852107,126.5874206898,NULL,NULL,'10:00~17:00 (마지막 주문 16:30)','매주 화요일 / 설·추석 연휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2714222','ATTRACTION','스누피가든','스누피 가든 하우스는 감정에 솔직하고 개성 있는 피너츠 친구들을 만나 그들 간의 상호 관계를 통한 공감과 위로의 메시지를 얻는 곳이다. 가든 하우스의 테마홀은 피너츠 에피소드에 담긴 일상의 이야기와 ‘Peanuts, Nature & Life’를 주제로 나의 일상을 연결할 수 있는 공간이다. 5개의 테마홀과 카페 스누피, 피너츠 스토어에서 걷고, 보고, 먹고 쉬면서 피너츠 캐릭터를 통해 지금의 나에게 휴식과 위로의 메시지를 건네어보길 바란다. 매주 수요일은 반려동물데이로, 반려동물과 동반입장이 가능하다. 반려동물과 동반 시야 외 가든에선 목줄을 착용해야 하며, 실내(전시관, 카페, 스토어)에선 케이지/슬링백/반려동물 유모차 탑승이 필수이다.','제주특별자치도 제주시 구좌읍 금백조로 930',NULL,33.4433716489,126.7786050101,NULL,'https://www.instagram.com/snoopygardenkorea','09:00~18:00 (입장마감 : 종료 1시간 전)','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2723542','ATTRACTION','한담해변','한담해변은 제주 북서부에 위치하여 애월에서 곽지까지 해안을 따라 이어진다. 제주시가 2009년 숨은 비경 31로 선정했으며, 맑고 투명한 바다로 유명하다. 애월 앞바다의 장관을 편안하고 친숙하게 접할 수 있다. 해안의 모양을 따라 구불구불하게 이어지는 산책로는 1.2km에 이르며, 바다의 주변 경관과 현무암이 조화를 이루고 있다. 바다가 가까이 있어 제주의 바다를 제대로 느끼며 산책의 여유로움을 느낄 수 있다. 봄에는 유채꽃으로 채워진 산책로를 만날 수 있으며, 여름에는 초록빛이 가득한 산책로를 걸을 수 있다.','제주특별자치도 제주시 애월읍 애월로1길 26-4',NULL,33.4627528206,126.3100950683,NULL,'https://www.visitjeju.net','상시 개방','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2751986','ATTRACTION','포레스트 공룡사파리','생동감 있게 움직이는 공룡들과 스탬프 미션이 기다리고 있는 포레스트 공룡사파리는 제주 최대 사파리테마파크이다. 포토 존, 힐링 존, 체험 존, 페인팅 존, 실내 놀이시설 등 다양한 공간과 체험을 즐길 수 있으며, 어린이가 올라타도 되는 안전하고 편안한 동물 모형과 어른들이 쉴 수 있는 공간까지 가족 모두가 즐길 수 있는 테마파크이다. 공룡사파리 존은 마치 살아 숨 쉬는 듯한 공룡 친구들을 만날 수 있으며, 직접 동물을 만져보고 동물들에게 먹이도 주며 동물과 교감해 보는 동물 먹이 주기 체험 존과 어린이들만의 개성으로 동물을 페인팅해 보며 어린이의 창의성을 배가하는 페인팅 존, 비가 오나 눈이 오나 날씨와 상관없이 신나게 놀 수 있는 실내놀이터 존 등에서 어린이는 물론 어른들도 시간 가는 줄 모르는 흥미진진한 가족 여행지이다.','제주특별자치도 제주시 조천읍 선교로 474-1',NULL,33.4630619581,126.7095690192,NULL,NULL,'09:00~17:30 (입장 마감 16:00)','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2763739','ATTRACTION','제주 교래자연휴양림','우리나라 최초로 곶자왈 지대에 조성된 자연휴양림으로, 곶자왈 생태를 가까이 체험할 수 있다. 곶자왈은 숲을 뜻하는 곶과 암석 덩어리를 뜻하는 자왈이 합쳐진 제주어로, 화산이 분출한 용암 지형 위에 나무와 돌이 뒤섞여 이룬 제주만의 독특한 숲을 말한다. 함몰지와 돌출지가 불규칙하게 이어져 난대수종과 온대수종이 함께 자라며, 화산석을 휘감고 뿌리를 드러낸 나무와 노루굴, 숯가마터 등 옛 생활의 흔적도 만날 수 있다. 휴양림은 숲속의 초가와 야외공연장을 갖춘 휴양지구, 야영장과 야외무대, 풋살경기장이 있는 야영지구, 곶자왈 생태를 관찰할 수 있는 생태체험지구, 큰지그리오름까지 오르는 오름산책로가 있는 삼림욕지구 등 4개 구역으로 나뉘어 있다. 생태관찰로를 따라 곶자왈의 원시림을 천천히 걷거나 오름에 올라 제주 동부의 풍경을 바라보며 숲속 휴식을 즐기기 좋다.','제주특별자치도 제주시 조천읍 남조로 2023',NULL,33.4418,126.6667,NULL,'https://www.foresttrip.go.kr','- 09:00~18:00[생태관찰로 입장 마감]- 하절기(3월~10월) 17:00- 동절기(11월~2월) 16:00[오름관찰로 입장 마감]- 하절기(3월~10월) 16:00- 동절기(11월~2월) 15:00[숙박동·야영장 입장]- 숙박동 15:00~22:00- 야영장 13:00~20:00※ 입실시간 이후 체크인 불가','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2779454','ATTRACTION','종달리 수국길','제주도 북동쪽 구좌읍에 자리한 조용한 마을 종달리에는 종달리 수국 길이라는 테마 거리가 형성되어 있다. 종달리는 공항에서 제주 동부를 향해 달리면 비자림을 지나 지미봉 자락에서 만나게 되는 마을이다. 수국은 흙의 산도에 따라 색이 하늘색에서 분홍색까지 달라지는 신비로운 꽃이다. 보통 6월 중순에서 말, 늦으면 7월 말까지 종달리 바닷길을 따라 형형색색의 수국이 만개한 모습을 볼 수 있다. 수국은 흙의 산도에 따라 하늘색에서 분홍색까지 색이 달라진다. 다만, 이 테마 거리는 도로 한쪽으로 자전거도로 겸 인도가 마련되어 있지만, 차가 지나다니는 도로변이니 조심해야 한다.','제주특별자치도 제주시 구좌읍 종달리',NULL,33.5077,126.9111,NULL,'https://www.visitjeju.net/kr/','상시 개방','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2788436','ATTRACTION','탑동광장','탑동광장은 탑동해변공연장을 중심으로 길게 조성된 광장 산책로가 있으며 도민이나 관광객이 밤바다를 보며 산책을 하거나 행사가 진행되는 문화공간으로 조성 되어있다. 여름이면 시원한 바닷소리를 들으며 산책을 즐기는 사람들과 버스킹 등 작은 공연이 열리는 모습을 볼 수 있다.','제주특별자치도 제주시 중앙로 1',NULL,33.51807,126.526565,NULL,'https://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2798882','ATTRACTION','제주 우도 천진항 대합실','제주도의 동쪽 끝에 있는 우도는 물소가 머리를 내민 모양(우두형)으로 있는 것 같다고 해서 붙여진 이름이다. 서울 면적의 약 100분의 1이며, 인구가 1,800여 명 정도 되는 제주도의 섬이다. 우도에는 2개의 선착장 천진항과 하우목동항이 있는데 우도의 관문 항구이자 관광객들에게 많이 알려진 곳은 천진항이다. 우도 유채꽃 마을 정보 센터와 바로 붙어있는 우도 천진항 대합실은 크지 않은 규모로 매표소와 대기석 그리고 간단한 간식과 기념품을 구매할 수 있는 매점이 있다. 대합실 근처에는 우도 관광의 편의를 위해 전기자동차 대여소들이 즐비해 있다. 우도로 들어올 때는 자동차와 스쿠터를 가지고 들어올 수 있다. 자동차는 선적증 구입 후 출항 시간 10분 전까지 선원의 지시에 따라 반드시 면허증 소유자가 선적시켜야 한다.','제주특별자치도 제주시 우도면 우도해안길 70',NULL,33.4928040988,126.951540314,NULL,NULL,'07:30~18:00 ※ 30분 간격 운항 ※ 정원의 초과, 물때, 화물, 날씨에 따라 도착항이 변경 또는 조금 빨라지거나 지연될 가능성이 있음','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2930935','ATTRACTION','한담해안산책로','곽금올레길이라고도 부르는 한담해안산책로는 애월항에서 곽지과물해변까지 해안을 따라서 조성된 산책로이다. 주변 경관과 조화를 이루고 있어 아름답다. 총길이는 1.2㎞이며 바로 옆에 파도가 철썩이는 해안 길을 따라 걸을 수 있다. 2009년 제주시가 기존의 관광 명소 이외에 제주시 일대의 대표적인 장소 31곳을 선정해 발표한 ‘제주시의 숨은 비경’ 중 하나이기도 하다. 용암이 굳어지면서 만들어진 기암괴석이 시선을 끌고 검은 바위로 이루어진 해안을 따라 구불구불하게 이어지는 길은 산책길에 재미를 더해준다. 제주도의 서쪽에 있어 아름다운 일몰을 잘 감상할 수 있다는 점도 이곳의 매력 포인트다.

(출처 : 비짓제주)','제주특별자치도 제주시 애월읍 곽지리',NULL,33.4591976873,126.3105978795,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2863615','ATTRACTION','김녕 청굴물','청굴물이 위치한 동네 이름은 청수동인데, 청수동의 원래 지명은 청굴동이다.
청굴물은 용암대지 하부에서 지하수(용천수)가 솟아나는 곳이다. 용암대지의 하부에는 물이 잘 스며들지 않는 점토층이 분포하고 있어 지표에 내린 빗물이 지하로 스며들지 못하고 해안선 부근에서 솟아나게 된다. 김녕 해안에는 여러 곳의 용천수가 있지만 청굴물은 그중에서 차갑기로 소문이 나있다.','제주특별자치도 제주시 구좌읍 김녕리','1296',33.5583,126.7512,NULL,'https://www.visitjeju.net','상시 개방','연중무휴',90,0,'2026-11-09 16:07:51'),
('50110','KTO_TOURAPI','2946628','ATTRACTION','환상숲곶자왈공원','곶자왈은 제주도에 위치한 특정한 숲 지대를 일컫는 말로 용암이 분출되어 흐르며 남긴 현무암 사이로 식물이 함께 살면서 형성해 놓은 원시림이다. 용암이 형성해 놓은 공기통로와 요철형의 지형적 특성 때문에 같은 곶자왈 내에서도 다른 기후 환경이 형성되어 남방계 식물과 북방계 식물이 함께 관찰되는 독특한 생태계를 자랑한다. 흙이 아닌 용암 지형 위에 다양한 동식물이 자생하는 이곳은 제주만의 독특한 원시 생태를 잘 보여준다. 양치식물과 거대한 나무의 뿌리가 얽힌 풍경 안으로 들어서면 시간과 공간이 바뀌는 듯한 경험을 하게 된다. 환상숲 곶자왈공원은 1시간마다 숲 해설 투어가 진행되며 사전 예약이 필요하다. 그리고 이곳은 신비로운 분위기로 여러 뮤직비디오 촬영지로 활용된 곳으로 대표적으로 2015년도에 발매된 에프엑스 뮤직비디오 촬영지의 배경이 된 곳이다.','제주특별자치도 제주시 한경면 녹차분재로 594-1',NULL,33.322401864,126.262919972,NULL,'http://www.jejupark.co.kr/','월요일~토요일 09:00~17:00','매주 일요일',90,0,'2026-11-08 01:30:00'),
('50110','KTO_TOURAPI','126458','ATTRACTION','원당사지','제주시에 위치한 원당사지는 보물로 지정된 제주 불탑사 오층석탑이 남아 있는 절터이다. 고려시대에 탐라가 원나라의 지배 아래에 있을 때 원나라 사람들이 세운 절 중의 하나가 원당사였다. 원나라 기황후가 고려의 풍수가들까지 동원하여 명당자리에 절을 지어 불공을 드리기 위하여 세웠다는 전설이 있다. 원당사는 없어졌지만, 17세기 중엽까지 존속되었던 것으로 보이며 당시 경내에 있던 석탑은 그대로 남아 고려시대 사찰의 면모를 보여주고 있으며, 원당사지에는 불탑사가 자리하고 있다.','제주특별자치도 제주시 원당로16길 41','(삼양일동)',33.5290247083,126.5984611646,NULL,'https://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-11-06 17:36:57'),
('50110','KTO_TOURAPI','127863','ATTRACTION','추자도','제주도와 한반도 중간에 위치한 추자도는 제주도에서 45㎞, 해남에서는 35㎞ 떨어져있는 섬으로 1,600명 가량의 인구가 살고 있는 유인도이다. 추자도는 상추자도와 하추자도로 이루어져 있으며 인근에는 추포도, 횡간도까지 4개의 유인도와 38개의 무인도가 있다.
추자도에 마을이 처음 들어선 것은 고려 원종 12년(1271년)부터이며 옛날 뱃길로 제주와 육지를 오가다 바람이 심하면 바람을 피해가기 위해 기다리는 섬이라 하여 후풍도라 불리었다. 그 후 조선 태조 5년 이 섬에 추자나무 숲이 무성한 탓에 추자도로 불리게 되었다고 한다.
제주시에서 추자도는 배로 이동이 가능하고, 1시간 반 정도의 시간이 소요된다. 추자도는 예로부터 멸치 잡이로 유명하며 벵어돔, 돌돔, 참돔, 전갱이 등의 고급 어종이 많이 잡혀 바다 낚시에 대한 인기가 상당히 높다.
근래에 추자올레코스가 생긴 후부터는 낚시꾼 뿐만 아니라 일반 관광객도 많이 찾는 섬이 되었다. 이로 인하여 민박 등의 숙박 시설도 마을마다 운영하고 있으며 펜션도 운영된다.
낚시꾼들의 성지이자 올레꾼들의 필수 코스인 추자도는 사실 낚시와 올레길만으로 설명되지 않는 다채로운 매력을 가지고 있다. 추자군도부터 마을 전경, 바다와 몽돌해안까지 색다른 제주를 프레임에 담아보고 싶은 여행자에게 떠오르는 인생샷 성지 추자도에서의 포토존 투어를 추천한다.','제주특별자치도 제주시 추자면',NULL,33.9483,126.3198,NULL,'http://www.visitjeju.net/kr','상시 개방','연중무휴',90,0,'2026-11-06 17:28:53'),
('50110','KTO_TOURAPI','127202','ATTRACTION','어승생','정상에는 둘레 약 250m가량의 원형 화구호(火口湖)가 있으나 늘 물이 고여있지는 않다. 남서쪽에는 외도천 상류, 동쪽에는 도근천 상류를 끼고 있다. 오름 정상에는 일제시대 일본군이 설치했던 화포 시설 잔해가 남아 있으며, 남사면 중턱에는 샘이 있다. ‘어승생오름’ 북쪽 기슭에 한밝저수지가 있는데, 명마의 산지로 이름났던 어승생에서 발원하는 물이 계곡을 타서 이곳에 모인다. 현재는 중산간 지대의 수원인 어승생저수지로 사용되고 있다. 민간에서는 어스승이, 어스싱이라고 한다. 어승생(御乘生)은 한자의 뜻 그대로 임금이 타는 말(御乘馬)이 낳기 때문에 붙인 것이라면 음독자로 어승생의 표기라 할 수 있는데, 민간의 어스승이, 어스싱이 등을 고려하면 음가자의 결합 표기라 할 수 있다.

(출처 : 제주 문화관광 홈페이지)','제주특별자치도 제주시 해안동','산220-12 (일대)',33.3856288186,126.5067396323,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-11-06 17:27:16'),
('50110','KTO_TOURAPI','128444','ATTRACTION','낙천아홉굿마을','낙천리 아홉굿 마을은 올레길 13코스 중간지점에 위치해 있으며, 아홉굿은 제주도에서 보기 드문 9개의 샘이 있다는 뜻과 마을 방문객에게 아홉 가지 좋은(good) 것을 나눠주는 즐거운 마을이라는 의미를 가지고 있다. 땅이 기름져서 밭작물이 맛있기로 유명하며, 특히 보리가 맛있기로 유명하다. 천혜의 자연경관으로 북제주 10경을 볼 수 있는 아홉굿 마을은 100m 지하 암반수로 키워낸 보리, 토마토, 파프리카, 브로콜리 등 건강한 먹거리와 다양한 체험거리가 있는 전통 농촌문화마을이다.','제주특별자치도 제주시 한경면 낙수로 97',NULL,33.3278172101,126.2264114428,NULL,'http://ninegood.1945.co.kr/index.php','09:00~17:00','매주 토요일 / 일요일',90,0,'2026-11-06 17:14:01'),
('50110','KTO_TOURAPI','128443','ATTRACTION','교래 삼다수마을','교래 삼다수마을은 교래리 마을 전체를 새로운 관광지로 조성한다는 목표 아래 마을과 제주개발공사가 손잡고 탄생시킨 곳이다. 교래 삼다수마을은 교래리의 지역명과 제주 삼다수를 합친 명칭으로, 삼다수 생수 수원 발생지이기 때문에 삼다수마을로 불리고 있다. 동남쪽으로는 넓고 푸른 목장지대와 오름이 펼쳐져 있고 서남쪽으로는 울창한 숲과 계곡이 아름다운 풍경을 이룬다. 2018년 1월 지질공원 대표명소로 추가 지정·고시되었으며, 지질학적 가치가 높은 교래곶자왈, 교래리 퇴적층, 맨틀 포획암, 돌문화공원, 산굼부리 등이 위치해 있다. 생태적 측면에서 삼나무 숲길을 중심으로 희귀 식물인 붓순나무와 활 칠 나무 군락지가 있으며, 다양한 생물들이 공존하고 있다. 역사문화적 측면에서 본향당과 산마장, 잣성, 사냥터 등의 유적지가 분포하고 있다. 제주개발공사와 교래리 마을 간의 협력에 의해 지질공원 대표명소로 확대된 최초의 사례라는 측면에서 중요한 의미가 있다. 삼다수마을 숲길 시작점에는 제주 삼다수의 가치를 알리는 물홍보관이 있으며 방문 전 예약해야 관람할 수 있다. 또한 토종닭유통특구로, 이를 활용한 다양한 토속 음식점들이 자리 잡고 있어 여행의 다양한 재미를 충족시킬 수 있는 마을이다.','제주특별자치도 제주시 조천읍 교래3길 98',NULL,33.4315529966,126.6746336445,NULL,'https://www.visitjeju.net','상시 개방','연중무휴',90,0,'2026-11-06 17:08:23'),
('50110','KTO_TOURAPI','129073','ATTRACTION','구엄어촌체험마을','구엄어촌체험마을은 돌염전의 역사를 품고 있는 어촌마을로, 아름다운 해안절경을 자랑한다. 북쪽으로는 남해와 접해있고, 서쪽으로는 원내천이 흐르는 대부분의 지역이 평지로 이루어져 있다. 특히, 구엄포구는 거북이 껍질처럼 독특하게 생긴 자연 염전을 볼 수 있는 곳으로, 넓데 드러누운 현무암 위에 차흙으로 둑을 쌓고 그곳에 고인 바닷물이 햇볕에 마르면서 생기는 소금을 생산하던 곳이다. 약 390여 년 동안 품질이 뛰어난 천일염이 생산되다가 해방 이후 폐기되어 소금 생산을 하지 않고 있지만, 2009년에 제주시에서 돌염전 일부를 복원하였다.
이 돌염전을 ‘소금빌레’라고도 하는데, 빌레란 제주어로 ‘너럭바위’를 뜻한다고 한다. 구엄어촌체험마을에서는 선상낚시체험, 바릇잡이체험, 보말조배기 만들기 체험, 투명카약 등의 체험 프로그램을 운영하고 있다.','제주특별자치도 제주시 애월읍 애월해안로 715-1',NULL,33.4841803029,126.3773708009,NULL,NULL,'10:00~16:00',NULL,90,0,'2026-11-06 16:59:19'),
('50110','KTO_TOURAPI','129147','ATTRACTION','우도 등대','우도 등대는 제주 최초로 빛을 밝힌 등대로, 1906년 3월 처음 불을 밝혔다. 2003년 12월, 높이 16m의 원형 콘크리트 등대를 신축하였고, 국내 기술로 개발한 대형 회전식 등명기를 설치해 50㎞ 밖에서도 확인 가능한 불빛을 비추고 있다. 주변에는 우리나라 최초로 등대를 테마로 한 등대 공원을 조성하여 지역 경제 발전에 기여하고 있다. 등대 공원에서는 홍보 전시실 및 항로 표지 3D체험관과 세계 7대 불가사의 중 하나인 파로스 등대 등 국내외 유명한 등대 모형 14점을 전시하여 우도봉에 오른 관광객들에게 즐거움을 더해주고 있다. 또한, 우리나라 최초로 등대를 테마로 한 등대공원을 조성하여 해양관광상품을 개발하고, 지역경제 발전 기여를 위해 노력하고 있다.','제주특별자치도 제주시 우도면 우도봉길 105','(우도면) 부근',33.4932,126.9661,NULL,'https://www.visitjeju.net/','09:00~18:00','연중무휴',90,0,'2026-11-06 16:56:04'),
('50110','KTO_TOURAPI','129403','ATTRACTION','복신미륵','제주의 복신미륵은 한 쌍의 미륵으로 조선시대에 쌓은 제주성을 중심으로 동쪽에 있는 것은 동자복, 서쪽에 있는 것은 서자복이라고 한다.
동자복은 만수사 옛터인 민가 안에 자리하고 있으며, 마을의 평안과 여러 활동의 안전을 기원하는 석불로, 집안의 제액, 육아에 효험이 있다고 하여 제를 올렸으며, 제주성의 동쪽에서 성안을 수호하는 기능도 하였다.
서자복은 용화사 안에 자리하고 있으며 옛날 제주성의 서쪽에서 성 안을 수호하는 기능을 하였다 한다. 돌모자를 쓰고 있으며, 인자하게 내려다보는 눈, 우뚝한 코, 지그시 다문 입, 커다란 귀 등에서 자비로운 모습을 보여준다. 곁에는 남근을 상징하는 동자상이 서 있는데, 여기에 걸터앉아 치성을 드리면 아들을 낳는다고 믿고 있다. 매년 음력 2월 15일과 11월 15일이면 미륵을 위한 불공이 법당 안에서 행하여진다. 정확한 제작 시기는 알 수 없지만 고려시대로 추정하며, 고을을 수호하고 아들 낳기를 바라는 민간신앙과 불교의 결합을 보여주는 예이다.','제주특별자치도 제주시 동한두기길 7-6 (용담일동)',NULL,33.5155343282,126.5154302364,NULL,NULL,'용화사 08:00~20:00','연중무휴',90,0,'2026-11-06 16:38:51'),
('50110','KTO_TOURAPI','316058','ATTRACTION','보림사(제주)','보림사는 1957년에 창건되었으며 제주 사라봉 입구에 자리 잡고 있다. 절에는 대웅전, 법당, 천왕문, 보림사 부도, 보림사 탑 등이 있다. 특히 2002년 5월 15일 제주도 유형문화유산으로 지정된 목조관음보살좌상이 보림사 본존불로 봉안되어 있는데, 전라남도 순천 선암사에서 조선 후기에 제작된 불상으로 보림사 창건 당시 제주로 옮겨 온 것이다. 보림사는 제주 오름인 사라봉 초입에 있어서 불교 신자뿐만 아니라 제주도민과 관광객이 자주 찾는 곳이다. 보림사 사찰 주변에는 칠머리당영등굿 전수관, 모충사, 우당도서관, 국립제주박물관 등이 있어 제주도 여행길에 함께 둘러보는 것도 좋다.','제주특별자치도 제주시 사라봉동길 61',NULL,33.517477992,126.5462801727,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-11-06 16:21:04'),
('50110','KTO_TOURAPI','317558','ATTRACTION','불탑사(제주)','불탑사는 제주시 삼양동에 위치한 사찰로 대한불교조계종 제23교구 관음사의 말사이다. 불탑사는 원당봉 기슭에 자리하고 있다. 불탑사의 원찰인 원당사는 고려 말 제주도의 3대 사찰 중 하나였다. 1948년에 발생한 제주 4.3 사건 당시 사찰 대부분이 파손되었으며 1953년에 재건했다. 이후 여러 차례의 보수와 확장 작업을 거쳐 오늘에 이른다. 현재 경내에는 대웅전, 요사채, 종각, 천왕문 등이 있으며 특히 이곳에 보존된 오층석탑은 제주도 유일의 고려시대 석탑으로 1993년 11월 보물로 지정되었다.','제주특별자치도 제주시 원당로16길 41','(삼양일동)',33.5291274644,126.597861218,NULL,'https://www.visitjeju.net/kr/','상시 개방','연중무휴',90,0,'2026-11-06 16:19:03'),
('50110','KTO_TOURAPI','347234','ATTRACTION','월정사(제주)','월정사는 제주 최초의 불교 선원으로서, 제주 4·3사건 당시 제주도민과 함께 근대사의 아픔을 겪었던 사찰이자 대한불교 조계종 본사 관음사의 말사이다. 전하는 말에 따르면 월정사 자리는 1871년 무렵 토굴을 마련하고 수행하던 승려가 머물렀던 곳이라고 한다. 1938년 10월 1일 월정사에 조선불교 중앙선리참구원 제1지방 분원이 마련되어 제주 최초의 선원이 탄생했음을 알리는 기록이 남아 있다. 이 제주 선원은 1940년대까지 존속했으며 참여한 승려의 수는 10명 이내로 기록되어 있다. 1960년대 승려들의 노력으로 월정사 터에 난민 보건 주택을 짓고 법당으로 사용하면서 사찰의 명맥을 유지하였다. 1970년대 지문스님에 의해 대웅전과 요사가 신축되면서부터 월정사를 본격적으로 재건했다. 계속된 불사에 힘입어 2001년 10월 25일 전통 사찰로 지정되었으며 현재 월정사에는 2002년 12월 제주도 문화유산자료로 지정된 소조여래좌상과 목조보살입상이 보존되고 있다.','제주특별자치도 제주시 아연로 216-5','(오라이동)',33.4667305444,126.5100846989,NULL,NULL,'05:00~20:00','연중무휴',90,0,'2026-11-06 16:15:26'),
('50110','KTO_TOURAPI','482093','ATTRACTION','천왕사(제주)','아흔아홉 골의 수려한 풍광 속에 들어앉은 천왕사는 한라산 어승생 동쪽에 수많은 봉우리와 골짜기로 이루어진 아흔아홉 골 중 하나인 금봉곡 아래 위치한 사찰이다. 1955년 천왕사 근처 토굴에서 참선수행하던 비룡스님에 의해 수영산 선원이란 명칭으로 처음 창건되었다. 비록 건립된 지 오래되지 않았으나 1994년 전통 사찰로 지정되었다. 대웅전 바로 뒤로는 용바위라 불리는 커다란 바위가 있고, 마당 왼쪽 자락에 기세 좋게 곧게 뻗은 바위가 울창한 숲과 어우러져 절경을 이룬다. 사찰 옆의 냇물을 따라 올라가면 한라산의 유일한 폭포라는 선녀 폭포가 나오고, 사찰 입구에는 약수터가 있다. 특히 가을에 기암절벽 아래 물드는 단풍이 장관으로 알려져 있다.','제주특별자치도 제주시 1100로 2528-111 (노형동)',NULL,33.4082569714,126.4939865217,NULL,'https://www.visitjeju.net','상시 개방','연중무휴',90,0,'2026-11-06 16:12:46'),
('50110','KTO_TOURAPI','879633','ATTRACTION','물드리네','제주 한경면에 위치한 물드리네는 천연염색 체험장이다. 2010년 신라대학교 전통염색연구소 제주교육장으로 인증받은 우수한 염색교육장으로 알려져 있다. 500여 평의 규모에 전시실, 염색체험장이 있으며 근처에 염료식물을 재배하고 있다. 물드리네는 체험학습자의 연령별, 인지 정도에 따른 염색체험과 염색에 관심이 있는 사람들을 위한 천연염색교실을 운영하고 있다. 염색 재료는 제주풋감, 억새, 귤, 찻잎, 동배잎, 쪽, 홍화, 자근, 치자 등 제주지역의 나무와 풀 그리고 각종 한약재를 사용한다.','제주특별자치도 제주시 한경면 낙산로 4-28',NULL,33.3227122567,126.2269337305,NULL,'http://cafe.naver.com/mulfamily','10:10~17:00 (휴게시간 12:00~13:30)','매주 일요일',90,0,'2026-11-06 16:07:58'),
('50110','KTO_TOURAPI','1069292','ATTRACTION','별도봉','별도봉은 화북악이라고 부르는 곳으로 제주항과 제주 앞바다가 한눈에 내려다보이는 오름이다. 별도봉은 화산 쇄설성(碎屑性) 퇴적암과 용암으로 이루어진 기생화산으로 화북일동의 동쪽 해안에 자리하고 있다. 정상봉에서 북측 사면의 등성이가 바다 쪽으로 뻗은 벼랑이 있다. 벼랑 밑 해안단에는 고래굴과 아기 업은 돌이라 불리는 기암이 있다. 낮은 산이지만 해안 절벽을 끼고 조성된 장수산책로가 있으며 연인과 가족들이 많이 찾는다. 주변에 국립제주박물관, 민속자연사박물관 등 제주의 역사와 문화를 소개한 박물관들이 있으며, 삼양해수욕장, 용담포구 등 제주의 푸른 바다를 즐길 수 있는 관광지들이 있어 연계관광으로도 좋다.','제주특별자치도 제주시 선반로 화북일동',NULL,33.5192,126.5531,NULL,'http://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-11-06 15:47:07'),
('50110','KTO_TOURAPI','1621032','ATTRACTION','평화통일 불사리탑','평화통일 불사리탑은 반구형으로 건립한 불교사원으로 1998년 8월 15일 완공되었다. 조선시대의 억불정책에 맞서 불교중흥을 위해 헌신하다가 제주도로 유배된 허응당 보우대사와 환성 지안대사의 전법 정신을 이어 조국 통일과 세계평화를 염원하며 세운 사찰이다.
탑은 민족의 영산 백두의 천지에 정방향으로 맞추어 건축했고 한라산과 백두산이 불사리탑을 축으로 서로 일직선상에 놓이도록 했다. 불사리탑의 높이는 33M로 이것은 불교에서 말하는 천상세계 삼십삼천을 상징하는데 1층은 둥근 우주의 완전한 평화와 행복, 2층은 깨달음과 열반으로 이끄는 올바른 여덟 가지 길, 3층은 108번뇌를 상징한다.','제주특별자치도 제주시 조천읍 일주동로 884',NULL,33.5319333116,126.636229807,NULL,'http://www.visitjeju.net',NULL,NULL,90,0,'2026-11-06 15:44:51'),
('50110','KTO_TOURAPI','1884191','ATTRACTION','가마오름','제주시 한경면 수룽이마을 뒷산으로 마을 남동쪽 약 500m 지점에 있는 오름이다. 수룡동 마을안길로 들어가면 쉽게 오를 수 있다. 오름산모양이 가마솥을 엎어 놓은 모양과 같이 생겼다 하여 가마오름이라 부르고 있으나, 학자들의 어원적 해석에 의하면 가마는 감에서 나온 것이고, 감은 북방어로 신 또는 신성하고 거룩하다는 뜻으로 해석하고 있다. 즉, 가마오름은 신령스러운 산이라는 뜻으로 풀이하고 있다. 주봉인 남쪽 봉우리를 중심으로 북쪽으로 뻗은 등성마루에는 언덕 같은 봉우리가 솟아 있고, 완만한 동사면은 북동쪽으로 말굽형 화구를 이루며 얕고 넓게 벌어져 있으며 붉은 송이로 이루어져 있다. 해송과 잡목이 어우러져 숲을 이루고 있으며, 풀밭에는 술패렝이꽃이 여기저기 보인다. 이 오름에는 일제 강점기 때 일본군이 주둔했던 곳으로, 지금도 인공적으로 파인 수직굴이 여러 개 산재해 있다.','제주특별자치도 제주시 한경면 청수리','1205',33.3057,126.2466,NULL,'http://www.visitjeju.net/','※ 일부 출입이 제한되거나 통제되므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-11-06 15:42:09'),
('50110','KTO_TOURAPI','1884521','ATTRACTION','가새기오름','가새기오름은 오라동 연미마을 북서쪽에 가로누운 자그마한 화구 없는 원추형 화산체로서, 남북으로 긴 등성이에 해송이 우거져 숲을 이루고 있다. 풍수설에 의하면 이 오름 남쪽에 있는 민오름이 개의 형국이고, 그 밑에 있는 이 오름은 어미개에 딸린 강아지의 형국이라는 것에서 [개새끼오름]이라 불리고 있다. 어미개와 강아지가 어울린 모습에 개의 젖가슴을 상징하는 지세라 하여 북서쪽 오름 자락은 예로부터 길지로 꼽혀왔다고 한다.','제주특별자치도 제주시 오라삼동','2848',33.48934,126.50385,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-11-06 15:36:48'),
('50110','KTO_TOURAPI','1889809','ATTRACTION','개오리오름','개오리오름은 제주시 조랑말 목장 동쪽의 방송중계탑이 설치되어 있는 오름이다. 크고 작은 세 개의 봉우리로 이루어진 다양한 형태를 갖고 있는 복합형 화산체이며, 개오리오름은 주봉인 송신탑이 서 있는 곳의 오름을 말한다. 족은개오리는 북쪽에 서향으로 벌어진 말굽형 화구를 갖는 것이고, 가운데에 샛개오리라 부르는 원추형의 작은 오름이 있다. 전체적으로 두 개의 말굽형 화구를 갖는 복합형이다. 전사면이 낙엽수, 상록수 등이 울창하게 우거진 자연림을 이루고, 일부에 삼나무, 소나무가 있다. 겨울 한동안은 잎이 다 떨어진 회갈색 사면에 층층으로 늘어선 삼나무 대열이 이채롭다. 산 모양이 개오리(가오리)처럼 생겼다는 이름으로 가오리오름, 개워리오름, 개월오름으로 불리기도 한다.','제주특별자치도 제주시 봉개동',NULL,33.4262,126.6125,NULL,'https://www.visitjeju.net/','※ 일부 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-11-06 15:18:55'),
('50110','KTO_TOURAPI','1890872','ATTRACTION','뒤굽은이오름','뒤꾸부니오름, 후곡악(後曲岳) 등 여러 별칭이 있는 뒤굽은이오름은 뒷부분이 구부러진 오름이라는 데에서 유래했다. 남쪽으로는 구부러지고 북쪽으로 벌어진 굼부리를 가지고 있다. 제주 오름의 중심지인 송당마을에서 도보로도 접근이 쉽다. 북쪽으로 입구가 벌어진 말굽형 분화구가 있으며 넓은 분화구가 전체적으로 침식된 상태이다. 오름 대부분이 풀밭으로 덮여 있으며 북서쪽 일부 비탈면에만 인공적으로 심은 삼나무, 편백, 해송 등이 우거져 있다. 오름의 입구에서 정상까지는 약 10분이 걸리나 오르는 길에 따라 가파른 곳도 존재한다. 이정표가 존재하지 않으므로 오름의 전체적인 형태를 한눈에 바라보며 정상을 찾아 길을 올라야 한다. 정상에서는 제주 동부권의 랜드마크인 다랑쉬오름, 돝오름, 용눈이오름 등을 조망할 수 있다.','제주특별자치도 제주시 구좌읍 송당리 산38',NULL,33.4792,126.7671,NULL,NULL,'상시 개방※ 일부 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-11-06 15:14:19'),
('50110','KTO_TOURAPI','1895633','ATTRACTION','비양봉','비양봉은 한림읍 협재리 앞바다 비양도에 있는 기생화산이다. 비양도는 제주의 화산체 중 가장 나중에 생긴 막내 섬으로, 작은 섬이고 3시간 정도면 충분히 둘러볼 수 있는 규모다. 서기 1002년 6월에 산이 바다 한가운데에서 솟아 나왔는데, 산꼭대기에서 네 개의 구멍이 뚫리고 붉은 물이 닷새 만에 그쳐 그 물이 엉겨 모두 돌이 되었다고 기록한 것으로 보아, 이 시기 비양봉에서 어떤 화산활동이 있었던 것으로 추정한다. 섬 중앙에는 대형 분화구와 소형 분화구가 있으며, 대형 분화구 사면에 낮고 작은 2개의 분화구가 딸려 있다. 오름 주변 해안에서는 대형의 굴뚝형 분기공인 애기 업은 돌과 초대형 화산탄 모양의 베개용암 등의 수중용암들을 볼 수 있다. 보통 비양봉으로 통하나 주민들 사이에서 암메라고 불리기도 한다. 비양봉 정상을 향해 계단을 오르다 보면 비양봉 전망대가 나오며, 이곳에서는 제주의 푸른 바다와 시내를 한눈에 볼 수 있다. 또, 등대에서 보는 제주의 노을은 장관을 연출하며 사진 명소로도 유명하다.','제주특별자치도 제주시 한림읍 협재리',NULL,33.408546,126.227103,NULL,'http://www.visitjeju.net/','08:30~17:30','연중무휴 ※전화문의바람',90,0,'2026-11-06 15:12:20'),
('50110','KTO_TOURAPI','1895611','ATTRACTION','천아오름','어승생악 서쪽 지점 신엄공동목장 안에 위치한 오름으로, 남쪽 봉우리를 중심으로 북서쪽으로 패어있는 소규모 말굽형 화구를 이루고 있다. 천아오름이라는 이름은 옛 지도에 이곳이 참나무봉우리로 표기된 것에서 따왔다. 해송이 주종을 이루며 잡목이 우거지고 꽝꽝나무가 많다. 천아오름 동녘 자락에 속칭 무수내(무수천 상류)가 있고, 이 냇가에는 어승생저수지의 보조수원인 천아수원이 개발되어 있다. 제주시와 애월읍의 경계를 이루며 계곡 양안에서 우거진 온대림은 참꽃나무와 낙엽활엽수의 단풍 등이 있어 경치가 수려하다. 오름은 경사가 완만하여 굳이 오르지 않더라도 평탄하고 주변의 어승생악, 붉은오름 등을 관찰할 수 있다. 천아오름은 사유지이며 탐방로가 정비가 되어있지 않아 천아계곡까지만 탐방하는 것을 추천한다.','제주특별자치도 제주시 애월읍 산록서로 678-207',NULL,33.3956228393,126.4448101909,NULL,'http://www.visitjeju.net/','※ 일부 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-11-06 15:06:46'),
('50110','KTO_TOURAPI','1899959','ATTRACTION','도리미오름','도리미오름은 비치미오름과 자락을 맞대어 이어진 오름이다. 말굽형 화구로 완만한 등성이로 이루어진 대형의 원형 분화구였으나 이차적인 용암 유출에 의해 화구가 동북 방향으로 터진 형태를 하고 있다. 화구 안에는 북측으로 치우쳐 미끄러짐에 의해 만들어진 원추형의 알오름이 낮게 솟아 있으며, 문헌상에는 민오름 알오름으로 표기되어 있으나 이는 민오름과는 관계가 없다고 한다. 오름의 정상에는 용암 유출의 흔적으로 생긴 커다란 용암바위들이 박혀 있으며, 그 외의 지역은 풀밭오름이고 화구 내에는 인공 초지가 조성되어 있다. 오름 능선은 완만하고 오르는데 힘들지 않아서 주변의 오름들을 조망하며 오르기 좋다. 정상에 오르면 한라산과 교래리 오름군을 볼 수 있다.','제주특별자치도 제주시 구좌읍 송당리','산 255-1',33.4287,126.7665,NULL,'http://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-11-06 15:05:21'),
('50110','KTO_TOURAPI','1906211','ATTRACTION','두맹이골목','두맹이골목은 제주시 일도2동에 위치한 벽화마을이다. 이 골목 일대는 제주시에서도 가장 낙후되었던 곳 중 하나로, 2008년부터 이 골목을 대상으로 한 문화거리조성 프로젝트가 시작되었다. 첫해에는 한국민족예술인총연합 제주도지회가 공공미술공모사업을 진행해 당선된 작품을 골목에 벽화로 채워 넣기 시작했다. 이후에는 제주 지역 대학생들과 인근 초등학교 학생들이 참여하여 더 많은 벽화를 그렸다. 두맹이골목은 2009년 7월 제주시가 선정한 제주시 숨은 비경 31중 하나로 선정되었으며 다양한 벽화를 감상하면서 조용한 제주 마을을 거닐 수 있다.','제주특별자치도 제주시 동문로16길 17-4 (일도이동)',NULL,33.512015738,126.5349117257,NULL,'https://www.visitjeju.net/kr',NULL,'연중무휴',90,0,'2026-11-06 15:03:23'),
('50110','KTO_TOURAPI','1918646','ATTRACTION','거슨새미오름','거슨세미오름은 제주시 구좌읍 대천동 사거리에서 송당을 잇는 비자림로에 위치해 있다. 이 오름 서남쪽 굼부리(분화구)에는 한라산쪽으로 거슬러 흐르는 샘이 있어 거슨새미 라고 부른다. 서쪽으로 벌어진 말굽형 오름으로 북쪽에는 안돌오름과 밧돌오름이 있고 남쪽에는 칡오름, 민오름이 있다. 오름 입구에서 왼쪽으로는 샘을 거쳐 정상으로 가는 길, 오른쪽으로는 비자나무 산림욕장, 삼나무와 편백나무 숲길이 이어지는 둘레길과 연결되어 있다. 둘레길은 어린아이와 노약자들도 충분히 탐방이 가능할 만큼 평탄한 구간으로 산책과 함께 산림욕을 즐길 수 있다. 이 곳의 비자나무는 송당리민들이 직접 조림한 것으로 비자나무 열매를 채취하고 판매하여 주민소득 창출의 기회가 되고, 이곳을 찾는 여행자들에겐 멋진 산림욕장을 제공하고 있다.','제주특별자치도 제주시 구좌읍 송당리','산145',33.4521,126.761,NULL,'http://www.visitjeju.net/','※ 일부 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-11-06 15:00:05'),
('50110','KTO_TOURAPI','1918950','ATTRACTION','괴오름','괴오름은 제주시 애월읍 봉성리에 위치한 오름이다. 북돌아진오름과 이웃한 오름으로 고양이 등처럼 구부러진 모양을 하고 있어서 괴오름이라 부르고 있으며, 북쪽으로 벌어진 말굽형 화구의 굼부리 형태이다. 주요 식생은 잡목으로, 자연림이 울창한 숲을 이루면서 숲그늘 아래에는 새우난, 복수초, 천남성 등이 자생하고, 오름 주변 목장에는 갯취가 분포하고 있다. 지형이 마치 고양이 모양으로 생겼다는 데서 괴오름 또는 괴미라고 불리었으며, 괴(고양이)는 돝(돼지) 따위와 같이 우리나라 옛말이 제주방언으로 남아있는 예이기도 하다.','제주특별자치도 제주시 애월읍 봉성리 산41',NULL,33.3575,126.3731,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-11-06 14:55:52'),
('50110','KTO_TOURAPI','1925366','ATTRACTION','열안지오름(오라동)','열안지오름은 제주과학고등학교 서쪽 편에 위치하고 있는 표고 583m인 오라동을 대표하는 오름이다. 오름 전체가 해송과 편백나무 등이 울창한 숲으로 이루고 있고, 남동쪽에는 ‘열안지 물’이라는 샘물이 있다. 열안지의 지명은 ‘산 모양이 기러기가 줄을 지어 날아가는 형상’에서 유래했다. 제주 4·3 당시 열안지 오름 일대의 숲과 계곡은 오라리 주민들의 피신처이기도 했으며, 많은 주민들이 토벌대에 의해 희생된 눈물의 대지이기도 하다.

(표고는 583.2m, 비고는 113m, 둘레는 2,545m이며, 면적은 368,262㎡, 저경이 902m이다.)','제주특별자치도 제주시 오라이동 산92',NULL,33.4265659455,126.5207040706,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-11-06 14:52:13'),
('50110','KTO_TOURAPI','636266','ATTRACTION','거문오름','거문오름은 화구 중심으로부터 유출된 용암류의 침식계곡은 유선형의 골짜기를 이루며 약 4㎞ 정도 연속되어 나타난다. 오름 동남쪽의 목장지에는 화구 없는 화산체인 용암암설류의 원뿔꼴 언덕들이 집중 분포 구좌읍 송당리에 있는 거미오름을 일명 동검은오름이라고 하는데, 이는 이오름(서검은오름)과 구별하기 위한 호칭이라고 한다. 지역주민들 사이에는 분화구의 별칭으로 거물창(거멀창) 이라고 불리기도 하고, 숲으로 덮여 검게 보인다 하여 검은오름이라 부르고 있으나, 학자들의 어원적 해석으로는 검은은 神이란 뜻의 고조선 시대의 [감·검]에 뿌리를 두는 것으로 풀이하고 있다. 즉 검은오름은 신령스런 산이라는 뜻이다. 해송, 삼나무, 측백나무가 조림되어 있고, 울창한 숲을 이룬다.','제주특별자치도 제주시 조천읍 선교로 569-36',NULL,33.4547,126.7179,NULL,'https://www.jeju.go.kr/wnhcenter','09:00~14:00(30분 간격 출발)※ 1일 11회 탐방 가능하며 자세한 탐방 시간은 공식 홈페이지 참조','매주 화요일 / 설·추석 연휴※ 기상 악화 시 전면통제',90,0,'2026-11-05 14:40:53'),
('50110','KTO_TOURAPI','2836910','ATTRACTION','송당무끈모루','송당무끈모루는 송당리 비자림로에 있다. 모루는 산마루 할 때 마루 즉 작은 언덕을 뜻하지만, 지금은 특별히 경사나 구릉을 느낄 수 없다. 이 장소에 안도르 카페가 생기며 사진 스폿으로 알려지기 시작했다. 나무 사이로 넓은 초록 들판이 보이고, 멀리 삼나무숲과 오름을 배경으로 사진을 찍으면 분위기 있는 장면을 연출할 수 있다. 시외버스를 타면 바로 앞까지 갈 수 있어 뚜벅이 여행자들도 접근이 쉬우며 사진 스폿에는 주말에 줄 서는 사람이 많다. 근처 비밀의 숲으로 유명해진 안돌오름과 묶어 사진을 찍으러 오는 여행자가 많다. 근처 함께 방문하기 좋은 여행지로 아부오름, 비자림, 안돌오름 등이 있다.','제주특별자치도 제주시 비자림로 1661-13',NULL,33.4567748088,126.7718717118,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-11-05 14:36:34'),
('50110','KTO_TOURAPI','2704407','ATTRACTION','명월성지','제주시에 위치한 명월성지는 동쪽과 남쪽 및 서쪽에 각각 성문이 있었다. 성안에는 수량이 풍부한 샘이 있었고, 건물로는 객사, 별창, 군기고 등이 있었으나 지금은 하나도 남아 있지 않다. 명월포는 1270년에 삼별초의 별장 이문경이 고려에서 파견된 관군을 진압하고 탐라를 점령할 때 상륙한 곳이며, 김방경이 삼별초를 정벌할 때에도 그 일진이 이곳으로 상륙하였다. 더욱이 1374년 목장을 관리하기 위해 몽고에서 파견된 몽고인 목자들이 반란을 일으켰을 때, 이를 진압하기 위하여 최영 장군이 상륙한 곳도 명월포였다. 예전의 모습은 없지만 현재 복원한 남문 위의 망루에 올라가면 한림읍이 한눈에 보인다.','제주특별자치도 제주시 한림읍 명월리 2236',NULL,33.4007537003,126.2603927584,NULL,'https://visitjeju.net/kr/','상시 개방','연중무휴',90,0,'2026-11-05 14:21:48'),
('50110','KTO_TOURAPI','2791501','ATTRACTION','애월해안도로','제주 공항에서 불과 10㎞ 정도 달리다 보면 아름답기로 소문난 애월해안도로를 만날 수 있다. 북서부의 해안선을 따라서 이어진 애월해안도로는 빼어난 제주의 바다 풍경을 감상할 수 있는 약 9km의 드라이브 코스이다. 자전거 전용도로와 도보길도 잘 갖추어져 있어 드라이브 외에도 사이클링과 산책 등의 방법으로 다양하게 즐길 수 있다
이 도로는 제주 올레길 16코스의 일부이며, 자전거 라이딩과 트레킹의 명소로도 유명하다. 가는 길목마다 구엄포구, 남도리쉼터, 신엄리 방파제, 고내포구, 다락 쉼터, 큰 바위 얼굴 등 해안 명소들이 많아 중간중간 내려 아름다운 풍경을 감상하는 것도 좋다. 또한 다양한 맛집들과 카페, 숙박시설 등이 많이 있어 여행객들의 제주 여행 코스로서도 인기가 많다.','제주특별자치도 제주시 애월읍 구엄리',NULL,33.4825,126.3754,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-11-05 13:56:06'),
('50110','KTO_TOURAPI','2742267','ATTRACTION','용수항','용수항은 한경면 용수리에 위치한 소규모 어항으로, 용수리포구 또는 용수포구로 불리기도 한다. 용수항의 옛 이름은 쇠머리 코지 자락에 있는 포구라 하여 ‘우두포’라고 했다. 용수항 앞바다에서는 제주도에서 가장 큰 무인도인 차귀도의 푸른 실루엣이 보인다. 포구의 양쪽으로는 마을을 지켜주는 방사탑이 우뚝 서 있는데, 해의 부리 모양과 닮았다고 하여 매주제가라고 불리는 탑이다. 한국 최초의 신부인 김대건 천주교 신부가 중국 상하이에서 사제 서품을 받은 뒤 귀국하다 풍랑을 만나 표류한 곳이 바로 용수항이다. 이후로 천주교 제주교구는 이곳을 성지로 선포하고, 2006년 포구 앞에 김대건 신부 표착기념관을 세웠으며, 2008년에는 기념관 옆으로 기념 성당을 조성하였다. 인근 관광 명소로는 절부암, 차귀도, 협재해수욕장 등이 있다.','제주특별자치도 제주시 한경면 용수리',NULL,33.3233,126.1664,NULL,'https://www.visitjeju.net/kr/','상시 개방','연중무휴',90,0,'2026-11-05 13:53:06'),
('50110','KTO_TOURAPI','2792565','ATTRACTION','이호테우 말 등대','이호테우 말 등대는 제주도 도심과 제일 가까운 이호테우해변에 자리 잡은 등대로 제주의 조랑말을 형상화하여 만든 등대이다. 높이 12m의 빨간 말 등대와 하얀 말 등대가 각각 안쪽 방파제와 바깥 방파제에 한 마리씩 자리 잡고 있다. 등대의 색이 흰색과 빨간색으로 칠해진 이유는 배들이 흰색, 빨간색 등대를 보고 배가 나아가는 방향을 결정하기 때문이라고 한다.
이 등대는 제주도의 푸른 바다와 파란 하늘 배경과 잘 어울려 많은 사람들이 제주의 풍경과 추억 사진을 찍기 좋은 곳으로 즐겨 찾고 있다. 또한 도두동무지개해안도로와 함께 인기가 높은 여행지로 제주 공항과도 가까워 비행기를 타기 전에 잠시 들러 보는 것도 좋다.','제주특별자치도 제주시 서해안로 58 (이호일동)',NULL,33.501884,126.452066,NULL,'https://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-11-05 13:47:58'),
('50110','KTO_TOURAPI','2791523','ATTRACTION','제주양떼목장','제주 애월읍에 있는 제주 양떼목장은 양뿐만 아니라 염소, 말, 돼지 등 다양한 동물들을 만날 수 있는 자연 친화적인 공간이다. 동물에게 먹이를 줄 수 있는 목장 체험은 물론이고, 신선한 산양유 커피를 맛볼 수 있는 목장 카페, 통나무 펜션까지 운영해 다른 체험 목장보다 풍성한 추억을 만들 수 있다. 다양한 프로그램이 있는 체험 목장에서 숙박까지 하는 이색 체험이 마련되어 있어 관광객에게 인기가 많은 관광지이다.','제주특별자치도 제주시 애월읍 도치돌길 289-13',NULL,33.411238,126.365306,NULL,'http://www.sheepinjeju.com','- 10:00~18:00- 입장 마감 17:30','매주 월요일',90,0,'2026-11-05 13:45:29'),
('50110','KTO_TOURAPI','1206420','ATTRACTION','제주힐링명상테마파크','제주힐링명상테마파크는 명상 분야의 자격을 갖추고 오랜 기간 전문성을 키워온 운영 인력과 함께 체계적이고 전문화된 힐링 및 체험 프로그램을 보유한 테마파크이다. 한국 고유의 호흡법과 명상, 기문화 전파를 통해 행복한 삶을 추구하는 공간이 되고 있으며 2021년 제주 웰니스 관광지로 선정됐다. 자연이 선물한 드넓은 들판이 있고 한림해변과 비양도를 품은 바다가 한눈에 내려다보이는 곳에 위치한 교육 및 연수용 강의장, 아름답게 꾸민 일지기(氣)가든, 역사문화공원, 자연쉼터에서 가볍게 산책을 즐기기 좋다. 또 다른 시설 국궁장에서는 국궁지도사의 전문지도를 통하여 전통 활 쏘기의 프로그램을 경험할 수 있다.','제주특별자치도 제주시 애월읍 어음13길 196',NULL,33.3955670091,126.36105573,NULL,'http://www.jejuspirit.com','- 09:00~18:00- 입장 마감 17:00','연중무',90,0,'2026-11-05 13:39:12'),
('50110','KTO_TOURAPI','2847703','ATTRACTION','샤이니숲길','샤이니숲길은 삼다수 목장 인근에 위치한 작은 숲길이다. 삼다수목장 입구를 지나 좌측 도로가를 살펴보면 약 200m 길이의 숨겨진 숲길을 찾아볼 수 있다. 나뭇가지 사이로 햇빛이 들어오는 숲길이라 ‘sunshine’에서 붙은 이름이다. 길 양편으로 곧게 뻗은 편백나무와 함께 어우러진 낮은 돌담으로 산책하며 사진을 남기기 좋다. 포토스팟으로 입소문이 나면서 웨딩촬영과 스냅사진 촬영 등으로 많은 사람들이 찾는 곳이다.','제주특별자치도 제주시 조천읍 교래리','719-10',33.4272792375,126.6617076193,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-11-05 13:22:58'),
('50110','KTO_TOURAPI','2759036','ATTRACTION','도시해녀','도시해녀는 제주 바다에서 직접 해녀를 체험할 수 있는 곳이다. 물이 무섭거나 수영을 못하는 사람도 물에 뜨는 방법과 호흡법, 안전 수칙을 꼼꼼히 알려주는 강사와 함께 체험을 즐길 수 있다. 수영을 못해도 안전장구 착용으로 체험이 가능하며 잠수방법 교육, 해산물 채취, 수중 촬영 등 다양한 체험이 가능하다. 아름다운 제주의 바다를 온몸으로 느낄 수 있는 곳이다.','제주특별자치도 제주시 애월읍 하귀미수포길 16-1',NULL,33.4842537573,126.4025480925,NULL,'https://www.instagram.com/city.diver','09:00~15:00','연중무휴',90,0,'2026-11-05 13:14:52'),
('50110','KTO_TOURAPI','347233','ATTRACTION','월영사(제주)','월영사는 한국불교 태고종 사찰로, 애월읍 상귀리 파군봉에 위치하고 있다. 월영사가 자리 잡고 있는 파군봉은 고려 시대 여몽연합군의 상륙부대를 맞아 삼별초가 항전했던 전적지다. 이곳에서 삼별초가 대파되었다고 전해져 파군봉이라 불린다. 월영사는 1936년 완주 위봉사의 상귀리 포교당으로 설립되어, 1945년 무렵에는 귀이사라는 이름으로 변경했으나 1948년 제주 4·3사건으로 모두 소실되었다. 4·3사건의 상흔을 이겨내고 옛 사찰의 명맥을 이으며, 지학 스님에 의해서 월영사가 창건된 후 여러 번의 불사를 거쳐 오늘날에 이르고 있다. 이 사찰에는 대웅전과 법당, 요사, 종각 등이 갖추어져 있으며, 법당 내부에는 조선시대 불상이자 제주특별자치도 문화유산자료인 목조여래좌상이 봉안되어 있다.','제주특별자치도 제주시 애월읍 하귀동남2길 40-16',NULL,33.4778027196,126.4140072753,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-11-03 16:19:07'),
('50110','KTO_TOURAPI','129146','ATTRACTION','추자도 등대','제주도의 다도해 추자도는 빼어난 경치와 더불어 풍성한 어족, 어장을 갖춘 청정 해양자원의 보고이며 흑비둘기 및 슴새의 서식지인 사수도(천연기념물)와 최영 장군 사당, 박씨처사각 등의 문화유산이 있다. 상추자도, 하추자도, 횡간도, 추포도 네 개의 유인도와 38개의 무인도로 이루어졌다. 추자도 등대는 제주해협과 부산, 목포 등 내륙을 오가는 여객선과 화물선 그리고 동중국해를 항해하는 선박들의 안전한 밤길을 인도하는 역할을 하고 있다. 1980년 2월 27일 점등된 추자도 등대는 규모가 작고 노후되어 철거하고 그 자리에 사무실과 홍보관 등을 갖추고 등대를 신설하였다.','제주특별자치도 제주시 추자면 영흥리 77-3',NULL,33.9553,126.2967,NULL,'https://www.visitjeju.net/kr','상시 개방','연중무휴',90,0,'2026-11-03 15:16:42'),
('50110','KTO_TOURAPI','127310','ATTRACTION','금산공원(납읍난대림지대)','제주시 애월읍 납읍리 마을에 인접하여 약 일 만평에 이르는 넓은 면적에 속칭 ‘금산공원’이라 불리는 곳에 울창한 상록수림이 있다. 이곳은 자연림의 원형을 보존하고 있는 표본지역으로 원식생 연구에 기초적인 자료를 제공하고 있다. 때문에 학술 자원으로서 가치가 높고, 천연기념물로 지정되어 보호되고 있는 납읍난대림지대이다. 이곳은 제주시의 서부 지구에서 평지에 남아있는 유일한 상록수림으로 상록교목 및 60여종의 난대성 식물이 자라고 있으며, 원시적 경관이 그대로 보존되고 있어 수목가지의 절취, 식물 채취 행위 및 야생 동물의 포획 등 자연을 손상시키는 행위가 일체 금지되고 있다. 납읍리는 예로부터 반촌[班村: 양반이 주민의 다수를 차지하는 마을]으로 유명하다. 이곳의 난대림지대는 예로부터 이 마을의 문인들이 시를 짓거나 담소를 나누는 휴양지로서 이용되었기 때문에 경작지와 인가가 주위에 있으며 보존이 잘 되었다고 한다. 이곳의 식생은 주로 후박나무, 생달나무, 종가시나무 등이 상층목을 이루고, 하층에는 자금우, 마삭줄 등이 전면을 덮고 있으며, 송악이 상층목의 수관[樹冠]을 감아 올라가고 있다. 나무의 종류는 비교적 단순하나, 전형적인 난대림상을 이루고 있다.

(출처 : 제주 문화관광 홈페이지)','제주특별자치도 제주시 애월읍 납읍리',NULL,33.433864846,126.3306993575,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-11-03 13:39:28'),
('50110','KTO_TOURAPI','2469467','ATTRACTION','맥파이 브루어리','경리단길 골목서 동네 친구 4명이 맥주를 마시다 시작하게 된 사업이 바로 맥파이 브루잉 컴퍼니이다. 물 좋고 공기 좋은 제주도에 양조장을 두고 있다. 맥파이 제주 양조장투어는 예약 후 이용 가능하다. 예약은 네이버 예약과 메일로 접수할 수 있다. 또한, 평일 저녁과 주말 4개 시간대로 투어가 가능하다. 이곳에서는 맥주가 만들어지는 모든 과정을 처음부터 끝까지 직접 확인할 수 있으며, 투어를 위해 따로 마련된 전시장이 아니기 때문에 양조설비 사이를 직접 돌아보며 설명을 듣고 질문을 할 수 있다. 1인당 지급하는 참가비에는 투어를 포함해 맥주 한 잔 가격이 포함되어 있다. 이밖에도 수제 맥주에 관한 다양한 교육 프로그램을 진행하고 있다. 맥주뿐만 아니라 맥주에 담긴 문화를 함께 나눌 수 있는 프로그램도 제공하고 있어 맥주를 좋아하는 사람들에게 인기 있는 양조장이다. 탑동에 맥파이 펍이 있으니 가까운 시내에서 간단하게 맥파이 맥주를 한 잔 즐겨보자.

(출처 :제주 문화관광 홈페이지)','제주특별자치도 제주시 동회천1길 23',NULL,33.5031585786,126.6172155696,NULL,'https://www.magpiebrewing.com/tours','12:00~20:00※ 매월 첫째 수요일은 17:00 마감','매주 월요일~화요일',90,0,'2026-11-03 08:57:10'),
('50110','KTO_TOURAPI','315926','ATTRACTION','보덕사(제주)','보덕사는 대한불교조계종 제23교구 본사 관음사의 말사로, 1943년 초가에 18평의 법당을 지음으로써 창건되었다. 보덕사 대웅전에는 창건 당시 안봉려관이 해남 대흥사에서 모셔온 17세기의 목조여래좌상이 안치되어 있다. 이 불상은 문화유산 자료로 가치를 인정받아 제주특별자치도 문화유산 자료로 지정되었고 전체 높이가 66cm로 큰 규모에 속한다. 근대 제주불교 중흥기에 선봉 스님이 각 사찰마다 모시고 다니면서 그곳 불사에 힘을 실어주었다는 일화로 유명하다. 보덕사 경내에는 1992년에 석조 지장보살상을 봉안하였는데, 이로써 지장도량으로 거듭나며 중생제도에 앞장서고 있다. 제주 불교 중흥의 맥을 면면히 이어오고 있는 보덕사는 현재에도 소원성취를 기원하는 많은 불자들의 귀의처로 끊임없는 발길이 이어지고 있다.','제주특별자치도 제주시 독짓골8길 26',NULL,33.4916724431,126.5324792689,NULL,NULL,NULL,'연중무휴',90,0,'2026-11-03 08:20:40'),
('50110','KTO_TOURAPI','2704435','ATTRACTION','하도해변','하도해변은 제주시 구좌읍 하도리의 해맞이해안로를 따라 자리한 해변이다. 넓은 백사장과 비교적 얕고 완만한 바다가 펼쳐져 있으며, 바다 건너 우도를 조망할 수 있다. 성산과 종달, 하도, 세화를 잇는 제주 동부 해안 드라이브 일정 중 들르기 좋다. 맑은 바다를 바라보며 산책하거나 물놀이와 카약 등 해양레저를 즐길 수 있다. 해양레저 프로그램과 샤워시설은 계절과 현장 상황에 따라 운영 여부가 달라질 수 있으므로 이용 전에 확인해야 한다. 비지정 해수욕장으로 안전요원이 배치되지 않은 시기와 구간이 있을 수 있어 물놀이할 때는 기상과 해상 상태를 살펴야 한다.

◎ 한류의 매력을 만나는 여행 정보 - 예능 
제주에서 가장 아름답기로 유명한 해안 도로의 하도리 도로변에 위치한 해수욕장이다. 제주의 다른 해수욕장에 비해 한적하고, 넓은 백사장과 얕고 맑은 바다를 갖춘 곳으로 온화한 경관이 펼쳐진다. 파도가 높지 않고 잔잔해 스노클링, 카약 등의 해양 레저 체험을 할 수 있으며 의 비와 노홍철처럼 조용히 간이 테이블과 의자를 펴고 커피를 마셔도 좋다.','제주특별자치도 제주시 구좌읍 해맞이해안로 1973',NULL,33.5135036072,126.8988002817,NULL,'https://www.visitjeju.net/kr','상시 개방','연중무휴',90,0,'2026-11-02 01:30:02'),
('50110','KTO_TOURAPI','2858656','ATTRACTION','창꼼','창꼼은 북촌환해장성, 북촌 용물 동쪽에 있다. ‘창꼼’은 창 고망(구멍) 난 돌이라 하고, 뙤창문의 제주어이기도 하다. 뙤창문은 방문에 낸 작은 창문을 뜻한다. 말처럼 창을 뚫어 놓은 듯한 기암으로, 서 있는 바위에 구멍이 나 있어 여행자들은 이 구멍을 통해 사진을 찍는다. 창꼼바위에서는 바다 쪽으로 다려도가 보이고, 방파제가 보인다. 창꼼 가까이 있는 용물은 용천수를 뜻하며 지하를 흐르다 바다 가까이에서 분출하는 지하수를 말한다. 이곳 역시 사진 포인트이다.

◎ 한류의 매력을 만나는 여행 정보 - 드라마 
‘창꼼’은 우영우의 멘토 정명석 변호사가 아내와의 일을 회상하던 장소이다. 이 바위는 보통 바위와는 조금 다르게 한가운데 동그랗게 구멍이 뚫려있다. 그 구멍으로는 그림 같은 제주 바다가 보인다. 제주 특유의 푸르고 아름다운 풍경이 유독 돋보이는 명소라 기념사진을 찍으러 온 많은 여행객을 찾아볼 수 있다. 창꼼바위 앞에서 바다를 배경 삼아 사진 한 장 남겨보는 것을 추천한다.','제주특별자치도 제주시 조천읍 북촌리 403-9',NULL,33.5524569519,126.7000206241,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-30 13:32:22'),
('50110','KTO_TOURAPI','1926379','ATTRACTION','정물오름','정물오름의 명칭은 오름 앞에 있는 정물샘의 이름에서 따왔다. 제주도는 전국의 연평균 강수량에 비해 훨씬 많은 강수량에도 불구하고 마실 물이 귀했다. 특히, 중산간 지역에서 식수를 구하는 것은 더욱 어려워서 귀하게 여겼는데, 식수로 사용할 수 있던 물 중의 한 곳이 정물샘이다. 이 샘은 물이 깨끗하고 양이 많아 이곳에서 꽤 먼 곳의 마을 사람들도 물을 길러다 마셨다고 한다. 
정물오름의 물은 사람뿐만 아니라 가축에게도 소중했는데 이 부근에 제주도에서 가장 유명한 이시돌목장이 자리 잡고 있다. 정상에 오르면 당오름과 정물오름과 함께 생명수를 공급했던 원물오름이 한 선상에 있고 평화로운 분위기의 주변 도로들을 볼 수 있다. 계절의 변화에 따라 다른 풍경을 만들어 내는 이시돌목장을 보는 것도 즐겁다. 풀이 파릇파릇한 넓은 목장에서 따스함과 여유가 느껴지는 말들의 움직임이 계절의 기운을 전한다.

(출처 : 비짓제주)','제주특별자치도 제주시 한림읍 금악리','산52-1',33.337997,126.330205,NULL,'http://www.visitjeju.net/','상시 개방※ 일부 출입이 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-10-30 08:45:59'),
('50110','KTO_TOURAPI','126434','ATTRACTION','수월봉','제주의 가장 서쪽 끝머리에 있는 한경면 고산리에 가면 제주에서 가장 넓은 들이 있다. 이 들판 끝 해안가에 솟아있는 조그마한 봉우리가 수월봉이다. 수월봉은 해안에 돌출해 있는 높이 약 77m의 봉우리로 절벽이 예리하고 운치가 있으며 곳곳에서 솟는 용천수는 약수로 유명하다. 수월봉 정상에는 기우제를 지내던 육각정인 수월정이 있다. 수월봉 아래 해안을 끼고 이어지는 절벽은 화석층이 뚜렷하여 자연의 신기함을 더하는 곳이다. 수월봉에서는 제주에서 가장 아름답다는 섬인 차귀도가 내려다 보이고, 더욱이 수월봉 정상에 있는 수월정에 앉아서 바라보는 낙조는 제주 어느 곳에서 보는 것보다 아름답다.','제주특별자치도 제주시 한경면 고산리 3760',NULL,33.2947589554,126.1634097074,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-29 15:48:03'),
('50110','KTO_TOURAPI','228859','ATTRACTION','수월봉과 차귀해안','수월봉은 해발 77m 높이의 제주 서부지역 조망봉이다. 특히 깎아 만든 듯한 수월봉 해안절벽은 동쪽으로 2㎞까지 이어져 있다. 이 해안절벽은 ‘엉알’이라 불리며, 벼랑 곳곳에는 샘물이 솟아올라 ‘녹고물’이라는 약수터로 널리 알려져 있다. 수월봉 아래쪽에는 해안선을 따라 지질트레일이 있다. 해안 절벽을 따라 화산 퇴적물이 쌓여 있는 모습이 유명하다. 수월봉 정상에는 기우제를 지내던 육각정인 수월정이 있으며 수월정 옆으로는 고산기상대가 우뚝 서 있다. 우리나라 남서해안 최서단에 있는 기상대로서 거의 모든 기상 관측이 이루어지는 곳이다. 이곳 5층에는 일반인인도 출입 가능한 전망대가 있다. 수월정에 앉아서 차귀도로 떨어지는 낙조의 모습은 제주도에서 아름답기로 손꼽히는 일몰 중 하나이다. 수월봉 언덕이 해안가에 우뚝 솟구쳐 있는 절벽이기 때문에 정상부에 쳐놓은 울타리 바깥으로 나가지 않도록 주의해야 한다.
또한 북쪽으로 보이는 해안가에 차귀도라는 섬이 있는데 정상부에만 초지가 형성되어 있고 그 외는 온통 검은 바위 절벽으로 이루어져 있다. 한때 유인도였다고도 전해진다.','제주특별자치도 제주시 한경면 노을해안로 1013-70',NULL,33.2940923598,126.1629958718,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-29 15:45:46'),
('50110','KTO_TOURAPI','598558','ATTRACTION','우도산호해변 홍조단괴 서빈백사','우도 산호해변은 에메랄드빛으로 부서지는 햇살 아래 하얗다 못해 푸른빛이 감돌며, 우도 서쪽의 하얀 모래해변이라 하여 서빈백사로 불린다. 수심에 따라 바다 빛깔이 달라 남태평양이나 지중해의 어느 바다와 비교해도 손색이 없다. 여름에는 해수욕장으로, 봄, 가을에는 사진 찍기 좋은 곳으로 인기가 많으며, 인근에는 우도 땅콩을 넣은 아이스크림, 수제버거 등 식당과 아기자기한 카페들이 많이 들어서 있다. 이곳의 모래는 해양 조류 중 하나인 홍조가 해안으로 쓸려와 퇴적된 것으로, 이러한 해변을 홍조단괴 산호해변으로도 불린다. 홍조단괴란 홍조류가 생리과정에서 탄산칼슘을 축적하여 돌처럼 단단하게 굳어져 버린 상태를 말한다. 홍조단괴로 이루어진 해변은 세계에서도 몇 곳 없어 학술적으로도 희소가치를 지닌다.','제주특별자치도 제주시 우도면 우도해안길 252',NULL,33.5026500483,126.9437380307,NULL,'http://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-10-29 14:41:32'),
('50110','KTO_TOURAPI','1162240','ATTRACTION','제주도 국가지질공원','제주도는 한반도 서남단에서 남쪽으로 약 90㎞ 떨어져 있는 대륙붕 위의 화산섬으로 화산분출물로 형성되었다. 화산지형이 원형 그대로 잘 보존돼 지구과학적 가치가 크고, 경관도 아름답다. 제주도는 이 가운데 경관이 뛰어난 명소 9곳(한라산, 성산일출봉, 만장굴, 서귀포층, 산방산과 용머리해안, 수월봉, 중문 대포해안 주상절리대, 천지연폭포)을 유네스코 세계지질공원 네트워크(GGN)에 세계지질공원으로 인증받았다. 유네스코가 지원하는 세계지질공원은 지질학적으로 가치가 있고, 희귀하며 경관이 아름다운 지역으로 교육과 지질관광이 활발히 이루어져 지역 경제 발전에 기여하는 곳을 말한다. 제주도는 유네스코가 인정하는 지질공원, 생물권 보전지역, 세계 자연유산을 보유함으로써 세계적인 자연관광지로서 거듭나고 있다.
한라산은 제주도 순상화산의 중심 봉우리이며 1,950m의 해발고도로 남한에서 가장 높은 산이다. 한라산은 제주도의 상징이자 한반도와 주변 해역에서 일어난 제4기 화산활동의 대표적인 산물이기도 하다. 정상부에 깊이 108m, 너비 550m의 화구호인 백록담 분화구가 있으며 영실기암의 가파른 암벽과 약 40여 개의 오름 등 여러 화산지형을 갖고 있다. 풍화와 침식에 의해 순상화산의 원래 지형이 파괴되지 않은 상태로 남아있는 한라산은 2002년과 2007년에는 각각 유네스코 생물권 보전지역과 유네스코 세계 자연유산으로 등재되었다.
전형적인 수성화산으로 높이 179m로 제주도 동쪽 해안에 거대한 고대의 성곽처럼 우뚝 솟아있다. 성산일출봉 응회구는 수심이 얕은 해저에서 분출하여 해수면 위로 성장한 섯치형 화산의 탄생과 성장과정을 잘 보여주고 있다. 2000년과 2007년에 각각 천연기념물과 유네스코 세계 자연유산으로 지정되었다.
만장굴은 거문 오름에서 흘러나온 용암이 땅 위를 흐르다 만들어진 용암동굴로 전체 길이 약 7,400m, 최대 높이 약 25m, 최대 폭 약 18m로서 제주 세계 자연유산의 한 부분인 거문 오름 용암 동굴계에 속하는 용암동굴이다.
서귀포층은 수성화산 활동으로 생긴 화산재가 해양 퇴적물과 함께 쌓이기를 반복해 생겨난 약 100m 두께의 퇴적층으로 천연기념물로 지정되어 있다.
산방산은 제주도의 남서부 해안에 위치하고 있으며, 395m의 높이를 지닌 거대한 용암 돔이다. 밝은 회색을 띠고 있는 산방산 용암 돔은 주상절리가 잘 발달한 조면암으로 구성되어 있다.
용머리 해안은 산방산 용암돔의 남쪽 해안에 있는 용머리는 제주에서 가장 오래된 화산 지형으로 수성화산 활동으로 만들어진 응회환의 일부이다. 용머리는 작은 돌기처럼 돌출해 있는 형상을 하고 있으며, 바닷속으로 들어가는 용의 머리를 닮았다하여 ‘용머리’로 불리며 해안경관이 뛰어나다.
수월봉은 제주도의 서쪽 가장자리에 위치하고 있는 기복이 낮은 언덕 형태의 화산 쇄설성 퇴적층이다. 땅속에서 올라온 마그마가 지하수를 만나 격렬하게 폭발하면서 뿜어져 나온 화산재들이 쌓여 형성된 응회암의 일부로 높이가 77m이다.
대포동의 주상절리 용암은 인근에 있는 녹하지악이라는 오름에서 분출된 용암이 해안으로 흘러와 굳으면서 생겨났다. 주상절리의 기둥이 두껍게 잘 만들어져 있는 아랫부분과 주상절리의 기둥이 가늘고 복잡하게 만들어져 있는 윗부분의 수평과 수직 단면에서 잘 발달되어 있다.
천지연폭포는 높이는 22m, 폭은 12m이며 폭포 아래에는 수심 20m의 호수가 형성되어 있다. 폭포의 하류는 서귀포항까지 약 1㎞ 정도의 계곡을 형성하는데 이곳에 서식하는 무태장어, 담팔수나무 및 난대림은 천연기념물로 지정되어 있다.','제주특별자치도 제주시 조천읍 선교로 569-36',NULL,33.4568710872,126.7142437274,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-29 14:31:29'),
('50110','KTO_TOURAPI','1351320','ATTRACTION','아부오름','아부오름은 일찍부터 아보름이라 불렸고 송당마을과 당오름 남쪽에 있어서 앞오름이라 하여 이것을 한자로 빌어 표기한 것이 전악(前岳)이다. 또한 산 모양이 움푹 파여있어 마치 가정에서 어른이 믿음직하게 앉아있는 모습과 같다하여 아부오름(亞父岳)이라고도 한다. 어렵지 않게 오름 둘레까지 오를 수 있고 제주오름의 모습을 가깝게 느낄 수 있어 최근 각광 받고 있다. 오름 정상에 함지박과 같은 둥그런 굼부리가 파여있다. 특히 굼부리 안 원형 삼나무숲의 특징적인 모습이 주목 받고 있다. 오름 대부분은 풀밭으로 이루어져 있는데, 인공으로 심은 삼나무가 있고 그 사이로 상수리나무, 보리수나무 등이 있다. 풀밭에는 송양지꽃, 풀솜나물, 향유, 쥐손이풀, 청미래덩굴, 찔레 등이 여기저기 서식한다. 아부오름 주변에는 새미오름, 민오름, 백악이오름, 문석이오름 등의 오름이 둘러싸고 있다.','제주특별자치도 제주시 구좌읍 송당리','산164-1',33.4473,126.7776,NULL,'http://www.visitjeju.net/','※ 일부 출입이 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-10-29 14:16:23'),
('50110','KTO_TOURAPI','1898906','ATTRACTION','엉알해안','제주시 한경면 고산리에 있는 엉알해안은 제주시 숨은 비경 31곳에 선정된 곳이다. 수월봉 밑에서부터 해안선을 따라 2km가량 이어져 있다. 이 해안지대에는 원래 이 지역 일대 어민들의 어장이 있었으나 현재는 주로 산책로로 이용되고 있다. 
해안절벽이 퇴적층으로 이루어져 있으며, 낙조가 아름다운 곳이다. 유네스코에서 등재한 세계지질공원으로서 올레 12코스에 해당하며 아름다운 해안 풍경을 감상하면서 여유롭게 산책을 즐길 수 있어 많은 사람이 찾는 관광명소이다. 해안을 따라 형성된 해식애를 온통 뒤덮으며 지천으로 피어있는 구절초가 볼거리이다.
주변 관광지로는 차귀도잠수함관공, 절부암, 고산리선사유적 등이 있다.','제주특별자치도 제주시 한경면 고산리','3427-33',33.299392,126.16761,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-29 14:14:40'),
('50110','KTO_TOURAPI','126468','ATTRACTION','방선문','제주시를 관통하는 한천 상류 약 6km 지점에 효성이 지극한 나무꾼이 신선을 만났다는 전설을 가진 방선문(訪仙門)이 있다. 전설에 의하면 방선문은 신선 세계로 통하는 문으로 신선 세계와 인간 세계의 경계이다. 옛날 백록담에서는 매년 복날이면 하늘에서 선녀들이 내려와 목욕했는데 이때마다 한라산 산신은 방선문 밖 인간세계로 나와 선녀들이 하늘로 돌아갈 때까지 머물러 있어야만 했었다. 그런데 어느 복날 미처 방선문으로 내려오지 못한 한라산 산신이 선녀들이 목욕하는 모습을 훔쳐보고 말았고, 이에 격노한 옥황상제가 한라산 산신을 하얀 사슴으로 만들어 버렸다고 한다. 그 뒤 한라산 산신은 매년 복날이면 백록담에 올라가 슬피 울었고, 하얀 사슴의 연못이라는 백록담의 이름은 이 전설에서 유래한 것이다.
또한, 방선문 일대는 한국 고전문학 중 해학소설의 백미이자 판소리 열두 마당의 하나인 ‘배비장전’의 무대이기도 하다. 예부터 제주에 부임한 목사를 비롯한 지방 관리뿐만 아니라 유배인까지 많은 선인들이 이곳에서 풍류를 즐겼고, 방선문 곳곳에는 그들이 남긴 마애명이 많이 남아 있는데 ‘訪仙門’ , ‘登瀛丘’등을 비롯해 50여 개의 마애명이 남아있다. 
철 따라 아름다운 경치를 자아내지만, 특히 봄철의 진달래꽃은 영주 12경의 하나로 꼽힐 만큼 아름답다. 부근에는 높이 10m, 너비 30~50m의 오등동계곡이 있어 한결 운치를 더해준다.','제주특별자치도 제주시 거북새미길 48-26','(오등동)',33.452284,126.517817,NULL,NULL,'계곡 입구 숲길 탐방 가능※ 방선문 계곡은 낙석 우려로 출입 통제. 안전끈 설치 구역 출입금지','연중무휴',90,0,'2026-10-29 10:27:03'),
('50110','KTO_TOURAPI','126445','ATTRACTION','제주 토끼섬 문주란 자생지','문주란 자생지는 하도리 해안에서 50m쯤 떨어진 토끼섬에 위치해 있다. 섬 주변은 바위로 둘러싸여 있으며, 안쪽으로 형성된 모래땅에 문주란 군락이 형성되어 있다. 이 자생지는 한때 많이 파괴되었으나 사람들의 노력으로 보존 및 관리되고 있다.
제주 토끼섬은 우리나라 유일의 문주란 자생지로서 기후로 보아 분포의 북쪽 한계 지역이기 때문에 학술적 가치가 높아 천연기념물로 지정하고 보호하고 있다. 문주란은 일본, 중국, 인도, 말레이시아, 우리나라 등에 분포하는 식물로 연평균 온도가 15℃, 최저온도가 -3.5℃ 이상인 환경에서 자란다. 꽃은 흰색으로 7~9월에 피는데, 이 꽃이 활짝 피는 것은 밤중이며 향기가 강하게 난다.

※ 토끼섬 주변은 간조 시에도 수심이 깊고 곳곳에 깊게 패인 곳이 있어 위험하므로 도보 이동은 자제하고, 방문 전 현지 안내를 확인해야 한다.','제주특별자치도 제주시 구좌읍 문주란로','(구좌읍)',33.5202002058,126.9083270194,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-28 18:04:24'),
('50110','KTO_TOURAPI','126463','ATTRACTION','연북정','조천읍 조천리 바닷가에 위치한 조선시대의 정자이다. 제주특별자치도 유형문화유산으로 지정되어 있다. 연북정은 객사(客舍)로, 원래 조천성(朝天城) 밖에 있었다고 하나 창건 연대는 미상이며, 1590년(선조 23)에 이옥절제사(李沃節制使)가 성을 동 북쪽으로 물려 쌓고 그 위에 옮겨 세워 쌍벽정(雙壁亭)이라 하였다고 한다. 교수(敎授) 곽기수(郭期壽)의 중창기에 의하면, 조천관은 바다 어귀에 있는데, 육지로 나가는 사람들이 바람을 관측하는 곳이다. 조천(朝天)이라 이름을 지은 것도 이 때문이다. 절제사 이옥이 부임한 다음 해 경인년 (庚寅年)에 막부(幕府)의 제공(諸公)과 협의하고 아전과 주민에게, ‘조천에 관을 두게 된 것은 실로 도적들이 다니는 길목의 요충이며, 왕명을 받은 사신들이 왕래하는 곳이기 때문인데, 이같이 성이 좁고 건물이 노후해서야 되겠는가, 어찌 농사를 짓는 틈틈이 개축하여 웅장하고 화려하게 하여야 하지 않겠는가.’ 하니, 모두가 옳다고 하였다. 
마침내 여러 재주 있는 역군들을 동원하여 10월에 착공하고 12월에 마쳤다. 성은 동북쪽으로 물려서 쌓고 그 위에 망루를 안치하여 쌍벽(雙璧)이라 하였다. 쌍벽(雙璧)은 청산녹수(靑山綠水)에 접하여 있다는 뜻에서 붙인 이름이라고도 한다. 그 후 선조 32년(1599)에는 성윤문(成允文) 목사가 그 건물을 중수하고 ‘임금을 사모한다’는 뜻으로 연북정(戀北亭)이라 개칭하였다. 지금의 건물은 1973년에 보수한 것인데, 보수 당시 ‘용(龍) ·가경이십오년경진이월십오일진시입주상량(嘉慶二十五年庚辰二月十五日辰時入柱上樑) · 호(虎)’라 한 명문(銘文)이 발견된 것으로 보아, 연북정은 가경(嘉慶) 25년, 즉 순조 20년(1820) 마지막으로 보수된 듯하다. 이 정자가 세워져 있는 조천포구는 화북포와 함께 관원이나 도민들이 본토를 왕래하는 관문(關門)이었을 뿐만 아니라 순풍을 기다리며 머무는 휴식처이기도 하였다. 일제강점기에는 이 정자가 경찰관 주재소로 사용되기도 하였다.','제주특별자치도 제주시 조천읍 조천리','2690',33.540199011,126.6359546425,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-28 18:04:23'),
('50110','KTO_TOURAPI','127909','ATTRACTION','명월대','명월대는 조선 말기 지방 유학자들과 시인들이 어울려 풍류를 즐기던 곳이다. 1981년 제주특별자치도 기념물로 지정되었다. 대는 마을을 끼고 있는 천변 중앙의 자연암벽 위에 8각형의 석축을 3단으로 쌓고 그 위에 원형의 반석을 만들었으며, 최근에 와서 콘크리트 처리를 하였다. 그 옆에는 석비가 세워져 있는데, 앞면에 \'명월대\'라고 음각되어 있다. 또 명월대 주변에 1910년 경에 만들어진 돌다리가 있는데, 이는 제주도에서는 흔치 않은 석교이다. 명월대가 있는 천변은 상류에서 하류에 이르기까지 수백 년 된 팽나무 60여 그루와 푸조나무가 군락을 이루고 있어 자연 경관이 수려할 뿐만 아니라 간간이 흐르는 물소리가 정결하다.','제주특별자치도 제주시 한림읍 명월리',NULL,33.389,126.2662,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-28 18:04:23'),
('50110','KTO_TOURAPI','228864','ATTRACTION','절부암','제주시 한경면 용수리 포구에 사철나무, 후박나무, 동백나무 등 난대식물 군락을 이루고 있는 곳에 절부암이란 바위가 있다. 1981년 8월 26일 제주특별자치도 기념물로 지정된 이 바위는 고씨 부인의 절개를 기리고 있는 바위이다. 조선 후기 이 마을의 어부 강사철이 고기잡이를 나갔다가 거센 풍랑으로 변을 당하였다. 그의 처 고씨는 며칠 동안 남편을 찾아 헤매다가 끝내 남편을 찾지 못하자 남편의 뒤를 따르는 것이 도리라 생각하여 소복을 입고 이곳 나무에 목매어 자살하고 말았다. 그러자 홀연히 남편의 시체가 이 바위 밑에 떠올랐으므로 사람들은 감탄하였다 한다. 이를 신통히 여긴 당시 판관 신재우는 고씨가 자결한 바위에 절부암이라는 글귀를 새겨 후대에 기리게 하였다. 또한 관에서는 이들 부부를 합장한 후 그 넋을 위로하고자 이 마을 주민들로 하여금 매년 제사를 지내도록 하였다.','제주특별자치도 제주시 한경면 용수리','4241-5',33.3238,126.1671,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-28 18:04:23'),
('50110','KTO_TOURAPI','1621045','ATTRACTION','신촌향사','신촌향사는 조선시대 마을의 공무를 처리하던 곳이었다. 조선 순조 5년(1805)에 이곳으로 옮겨지었다고 하며, 그 뒤로도 여러 차례 고쳐서 원래 형태에서 많이 바뀐 것으로 보이며, 침수에 대비하여 지대를 높이면서 본래의 분위기를 거의 잃었다. 신촌향사는 앞면이 7칸으로 제주도의 일반 민가보다 규모가 크고 가운데 있는 대청도 넓다. 그러나 구조와 양식 등은 민가와 거의 비슷하다. 우진각 지붕의 기와집이며, 전면퇴는 개방되어 있고 내진주에 세살문을 달았으나, 후면은 퇴기둥에 심벽을 치고 간마다 판장문을 달았다.','제주특별자치도 제주시 조천읍 신촌5길 27',NULL,33.5365120872,126.6206708232,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-28 18:04:23'),
('50110','KTO_TOURAPI','1918421','ATTRACTION','폭낭오름','폭낭오름은 제주도 제주시 애월읍 봉성리에 있는 오름으로, 효명 목장 진입로 근처에 있다. 오름의 이름은 오름에 큰 폭낭(팽나무)이 있어서 붙여졌다고 하는데, 지금은 그 나무를 찾을 수 없다고 한다. 오름의 정상부에는 하나의 말굽형 화구와 남서쪽에 두 개의 원추형 화구로 이루어진 복합형 화산체이며, 높이는 645.5m, 비고는 76m이다. 오름 전 사면이 완만하면서 사면을 따라 풀밭을 이루고, 주요 식생은 산 뽕나무, 분단나무, 자귀나무, 보리수나무, 꽝꽝나무 등이 있고, 오름 정상부에는 가운데가 얕게 우물져 가시덤불과 잡초가 우거져 있다.','제주특별자치도 제주시 애월읍 봉성리 산43',NULL,33.3521218118,126.3819476663,NULL,'https://www.jeju.go.kr/is/oreum','상시 개방','연중무휴',90,0,'2026-10-23 16:26:57'),
('50110','KTO_TOURAPI','1925369','ATTRACTION','열안지오름(봉개동)','열안지오름은 제주시 봉개동에 위치한 오름이다. 화구는 침식되어 원래의 형태가 말굽형인지 원추형인지 구분이 곤란하나 전체적인 형태로 보아 말굽형 화구였던 것으로 추정된다. 경사진 북사면에는 해송이 숲을 이루고 있으나 남사면은 경작지의 경계에서부터 띠(새)가 덮인 풀밭 오름을 이루고, 남북 사면 기슭에는 명도암 마을의 개척자 고이지의 묘가 있다. 열안지오름을 줄여서 보통 열안지라고 부르며, 한자명은 열안지악, 열안악,열안산 등으로 표기되어 있고, 산 모양이 기러기가 열을 지어 날아가는 형상이라는데 연유하여 붙여진 이름으로 열안지라고도 하고, 제비가 알을 품은 형국이라 하여 연난지라고도 한다.','제주특별자치도 제주시 봉개동 산778-1',NULL,33.4730747672,126.6053526429,NULL,'https://www.jeju.go.kr/is/oreum','상시 개방','연중무휴',90,0,'2026-10-23 16:19:12'),
('50110','KTO_TOURAPI','2765227','ATTRACTION','바리메오름','바리메 오름은 제주시 애월읍 어음리에 있는 오름으로 오름 중 높고 경사가 가파른 오름에 속한다. 오름 정상 분화구 모양이 절에서 쓰는 승려들의 공양 그릇 바리를 닮았다고 하여 바리메 오름으로 불리게 되었다. 오름의 서쪽으로는 목장이 들어서 있고, 나머지 경사면은 소나무가 무성히 자라고 있다. 경사가 있는 오름으로 둘레길처럼 운동화 차림보다는 등산화 차림이 편할 수 있다. 등산로를 따라 다양한 야생화와 피어있고 정상에는 다래 오름, 폭낭오름, 괴오름, 북 돌아진 오름 등이 있어 크고 작은 오름들이 어울려 있는 진풍경을 만날 수 있다.','제주특별자치도 제주시 애월읍 어음리 산 21',NULL,33.3771308148,126.3880197641,NULL,'https://www.jeju.go.kr/is/oreum/park','상시 개방','연중무휴',90,0,'2026-10-22 15:25:49'),
('50110','KTO_TOURAPI','1926369','ATTRACTION','정물알오름','정물알오름은 정물오름에 딸린 오름이란 뜻으로 붙여진 이름으로 금악 이시돌목장 내에 있는 정물오름의 서쪽 기슭에 위치해 있다. 원추형의 작은 오름이며 오름 앞에 있는 정물샘으로 유명한 오름인데, 정물샘의 물이 깨끗하고 양이 많아 식수가 귀한 제주에서 꽤 먼 곳의 마을 사람들도 물을 길어다 마셨다고 한다. 봉우리는 항공사진 판독 결과 화산체의 형태와 화구의 존재가 인정되어 정물오름과는 별개의 독립된 화산체로 보아야 하며, 주변의 언덕들은 정물오름 화구에서 흘러나오는 암설류로 이루어진 것으로 추정된다. 해송이 주를 이루며 삼나무 조림지 등과 함께 울창한 숲이 펼쳐져 있다.','제주특별자치도 제주시 한림읍 금악리','산105-1',33.3399,126.3249,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-22 11:25:24'),
('50110','KTO_TOURAPI','1928421','ATTRACTION','다려도','섬의 모습이 물개를 닮았다고 해서 달서도라고도 한다. 제주도 북부 끝의 북촌리 마을 해안에서 400m 정도 거리의 앞바다에 떠 있는 무인도이다. 온통 현무암으로 이루어진 바위섬으로 독립된 작은 섬이 모여 이 섬을 이룬다. 거센 파도와 해풍에 의해 바위가 갈라지는 절리 현상을 곳곳에서 볼 수 있으며, 작은 섬과 섬 사이는 소규모의 모래벌판으로 연결되어 있다. 다려도는 천연기념물 원앙의 집단 도래지로 유명하여 해마다 12월에서 2월 사이에 적게는 수백 마리에서 많게는 수천 마리의 원앙이 찾아온다. 제주시가 발표한 제주시 숨은 비경 31곳 중 하나이며 북촌리 마을의 어선을 이용해 바다 위에 그림같이 떠있는 듯한 절경의 다려도 주변을 둘러볼 수 있다.

(출처: 비짓제주)','제주특별자치도 제주시 조천읍 북촌리',NULL,33.5572007676,126.695318174,NULL,'https://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-10-22 11:23:53'),
('50110','KTO_TOURAPI','1933217','ATTRACTION','바늘오름','제주시 조천읍 교래리에 위치한 이 오름은 주변에 가시덤불이 많아 바늘오름 또는 제주 사투리로 바늘을 이르는 바농오름이라고도 한다. 오름은 삼나무로 뒤덮여 숲을 이루고 있고, 삼나무를 벗어나면 해송과 낙엽수림, 잡목이 우거져 숲을 이루고 있다. 원형 화구 안에는 풀밭을 이루고 있는 가운데 해송, 쥐똥나무, 찔레나무, 청미래덩굴, 윤노리나무 등이 식생하고, 말굽형 화구 안에는 보리수나무와 잡목 등이 우거져 자연림의 숲을 이루고 있다. 동쪽에 북동쪽으로 깊은 골이 패어 있는 곳에 상록수림이 형성되어 있다. 오름의 남동쪽에는 주로 해송이 있다. 정상에서는 억새가 피는 계절이면 억새가 정상을 뒤덮을 정도로 가득하다. 날이 좋을 때는 바늘 오름 정상에서 한라산의 모습이 아주 가깝게 보이기도 한다. 또한 바늘오름 인근에는 돌문화공원, 에코랜드 등 가볼 만한 곳이 많아 위치적으로도 좋다.','제주특별자치도 제주시 조천읍 교래리','산 108',33.453675,126.653999,NULL,'http://www.visitjeju.net/','※ 일부 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-10-22 11:21:19'),
('50110','KTO_TOURAPI','1933208','ATTRACTION','둔지봉','둔지는 제주 방언으로 평지보다 조금 높은 곳을 가리키는 말로, 둔지봉(둔지오름)은 주변에 둔지(용암 암설류)가 많아 붙여진 이름이다. 관광객이 많이 찾는 오름은 아니나, 정상에서 제주도를 한눈에 내려다볼 수 있는 조망권을 갖고 있다. 높지 않지만 오르는 도중에 다소 가파른 구간이 존재한다. 둔지봉은 남서쪽으로 벌어진 말굽형 화구를 가지고 있는데, 원지형이 비교적 잘 보존되어 있다. 화구 앞쪽에는 용암 부스러기로 이루어진 작은 구릉들이 많이 있다. 둔지봉은 소나무, 삼나무, 편백나무 군락으로 이루어져 있으며 해송과 억새 또한 넓게 분포하고 있다. 오름을 오르다 보면 각양각색의 돌담으로 둘러싸인 무덤이 많은 것을 볼 수 있다. 날씨가 좋은 날 정상에 오르게 되면 한라산과 구좌읍, 조천읍 내의 오름들을 모두 조망할 수 있다.','제주특별자치도 제주시 구좌읍 한동리','산 40',33.501216,126.797289,NULL,'http://www.visitjeju.net/','※ 일부 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-10-22 11:18:51'),
('50110','KTO_TOURAPI','1941153','ATTRACTION','삼의악오름','제주특별자치도 제주시 산천단 인근에 위치한 삼의악오름은 세미오름, 삼의양오름으로도 불린다. 정상에는 풀밭으로 이루어진 원형의 산정분화구가 있으며, 남쪽 사면의 골짜기에서는 샘이 솟아난다. 동쪽 사면에는 해송이 듬성듬성 자라고, 남쪽 골짜기 주변에는 자귀나무와 산수국 등 다양한 식생이 어우러져 있다. 정상에 오르면 사방으로 탁 트인 제주 풍경을 감상할 수 있으며, 비교적 완만한 구간을 따라 오름을 탐방하기 좋다.샘이 솟아 나와 세미오름이라 부르던 것이, 지금은 한자의 음을 빌어 표기한 삼의양악(三義讓岳) 등으로 불린다.','제주특별자치도 제주시 아라일동','산 24-2',33.4394,126.5622,NULL,'http://www.visitjeju.net','※ 일부 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-10-22 11:17:11'),
('50110','KTO_TOURAPI','1945394','ATTRACTION','손지오름','손지오름은 제주시 구좌읍 종달리에 위치한 오름이다. 이 오름은 한라산의 축소판 같은 생김새 때문에 한라산의 손자라는 의미로 손지오름이라고 불린다. 손지는 손자의 제주식 표현이며, 이 외에 손자봉, 손지악이란 이름도 같이 쓰인다. 손지오름은 따라비오름, 큰사슴이오름과 함께 가을철 억새가 아름다운 3대 오름에 손꼽힌다. 화구 능선에 오르기 위해서는 빽빽하게 들어선 억새 숲을 헤쳐 가야 한다. 억새가 한 방향으로 눕혀져 있는 것은 앞선 사람들이 만들어 놓은 길이다. 길은 여러 갈래로 흩어져 있지만 모두가 정상을 향하고 있다. 손지오름의 볼거리는 억새 군락이나 시원한 오름 조망만이 아니다. 남쪽 알봉 아래로는 광활한 목장 지대가 자리하고 있다. 이곳의 초지는 자연적으로 형성된 것이어서 방목된 소들은 홀로 봉우리에 오르기도 하고 때론 떼를 지어 평지를 활보한다. 손지오름에서 바라본 목가적인 풍경은 제주의 가을 정서와 매우 잘 어울린다. 

(출처: 비짓제주)','제주특별자치도 제주시 구좌읍 종달리','산 52',33.456443,126.819528,NULL,'http://www.visitjeju.net/','※ 일부 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-10-22 11:11:20'),
('50110','KTO_TOURAPI','1945414','ATTRACTION','새신오름','제주시 한경면 산양리 산양초등학교 북동쪽 지점 도로변에 위치한 오름으로 나지막한 언덕 형태를 띠고 있다. 오름 정상에는 마을에서 암메(암메창)라 부르는 둥그런 화구가 약 20m 정도의 평지에 있고, 화구 안에는 농경지와 초지, 그리고 묘지가 조성되어 있다. 이 오름은 문헌이나 묘비에 조소악으로 표기되어 있다. 새신 오름의 새신은 ‘새가 있는’이라는 뜻을 지닌 제주어로 초집을 덮는 새가 있는 오름이라는 데서 유래하였다. 한자를 차용하여 조소악 또는 신서악이라고도 한다. 소나무를 비롯하여 다양한 잡목과 수풀이 자리하고 있어 제주의 자연을 그대로 느끼게 해준다.','제주특별자치도 제주시 한경면 청수리','2661-4',33.297828,126.237948,NULL,NULL,'※ 일부 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-10-22 11:09:28'),
('50110','KTO_TOURAPI','1945592','ATTRACTION','송아오름','송아오름은 제주시 한경면 조수리 한양동 사거리 남쪽 도로변에 있으며 완만한 사면의 등성마루는 심한 침식을 받아 원래의 형태를 정확히 파악할 수는 없으나 화구 남쪽이 터진 말굽형 분화구로 추정된다. 오름 전사면은 해송이 숲을 이루고 있으며 동쪽 기슭 도로변에는 예전에 식수로 이용했던 것으로 보이는 못이 있고 못가에는 수령이 백여년 이상으로 추정되는 팽나무 등 노거수목 2그루가 서 있다. 오름에 해송이 많아서 한자로 송악, 송화악이라고 표기하고 있는 것으로 보아 송아오름은 이에 비롯된 이름인 듯하다. 그러나 일부 사람들은 송아지 형체를 하고 있다 하여 송아오름이라 부른다고 한다.','제주 제주시 한경면 조수리 134','송아오름',33.3359,126.2384,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-22 11:08:35'),
('50110','KTO_TOURAPI','1957971','ATTRACTION','제주도 관광특구','한반도의 남서해상에 위치하는 제주도는 특별자치도로 지정된 국내 최대의 관광 지역이다. 전 지역이 관광특구로 지정될 만큼 발길 닿는 곳마다 아름다운 자연 경관이 펼쳐진다. 내외국인을 합쳐 한 해 약 1,500만명 이상의 관광객이 다녀갈 정도로 매력적인 이 섬의 크기는 남북으로 31㎞, 동서로 73㎞에 이른다. 유네스코 3관왕(세계자연유산, 세계지질공원, 생물권보전지역) 지역이며, 세계7대자연경관 지역으로 지정된 제주도는 온대 지방의 특징을 가진 한반도의 육지와는 다른 기후대에 자리했다. 덕분에 아열대에서 아한대에 이르는 제주만의 식생을 보유했다.
제주도의 색다른 자연은 이 섬을 찾은 여행자들의 발길을 붙잡는다. 섬 한가운데 우뚝 솟은 한라산과 산기슭에 솟아 오른 크고 작은 오름이 만들어 내는 풍경, 해안에 펼쳐진 주상절리는 화산섬 제주도를 대표하는 풍경이다. 바다에서 한라산을 향해 오르다 만나는 중산간 지역은 자연이 주는 선물이다. 제주세계자연유산센터가 있는 거문오름을 찾아 중산간의 자연을 탐방하는 것도 좋다. 제주의 방언과 생활풍습도 이색적이다. 해안선을 따라 이어진 182㎞의 일주도로는 자동차는 물론 스쿠터나 자전거를 타고 달리면 좋다. 도보길인 ‘제주올레’를 따라가면 걸어서 제주도를 한 바퀴 돌 수 있다.제주도는 ‘국제관광도시’ ‘국제자유도시’ 라는 이름에 걸맞게 관광은 물론 정치·경제에서도 육지의 자치구들보다 자유롭고 다양한 정책을 펼치고 있어 외국인들에게도 인기 있다.

* 제주도 관광특구 현황
1) 범위 : 제주특별자치도 전역(부속 도서 제외)
2) 면적 : 1,809.56k㎡
3) 관광특구 지정일 : 1994년 8월 31일

* 제주도 관광특구 시설 현황
한라산, 오름, 해안일주도로, 중산간 지역, 제주올레 도보길, 해수욕장, 박물관, 갤러리, 중문 관광 단지 등','제주특별자치도',NULL,33.3911280094,126.4961293824,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-21 16:55:15'),
('50110','KTO_TOURAPI','1960087','ATTRACTION','귤림서원','귤림서원은 제사 기능을 가진 충암묘와 교육 기능을 가진 장수당이 복합되어 이루어진 서원이다. 1578년에 제주판관 조인후가 기묘사화로 제주도에 유배되어 사사된 김정의 넋을 위로하기 위하여 그의 적거지에 사묘를 세운 것에서 비롯되었다. 그 후 1660년 제주목사 이괴가 장수당을 건립하였고, 1667년에는 제주판관 최진남이 김정의 사묘를 장수당 남쪽인 현재의 오현단 안에 옮겨 짓고, 이를 사로 하고 장수당을 재로 하여 귤림서원이라 현액하였다. 1682년 신경윤이 제주목사로 있을 때 예조정량 안건지를 제주도에 파견하여 귤림서원으로 사액을 하고 김정, 송인수, 김상헌, 정온의 4현을 봉향하다가 1696년에 이익태 절제사 때 송시열이 추향됨으로써 5현을 배향하게 되었다. 1871년 서원 철폐령에 의해 폐원되었는데, 1892년 제주 사람 김의정이 중심이 되어 귤림서원 자리에 오현의 뜻을 후세에 기리고자 조두석을 세우고 제단을 쌓아 제사를 지내기도 하였다. 2000년 이후 귤림서원 복원 작업에 들어간 제주시는 학생들이 공부하던 장수당과 협문, 돌담 등을 완성한 데 이어, 2007년 8월 향현사 복원을 마무리 지었다. 조선 시대 유학과 유교 문화의 전당으로 제주 유생들의 지주 역할을 하였던 귤림서원이 복원됨으로써 제주 선현의 정신을 되살리는 계기를 마련할 수 있게 되었다.','제주특별자치도 제주시 이도일동','1438',33.506029,126.527593,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-21 16:53:28'),
('50110','KTO_TOURAPI','1965800','ATTRACTION','높은오름','이 오름은 주변 일대에서 유일하게 고도가 높은 오름으로 능선미가 선하고, 주위에 산재된 뭇 오름을 압도하는 느낌을 주어 높은 오름이라 불리고 있다. 정상에는 원형 굼부리가 세 개의 봉우리를 이어가면서 위용을 자랑하고 있다. 등성이 여기저기에는 크고 작은 바위들이 있고 그 틈새에는 사스레피나무와 부처손이 자라나고 있으며, 등성이 일부에서는 물매화, 미나리아제비, 제비꽃, 피뿌리풀들도 서식되고 있음이 발견된다. 표고가 높기 때문에 정상에서는 사방을 시원스레 조망할 수 있으며, 특히 다랑쉬, 거미오름, 백약이로 이어지는 조망이 매우 뛰어나다.','제주특별자치도 제주시 구좌읍 송당리','산 213-1',33.4573,126.7928,NULL,'https://www.visitjeju.net','※ 일부 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-10-21 16:49:04'),
('50110','KTO_TOURAPI','1973369','ATTRACTION','윗세오름','한라산 정상 밑에 서쪽으로 웃세오름 대피소 주변에 영실등산 코스를 따라서 세 개의 오름이 서로 이어져 있는데, 이 오름들은 세오름(삼형제오름)에 비해 위쪽에 있다고 하여 윗세오름이라고 부르게 되었다. 윗세오름은 한라산 서쪽 등줄기로서 남북의 분수령을 이루며 서귀포시와 제주시의 경계가 되고 있으며, 윗세오름은 각각 독자적인 호칭을 가지고 있는데, 위로 부터 남사면에 붉은 흙이 드러나 있는 것이 붉은오름, 가운데 길게 가로누운 것이 누운오름, 막내격인 작은 오름이 족은오름 또는 새끼오름이라고 부른다. 이들은 삼형제에 빗대어 맏이를 큰오름, 둘째를 샛오름, 막내를 족은오름이라고도 한다. 웃세오름은 봄철 철쭉과 진달래꽃이 필때는 꽃바다를 이루어 아름다운 모습을 볼 수 있다. 붉은오름과 누은오름사이 남쪽 등산로변에 노루샘이 있어 등반객이 많이 이용하고 있다.','제주특별자치도 제주시 애월읍 광령리','산 183-1',33.3608,126.5207,NULL,'http://www.visitjeju.net/','※ 일부 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-10-21 16:47:39'),
('50110','KTO_TOURAPI','2045014','ATTRACTION','유수암마을','유수암마을은 제주공항에서 남서쪽으로 15km 떨어진 지점에 위치하고 있으며 중산간 마을이다. 형제봉 오름들과 맑게 솟아 흐르는 유수암물, 무환자나무 및 팽나무 군락지와 어우러져 천혜의 자연환경을 갖추고 있는 자연생태우수마을이다. 마을 주민들과 함께 할 수 있는 농촌 체험학습을 진행하고, 두부, 오메기떡, 빙떡, 건강색깔수제비, 감귤쨈만들기와 같은 전통음식체험과 전통 초가집 줄놓기, 활쏘기, 녹차밭 승마체험, 목공교실 등 전통문화체험을 다양하게 운영하고 있다. 소박하게 꾸며져 있어 편히 쉬어 갈 수 있는 팜스테이도 있다.','제주특별자치도 제주시 애월읍 유수암평화길 14','(애월읍)',33.4413484581,126.4030757859,NULL,'http://jejuyusuam.co.kr/index.php','※ 체험별로 상이함','연중무휴',90,0,'2026-10-21 16:43:43'),
('50110','KTO_TOURAPI','2503694','ATTRACTION','제주맥주','제주맥주는 30년 양조 노하우를 보유한 뉴욕 No.1 크래프트 맥주사 브루클린 브루어리와 15년 이상 경력의 세계 반열 브루어가 참여하여 탄생한 양조장이다. 좋은 맥주로 맥주 미식 문화를 창조하는 것을 목표로 하고 있다. 국내 최고 양조 시설을 갖추고 있으며, 도슨트의 안내에 따라 체험 및 내부 시설 관람을 할 수 있는 투어 프로그램을 운영하고 있다.','제주특별자치도 제주시 한림읍 금능농공길 62-11','(한림읍)',33.35844999,126.2412538214,NULL,'http://jejubeer.co.kr','12:30~19:30 (양조장PUB 주문 마감 19:00)','매주 월요일, 화요일 / 설, 추석 전날 및 당일',90,0,'2026-10-21 16:29:23'),
('50110','KTO_TOURAPI','2554570','ATTRACTION','제주샘주 양조장','제주샘주는 과거 제주 조상들이 즐겨 마시던 전통주를 제주 청정 지하 암반수로 빚어 재현함과 동시에 현대인의 기호에 맞게 주질을 변형, 발전시키고자 하는 목적으로 운영하고 있다. ‘찾아가는 양조장’에 선정되어 다양한 체험 프로그램을 진행 중인데, 제주 전통주인 ‘고소리 술’과 ‘오메기 술’을 직접 맛보고, 술이 만들어지는 과정도 알아갈 수 있다. 오메기떡 체험, 쉰다리 체험, 칵테일 만들기 체험 등이 가능하다. 제주도에서 특별한 경험을 해보고 싶다면, 제주샘주에 들러보기를 추천한다.','제주특별자치도 제주시 애월읍 애원로 283',NULL,33.4444387208,126.3373984952,NULL,'https://www.jejusaemju.co.kr/','09:30~18:00 (휴게시간 12:00~13:00)','설·추석 연휴',90,0,'2026-10-21 16:20:14'),
('50110','KTO_TOURAPI','2606209','ATTRACTION','화조원','제주 화조원(花鳥園)은 다양한 새들과 알파카 등 온순한 소동물들을 가까이에서 보고, 직접 만지며 교감할 수 있는 체험형 조류 동물원이다. 단순히 관람만 하는 공간이 아니라 아이부터 어른까지 자연스럽게 동물과 소통할 수 있도록 구성되어 있어 가족 단위 방문객들에게 특히 인기가 많다. 하루 4차례 진행되는 조류생태설명회에서는 사육사가 직접 새들의 생태와 습성을 설명해 주어 시간대에 맞춰 방문하면 더욱 알찬 관람이 가능하다. 조류 외에도 토끼, 잉어, 미니말 등 다양한 소동물에게 먹이를 주는 체험이 마련되어 있어 아이들이 배우며 즐거운 추억을 쌓을 수 있는 공간이다.','제주특별자치도 제주시 애월읍 애원로 804',NULL,33.4113070173,126.3720043562,NULL,'http://flowerbirdpark.com','[하절기(3월~10월)]09:00~18:00 (입장 마감 17:00)[동절기(11월~2월)]09:00~17:30 (입장 마감 16:50)','연중무휴',90,0,'2026-10-21 16:16:50'),
('50110','KTO_TOURAPI','2606696','ATTRACTION','제주대 벚꽃길','제주대 벚꽃길은 제주도에서 가장 유명한 벚꽃 명소 중 하나이다. 제주시청을 지나 1131번 도로를 타고 내려가다 보면 왼편으로 제주대학교 진입로가 나타난다. 제주대학교 입구까지 도로변에 벚나무들이 즐비하게 늘어서 있으며, 만개한 벚꽃을 보기 위해 많은 이들의 발걸음이 이어지고 있다. 꽃 터널을 지나가는 듯한 환상적인 기분을 느낄 수 있는 드라이브 코스로, 만개한 꽃송이가 떨어지는 광경이 눈이 내린 설경을 보는 것 전해질 정도로 아름다운 벚꽃길을 만끽할 수 있다.','제주특별자치도 제주시 제주대학로 102',NULL,33.4579157425,126.5623994797,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-21 16:14:23'),
('50110','KTO_TOURAPI','2704232','ATTRACTION','성불오름','성불오름은 구좌읍 송당리에 있는 소화산체이다. 성불오름이라는 이름은 오래전 이 오름에 있었던 성불암이라는 암자에서 비롯되었다는 설과, 오름의 모습이 승려가 불공을 올리는 모습을 떠올리게 하는 데서 붙여졌다는 설이 존재한다. 넓게 펼쳐진 마목장을 지나면 오름 입구가 나오며, 탐방로가 갈려져 있는데 어느 방향으로 가더라도 한 바퀴 돌아서 만나게 이루어져 있다. 이 오름은 말굽형 분화구를 지녔는데, 남쪽 봉우리에서 북쪽 봉우리에 이르는 등성마루에 둘러싸여 동향으로 살짝 파여있다.','제주특별자치도 제주시 구좌읍 중산간동로 2532',NULL,33.4219,126.7485,NULL,NULL,'※ 일부 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-10-21 16:08:10'),
('50110','KTO_TOURAPI','2704703','ATTRACTION','당산봉','당산봉은 세계지질공원 주요 명소인 곳으로, 올레 12코스의 끝자락에 있다. 당산봉은 오래전부터 당오름이라고도 불렸는데, 당이 신당을 뜻하는 말로, 옛날 당산봉 기슭에 뱀을 신으로 모시는 신당이 있었다고 하여 붙여진 이름이다. 당산봉은 물과 마그마의 폭발적인 반응에 의해 형성된 수성화산체로 안덕면에 있는 산방산, 용머리와 더불어 제주도에서 가장 오래된 화산체 중 하나이다. 당산봉 정상까지 경치를 감상하면서 오르다 보면 정상 바로 밑으로 거북바위와 전망대가 있다. 전망대에서 북쪽으로는 신창 풍차해안도로가 이어지고 남쪽으로는 수월봉, 산방산까지의 푸른 해안이 한눈에 펼쳐진다. 푸른 해안과 함께 한경면의 고즈넉한 평야의 풍경을 즐기는 것 또한 일품이다.','제주특별자치도 제주시 한경면 고산리','산 15',33.307779,126.172787,NULL,'https://www.visitjeju.net/kr/','※ 출입 통제 구역이 있어 방문 시 전화문의 요망','※ 출입 통제 구역이 있어 방문 시 전화문의 요망',90,0,'2026-10-21 16:06:51'),
('50110','KTO_TOURAPI','2705296','ATTRACTION','물뫼힐링팜','물뫼힐링팜은 자연, 농업과 함께 상생하며 다양한 치유 프로그램을 운영하고 있는 치유 농장이다. 밭담트레킹, 명상, 작물재배, 힐링 푸드 등 다양한 치유 프로그램을 통해 내 몸 안의 자연치유 기능을 깨우고 몸과 마음의 자유를 찾는 것을 목표하고 있다. 계곡 트레킹, 계곡 명상, 트레킹, 치유농장 등 다양한 체험을 하며 몸과 마음을 치유하는 여행을 경험해 볼 수 있다.','제주특별자치도 제주시 애월읍 예원로 51',NULL,33.4642345777,126.3965564296,NULL,NULL,'※ 체험별로 이용시간 상이하므로 전화문의 바람','연중무휴',90,0,'2026-10-21 16:05:39'),
('50110','KTO_TOURAPI','2714826','ATTRACTION','수산봉','애월읍 수산리에 있는 수산봉은 소화산체이다. 동그란 형태의 분화구를 지니고 정상에 물이 고인 작은 연못이 있어 물메오름 혹은 정상에 봉수가 있어 수산봉이라고 불린다. 제주 올레 16코스에 포함되어 올레길을 따라가다 보면 수산봉 근처에 있는 수산저수지와 곰솔을 지나 수산봉 정상에 오르게 된다. 수산봉은 계단과 길이 잘 다듬어져 있어 어린 자녀와 함께 오르는 가족단위 여행객도 많다. 수산봉의 산행시간은 약 20분 정도 소요되며 주변을 둘러보며 올라갈 계획이라면 40분 정도 계획을 하고 가면 된다.','제주특별자치도 제주시 애월읍 수산리 산1-1',NULL,33.4732,126.385,NULL,'https://www.visitjeju.net/kr','※ 일부 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-10-21 16:02:08'),
('50110','KTO_TOURAPI','2723555','ATTRACTION','평대해변','평대해변은 동쪽의 명소인 월정리해변과 세화해변 사이에 자리하고 있으며, 제주올레 20코스가 지나는 곳이다. 구좌읍 평대리는 당근 생산지로 전국 최고인 곳이지만, 뱅듸라는 옛 이름을 간직한 시골마을이다. 해변이라기엔 작은 편이여서 덜 알려진 바다이다. 바닥에 모래까지 투명하게 비칠 정도로 깨끗다. 바다 빛깔은 옆동네인 세화나 월정에서 보던 것만큼 여전히 아름답다.
아담한 해변은 아이들과 물놀이, 모래놀이를 하기에도 좋고, 한적한 해변은 나만 알고 싶은 제주바다로 손색이 없다.

(출처 : 제주 문화관광 홈페이지)','제주특별자치도 제주시 구좌읍 평대리 1994-20',NULL,33.5332086982,126.8405857846,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-21 15:56:56'),
('50110','KTO_TOURAPI','2724387','ATTRACTION','안돌오름','구좌읍 송대천간 도로 건영목장 입구 주변에서 서쪽방향으로 바라보면 세 오름이 나란히 있는데, 제일 왼쪽의 도로가에 붙어 있는 것이 거슨세미, 오른쪽에 나란히 안돌오름, 밧돌오름이다. 남서쪽에 있는 안돌오름은 안쪽에 들어앉아 있어서 안돌오름(內石岳)이라 부르고 있으며, 웃송당에서 송당공동묘지를 돌아 들어가면 오름 앞에 이르게 된다. 안돌오름은 북서쪽 봉우리가 정상이고, 남동쪽 봉우리와의 사이에 동쪽으로 골이 파여 있는 형태로 말굽형 화구를 이루면서, 화구 안사면의 골이 패인 곳에서만 유일하게 나무가 우거져 자연림의 숲을 이루고 있는 특징을 보이며, 그 외 사면은 매끈한 풀밭오름이다.','제주특별자치도 제주시 구좌읍 송당리 산 66-2',NULL,33.4572744947,126.7560703896,NULL,'https://www.visitjeju.net','※ 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-10-21 15:49:19'),
('50110','KTO_TOURAPI','2738665','ATTRACTION','도두봉','도두봉은 제주공항 북쪽 도두동 해안가에 있는 오름으로, 경사가 완만하여 오르기 쉬운 편에 속한다. 남사면은 풀밭을 이루며 듬성듬성 해송이 자라고, 북사면은 삼나무와 낙엽수 등이 어우러져 숲을 이룬다. 봉우리는 두 개이며, 동쪽 봉우리가 더 높다. 주변에는 국수나무, 팥배나무, 덜꿩나무, 예덕나무를 비롯해 여러 종류의 새우란과 바람꽃 등 다양한 자생식물이 자라고 있다.
오르는 길과 정상에서는 제주국제공항에서 비행기가 뜨고 내리는 모습을 볼 수 있으며, 푸른 바다와 어우러진 풍경이 장관을 이룬다. 특히 정상 부근에는 나무들이 맞물려 초콜릿 ‘키세스’를 닮은 모양을 이루는 유명한 포토존인 ‘키세스존’이 있어 방문객들에게 인기가 많다. 나무 사이로 바다를 배경 삼아 사진을 찍을 수 있어 특별한 추억을 남기기에도 좋다. 이처럼 도두봉은 규모가 작은 오름이지만 아름다운 자연경관과 독특한 포토존을 함께 즐길 수 있는 매력적인 장소이다.','제주특별자치도 제주시 도두항길 4-17 (도두일동)',NULL,33.5082,126.4688,NULL,'https://www.visitjeju.net/','※ 상황에 따라 출입이 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-10-21 15:47:47'),
('50110','KTO_TOURAPI','2738692','ATTRACTION','용연구름다리','용연구름다리는 제주공항 서쪽에 위치한 다리이다. 용연은 제주시 용담동에 위치한 계곡의 물이 유입되는 하천으로, 산등성이부터 바닷가로 흘러 바닷물과 민물이 만나 신비로움을 선사한다. 용연은 가뭄이 들어도 물이 마르지 않아 이곳에 살던 용이 승천해 비를 내리게 했다는 전설이 내려온다. 물이 풍부해 선인들이 풍류를 즐긴 장소로도 이용되었다. 출렁다리로 연결된 용연구름다리는 용연의 기암절벽 사이를 잇는, 현수교 형태이다. 붉은빛이 감도는 정자와 에메랄드빛 계곡이 어우러진 경관을 감상할 수 있다. 특히 야경이 멋진 곳으로, 저녁 산책코스로 좋다. 밤이면 다리에 켜지는 불빛들과 잔잔한 호수, 그리고 우거진 나무숲들이 어우러진 모습을 볼 수 있다. 또한 제주올레 17코스가 통과하는 곳으로 제주 자연의 아름다움과 은은함을 느낄 수 있다.','제주특별자치도 제주시 흥운길 73 (용담이동)','2581',33.5152034016,126.513987656,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-21 15:44:44'),
('50110','KTO_TOURAPI','2738683','ATTRACTION','연대포구','연대포구는 ‘마지리포’라고도 불린다. 이곳은 예전 제주 포구의 모습 그대로를 가장 잘 보존하고 있는 포구 중 하나다. 포구의 모습뿐만 아니라 포구 근처에 해녀 탈의장과 물질에 사용했던 테왁이나 망사리 같은 도구들이 탈의장 한편에 보관되어 있다. 
연대포구에서는 산책도 즐길 수 있다. 포구가 있는 연대마을에서 외도 1동까지 산책로를 조성했으며, 외도동 해안에는 친수공원도 만들었다. 
제주에는 해안 산책로가 예쁜 곳이 많지만 그중에서도 연대 포구 해안 산책로는 동네 주민들이 적극 추천할 정도로 일몰이 예쁘고 산책로에서 보는 포구의 모습이 평화롭다.','제주특별자치도 제주시 외도이동',NULL,33.495,126.4267,NULL,'https://www.visitjeju.net/kr/','상시 개방','연중무휴',90,0,'2026-10-21 15:37:59'),
('50110','KTO_TOURAPI','2738701','ATTRACTION','월정리해안도로','월정리해안도로는 풍차와 애매랄드 빛 바다를 보며 드라이브를 즐기기 좋은 곳이다. 월정리해안도로의 정식 명식은 ‘김녕-오조해안도로’로 김녕부터 성산 오조리까지 이어지는 긴 해안도로인데, 여러 사람들이 찾는 예쁜 해수욕장이나 유명 카페들이 월정리에 많이 있어서 인지 월정리해안도로라 불리고 있다. 월정리해변 바로 앞에는 많은 카페들이 있어서 성수기와 비성수기를 불문하고 관광객이 많지만, 이 구간만 벗어나면 도로는 비교적 한적하다.

(출처 : 제주 문화관광 홈페이지)','제주특별자치도 제주시 구좌읍 월정리 652-4',NULL,33.5565802339,126.7949200402,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-21 15:36:12'),
('50110','KTO_TOURAPI','2738705','ATTRACTION','용담해안도로','용두암부터 도두봉까지 이어지는 6㎞의 해안도로로, 제주도민들이 즐겨 찾는 드라이브 코스다. 특히 밤에 더욱 화려한 빛을 발한다. 올레 17코스 중 일부다. 정식 명칭은 ‘서해안로’지만, 제주 유명 관광지인 용두암과 가까이 자리하고 있어 용두암 해안도로 또는 용담 해안도로로 알려져 있다. 해안도로 중간중간 차를 대고 바다를 볼 수 있는 공원이 조성되어 있고, 바다를 비추는 조명도 설치되어 있어 밤낮으로 바다를 보기 위해 찾는 사람들이 많다. 해안도로의 마지막은 도두봉이 자리 잡고 있다. 도두봉은 경사가 완만해 누구나 올라가기 편하다. 특히, 도두봉은 노을 명소로도 유명한 오름이고 공항과 가깝기 때문에 제주도에 도착한 직후 또는 비행기 탑승하러 가기 직전에 들르기 좋다.','제주특별자치도 제주시 서해안로 687-8 (용담이동)',NULL,33.5155488078,126.5120931079,NULL,'https://www.visitjeju.net','상시 개방','연중무휴',90,0,'2026-10-21 15:33:30'),
('50110','KTO_TOURAPI','2740127','ATTRACTION','느지리오름','느지리오름은 어린이나 어르신들도 가볍게 오를 수 있는 오름으로, 상명리의 옛 이름인 느지리에서 유래된 이름이다. 16세기 이후 봉수가 설치되면서 망오름으로 불리기도 한다. 그만큼 오름 정상에 오르면 제주도 북서부 전역을 둘러볼 수 있을 정도의 넓은 시야를 자랑한다. 전망대까지 오르는 길은 나무가 우거져 있어 숲을 걷는 듯한 기분을 느낄 수 있고, 맑은 날에는 정상 전망대에서 한라산을 비롯한 북서부 오름을 두루두루 조망할 수 있다. 특히 정상에서 바라보는 해안과 석양의 모습은 장관으로 널리 알려져 있다. 전망대에서 선명하게 찾아볼 수 있는 새별오름부터 조금은 낯선 바리메오름, 북돌아진오름, 이달봉까지 찬찬히 돌아보며 안내판과 오름의 실제 모습을 비교하며 살펴보는 재미도 있다. 등산로가 오름의 완만한 능선과 두 개의 굼부리 둘레를 따라 조성되어 있어 급경사가 거의 없이 평탄하게 이어져 있다.','제주특별자치도 제주시 한림읍 봉수대길 5',NULL,33.3659,126.2615,NULL,'https://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-10-21 15:29:49'),
('50110','KTO_TOURAPI','2740135','ATTRACTION','알작지','제주시 내도동에 있는 알작지 해변은 평범한 모래사장으로 이루어진 해변과는 다르게 동글동글한 돌들로 이루어진 해변이다. 동그란 ‘알’과 돌멩이를 뜻하는 제주도 말 ‘작지’가 합쳐져 만들어진 알작지는 몽돌해변이다. 알작지의 자갈들은 한라산 계곡에서부터 운반되어 퇴적된 것들로, 오랜 세월 동안 무수천과 월대천을 따라 이곳 알작지까지 운반되는 동안 파도에 의해 다듬어지는 과정을 겪었기 때문에 자갈의 모양이 더욱더 동글동글하다. 알작지는 독특함과 아름다움을 공식적으로 인정받아 지난 2003년 12월, 문화유산으로 지정되었다. 진하고 동그란 먹돌과 차돌로 이루어진 해안가와 부서지는 파도가 어울리는 알작지 해변의 이국적인 풍경에 전문 사진작가들도 즐겨 찾는다. 바로 옆이 도심지인데도 불구하고 알작지는 한적하고 조용한 분위기를 만끽할 수 있어, 일상에 지친 시민들이 힐링하며 휴식을 취하기에 적합한 장소이다.','제주특별자치도 제주시 테우해안로 60',NULL,33.496,126.4397,NULL,'https://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-10-21 15:27:56'),
('50110','KTO_TOURAPI','2742297','ATTRACTION','월령포구','월령포구는 4·3 사건 당시 청년들이 산으로 올라가는 것을 방지하기 위해 마을 향장이 이 일대를 청년들 손으로 일일이 쌓도록 하였다. 그렇게 만들어진 포구는 현재에도 많은 어선들이 이용하고 있다. 특히 월령포구 방파제와 갯바위는 낚시 포인트로 낚시를 좋아하는 분들이 찾아와 낚시를 즐기는 곳이다. 무엇보다 인근 협재해수욕장이나 금능으뜸원 해변에 비해 조용하기 때문에 차분히 제주도 바다를 느낄 수 있다. 출어 준비를 위해 그물을 재정비하는 모습도 보고 방파제를 따라 걸으며 사색에 잠겨보는 것도 제주바다를 느끼는 방법 중에 하나다.
포구 인근에는 제주도의 독특한 자연경관을 보여주는 월령리 선인장 군락이 자리하고 있다. 해안가의 검은 현무암 돌담과 바위틈을 따라 자라는 손바닥 모양의 선인장은 푸른 바다와 어우러져 이곳만의 이색적인 풍경을 만들어낸다.

(출처 : 비짓제주)','제주특별자치도 제주시 한림읍 월령리 317-1',NULL,33.37852226,126.2163001391,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-21 15:26:29'),
('50110','KTO_TOURAPI','2742373','ATTRACTION','청수곶자왈','곶자왈이란 제주어로 ‘곶(숲)’과 ‘자왈(덤불)’의 합성어로 제주의 천연 원시림이라고 할 수 있다. 화산 활동 때 분출된 용암 위에 만들어진 곶자왈은 세계에서 유일하게 열대 북방한계 식물과 한대 남방한계 식물이 공존하는 제주의 독특한 지형이다. 청수 곶자왈은 제주도 내 최대 \'운문산 반딧불이\'의 서식지인 만큼 청정하게 유지되고 있는 생태 숲이다. 저녁이 되면 반딧불이의 빛이 만들어내는 동화 같은 신비함을 눈에 담을 수 있다. 반딧불이는 날씨에 영향을 많이 받기 때문에 아름다운 반딧불이의 빛을 보기 위해서는 날씨를 확인하고 오는 것이 좋고, 입장 시에는 어두운 옷을 착용해야 한다. 청수 곶자왈은 산책로도 잘 정비되어 있어 낮에 가볍게 산책을 즐기기에도 좋다. 곶자왈의 맑은 공기와 시원한 바람, 나무들의 속삭임을 들을 수 있는 곳이며, 평온함을 주는 곳이기에 일상에서 벗어나 한때의 여유로움을 느낄 수 있다.','제주특별자치도 제주시 한경면 연명로 348',NULL,33.3,126.2618,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-21 15:23:16'),
('50110','KTO_TOURAPI','2759120','ATTRACTION','고스트타운','고스트타운은 유령을 소재로 하여 유령의집, 유령미로, 공포가상현실 등 이색체험을 비롯하여 휴양 펜션, 해물요리전문테마식당, 카페, 편의점 등 쉴 곳과 각종 먹거리까지도 준비되어 있는 종합 테마파크이다. 제주 고스트타운은 가족, 친구들과 함께 방문하기 좋은 장소로, 신비롭고 색다른 여행을 선사한다.

(출처 : 고스트타운 홈페이지)','제주특별자치도 제주시 애월읍 부룡수길 35-14',NULL,33.4763658659,126.3568542953,NULL,NULL,'10:00~22:00','연중무휴',90,0,'2026-10-21 15:06:04'),
('50110','KTO_TOURAPI','2765233','ATTRACTION','용수성지','제주시 한경면 용수리 해안은 성 김대건 안드레아 신부가 중국 상해에서 출발해 서해로 귀국하다가 표착한 곳이다. 김대건 신부는 한국인 최초로 상해에서 사제품을 받았는데, 라파엘 호를 타고 귀국하던 중 큰 폭풍우를 만나 표류하다가 용수리 해안으로 오게 됐다고 한다. 이후 경기도 용인에서 사목 활동을 하다가 순교하였는데, 이 선교 열정과 순교 정신을 기리기 위해 용수리 포구를 성지로 선포하고 기념 성당과 기념관, 라파엘 호를 복원해 전시하고 있다. 올레길 12코스와 13코스의 연결지점인 용수 포구에 있어 천주교 신자가 아니더라도 한 번쯤 들러보기 좋은 곳이다.','제주특별자치도 제주시 한경면 용수1길 108',NULL,33.3228613088,126.1677281247,NULL,NULL,'09:00~18:00※ 자체 개별 미사 신청은 오후 시간대에만 가능','연중무휴',90,0,'2026-10-21 15:03:29'),
('50110','KTO_TOURAPI','2765268','ATTRACTION','저지문화예술인마을','제주시 한경면 저지리에 위치한 저지예술마을, 일명 새오름이라 하는 저지악이 마을 중심에 있어 풍광이 독특하고, 전국의 유명 예술인들이 모여 작품을 생산하는 문화예술인촌이 형성돼 있어 문화적 향취가 남다르다. 또 동양 최대의 분재 정원으로 알려진 생각하는 공원과 세계적으로도 희귀한 천연 난대림 지역인 곶자왈, 야생화가 지천인 방림원 등 이색 공간이 많아 제주의 문화와 함께 볼거리까지 풍성하게 돌아볼 수 있다.

(출처 : 제주 문화관광 홈페이지)','제주특별자치도 제주시 한경면 저지14길 28-4',NULL,33.3395129587,126.2671182747,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-21 15:01:20'),
('50110','KTO_TOURAPI','2767885','ATTRACTION','하우목동항','성산 일출봉 남쪽 바다에 자리한 우도는 매년 그 아름다운 풍광을 즐기기 위해 많은 방문객이 찾는 섬이다. 이 섬에는 2개의 항구가 있는데, 우도의 관문 항구인 천진항과 섬 중간에 자리한 하우목동항이 바로 그것이다. 천진항보다 크기는 작지만, 하얀 산호가 해안으로 밀려와 쌓인 서빈백사가 가까이 있다는 장점이 있다. 본섬으로 돌아갈 때는 구매한 티켓으로 하우목동항과 천진항 두 곳에서 모두 배를 탈 수 있어 처음에 천진항으로 입도했다면, 돌아갈 때는 하우목동항을 이용해 봐도 좋다. 성산항과 종달항에서 10~15분 정도가 소요된다.','제주특별자치도 제주시 우도면 우도해안길 352',NULL,33.5095675391,126.9435146093,NULL,NULL,'07:30~18:00 ※ 30분 간격 운항 ※ 정원의 초과, 물때, 화물, 날씨에 따라 도착항이 변경 또는 조금 빨라지거나 지연될 가능성이 있음','연중무휴※ 배 이용 시 배편 시간 확인 요망',90,0,'2026-10-21 14:58:28'),
('50110','KTO_TOURAPI','2774278','ATTRACTION','선흘2리마을','제주시 조천읍에 속하는 선흘 2리는 해발고도 200m~400m의 중산간 평지에 자리한 마을이다. 선흘이란 이름은 잡풀이 우거진 넓은 돌밭, 즉 곶자왈에서 유래한 이름으로 추측된다. 마을 내에는 곶자왈 외에도 알밤 오름, 윗밤 오름, 우진 제비 오름, 거문 오름, 부대 오름, 민 오름, 부소 오름 등 다수의 오름이 분포한다. 특히 거문 오름은 유네스코가 선정한 세계 자연유산으로, 선흘 2리는 이를 보존하기 위한 세계 자연유산마을로 지정돼 다양한 생태활동이 이뤄진다. 화산섬인 제주에서만 볼 수 있는 빌레(너럭바위)와 습지가 어우러진 흐린내 생태공원도 선흘 2리 마을의 절경으로 꼽힌다. 집들이 옹기종기 모여 앉은 마을 풍경과 계절마다 피고 지는 다양한 꽃들이 걷는 재미를 더한다.','제주특별자치도 제주시 조천읍 선교로 569-36',NULL,33.4568766427,126.714279835,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-21 14:53:05'),
('50110','KTO_TOURAPI','2778044','ATTRACTION','전농로 벚꽃거리','제주공항에서 자동차로 10분이면 도착할 수 있는 전농로는 하늘을 가득 메운 벚꽃터널이 인상적인 벚꽃길이다. 구도심인 삼도일동에 자리한 전농로는 약 왕복 2차선 도로로, 양쪽 도로변을 따라 제주 지역 자생종인 왕벚나무가 끝없이 이어져 있다. 짧게는 20년에서 많게는 100년 이상 된 이곳 왕벚나무들이 피우는 꽃은 제주에서도 아름다운 벚꽃명소로 유명하다. 해마다 봄이면 거리 가득 흐드러진 벚꽃이 그야말로 꽃 천지를 이룬다. 1992년부터 전농로를 배경으로 왕벚꽃축제도 열리고 있다. 연인과 데이트 혹은 가족들과 봄에 벚꽃구경을 하며 추억을 남길 수 있는 거리이다.','제주특별자치도 제주시 삼도일동',NULL,33.5044,126.5163,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-21 14:49:33'),
('50110','KTO_TOURAPI','2791450','ATTRACTION','성산세화해안도로','제주도 동쪽 끝자락의 해안을 따라 형성된 해안도로로, 구좌읍 세화리에서 서귀포시 성산읍 성산리까지 이어진다. 총 길이는 15.8㎞로 제주도 해안도로 중 가장 길이가 길며, 아름답기로 유명해 사람들이 많이 찾는다.
바다를 끼고 길게 이어지는 해안도로를 따라 자전거 전용도로가 마련돼 있어 드라이브를 즐기려는 관광객뿐만 아니라 자전거 타기와 하이킹을 하는 사람들도 많이 찾는다. 주변 관광지로는 외세의 침입에 대비해 조선 시대에 축조한 성곽인 별방진, 넓은 백사장과 맑은 바닷물을 자랑하는 하도해수욕장, 세화해수욕장 등이 있다.','제주특별자치도 제주시 구좌읍 종달리 112-1','시작점',33.5100596893,126.9065135348,NULL,'https://www.visitjeju.net/kr','상시 개방','연중무휴',90,0,'2026-10-21 14:48:05'),
('50110','KTO_TOURAPI','2791511','ATTRACTION','제주항','제주항은 제주 국제공항에서 차로 약 15분 거리에 떨어져 있는 국제 무역항으로, 제주도의 무역, 물류, 여객 수송의 역할을 모두 전담하는 주요 항구이다. 제주도 화물의 약 70%를 담당하고 있으며, 육지로부터 들어오는 대부분의 물류는 제주항을 통해 들어온다. 여객터미널로는 연안 터미널과 국제 터미널을 운영 중이며, 목포와 여수, 부산, 완도 등을 오가는 여객선이 운항하는 곳이다. 비행기와 달리, 자기 차량을 배에 싣고 제주도를 올 수 있다는 장점이 있어 여객선을 이용하는 사람이 많은 편이다.','제주특별자치도 제주시 임항로 111','(건입동)',33.5200386112,126.5342256801,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-21 14:46:31'),
('50110','KTO_TOURAPI','2791433','ATTRACTION','고내포구','제주시 애월읍에 자리한 고내 포구는 에메랄드빛 제주 바다를 감상할 수 있는 애월읍 해안도로를 따라 달리다 보면 지나게 되는 작은 포구이다. 여유롭고 고즈넉한 어촌 마을의 분위기가 가득한 이곳은 맑고 깨끗한 바다와 올레길 16코스로 인해 관광객이 많이 찾는 곳이다. 바다를 향해 길게 나 있는 방파제에는 사진을 찍으려는 사람들은 물론, 의자를 펴고 취미 낚시를 즐기는 사람을 종종 볼 수 있다. 물이 워낙 맑아서 바다를 들여다보면 물고기가 돌아다니는 모습이 직접 보일 정도다. 제주 올레길 16코스의 시작이자 15코스의 종점이기도 하다.','제주특별자치도 제주시 애월읍 고내리 1111-4',NULL,33.4670277639,126.3379034933,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-21 14:45:53'),
('50110','KTO_TOURAPI','2946074','ATTRACTION','금능포구','금능포구는 활기찬 해수욕장과는 또 다른 분위기로 한적하고 평화로운 바다의 모습을 감상할 수 있는 곳이다. 작은 선박들이 드나드는 작은 포구로 아담한 느낌이 있다. 어선들이 정박해 있는 모습이 마치 그림처럼 아름답다. 이곳은 2022년도 TVN 방영 드라마 드라마 속 많은 장면의 배경이 된 곳이며 해녀들의 대화 장소였던 정자가 있는 공터도 드라마를 본 이들에겐 특별하다. 극 중 박정준(김우빈)이 버스를 주차해 두고 이영옥(한지민)과 오붓한 시간을 보내곤 했던 장소이기 때문이다. 그 뒤로 보이는 방파제로 들어서면 귀여운 벽화가 그려져 있고 그 끝에 하얀 등대가 있다. 그 주변에는 많은 돌탑들이 쌓여있는데 하얀 등대와 돌탑을 배경으로 멋진 풍경 사진을 찍으며 추억을 남기기 좋은 장소이다.','제주특별자치도 제주시 한림읍 금능리',NULL,33.3902,126.2351,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-21 14:06:28'),
('50110','KTO_TOURAPI','2767900','ATTRACTION','용담공원','용담공원은 용두암 근처에 있는 작은 공원으로, 용연 다리와도 연결된 도심 속의 자그마한 쉼터이다. 근처 관광지인 용두암은 기암괴석 사이에 있는 용머리 모양의 관광 명소이며, 용연 다리는 용담 공원과 건너편을 잇는 거대한 출렁다리다. 밤이면 화려한 조명이 켜지면서 아름다운 야경을 자랑한다. 다리 건너편 용담공원은 비록 규모가 크지는 않지만, 오밀조밀 잘 꾸며놓아 산책하기에 좋다. 나무 벤치와 조각상이 설치되어 있어 해안을 바라보며 잠시 쉬었다가 갈 수도 있다.','제주특별자치도 제주시 용담일동','373-5',33.5139382278,126.515190955,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-18 14:01:12'),
('50110','KTO_TOURAPI','127745','ATTRACTION','용연','용연은 제주시 용담동에 위치한 호수로 계곡의 물이 유입되는 것이 특징이다. 산등성이부터 바닷가로 흐르는데, 바닷물과 민물이 만나 신비로움을 선사한다. 용연은 가뭄이 들어도 물이 마르지 않아 이곳에 살고 있는 용이 승천하여 비를 내리게 했다는 전설이 내려오기도 하고, 선인들이 풍류를 즐긴 장소로도 이용되었다고 한다.
나무로 연결된 용연구름다리는 용연 사이를 잇는 역할을 하며, 붉은빛이 감도는 정자와 에메랄드빛 계곡이 마치 그림의 한 폭처럼 어우러진 경관을 감상할 수 있다. 용연구름다리는 야경이 멋진 곳으로, 저녁 산책 코스로 손색이 없다. 밤이면 다리에 켜지는 형형색색의 불빛들과 잔잔한 호수, 그리고 우거진 숲이 장관을 이룬다. 제주 올레 17코스가 통과하는 이곳은 제주공항에서 차로 약 10분 정도 달리면 만날 수 있는 곳으로, 제주 자연의 아름다움과 은은함을 느낄 수 있다.
인근 명소로는 용머리 형상의 바위인 용두암, 제주의 역사를 담고 있는 가장 오래된 건물인 관덕정 등이 있다.','제주특별자치도 제주시 흥운길 73 (용담이동)',NULL,33.5151831924,126.5139006852,NULL,'https://www.visitjeju.net','상시 개방','연중무휴',90,0,'2026-10-18 13:55:20'),
('50110','KTO_TOURAPI','2652545','ATTRACTION','닭머르해안길','닭머루 입구에서 신촌포구까지의 구간으로 나무데크로 이어진 전망대와 산책로가 있으며, 가을에서 초겨울까지가 닭머르 해안길을 방문하기에 좋다. 닭머르 바위는 마치 닭이 흙을 파헤치고 그 안에 들어앉은 모습을 닮았다하여 이름이 붙여졌다. 아름다운 바다 전망을 자랑하는 이곳은 도민들은 이미 잘 알고 있는 곳이지만, 아직 여행객들에게는 잘 알려지지 않았다. 그렇기에 한적하게 산책을 즐기며 사진을 찍기에 제격인 장소이다. 닭머르 바위가 있는 곳은 나무갑판으로 길이 만들어져 있고, 그 길의 끝엔 해안정자가 자리 잡고 있다. 해안정자까지 이르는 길은 가을을 맞아 풍성해진 억새가 사진 찍기에 더없이 좋은 배경을 만들어준다. 특히 이곳은 일몰 장소로도 손꼽히는 곳이기에 해가 지기 바로 직전에 사진을 담는 것을 추천한다. 억새와 저물어가는 가을 해가 아름다운 배경과 조명을 만들어 줄 것이다.

(출처 : 제주 문화관광 홈페이지)','제주특별자치도 제주시 조천읍 신촌리 3403',NULL,33.5367573216,126.6173595815,NULL,'https://www.visitjeju.net','상시 개방','연중무휴',90,0,'2026-10-16 10:58:51'),
('50110','KTO_TOURAPI','2751854','ATTRACTION','도치돌 알파카목장','푸른 섬 제주 애월 숲 속에 있는 도치돌목장은 너른 초원을 자유롭게 다니는 알파카들을 만날 수 있는 곳으로 유명하다. 알파카들과 걷고 뛰고 교감하며 먹이 주기 체험을 할 수 있고 토끼, 포니, 말, 양, 염소 등 다양한 동물들을 만나볼 수 있어 남녀노소를 불문하고 인기가 좋다. 목장 산책로 곳곳에 피어있는 계절 꽃들이 여행의 낭만을 더해준다. 양옆으로 빼곡히 세워진 나무 덕에 자연을 체감할 수 있는 초록숲 산책길부터, 봄의 유채꽃밭, 여름의 능소화 기둥, 가을의 억새밭, 겨울의 동백 꽃밭으로 사계절 아름다운 자연을 만끽할 수 있다. 제주 자연을 그대로 살린 도치돌목장을 배경으로 동물들과 함께 멋진 사진을 남겨보자.','제주특별자치도 제주시 애월읍 도치돌길 303',NULL,33.4097232581,126.3667613632,NULL,NULL,'[하절기(2월15일~11월)]- 10:00~18:00- 입장 마감 17:00[동절기(12월~2월14일)]- 09:30~17:30- 입장 마감 17:00','연중무휴※ 내부 사정에 따른 비정기적 휴무일은 공식 인스타그램 공지 참고',90,0,'2026-10-15 16:03:03'),
('50110','KTO_TOURAPI','2742344','ATTRACTION','새별프렌즈','새별프렌즈는 제주 애월읍 새별오름 맞은편에 있는 목장이다. 제주공항, 중문 등 주요 관광지에서 가까워 접근성이 좋다. 제주도의 아름다운 자연경관과 함께 알파카, 말, 당나귀, 양, 흑염소, 토끼 등 다양한 동물들과 직접 교감을 나눌 수 있다. 당근 스틱을 구매하면 알파카와 당나귀에게 먹이 주기 체험을 할 수 있고 초원에서 승마체험을 할 수 있다. 다양한 체험 프로그램으로 가족 관광객들에게 인기가 많다. 마차를 타며 제주의 자연을 즐길 수 있고 자연을 배경으로 사진을 찍으며 힐링을 즐길 수 있다.','제주특별자치도 제주시 애월읍 평화로 1529',NULL,33.361554342,126.3636618097,NULL,'https://www.instagram.com/sbfriends_official','09:00~18:00 (입장 마감 17:00)','연중무휴',90,0,'2026-10-14 13:21:30'),
('50110','KTO_TOURAPI','3027466','ATTRACTION','달달미깡감귤밭','달달미깡감귤밭은 감귤이 맛있기로 소문난 남원읍에 위치해 있다. 주변에 건물도 없고 깨끗하게 관리가 잘 되어있어 방문객들의 반응도 좋다. 감귤밭 곳곳에 다양한 포토존이 있어 감귤체험을 하며 멋진 사진도 남길 수 있다. 전망대에서 주변 풍경을 한눈에 담고 파라솔 테이블에 앉아 감귤체험에서 직접 수확한 귤을 먹으면서 힐링해도 좋다. 또한, 초록색 감귤나무와 빨간 지붕이 특색인 카페 자체만으로도 소담하고 아늑한 감성을 자극한다. 감귤체험 후 예쁜 감귤밭이 보이는 뷰 맛집 카페에서 다양한 음료를 마시며, 창가 앞 포토존에서 예쁜 SNS 감성 사진은 덤으로 건질 수 있다. 맞은편에는 걸서악(걸세오름)이 병풍처럼 펼쳐져 있는데 도보로 12분 정도면 도착하니 관심이 있다면 오름도 함께 다녀와도 좋다.
모든 나무 아래는 눈이 내린 듯 하얀색 타이백원단이 깔려 있는데, 이것은 햇빛을 반사시켜 더욱 많은 빛을 감귤나무가 받게 해서 당도를 높이는 재배 방식이라고 한다. 9월 초가 지나면서부터 그다음 해 1월까지 본격적으로 타이벡감귤체험이 시작된다. 한여름 8월 한 달 정도 기간 동안에는 청귤체험도 가능하다고 하니, 직접 청을 담아 에이드를 만들어 먹는 것도 가능하다.','제주특별자치도 제주시 해안마을8길 46 (해안동)',NULL,33.4556758294,126.4508725359,NULL,'https://www.instagram.com/daldalmikkang','10:00~17:00 (입장 마감 16:30)※ 매년 상이하므로 자세한 사항은 전화 문의 요망','연중무휴',90,0,'2026-10-14 11:38:38'),
('50110','KTO_TOURAPI','126436','ATTRACTION','성판악','성판악은 한라산국립공원의 성판악 등산로 주변에 위치하는 오름으로 한라산 동쪽 산록에서 가장 규모가 큰 단성화산이다. 단성화산은 일회의 분화 활동을 통해 형성되는 소형 화산체로서 제주에서는 오름으로 불린다. 성판악이라는 명칭은 산 중턱에 암벽이 널 모양으로 둘려 있는 것이 성벽처럼 보여 성널오름 또는 한자어로 성판악이라고 하게 됐다. 성판악은 전체가 삼림으로 덮여있으며 주변으로 성널계곡 등 크고 깊은 계곡이 발달해 있다. 제주시와 서귀포시를 잇는 5·16도로의 중간 지점 가장 높은 곳에 성판악휴게소가 있는데, 이곳은 한라산으로 오르는 등산로 중이 하나로 성판악이 시작되는 곳이다. 한라산 동쪽 코스인 성판악탐방로는 관음사탐방로와 더불어 한라산 정상인 백록담을 오를 수 있는 탐방로이며, 한라산탐방로 중 가장 긴 코스이다. 정상까지 대체로 완만한 경사를 이루지만 왕복 9시간 정도 소요되기 때문에 체력 안배에 신경을 써야 한다. 성판악탐방로는 한라산탐방로 예약시스템에서 사전예약을 해야 탐방이 가능하다.','제주특별자치도 제주시 조천읍 516로 1865',NULL,33.3848640612,126.6203818712,NULL,'https://www.jeju.go.kr/hallasan/','- 하절기(4월~9월) 05:00~12:30- 동절기(10월~3월) 05:00~11:30※ 자세한 사항은 전화 문의 요망','연중무휴',90,0,'2026-10-14 11:32:42'),
('50110','KTO_TOURAPI','1918643','ATTRACTION','한대오름','한대악이라고도 불리는 기생화산으로 이름의 유래는 전해지지 않았다. 전체적으로 완만한 경사를 갖고 있으며 비고가 낮고 2개의 봉우리가 산 정상에서 이어져 있는 형태이다. 전 사면에 해송, 삼나무가 주종을 이루며 잡목이 우거지고 진달래, 꽝꽝나무, 청미래덩굴 등이 자라고 있다. 오름 서쪽 지역에는 곰취 군락이 있고, 동쪽 자락에는 꽤 넓은 습원을 이루면서 주변에 물웅덩이가 많다. 한 대 오름은 제주 한라산 기슭 깊숙한 곳에 위치해 있으며 제주만의 풍경을 갖고 있다. 특히 단풍이 아름답기로 유명한 오름으로, 한 대 오름에 가려면 탐라각 휴게소에서 표고 밭길을 지나 표고 밭 관리사에 이르고 그곳에서 약 1km 안으로 걸어 들어가면 평평한 습지와 함께 가로누워 있는 한 대 오름이 나온다.','제주특별자치도 제주시 애월읍 봉성리 산 1',NULL,33.3563301244,126.4244500997,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-13 17:01:37'),
('50110','KTO_TOURAPI','2765248','ATTRACTION','삼양해안도로','삼양 해안도로는 제주 북부에 있는 삼양동 해안을 따라 이어져 있는 도로다. 삼양동 마을에서 시작해 삼양 해수욕장에서 끝이 나며, 해안 도로 중 가장 거리가 짧다. 검은 모래 해변을 따라 연결된 이곳은 양쪽의 도로변을 따라 가로등이 이어지며, 일몰과 야경이 아름다워 관광객들이 많이 찾는다. 7월에는 삼양 검은 모래 해변축제가 열리며, 검은 모래로 모래찜질을 하면 신경 질환 및 비만 치료, 관절염 등에 효험이 있다고 하여 관광객과 현지 도민의 방문도 잦은 곳이다. 제주시가 선정한 ‘제주시 숨은 비경 31’에 포함된 곳이기도 하다.','제주특별자치도 제주시 삼양삼동 2582-1',NULL,33.5253081583,126.5788103001,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-13 16:43:49'),
('50110','KTO_TOURAPI','2779457','ATTRACTION','종달리해변','‘종처럼 생긴 산(지미봉) 밑에 위치한다’라는 뜻을 가진 종달리해변은 넓은 모래 해변이 깔려있다. 비교적 잘 알려지지 않은 종달리해변은 조용하게 여행하고 싶은 사람들에게 추천하는 곳이다. 종달리해변에서는 성산일출봉과 우도가 아름답게 보인다. 특히 종달리해변 옆에 있는 해안도로는 수국이 아름답기로 유명한 길이 형성되어 있다.','제주특별자치도 제주시 구좌읍 종달리','565-72',33.4963,126.9107,NULL,'https://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-10-13 09:27:09'),
('50110','KTO_TOURAPI','2863882','ATTRACTION','나바론하늘길','나바론하늘길은 돈대산, 추석산 등과 더불어 추자를 대표하는 큰산에서 독산의 해안으로 이어지는 급경사면 기암을 말한다. 큰 산에서 독산까지 이어지는 도보길로 산의 능선을 따라 걷는다. 길을 걷는 동안 추자 섬에서 보이는 망망대해를 감상하며, 중간에는 숲길을 지나고, 상추자도항과 포구마을의 모습도 볼 수 있다. 아찔한 절벽을 옆으로 하여 걷는 과정에서 경사가 이어지는 절벽과 해수면과의 차이가 심하기 때문에 이와 같이 부르며, 영화 ‘나 바론 요새’에 등장하는 지중해 섬과 닮았다고 해서 붙여진 이름이라는 이야기도 있다. 산 위로 오르는 길이 가파를 뿐 아니라 길폭이 좁으며 가드 바깥은 낭떠러지이므로 안전에 유의하여 걸어야 한다.','제주특별자치도 제주시 추자면 대서리 산186',NULL,33.9612164058,126.2866108757,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-12 15:10:14'),
('50110','KTO_TOURAPI','2763820','ATTRACTION','아날로그감귤밭','아날로그감귤밭은 그 이름처럼 아날로그 감성으로 가득 채워진 감귤 체험장 & 카페다. 귤이 나는 철에는 농약을 치지 않은 귤 밭에서 직접 귤을 따는 체험을 해볼수 있다. 귤 밭 곳곳에 꾸며진 포토 스팟은 제주에서의 감귤 체험을 특별한 감성으로 채울 수 있게 공간을 선물한다. 유기농 음료를 마실 수 있는 카페의 내부 공간도 카메라 셔터를 유발할 만큼 깔끔하고 감각 있게 꾸며져 있다. 애견 동반과 외부 음식은 반입이 금지된다.','제주특별자치도 제주시 해안마을5길 124-85 (해안동)',NULL,33.4579594741,126.4632900154,NULL,'https://www.visitjeju.net','10:00~18:00','매주 금요일',90,0,'2026-10-12 15:05:32'),
('50110','KTO_TOURAPI','3037417','ATTRACTION','미깡창고','애월읍 광령리에 위치한 감성카페이다. 가게 외관은 귤 창고를 개조한 건물에 빈티지한 감성을 더한 모습이다. 가게 뒤편에 주차장이 있어 편리하다. 야외에 돌이 많고 위험해 케어키즈존을 강조하고 있다. 10월 중순 귤 수확 철에는 감귤 따기 체험이 가능하므로 인스타그램을 참조해서 방문해 보는 것도 좋겠다. 입구 길 양옆 억새길을 지나 테이블이 놓인 야외 정원에 들어오면 박공지붕의 카페건물이 눈에 들어온다. 카페 내부는 나무 천장이 드러나고 거친 시멘트벽이 우드톤의 가구들과 어우러져 편안하고 이국적인 느낌이다. 미깡창고에는 곳곳에 거울 셀카존을 마련하여 목가적인 분위기를 배경으로 제주도에서의 잊지 못할 인생샷을 남길 수 있다. 감성카페인 미깡창고에서 맛볼 수 있는 대표메뉴들은 모두 제주를 대표하는 단어들이다. 미깡주스, 돌담, 오름, 밭길 등이 그것이다.','제주특별자치도 제주시 애월읍 중산간서로 6710-1',NULL,33.4604843378,126.445244899,NULL,'https://www.instagram.com/mikkang_storage','11:00~17:00 (마지막 주문 16:00)','- 매주 수요일',90,0,'2026-10-12 14:41:28'),
('50110','KTO_TOURAPI','2858860','ATTRACTION','액티브파크 제주','액티브파크 제주는 남녀노소 누구나 신나는 체험을 통해 최고의 성취감을 느낄 수 있는 복합체험공간이다. 이곳은 아이부터 어른까지 모두가 즐길 수 있는 다양한 액티비티가 마련되어 있다. 대표적인 시설 중 하나인 클립 앤 클라임은 독특한 디자인과 안전한 시스템을 갖춘 실내 클라이밍 놀이로 도전과 재미를 동시에 느낄 수 있어 남녀노소 인기가 많은 체험이다. 친환경 카트 트랙 위에서 스피디 하고 바람을 가르는 짜릿한 질주 체험을 느낄 수 있는 엑티브 파크의 카트 체험은 일상의 스트레스를 시원하게 날려버릴 수 있다. 여기에 호기심 많고 에너지가 넘치는 어린이들을 위한 키즈 카페도 마련되어 있는데, 이곳은 마치 마법 같은 공간으로 아이들에게 창의력과 상상력을 자극하고 다양한 놀이를 통해 배움의 즐거움을 느끼게 해준다.','제주특별자치도 제주시 한림읍 금능남로 76',NULL,33.3811423978,126.2360784858,NULL,'http://activepark.co.kr/','09:30~18:00','연중무휴',90,0,'2026-10-07 13:46:30'),
('50110','KTO_TOURAPI','2853484','ATTRACTION','삼무공원','삼무공원은 제주 시내 연동에 있다. 1978년 도시 근린공원으로 조성하였으며 삼무의 의미는 제주에 도둑, 대문, 거지가 없다는 삼무에서 따 온 이름이다. 삼무공원은 베두리오름에 조성된 공원으로, 베두리오름은 작은 언덕으로 삼무공원이 곧 베두리오름이다. 공원에는 증기기관차가 있는데, 1978년 박정희 대통령이 섬에 사는 아이들에게 기차를 보여주려고 사용이 중단된 기차를 흑산도와 제주도에 보낸 것이다. 현재는 제주도에만 미카형 증기기관차가 남아있다. 연동 주민들이 산책과 운동을 즐기는 공원으로 봄에는 능수 벚꽃이 아름다워 여행자들이 찾아온다.','제주특별자치도 제주시 신대로10길 48-9 (연동)',NULL,33.4914567959,126.4924541997,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-07 09:56:35'),
('50110','KTO_TOURAPI','4073368','ATTRACTION','향사당','조선 시대 제주 고을의 어른들이 봄과 가을 두 차례 모여 활쏘기와 주연을 베풀며 고을의 당면 과제를 의논하고 민심의 동향을 살피던 향사당이 제주시 원도심 골목길 안쪽에 자리한다. 향사당은 본래 유향소의 기능을 담당했으나 1475년(성종 6) 예악과 덕행을 세우는 향사음례를 행하는 유향소라는 뜻으로 개칭됐으며, 좌수 1인·별감 3인을 임원으로 두고 지방 자치 기능까지 수행했다. 당초 가락천 서쪽에 있던 건물은 1691년(숙종 17) 현 위치로 이전됐고, 1981년 현재의 모습으로 고쳐 지어졌다. 홑처마 팔작지붕에 2고주 7량 구조이며 중앙 대청에 우물마루를 깔았고, 현무암으로만 쌓은 화방벽과 도리 방향 첨차 설치가 독특한 건축적 특징으로 꼽힌다. 1975년 제주특별자치도 유형문화유산으로 지정되었으며, 현재는 제주 국가유산 방문자센터로 활용되고 있다.','제주특별자치도 제주시 중앙로12길 29 (삼도이동)',NULL,33.5120459469,126.5216321815,NULL,'https://www.heritage.go.kr/','09:00~18:00','연중무휴',90,0,'2026-10-07 09:37:07'),
('50110','KTO_TOURAPI','1918413','ATTRACTION','지미봉','지미봉은 제주도의 아름다운 오름 중 하나로, 제주시 구좌읍 종달리 마을 입구 동북 방향에 자리 잡고 있다. 원뿔 모양의 동쪽 봉우리가 주봉(정상)이며 북쪽에서 바라보면 두 개의 봉우리로 이루어졌고, 서북쪽 기슭에는 하도리 창흥동 양어장이 있다. 이 지역은 철새 도래지로서, 겨울이 되면 겨울 철새인 저어새, 도요새, 청둥오리 등이 날아와 겨울을 난다. 성산 일출봉과 우도, 종달항과 종달리 앞바다를 한눈에 내다볼 수 있다. 지미봉은 올레길 21코스에 자리하고 있어 올레길 관광객들도 찾고있다. 오름 꼭대기에 봉수대의 흔적이 남아 있는데, 북서로 왕가 봉수, 남동으로 성산 봉수와 교신하였다고 한다. 지미라는 이름이 붙은 것은 이곳이 제주 섬의 꼬리 부분에 해당하기 때문이고, 지미봉이라 표기하며, 속칭으로는이라고 부른다. 예전에 한경면 두모리를 섬의 머리 또는 제주 목의 머리라 하고, 동쪽 끝의 이 오름을이라 했다고 한다. 두산봉, 은월봉, 식산봉 북사면에 말굽형 분화구가 북향으로 벌어진다.','제주특별자치도 제주시 구좌읍 종달리 산3-1',NULL,33.499326185,126.9025217376,NULL,'http://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-10-02 13:57:54'),
('50110','KTO_TOURAPI','2781326','ATTRACTION','김녕항','제주 바다를 떠올리면 에메랄드빛 예쁜 바다를 상상하기 마련이다. 제주에는 물빛이 아름다운 해변이 많지만, 그중에서도 동쪽에 있는 김녕항은 투명하고 깊은 물과 고즈넉한 분위기로 많은 관광객에게 사랑받는 곳이다. 김녕항은 요트를 탈 수 있는 요트장이 있으며, 근처에는 야영이 가능한 성세기 해변이 있다. 김녕포구의 백사장은 간조에만 볼 수 있으며, 그 외 시간은 항상 물이 차 있어 패들보드나, 스노클링, 다이빙을 즐기는 이들이 많다. 김녕포구의 방파제는 낚시꾼들에게 좋은 낚시터가 되어주기도 한다.','제주특별자치도 제주시 구좌읍 김녕항1길 50-13',NULL,33.56,126.7375,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-10-02 09:48:03'),
('50110','KTO_TOURAPI','2794659','ATTRACTION','도두항','도두항은 용두암 해안도로와 이호테우 사이에 있는 방파제로, 관탈도와 추자도행 낚시 배들이 출항하는 곳으로 유명하다. 제주 국제공항에서 차로 15분 거리에 있고, 발판도 비교적 좋아 낚시꾼들이 즐겨 찾는다. 제주 시내에서 가깝고, 숙박시설과 신선한 해산물이 있는 유명 맛집, 낚시점들이 적절히 위치해 있어 관광객과 현지인 모두 편리하게 이용할 수 있다. 또한, 유람선과 요트 등 해양 레저 시설도 있어 많은 관광객이 찾는 곳이다.','제주특별자치도 제주시 도공로 2','(도두일동)',33.5061363438,126.4649879968,NULL,'http://www.visitjeju.net/','상시','연중무휴',90,0,'2026-10-01 15:20:46'),
('50110','KTO_TOURAPI','129402','ATTRACTION','방사탑(제주)','부정과 악의 출입을 막아 마을을 편안하게 하고자 쌓은 신앙 대상물로, 마을의 어느 한 방위에 불길한 징조가 보이거나 지형의 기가 허한 곳에 마을 공동으로 쌓아 올린 돌탑이다. 조천읍 신흥리에는 처음에 다섯 기의 탑을 쌓았으나 지금은 포구 방파제 부근과 북서쪽 바닷가에 한 기씩, 두 기가 옛 모습대로 남아 있으며 1995년 제주도 민속자료로 지정되었다. 방파제 부근 큰개에 있는 신흥리 1호탑은 큰개탑이라 불리며, 새들이 움푹 파인 상부에 날아와 새끼를 부화하는 곳으로 이용해 생이탑이라고도 한다. 북서쪽 바닷가 새백개 쪽에 자리한 신흥리 2호탑은 오다리 코지에 있다 하여 오다리탑이라 불린다. 상부에 양근(陽根) 같은 석상을 세워 두어 양탑이라 하고, 이와 대비해 1호탑은 음탑이라고도 부른다. 바다 위에 우뚝 선 돌탑이 제주의 옛 민간신앙을 보여주어, 물때에 맞춰 포구를 거닐며 함께 둘러보기 좋다.','제주특별자치도 제주시 조천읍 신흥로1길 25',NULL,33.5474654395,126.6505174109,NULL,'https://www.heritage.go.kr','상시 개방','연중무휴',90,0,'2026-09-30 13:14:35'),
('50110','KTO_TOURAPI','1906195','ATTRACTION','동백동산','조천읍 선흘리에 위치한 동백동산은 제주 생태관광의 또 다른 명소이다. 동백동산은 생태적 우수성을 인정받아 2011년에는 람사르 습지로, 2014년에는 세계지질공원 명소로 지정되었다. 화산 폭발 후 흘러내린 용암이 쪼개지면서 형성된 제주의 숲, 곶자왈은 물이 고이는 습지가 만들어지기 어려운 구조다. 하지만 동백동산은 용암이 판형으로 남아 물이 빠져 내려가지 않고 고여 있게 된다. 이를 파호이호이용암이라 부르며 이 용암으로 습지와 동굴, 그리고 용암 언덕 튜물러스가 만들어져 숲을 이룬다. 전국 최대 상록수림인 동백동산 안에는 사철 마르지 않는 습지, 먼물깍을 만날 수 있는데 마을과 멀리 떨어져 있다 해서 먼 물의 의미와 끝을 일컫는 깍이 합쳐진 이름이다. 먼물깍은 다양한 수생식물과 곤충 및 양서류가 서식하는 생명의 보고이다. 돌덩이가 되어버린 불덩이, 서로 의지하며 키를 키우고 있는 나무와 덩굴, 건강한 생태계 속에 깃들여 사는 무수한 생명들, 그곳이 동백동산이다.','제주특별자치도 제주시 조천읍 동백로 77',NULL,33.5098,126.7155,NULL,'https://www.visitjeju.net/kr/','09:00~18:00','설·추석 당일※ 자세한 사항은 전화문의 요망',90,0,'2026-09-29 13:29:10'),
('50110','KTO_TOURAPI','2789378','ATTRACTION','제주신흥해수욕장','나만 알고 싶은 프라이빗 해수욕장을 찾는다면 제주 동쪽 조천읍에 있는 신흥해수욕장을 추천한다. 제주 올레길 19코스에 있으며 ‘민만 아는 작은 해변이지만 있을 건 다 있다. 돌벽으로 지어진 탈의실과 샤워 시설은 신축하여 시설이 모두 깨끗하다. 널리 알려지지 않은 곳이라 주로 숙소 사장님에게 추천받아 오는 관광객들만 찾아 성수기에도 북적이지 않는 해변이다. 주변에 주차하기도 편리하고 여름철에는 안전요원도 배치되어 안심하고 이용할 수 있다. 멀리 서우봉이 보이며 바로 옆에 카페가 있어 더욱 편리하다. 조용한 곳에서 물놀이 휴가를 즐기고 싶다면 방문해 보길 권한다.','제주특별자치도 제주시 조천읍 조함해안로 273-35',NULL,33.5519478453,126.64853098,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-09-28 18:29:41'),
('50110','KTO_TOURAPI','598696','ATTRACTION','소머리오름(우도봉)','제주시 구좌읍 종달리에서 조금 떨어진 우도(소섬)는 유인도로 소가 머리를 들고 누워있는 형태를 띠고 있다. 머리에 해당하는 부분을 소머리오름이라 하며, 우도 주민들은 섬머리로 통한다. 성산항에서 우도 동천진항까지 도항선이 운행되고 있으며 시간은 약 15분 소요된다. 오름의 남동 사면은 곧바로 해안단애를 이루며 바다로 내리지르고, 북사면은 용암유출에 의해 파괴된 형태로 완만한 용암대지의 우도마을로 이어져 있어 오름이 곧, 섬 그 자체인 셈이다. 소머리오름은 응회환의 수중 분화구이며 화구 안사면에는 저수지와 함께 병풍처럼 둘러쳐진 화구륜을 확인할 수 있고, 화구 중앙에 소위 알오름이라고 하는 화구구(火口丘)인 망동산이 솟아있다.','제주특별자치도 제주시 우도면 연평리','산18-2',33.491532,126.965127,NULL,'http://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-09-28 10:17:16'),
('50110','KTO_TOURAPI','2765234','ATTRACTION','궷물오름','제주시 애월읍 유수암리에 있는 궷물오름은 산이 높지 않고 둘러보는 게 오랜 시간이 걸리지도 않아 가벼운 마음으로 걸을 수 있는 오름이다. 오름 동쪽 굼부리에 ‘궷물’이라는 샘이 솟아난다 해서 붙여진 이름이다. 북동 방향에는 말굽형 분화구가 있고 남동쪽에는 노꼬메 오름이 자리하고 동남쪽에는 족은 노꼬메 오름이 있다. 오름까지 이어진 산책로가 잘 조성돼 있고 땀을 식힐 수 있는 시설이 마련되어 있어 남녀노소 가벼운 마음으로 찾을 수 있다. 가을이면 억새가 넘실대는 풍경이 매우 아름다운 곳이기도 하다.','제주특별자치도 제주시 애월읍 유수암리',NULL,33.3970759047,126.4074985985,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-09-22 14:37:11'),
('50110','KTO_TOURAPI','2785869','ATTRACTION','판포포구','제주 서쪽에 있는 판포포구는 스노클링 명소로 꼽힌다. 모래 바닥에 맑고 깨끗한 물빛 덕분에 신비로운 바닷속 풍경을 마음껏 눈에 담을 수 있기 때문이다. 스노클링 장비가 없더라도 여름철에는 판포리 청년회에서 장비를 대여해 준다. 샤워시설도 갖추고 있어 가벼운 몸으로 가더라도 스노클링의 매력을 즐길 수 있다. 스노클링 외에 패들 보트나 구명조끼, 일행끼리 여유롭게 쉬면서 포구 풍경을 감상할 수 있는 평상도 대여해 준다. 일반 해수욕장과 달리 포구 형태라 모래가 몸에 묻어나지 않고, 수심도 얕은 편이라 어린이들과 쾌적하고 안전하게 물놀이를 즐기기에도 좋다.','제주특별자치도 제주시 한경면 판포리 2877-3',NULL,33.3654096352,126.1996214294,NULL,'https://www.visitjeju.net','상시 개방','연중무휴',90,0,'2026-09-18 01:30:02'),
('50110','KTO_TOURAPI','3037793','ATTRACTION','금능돌담해변길','금능해변돌담길은 한림읍에 위치한 해안길로 탁 트인 바다와 돌담이 조화롭게 어우러진 올레 14코스 중 한 곳이다. 금능해수욕장에서 금능포구 쪽으로 해안을 따라 걸으면 돌담길을 만날 수 있다. 아기자기한 금능포구로 이어지는 길을 따라 걷다 보면 까만 현무암 돌담 위로 색색의 지붕들이 빼꼼히 머리를 내밀고 돌담 너머로 제주도의 푸른 바다가 펼쳐진다. 전형적인 제주의 모습을 간직한 금능포구와 돌담길 주변은 드라마 촬영지로 정겨운 풍경과 드라마의 여운이 남아 사랑받고 있는 곳이다. 또한, 해안 절벽 아래로 펼쳐진 에메랄드빛 바다를 감상할 수 있어, 여유로운 산책을 즐기기 좋은 곳이다. 금능포구에서는 비양도가 떠있는 바다 풍경을 조망할 수 있으며 비양도와 어우러지는 제주 일몰 명소이기도 하다.','제주특별자치도 제주시 한림읍 금능9길 24',NULL,33.3903147981,126.2290559324,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-09-16 22:35:50'),
('50110','KTO_TOURAPI','2789652','ATTRACTION','순례자의 교회','순례자의 교회 제주 올레길 13코스에 위치한 교회로 가장 작은 교회라고 알려져 있다. 예배 시간이 정해지지 않고 방문객을 맞이하는 시설도 없이 조용한 명상과 묵상을 할 수 있게 마련된 예배당이다. 교회 탑에 길 위에서 묻다라는 문구가 방문객들에게 많은 질문을 던진다. 종교에 상관없이 길 위에서 이곳을 지나는 모든 사람들에게 열린 공간으로 홀로 조용히 지나온 길들을 돌아볼 기회를 선사해 준다. 넓은 한경면 일대 전원 풍경에 자그마한 교회의 이국적인 모습이 조화를 이룬다. 입장료도, 운영시간도 따로 없어 부담 없이 지나가다 둘러보기 좋다.','제주특별자치도 제주시 한경면 일주서로 3960-24',NULL,33.319800755,126.180538112,NULL,'https://www.visitjeju.net/kr/','상시 개방','연중무휴',90,0,'2026-09-09 17:57:44'),
('50110','KTO_TOURAPI','2792595','ATTRACTION','자구내포구','자구내포구에 가면 차귀도가 눈앞에 펼쳐져 있다. 고래 등 같은 생김새 때문에 고래가 물 밖으로 나와 쉬는 것처럼 보이기도 한다. 한치와 오징어 제철 시기에는 포구에 오징어 말리는 모습을 볼 수 있고, 즉석에서 오징어 파는 점포들도 종종 볼 수 있다. 차귀도 가는 배가 자구내포구에 있어 차귀도 포구라고도 불린다. 자구내포구는 작은 포구라 관광 명소는 아니지만, 노을이 아름다운 곳으로 유명하다. 차귀도의 매바위 방향으로 해가 넘어가면서 멋진 풍경을 만들어낸다. 노을과 한적한 어촌의 풍경이 적절히 어우러진 정겨운 곳이다.','제주특별자치도 제주시 한경면 노을해안로 1161',NULL,33.3093600615,126.1651397772,NULL,'https://www.visitjeju.net/kr/','상시 개방','연중무휴',90,0,'2026-09-09 17:38:41'),
('50110','KTO_TOURAPI','2792568','ATTRACTION','조천함덕해안도로','조천함덕해안도로는 조천과 함덕을 잇는 약 4.5㎞ 길이의 해안도로다. 함덕에서가 아닌 조천에서 출발하여 달려도 되지만, 함덕에서 출발하는 편이 바다와 자동차의 거리가 가까워 제주 풍경을 즐기기에 더 좋다. 다른 코스들보다 쉬어갈 수 있는 곳이 많진 않지만, 어느 코스보다 바다와 마을을 구경하기 좋다. 해안도로의 시작인 함덕 서우봉 해변은 에메랄드빛 바다와 모래사장을 따라 심은 야자수가 이국적인 풍경을 연출한다. 도로는 해남 땅끝마을과 가장 가까운 관곶도 지나게 되는데, 관곶에서 바라본 제주시의 야경은 매우 아름답다. 맑은 날에는 추자도와 남해 도서까지 보인다고 한다.','제주특별자치도 제주시 조천읍 조함해안로 일대',NULL,33.542789,126.670523,NULL,'https://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-09-09 17:15:49'),
('50110','KTO_TOURAPI','2792603','ATTRACTION','협재포구','협재포구는 에메랄드빛 바다가 펼쳐지는 곳으로, 포구 옆에는 넓은 모래사장의 해수욕장이 있다. 포구 방파제 끝에는 작은 등대가 자리하고 있으며, 바다 건너편으로 비양도가 보여 아름다운 풍광을 자랑한다. 낚시를 즐기는 사람들이 찾는 곳이기도 하며, 주변에서는 계절에 따라 스노클링과 바나나보트 등 다양한 해양레저를 즐길 수 있다.','제주특별자치도 제주시 한림읍 협재리',NULL,33.3989,126.2426,NULL,'https://www.visitjeju.net/kr/','상시 개방','연중무휴',90,0,'2026-09-09 17:03:06'),
('50110','KTO_TOURAPI','2794667','ATTRACTION','사수항','사수항은 제주 국제공항 바로 뒤편에 있는 작은 항이다. 항구의 역할보다는 아름다운 일몰과 카페거리 등 인근 관광지로 더 유명하다. 사수항을 지나는 해안도로를 따라가다 보면 말 모양의 등대가 있는 이호테우 등대와 무지개 해안도로를 만날 수 있다. 근처에는 제주만의 독특한 감성이 묻어나는 카페들이 즐비한 카페거리가 있어 함께 들러보기 좋다. 특히 일몰이 매우 아름다우며, 로맨틱한 분위기를 연출한다.','제주특별자치도 제주시 서해안로 319 (도두이동)',NULL,33.50960274,126.4795124385,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-09-09 16:13:47'),
('50110','KTO_TOURAPI','2663250','ATTRACTION','신창풍차해안도로','제주도 서쪽 끝을 따라 연결된 신창 풍차 해안도로는 해상풍력단지가 조성되어 있어 해안도로를 따라 줄지어 서 있는 풍차를 만날 수 있다. 구불구불 해안선을 따라 보이는 하얀 풍차와 에메랄드빛 바다는 우리에게 상쾌한 가을 풍경을 보여준다. 여기에 저 멀리 보이는 차귀도까지 푸른 바다 위 다양한 볼거리가 펼쳐져 있다. 특히 신창 해안도로는 아름다운 일몰로도 손꼽히는 장소이기에 사진을 찍고 일몰을 감상하는 것도 좋다. 또한 해안도로를 달리다 보면 생태체험장이라는 이름의 산책코스를 발견할 수 있다. 이곳에는 자바리상과 원담체험장, 휴게 공간이 마련되어 있어 다양한 풍경으로 사진을 찍는 것이 가능하다. 산책코스 중간에 위치한 전망대는 전체적으로 한산한 편이니, 신창 해안도로를 걸으며 가볍게 사진을 남긴 후 전망대로 향해보자.','제주특별자치도 제주시 한경면 한경해안로 485',NULL,33.3430957258,126.1721252383,NULL,'https://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-09-09 09:19:17'),
('50110','KTO_TOURAPI','2779449','ATTRACTION','비밀의 숲','제주시 구좌읍에 있는 비밀의 숲은 SNS에서 포토존으로 유명해진 자연 숲길 명소다. 제주도의 유명 숲인 비자림, 사려니숲길과는 또 다른 매력을 지녔다. 희귀 편백나무 숲부터 넓은 초원, 돌담과 오두막 등 다채로운 구성과 제주도만의 감성을 담은 포토 스폿들이 있다. 특히 유채꽃과 핑크뮬리 등 사계절 아름다운 자연을 구경할 수 있다. 다만 사유지라 입장 전 촬영은 어려우며, 포장도로로 가기 위해서는 홈페이지에 안내된 주소를 참고해야 한다.

◎ 한류의 매력을 만나는 여행 정보 - 
 풀버전 첫 장면으로 부승관이 초록 숲을 느끼며 눈을 감았으며 앉아 있는 승관의 뒤로 밴드 멤버들이 폴짝 뛰어오르는 꽃밭도, 함께 산책하는 숲도 청량하다. 안돌오름 비밀의 숲은 이름 그대로 비밀스럽게 숨겨진 곳이다. 자연적인 숲엔 화장실조차 없지만 스냅사진을 찍으러 오는 사람들로 가득하다. 울창한 숲은 초지와 편백나무 숲으로 이어지며 곳곳엔 포토존이 있다. 특히 민트색 트레일러 앞은 촬영 필수 코스이니 사진을 찍어보길 추천한다.','제주특별자치도 제주시 구좌읍 비자림로 1741-212',NULL,33.4539663203,126.7553511105,NULL,'https://www.instagram.com/secretforest75','09:00~18:00','연중무휴 ※ 휴무일 인스타그램 참조',90,0,'2026-09-09 01:30:02'),
('50110','KTO_TOURAPI','2798892','ATTRACTION','화북포구','화북포구는 시가 있는 등대길로 이름을 알린 포구이다. 다른 포구와 다르게 등대 끝까지 방파제를 따라 시를 만날 수 있는데, 학생들이 등대, 포구, 바다와 관련된 시를 포구 끝까지 만들어 두었다. 덕분에 이곳을 방문하는 사람들은 시를 하나하나 읽으면서 등대 끝까지 산책할 수 있다. 등대 끝에는 그림을 그리는 아이와 망원경을 들고 바다를 바라보는 어린아이 등의 조형물이 설치되어 있다. 이 등대를 배경으로 사진을 찍으려고 방문하는 관광객도 많으며 저녁이면 주변을 산책하는 도민들도 많은 편이다.','제주특별자치도 제주시 화북1동',NULL,33.5255051282,126.5645505112,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-09-08 16:45:20'),
('50110','KTO_TOURAPI','2779527','ATTRACTION','구엄리 돌염전','제주 서쪽 해안 도로를 따라 달리다 보면 우리나라 유일의 돌 염전인 ‘소금빌레’를 만날 수 있다. 구엄리에 자리한 이 돌 염전은 용암이 굳어져 깨진 널찍한 현무암 지대에 흙을 돋우어 칸 칸마다 바닷물을 채우고 햇볕에 말려 천일염을 제조했다. 한때 소금밭의 규모가 4,958㎡에 이를 만큼 구엄리 사람들에겐 중요한 생계수단이었다. ‘염장이’로 불리던 이들은 귀한 소금밭을 큰딸에게만 상속했다. 여성의 생활력이 훨씬 강했던 제주의 특성을 짐작할 수 있는 부분이다. 1950년대까지도 활발하게 운영됐던 구엄리 돌염전은 육지에서 들어온 값싼 소금에 밀려 결국 사라졌다. 하지만 관광자원으로 새롭게 복원된 돌 염전은 제주 어디서도 만날 수 없는 특별한 풍경을 선물한다. 특히 염전에 물이 찼을 때 거울처럼 맑은 반영 사진을 찍을 수 있어 관광객들의 발길이 이어진다.','제주특별자치도 제주시 애월읍 애월해안로 708',NULL,33.4825790978,126.3774089402,NULL,'https://www.visitjeju.net/kr','상시 개방','연중무휴',90,0,'2026-09-08 16:04:51'),
('50110','KTO_TOURAPI','2847726','ATTRACTION','상가리야자숲','제주 애월읍 고하상로 326에 위치한 상가리야자숲은 이국적인 분위기를 자아내는 야자수 군락지이다. 그늘 아래 벤치와 포토존이 마련되어 있어 방문객들이 편안하게 휴식을 취하거나 사진을 촬영할 수 있다. 사계절 내내 푸른 소철과 야자수가 싱그럽고, 하늘을 배경으로 펼쳐진 풍경이 아름답다. 주차 공간은 마련되어 있지 않으므로 인근 도로에 주차한 후 방문해야 한다. 주변에는 고내포구, 애월항 한담해안산책로 등 관광 명소가 있어 함께 둘러보기 좋다. 상가리야자숲은 자연과의 교감을 원하는 이들에게 평화롭고 신비로운 힐링 공간을 제공하는 곳이다.','제주특별자치도 제주시 고하상로 326',NULL,33.4394340828,126.3584772018,NULL,'https://www.visitjeju.net/kr/','09:00~18:00','연중무휴',90,0,'2026-09-04 15:49:34'),
('50110','KTO_TOURAPI','2872927','ATTRACTION','신촌 4·3 성터','신촌리는 제주4·3 당시 신촌회담이 열렸던 곳으로, 조천 만세운동 등 항일운동의 역사를 간직한 조천읍의 작은 바닷가 마을이다. 신촌리 4·3 성터는 제주4·3 당시 돌을 쌓아 만든 성터로, 당시의 역사적 흔적을 살펴볼 수 있는 곳이다.
신촌리 4·3 성터는 닭머르해안 인근에 위치하며, 닭머르해안길은 해안누리길 50코스에 포함되어 있다. 해안길을 따라 주변 경관을 살펴보며 산책할 수 있으며, 역사적 흔적과 해안 풍경을 함께 둘러볼 수 있다.','제주특별자치도 제주시 조천읍 신촌리','(3403)',33.5376989336,126.6130984926,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-09-04 14:46:47'),
('50110','KTO_TOURAPI','2763726','ATTRACTION','제주스위스마을','제주스위스마을은 다채로운 색감의 상가와 숙박시설로 꾸며져 있으며 마을 곳곳에 여행자들을 위한 포토존들이 마련되어 있는 곳으로, 여러 공방과 아기자기한 소품 숍들이 있어 함께 구경하기 좋은 곳이다. 다채로운 색들의 건물들로 이어져 이색적인 매력을 더한다. 언덕배기에 지어진 마을이라 올라갈수록 아름다운 제주도의 바다가 펼쳐져 마치 동화 속에 들어온 듯한 느낌을 받을 수 있다.','제주특별자치도 제주시 조천읍 함와로 566-27',NULL,33.4939078385,126.6767796895,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-09-02 13:48:54'),
('50110','KTO_TOURAPI','2738659','ATTRACTION','구엄포구','노을이 아름다운 애월 해안도로를 따라가다 보면 작고 아담한 구엄포구를 만난다. 구엄포구 바로 옆에는 제주의 옛 생활을 엿볼 수 있는 돌염전이 있다. 구엄리 돌염전은 넓게 펼쳐진 현무암 위에서 소금을 생산하던 곳이다. 이곳은 ‘소금빌레’라고도 일컬어지는 곳으로, 구엄리 주민들이 천연 암반지대에서 소금을 생산하던 염전이다. 여기서 ‘빌레’란 너럭바위란 뜻의 제주도 사투리로, 즉 돌소금 밭이라는 뜻이다. 돌염전이 있는 해안길은 국내의 아름다운 해안도로인 해안 누리길로 선정된 바 있다. 구엄포구 한편에는 돌로 만든 도대불도 있다. 도대불이란 어부가 밤중에 고기잡이를 마치고 집으로 돌아올 때 불을 밝혀 안전하게 길잡이 역할을 했던 등대다. 도대불과 소금빌레 모두 제주에서만 볼 수 있는 중요한 해양 문화유산이다.','제주특별자치도 제주시 애월읍 구엄리',NULL,33.4843,126.3764,NULL,'https://www.visitjeju.net/kr/','상시 개방','연중무휴',90,0,'2026-09-02 10:58:02'),
('50110','KTO_TOURAPI','2765293','ATTRACTION','귤향기 감귤체험농장','귤향기 감귤체험농장은 제주 노형동에 자리하고 있는 감귤 체험농장으로, 제주 시내와 국제공항과도 가까워 접근성이 좋은 곳이다. 소정의 체험료를 내면 귤을 담을 바구니와 가위 등 체험 장비를 대여해 주고 1㎏을 가져갈 수 있다. 귤밭에는 예쁘게 꾸며져 있는 사진 명소가 많아 감귤 수확뿐만 아니라 기념사진도 남길 수 있다. 체험하면서 시식도 가능하며, 규모가 큰 편이라 여유롭게 체험할 수 있다. 체험 시기는 계절적 영향으로 변경될 수 있으며, 귤 따기 외에 하귤 청, 풋귤 청 만들기 등의 체험은 반드시 사전 예약을 해야 한다.','제주특별자치도 제주시 1100로 3118 (노형동)',NULL,33.4649059695,126.485764576,NULL,NULL,'- 토요일~목요일 09:00~17:30- 금요일 09:00~11:30※ 3월~7월 귤잼 또는 다용도양념장 체험은 단체 예약제로 운영됨','연중무휴',90,0,'2026-09-02 10:55:17'),
('50110','KTO_TOURAPI','1069144','ATTRACTION','사라봉','사라봉은 제주항 동쪽으로 바닷가를 접해 위치한 오름이다. 고운 비단을 뜻하는 사라봉은 제주에서 가장 아름다운 열 곳을 선정한 영주십경 중 사봉낙조에 해당하는 오름이다. 사봉낙조는 사라봉에서 지는 붉은 노을을 의미하며, 사라봉 정상에 올라 노을로 붉게 물든 바다를 볼 수 있다. 정상에 오르면 북쪽으로는 파란 바다, 남쪽으로는 웅장한 한라산을 볼 수 있고 발아래로 제주 시내의 모습이 보여 막힘없이 펼쳐진 낮의 풍경도 아름답다. 오름의 형태는 북서쪽으로 벌어진 말굽형 화구로서 붉은 송이로 구성된 기생 화산이고 전체적으로 소나무가 가득하다. 사라봉 남쪽에는 모충사가 있고 동쪽에는 별도봉이 연봉을 이루고 있으며, 산 일대는 공원으로 지정되어 있다. 공원 내에는 팔각정과 의병 항쟁 기념탑이 있고 체력단련시설과 음수대, 화장실 등의 편의시설이 잘 갖추어져 있어 관광객뿐만 아니라 도민들도 자주 방문하는 오름이다.','제주특별자치도 제주시 사라봉동길 61',NULL,33.5175946428,126.5461385165,NULL,'https://www.visitjeju.net/kr/','상시 개방 ※ 방문 전 통제 구역 확인 등 전화 문의 요망','연중무휴',90,0,'2026-09-02 10:48:43'),
('50110','KTO_TOURAPI','127336','ATTRACTION','우도','우도는 소가 누워있는 모양을 닮았다고 해서 일찍부터 소섬 또는 쉐섬으로 불렸다. 완만한 경사와 옥토, 풍부한 어장, 우도팔경 등 천혜의 자연조건을 갖춘 관광지로써 한 해 약 200만 명의 관광객이 찾는 제주의 대표적인 부속 섬이다. 성산항과 종달항에서 우도 가는 배를 탈 수 있는데 어디서 출발하든 15분 정도 소요된다. 섬의 길이는 3.8㎞, 둘레는 17㎞이며, 쉬지 않고 걸으면 3~4시간 걸리는 거리지만, 대부분의 관광객은 버스나 자전거, 미니 전기차를 타고 유명한 관광지 위주로 돌아볼 수 있다. 여유 있게 우도를 즐기고 싶다면 오전 아침배를 타고 들어가 오후 배를 타고 나와 하루 종일 우도에 머물러 보는 것도 좋다. 단, 기상에 따라 배 운항 여부가 달라질 수 있으니 우도 여행 일정을 짜는 데는 기상조건을 필히 확인해야 한다.

(출처 : 비짓제주 홈페이지)','제주특별자치도 제주시 삼양고수물길 1',NULL,33.5194704331,126.9510147412,NULL,'https://www.visitjeju.net/','상시 개방※ 여객선 운항시간 확인 요망','연중무휴※ 여객선 운항시간 확인 요망',90,0,'2026-09-02 09:45:45'),
('50110','KTO_TOURAPI','127529','ATTRACTION','비양도','제주도 서쪽 한림읍에 위치한 비양도는 제주의 화산체 중 가장 나중에 생긴 막내 섬이다. 면적은 0.5㎞으로 작으며 2~3시간 정도이면 충분히 둘러볼 수 있다. 섬 중앙 비양봉 일대에 2개의 분석구가 있고 섬의 북서쪽 해안에는 오래전에 사라진 분석구의 일부가 남아있다. 해안은 대부분 용암으로 구성되어 있으며 대형 화산탄과 애기업은돌이 대표적인 지질명소이다. 특히 화산탄은 10톤 규모의 초거대 크기로 직경이 5m에 달하며 현재까지 제주도에서 발견된 화산탄 중에 가장 큰 규모이다. 
섬 안의 해안 도로를 따라 걷다 보면 기암괴석을 볼 수 있는데, 애기업은돌과 코끼리 바위가 대표적이다. 또 뭍에서는 보기 드문, 바닷물로 된 염습지 필랑못이 있다. 바닷물이 드나들어 염분 변화가 큰 습지이다. 비양봉 전망대는 조금 더 오르면 하얀 등대가 있는데, 이곳에서 제주도 본 섬의 모습을 한눈에 볼 수 있다. 비양도에는 여러 포토 스폿이 있다. 쌓인 돌 틈 사이의 비치는 바다나 길가의 뿔소라 껍데기가 예쁘게 칠해진 돌담길이나 비양도 여행길의 즐거움을 남길 곳이 다양하다.
한림항에서 비양도를 들어가는 배를 탈 수 있는데, 현재는 하루에 4번 정도 들어오고 나가는 배편이 있고, 한림항에서 15분 정도면 비양도에 들어갈 수 있다. 자세한 시간표와 기상에 따른 스케줄이 다를 수 있기 때문에 방문 전 유선으로 확인하는 편이 좋다.','제주특별자치도 제주시 한림읍 한림해안로 146',NULL,33.4154196613,126.2621096355,NULL,'https://www.visitjeju.net','상시 개방※ 배 운항 시간 확인 요망','연중무휴※ 배 운항 시간 확인 요망',90,0,'2026-09-02 08:19:13'),
('50110','KTO_TOURAPI','2023328','ATTRACTION','하도어촌체험마을','하도어촌체험마을은 우도를 마주한 아름다운 바다와 제주 고유의 어촌 풍경을 간직한 마을이다. 아직 개발의 손길이 많이 닿지 않아 자연 그대로의 모습을 만나볼 수 있으며 마을 곳곳에서 제주의 자연과 역사, 해양문화를 경험할 수 있다.
천연기념물 토끼섬 문주란 자생지를 비롯해 하도 철새도래지에는 노랑부리저어새, 황새, 백로, 가마우지류 등 다양한 철새가 찾아와 생태관찰의 즐거움을 더한다. 조선시대 왜구의 침입을 막기 위해 축조된 별방진에서는 마을의 역사적 흔적을 살펴볼 수 있으며, 해녀박물관에서는 제주 해녀들의 삶과 문화, 풍습을 만나볼 수 있다. 푸른 바다와 하얀 백사장이 어우러진 하도해수욕장도 가까이 있어 아름다운 해안 풍경을 감상하며 여유로운 시간을 보내기 좋다.','제주특별자치도 제주시 구좌읍 해맞이해안로 1897-27',NULL,33.5199140583,126.9040579779,NULL,NULL,'10:00~17:00※ 기상악화 시 영업시간 변동※ 예약 필수로 전화 문의 후 방문 요망','매년 11월~3월',90,0,'2026-08-27 13:55:14'),
('50110','KTO_TOURAPI','2027203','ATTRACTION','백제사','백제사는 1,700여 년의 한국불교의 정통 법맥을 이어온 석가세존 태고보우국사를 종조로 모신 한국불교태고종 사찰이다. 불교의 생명 존중 사상과 자연 친화적인 한국의 사찰문화를 체험할 수 있도록 사부대중 누구에게나 열려 있는 도량이다. 백제사는 부처님의 가르침인 지혜와 자비를 바탕으로 불자 양성과 포교 및 청소년 교육을 위한 수행도량으로 설립되었다. 아름다운 제주의 청정한 자연과 수려한 경관을 느끼며 사찰에서의 고요한 휴식을 취할 수 있는 곳으로, 한국불교의 전통문화, 수행정신을 통해 참 존재를 찾아갈 수 있도록 템플스테이 등의 프로그램을 운영하고 있다.','제주특별자치도 제주시 애월읍 광령남6길 54',NULL,33.4488555391,126.4242196858,NULL,'https://www.visitjeju.net','상시 개방※ 전화 문의 후 방문 요망','연중무휴',90,0,'2026-08-27 13:35:13'),
('50110','KTO_TOURAPI','2661523','ATTRACTION','북촌마을 4·3길','북촌마을은 제주시 조천읍 동쪽 끝에 자리한 해변 마을이다. 일제강점기에는 치열한 항일운동이 펼쳐졌고, 해방 이후에는 주민 자치 활동이 매우 활발했던 곳이다. 그러나 1949년 1월 17일, 세계적으로도 유례를 찾기 힘든 비극적인 대규모 민간인 학살 사건이 이곳에서 자행되었다. 이로 인해 주민 300여 명이 희생당하는 등 북촌마을은 제주 4·3사건 최대의 피해 마을 중 하나로 남게 되었다.
마을에는 4·3사건 당시 도민들이 겪은 통한의 역사에 공감하고 인권과 평화의 소중함을 되새기기 위해 역사 교육의 장으로서 북촌마을 4·3길을 조성하였다. 4·3길의 출발이자 도착 지점인 너븐숭이 4·3기념관에서는 4·3길 무료 해설 서비스를 신청할 수 있다.','제주특별자치도 제주시 조천읍 북촌3길 3',NULL,33.546021407,126.688682938,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-08-06 13:42:43'),
('50110','KTO_TOURAPI','2661514','ATTRACTION','휴림','휴림은 2017년 개장한 에코힐링파크로 남녀노소 온가족이 함께 즐길 수 있는 숲속 체험을 제공한다. 제주시산림조합에서 운영하며 산림자원의 새로운 부가가치를 창출하기 위해 제주의 산림자원을 활용하여 조성되어있어 제주의 숲내음을 온몸으로 맡으며 휴식을 즐길 수 있다. 양묘체험, 숲속캠핑, 글램핑, 카라반 등을 체험할 수 있으며, 유치원 등의 단체가 이용할 수 있는 유아숲속 놀이터를 운영하고 있다. 숲카페, 캐주얼와인샵, 산림부산물인 편백 톱밥을 활용한 톱밥효소 찜질 체험장도 있어 숲이 주는 자연치유력과 힐링을 느끼는 느긋함도 가져볼 수 있다.','제주특별자치도 제주시 애월읍 광령남서길 40',NULL,33.4437791402,126.4287872275,NULL,NULL,'09:00~18:00','연중무휴',90,0,'2026-08-06 13:35:22'),
('50110','KTO_TOURAPI','2714306','ATTRACTION','제주 무지개해안도로','도두동 무지개 해안도로는 공항에서 차로 10분 거리에 있는 이색 도로다. 차량 추락을 막기 위해 해안도로를 따라 설치된 방호벽에 색을 입혀보자는 주민들의 의견을 반영하여 무지개색으로 칠했는데, 관광객들 사이에서 도두동 무지개 해안도로로 불리면서 명소가 되었다. 주변에는 해녀상을 비롯한 여러 조각상이 있어 구경하는 재미가 있고, 걸어서 이동이 가능한 곳에 도두봉이 있는데, 올레길 코스이면서 숨은 비경 중 하나이다. 경사가 완만하여 오르기 어렵지 않다.','제주특별자치도 제주시 도두일동 1734',NULL,33.5093583102,126.4724622276,NULL,'https://www.visitjeju.net/kr','상시 개방','연중무휴',90,0,'2026-07-29 14:13:07'),
('50110','KTO_TOURAPI','4091197','ATTRACTION','흘아카이브','제주의 곶자왈 생태에서 영감을 받아 전시와 차, 체험을 함께 운영하는 공간이다. 통유리창 너머로 보이는 수목과 자연광이 실내로 이어지며, 전시 관람과 사색을 통해 자신의 생각을 차분히 정리할 수 있도록 구성하였다. 대표 체험인 ‘먹을 수 있는 숲, 테라리움 디저트’는 곶자왈의 돌과 흙, 이끼를 닮은 크럼블·초콜릿·그래놀라·생크림 등을 투명한 용기에 쌓아 작은 숲 형태의 디저트를 만드는 프로그램이다. 체험 과정에서 제주 곶자왈과 선흘마을에 관한 이야기를 듣고, 완성한 디저트와 곶자왈을 모티프로 만든 블렌딩 차를 맛볼 수 있다. 체험에 참여하지 않아도 현장에서 차를 주문한 뒤 전시와 사색의 방을 개별적으로 이용할 수 있다.','제주특별자치도 제주시 조천읍 선진길 88',NULL,33.4580967783,126.7109921676,NULL,'https://www.instagram.com','[전시관람] - 10:00~18:00 [디저트 만들기 체험] - 10:00~17:00 중 회차별 운영','매주 월요일',90,0,'2026-07-23 11:00:09'),
('50110','KTO_TOURAPI','572973','ATTRACTION','새별오름','새별오름은 서부의 대표 오름으로, ‘저녁 하늘에 샛별과 같이 외롭게 서있다’하여 이름이 붙여졌다. 남봉을 정점으로 남서, 북서, 북동 방향으로 등성이가 있으며, 등성이마다 봉우리가 있다. 서쪽은 삼태기 모양으로 넓게 열려 있고, 북쪽은 우묵하게 파여 있다. 마치 별표처럼 둥그런 표창 같은 5개의 봉우리가 존재한다. 
10월이면 오름 가득 억새가 아름답게 피어나 가을을 느끼고 싶은 사람들이 많이 찾는다. 흐드러지게 피어난 억새는 오름 아래쪽에서부터 피어있는데, 아래쪽은 평지에 가까워 여유롭게 억새를 구경할 수 있다. 정상을 오르는 데 걸리는 시간은 20분 정도로, 제주의 오름 중 짧은 편에 속해 여유가 된다면 정상에서 제주의 가을을 감상하는 것을 추천한다.','제주특별자치도 제주시 애월읍 봉성리 산 59-8',NULL,33.3663,126.3576,NULL,'http://www.visitjeju.net','상시 개방',NULL,90,0,'2026-07-22 16:46:03'),
('50110','KTO_TOURAPI','572960','ATTRACTION','용눈이오름','구좌읍에 위치한 용눈이오름은 해발 247.8m, 높이 88m, 둘레 2,685m로 360여 개의 오름 중 유일하게 분화구가 3개다. 봄, 여름에는 잔디가 가을, 겨울에는 억새가 덮이며 계절마다 옷을 갈아입는다. 부드러운 능선이 유독 아름다워 많은 사진작가들이 찾는다. 한가운데가 움푹 패어있어 용이 누웠던 자리 같다는 뜻을 담아 용와악(龍臥岳), 용이 놀았던 자리라는 뜻을 담아 용유악(龍遊岳), 용의 얼굴 같다 하여 용안악(龍眼岳) 등으로 표기되었는데, 실제로 위에서 내려다보면 화구의 모습이 용의 눈처럼 보인다.

(출처 : 비짓제주)','제주특별자치도 제주시 구좌읍 종달논길',NULL,33.4587755524,126.8320410805,NULL,'http://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-07-21 15:07:53'),
('50110','KTO_TOURAPI','3097814','ATTRACTION','세기알해변','JTBC 〈웰컴투 삼달리〉 드라마 촬영지로 유명해진 세기알해변은 제주 김녕리에 위치한 바다이다. 빨간 등대와 풍력발전기, 에메랄드빛의 바닷물이 어우러져 그림과 같은 풍경을 자아낸다. 썰물 때면 넓은 하얀 모래사장이 펼쳐지며, 수심이 얕고 파도가 높지 않아 아이들이 놀기에 좋다. 또 세기알해변은 스노클링 명소로 인기가 많으며, 패들보드와 요트 등 다양한 수상레포츠를 즐기는 사람들도 많다.
세기알해변 옆 방파제를 따라 이동하면 작은 포구가 나오는데, 예로부터 유명한 이 포구는 ‘지픈개’, ‘세개’, ‘세기알’ 등의 지명으로도 알려져 있다. 포장도로가 생기고 방파제가 축조되면서 옛 포구의 모습은 거의 사라졌지만 지명은 그대로 남아 오랜 역사를 전하고 있다.','제주특별자치도 제주시 구좌읍 김녕리','1200-5',33.5577,126.7563,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-07-20 13:45:07'),
('50110','KTO_TOURAPI','1069322','ATTRACTION','산지천','산지천은 한라산 부근에서 제주시 도심을 관통하여 제주시 최대의 재래시장인 동문시장 옆을 흘러 제주항까지 흐르는 하천이다. 산업화가 한창이던 1960년대에 산지천을 덮어 주택과 상가건물을 지으면서 환경오염 문제가 생기자 1995년도에 복원사업을 시작했다. 2002년 맑은 물이 흐르는 현재의 산지천 모습을 갖게 되었다. 은어, 숭어, 밀어, 붕어 등의 민물고기들이 서식하고 있어 여름철이면 낚시를 즐기는 사람들과 아이들이 수영하는 모습을 종종 볼 수 있다. 쇼핑의 중심지 칠성통과 동문재래시장 등이 주변에 자리하고 있고 제주 올레 18코스의 시작점이기도 해 주변에는 늘 많은 사람이 북적거린다. 매년 산지천 축제를 열어 산지천 용천수가 흐르는 길을 따라 다양한 체험 공간과 전시, 먹거리 장터, 흥겨운 무대와 공연을 펼친다. 산지천을 따라 걸으면 옛 건물들을 개조해 독특한 현대 미술 전시 공간으로 바꾼 아라리오뮤지엄이 있고, 과거 제주 사람들에게 본인의 모든 것을 내놓고 나눔과 봉사를 몸소 실천한 김만덕 할머니를 기리는 김만덕기념관 등의 명소가 자리하고 있다.','제주특별자치도 제주시 건입동',NULL,33.5161751038,126.5299483887,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-06-26 17:25:48'),
('50110','KTO_TOURAPI','2759624','ATTRACTION','도련 감귤나무 숲','도련 감귤나무 숲은 감귤 따기 체험을 할 수 있는 체험 농장으로, 방문객이 한꺼번에 몰리는 불편을 줄이기 위해 하루 4타임으로 운영된다. 온라인 예약과 현장 결제가 모두 가능하다. 체험 전에는 감귤을 고르는 방법과 따는 방법에 대한 안내가 제공되며, 체험 후에는 지정된 구역에서 시식을 자유롭게 즐길 수 있다. 제주국제공항에서 약 20분 거리에 위치해 여행 동선으로도 좋다.','제주특별자치도 제주시 도련남3길 81',NULL,33.5002806517,126.587132322,NULL,'https://www.instagram.com/jejudrforest','10:00~16:00 (휴게시간 12:00~13:00)','체험별로 상이함',90,0,'2026-06-23 17:58:37'),
('50110','KTO_TOURAPI','4078062','ATTRACTION','족은노꼬메오름','족은노꼬메오름은 제주 오름 중 숲길과 오름을 함께 즐길 수 있는 곳이다. 노꼬메오름은 족은노꼬메오름과 큰 노꼬메오름으로 이루어져 있으며, 놉고메로 부르다가 시간이 흐르면서 노꼬메로 불려지고 있다.
큰노꼬메오름은 뾰족하게 도드라진 것이 특징이며, 족은노꼬메오름은 큰노꼬메의 북동쪽에 위치하고 있으며 경사가 낮지만 몸집이 매우 큰 것이 특징이다. 두 노꼬메오름은 나란히 위치하고 있기 때문에 ‘형제오름’이라고도 불린다.
제주방언으로 ‘작은’을 뜻하는 ‘족은’노꼬메오름은 이름 때문에 오르기 쉽다고 착각하기 쉬우나 호락호락하게 오를 수 있는 오름은 아니다. 족은노꼬메 오름을 오르는 길은 궷물오름, 큰노꼬메오름 등을 거쳐가는 여러 갈래가 있다.
족은노꼬메오름은 오르는 길이 잘 정비되어 있어 편하게 오를 수 있다. 정상에 오르게 되면 탁 트인 경치와 함께 반대편에 위치한 큰노꼬메오름의 모습을 조망할 수 있다. 

(출처 : 비짓제주 홈페이지)','제주특별자치도 제주시 애월읍 유수암리 산138',NULL,33.3937,126.418,NULL,'https://www.visitjeju.net','상시 개방','연중무휴',90,0,'2026-06-22 17:28:25'),
('50110','KTO_TOURAPI','636393','ATTRACTION','제주선인장마을','제주선인장마을은 제주시 한림읍 월령리 일대에 조성된 곳으로, 해안가를 따라 자생하는 손바닥선인장을 만날 수 있는 명소이다. 월령해안과 어우러진 선인장 군락은 이국적인 풍경을 자아내며, 계절에 따라 붉은 열매와 노란 꽃을 감상할 수 있다. 또한 마을 내 제주특산물개발원에서는 손바닥선인장을 활용한 진액, 백년초, 과립 제품 등 다양한 특산품을 생산하고 있어 제주 선인장의 가치를 체험할 수 있다. 아름다운 해안 풍경과 지역 특산물을 함께 만날 수 있는 제주만의 특색 있는 관광지이다.','제주특별자치도 제주시 한림읍 금능남로 418',NULL,33.354236595,126.2529225533,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-06-22 13:32:26'),
('50110','KTO_TOURAPI','637212','ATTRACTION','제주마방목지','제주마방목지는 제주특별자치도 제주시 5·16도로 인근에 위치한 방목지로, 제주 고유 혈통의 제주마를 가까이에서 볼 수 있는 곳이다. 넓은 초원에서 방목되는 제주마의 모습을 관찰할 수 있으며, 제주마는 천연기념물로 지정되어 보호·관리되고 있다. 한라산 중산간 지역의 드넓은 초원과 어우러진 풍경이 인상적이며, 계절과 날씨에 따라 각기 다른 매력을 선사한다. 문화유산 보호를 위해 방목지 내부 출입은 제한되며, 지정된 관람 구역에서 제주마와 자연경관을 감상할 수 있다.','제주특별자치도 제주시 516로 2480',NULL,33.4275893792,126.6036880018,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-06-22 13:26:22'),
('50110','KTO_TOURAPI','801097','ATTRACTION','제주 명도암참살이마을','제주 명도암참살이마을은 제주시 봉개동에 위치한 중산간 농촌마을로, 1604년경 조선시대 유학자인 명도암 김징용 선생이 유학을 전파한 데서 그 이름이 유래되었다. 마을 주변은 노루가 서식하고 약 16개의 오름이 둘러싼 자연환경으로, 자연연못과 습지가 잘 발달한 것이 특징이다. 이곳은 드넓은 목장과 초지가 어우러져 양 떼가 뛰노는 이국적인 풍경을 자아내며, 자연 그대로의 삶을 지향하는 ‘참살이’ 철학을 바탕으로 한 조용하고 평화로운 농촌 마을이다. 또한 마을 전체에서 연중 채소를 생산하여 신선하고 건강한 먹거리를 제공하는 친환경 농업 마을로 알려져 있다. 옛 자연환경과 생활 방식이 잘 보존되어 있어 제주의 중산간 마을 특유의 정취를 느낄 수 있는 곳이다.','제주특별자치도 제주시 명림로 268-71',NULL,33.4916790001,126.5948706883,NULL,'https://www.visitjeju.net/kr','체험별로 상이함※ 자세한 사항은 전화 문의 요망','연중무휴',90,0,'2026-06-18 10:35:49'),
('50110','KTO_TOURAPI','1890177','ATTRACTION','동검은이오름','제주시 구좌읍 종달리에 있는 동검은이오름은 동거문오름, 동거문이오름, 거미오름으로도 불린다. 조천에도 검은 오름이 있어 ‘동’을 붙였으며, 오름이 검은색을 띠는 것을 보고 검은이오름이라는 이름이 붙여졌다는 설과 오름 사면이 사방으로 뻗어나가는 모습이 거미집 같다고 하여 거미오름이라 한다는 설이 있다. 
일반적인 오름들처럼 둥글고 매끄러운 모습이 아니라 능선이 끊어질 듯 이어지며, 멀리서 보면 여러 개의 오름인 듯 보이는 모양을 하고 있다. 동거문오름은 보는 방향에 따라 다채로운 모양을 보인다. 백약이오름에서 바라보면 다리를 세운 거미 모양이며, 반대 방향에서 보면 혹이 두 개 달린 낙타 모양을 하고 있다.

(출처: 비짓제주 홈페이지)','제주특별자치도 제주시 구좌읍 종달리 산70',NULL,33.4494,126.8047,NULL,'http://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-06-15 17:45:07'),
('50110','KTO_TOURAPI','126462','ATTRACTION','오현단','조선시대에 이곳 제주도에 유배되거나 방어사로 부임하여 이 지방의 교학 발전에 공헌한 다섯 분(5현)을 기리고 있는 제단으로, 이들의 위패를 모시던 귤림서원의 옛 터에 마련되어 있다. 5현은 중종 15년(1520)에 유배된 충암 김정 선생, 중종 29년(1534)에 제주목사로 부임해 온 규암 송인수선생, 선조 34(1601)에 안무사로 왔던 청음 김상헌선생, 광해군 6년(1614)에 유배된 동계 정온 선생, 숙종 15년(1689)에 유배된 우암 송시열 선생 등 다섯 분이다. 고종 29년(1892) 제주사람 김의정이 중심이 되어 비를 세우고 제단을 쌓아놓았는데, 원래는 선조 11년(1578) 임진이 목사로 있을 때, 판관 조인준이 가락천 동쪽에 충암 김정을 모시기 위한 충암묘를 지은 것이 그 시초이다. 현종 6년(1665) 판관 최진남이 이 묘를 장수당 남쪽인 지금의 자리로 옮겨놓은 뒤, 숙종 8년(1682) 예조정랑 안건지를 제주도에 파견하여 ‘귤림서원’이라는 현판을 하사하여 김정 선생·송인수 선생·김상헌 선생·정온 선생 등 네 분의 위패를 모시도록 하였다. 숙종 21년(1695) 송시열 선생도 함께 모시면서 5현을 배향하게 되었으나, 고종 8년(1871) 서원 철폐령이 내렸을 때 서원이 헐리게 되어, 그 터에 이 제단을 설치하게 되었다. 단내에 있는 5현의 자취로는 철종 7년(1856) 송시열 선생의 글씨로 하여 판관 홍경섭이 바위에 새긴 ‘증주벽립’이라는 글씨와, 김정 선생과 송시열 선생의 ‘적려유허비’가 남아있다.','제주특별자치도 제주시 오현길 61','(이도일동)',33.5102618336,126.5255683759,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-06-12 17:54:10'),
('50110','KTO_TOURAPI','2905045','ATTRACTION','와흘메밀마을','제주 한라산 북쪽 사면 밑에 자리 잡은 와흘리는 구그네오름, 세미오름 등 여러 오름에 둘러 쌓여있고, 넓은 초지가 있는 중산간 마을이다. 산세모습이 마치 사람이 편안하게 누운 모습과 같다 하여 누울 ‘와’, 산 높을 ‘흘’이라 칭한 만큼 편안한 인심을 가진 사람들이 모여 하늘을 섬기던 전통을 잇고, 땅을 지키며, 이웃과 함께하는 아름다운 전형적인 농촌마을이다. 
매년 5월과 10월이면 하얀 메밀꽃이 만개해 사진 촬영 명소로 유명하다. 5월에는 축제가 열리며 다양한 체험행사도 진행한다. 
제주특별자치도 제주시 조천읍에 소재하고 있으며 제주공항에서 30분으로 제주시와 가까운 거리에 위치해 있다.','제주특별자치도 제주시 조천읍 남조로 2455',NULL,33.4827833507,126.650068827,NULL,'https://waheul.com','09:00~18:00','연중무휴',90,0,'2026-06-12 09:57:08'),
('50110','KTO_TOURAPI','127743','ATTRACTION','제주향교','제주향교는 훌륭한 유학자의 위패를 모시고 제사를 지내며 지방민의 교육과 교화를 위해 설립된 고려·조선시대의 국립 교육기관이자 제주의 학교이다. 조선 태조 원년인 1392년에 설립되었으며, 여러 차례의 개축과 이전을 거듭하다 순조 27년인 1827년 오늘날의 자리에 들어섰다. 인재 양성과 학문 수양의 목적으로 세워졌지만 조선 초 중엽 서원이 등장하면서 서원의 압력을 받아 교육기관으로서의 기능은 약화되었다. 대성전, 명륜당, 전사청, 계성사 등이 남아 있고 계성사에는 5성의 위패가 있다.','제주특별자치도 제주시 서문로 43',NULL,33.511128243,126.5158220408,NULL,'https://jejuhyanggyo.co.kr/','06:00~18:00※ 자세한 사항은 전화문의 요망','연중무휴',90,0,'2026-06-10 08:34:38'),
('50110','KTO_TOURAPI','2837222','ATTRACTION','코난해변','코난 해변 또는 코난 비치로 알려져 있으며 월정리해수욕장에서 제주 동쪽 구좌방파제 근처에 위치해있다. 큰 해수욕장은 아니고 특별한 시설은 없지만, 에메랄드빛을 가득 머금은 바다로 수심이 얕고 용암에 의해 형성된 바위가 바닷물을 막아 다양한 깊이의 물놀이 장소로 나뉜다. 바다 색이 워낙 아름다워 물놀이를 하지 않고 해변 근처의 예쁜 길을 쭉 산책만 해도 힐링이 가능하다. 또한 일몰 맛집이기 때문에 시간 맞춰 방문하는 것도 추천한다. 근처에는 해녀노래전승관, 월정리 해수욕장, 김녕해수욕장 등이 있다. 

◎ 한류의 매력을 만나는 여행 정보 - 예능 
동진, 혜원이 데이트를 즐긴 코난해변은 탁 트인 하늘과 에메랄드빛 바다, 그사이 우뚝 솟은 풍력발전기의 풍경이 한 장의 그림처럼 아름다운 곳이다. 제주 동쪽의 카약과 스노클링 명소로 떠오르고 있으며 운이 좋으면 돌고래 떼를 만날 수도 있다.','제주특별자치도 제주시 구좌읍 행원리','575-6',33.5575720498,126.8111907275,NULL,'https://www.visitjeju.net/kr/','상시 개방','연중무휴',90,0,'2026-06-10 08:34:38'),
('50110','KTO_TOURAPI','2742307','ATTRACTION','싱계물공원','제주시의 숨은 비경 중 하나로 선정되기도 했던 싱계물공원은 신창-풍차 해안이라는 이름으로 더 유명한 곳으로 주변의 풍력발전기들과 함께 이국적인 풍경을 보여준다. 싱게물(싱계물)은 제주 사투리로 ‘새로 발견한 갯물’이라는 의미이며 갯물이라는 것은 용천수를 의미한다. 싱계물공원에는 예전에 목욕탕으로 쓰이던 곳이 있는데, 돌담으로 남탕·여탕이 구분되어 있으며, 용천수라 맑고 깨끗하며 시원하다. 싱계물공원에는 등대까지 직접 걸어갈 수 있도록 바다 위로 다리가 설치되어 있다. 바람과 파도에 살짝 흔들거리기도 하는 다리를 건너면 마치 바다 위를 걷는 것만 같은 이색적인 느낌을 받을 수 있다. 바다에 떠 있는 느낌의 사진이나 근방의 억새를 배경으로 촬영을 많이 하며 최근에는 셀프웨딩 명소로 주목받고 있다. 싱계물공원의 최고의 아름다운 순간은 노을이 질 때다. 신창-용수 해안도로로 이어지며 바다와 풍차가 어우러진 이곳에서는 멀리 보이는 차귀도, 수월봉과 함께 떨어지는 낙조가 아름다운 풍경을 선사한다.','제주특별자치도 제주시 한경면 신창리 1322-1',NULL,33.3434173465,126.1738937595,NULL,'https://www.visitjeju.net/kr','상시 개방','연중무휴',90,0,'2026-06-05 08:42:51'),
('50110','KTO_TOURAPI','4063885','ATTRACTION','안친오름','제주에 위치한 안친오름은 아진오름, 좌악(座岳), 좌치악(座置岳), 아친악(雅親岳) 등 여러 별칭이 있다. 오름의 형상이 두 다리를 벌리고 앉아 있는 사람의 모양과 닮은 데서 유래한 명칭이다. 또한 안친오름의 ‘안친’은 ‘앉히다’에 대응하는 제주어 ‘안치다’의 관형사형으로, 오름의 형세가 ‘나지막하게 앉힌 솥과 같다’는 데서 유래하였다. 높이 192m, 둘레 924m, 총면적 4만 6443m² 규모의 기생 화산이다. 전체적으로 나지막하며 북쪽 비탈면에 북쪽으로 입구가 벌어진 말굽형 분화구가 있고, 분화구 안쪽의 넓은 풀밭 한가운데에는 여러 개의 묘가 자리 잡고 있다. 안친오름은 송당리 본동 북쪽에 있는 오름으로 형태가 나지막하기 때문에 오름으로 인식하기 어려우며 안친오름 일대는 대부분 농경지로 조성되어 있다.

(출처 : 비짓제주)','제주특별자치도 제주시 구좌읍 송당리 880-1',NULL,33.478751,126.785714,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-05-27 16:25:19'),
('50110','KTO_TOURAPI','3056205','ATTRACTION','관곶','제주 조천읍 신흥리에 있는 관곶은 일몰 명소로 알려진 관광지이다. 관곶은 제주에서 해남 땅끝마을과 가장 가까운 곳이며, 조천관 시대에 조천포구로 가는 길목에 있는 곶이라는 뜻으로 관곶이라고 불리고 있으며, 제주의 울돌목이라고 비유되는데 지나가는 배가 뒤집어질 정도로 파도가 거센 곳이다. 조망이 아름답고 바다로 지는 노을을 볼 수 있으며 산책로와 각종 편의시설이 잘 조성되어 있어 바다를 바라보며 힐링할 수 있는 제주의 숨은 관광지이다. 가족과 연인과 함께 제주 여행의 추억을 남기기 좋은 장소이다. 주변에는 신흥해수욕장, 신흥바다낚시공원 등이 있어 함께 둘러보기 좋다.','제주특별자치도 제주시 조천읍 조함해안로 217-1',NULL,33.5532235889717,126.64406921204653,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-05-27 10:28:53'),
('50110','KTO_TOURAPI','2779462','ATTRACTION','종달항(두문포항)','종달리 해안 도로는 봄과 여름 사이, 길을 따라 만개하는 수국 길로 유명하다. 하도리 해수욕장에서 왼쪽에 바다를 끼고 이 해안 도로를 따라 달리다 보면 자그마한 종달항과 해변이 나온다. 종달항 혹은 두문포항이라고도 불리는 작은 항구가 있다. 작은 어선이 선박해 있으며, 우도로 가는 여객선이 운항하는 항구이다. 이곳은 항구 자체로도 아름답기로 유명하다. 성산 일출봉과 우도가 보이고, 뒤편으로는 지미봉까지 보인다. 물이 맑고 잔잔해 가볍게 산책을 즐기기에도 좋은 곳이다.','제주특별자치도 제주시 구좌읍 종달리 484-10',NULL,33.4965502173871,126.910660686374,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-05-26 15:18:33'),
('50110','KTO_TOURAPI','1936339','ATTRACTION','제주 청수리마을','청수리 마을은 제주 생태계의 보고인 곶자왈 지역으로 다양한 야생식물과 야생화가 자생하고 있는 곳이다. 운문산 반딧불이의 최대 서식지인 청수리 마을은 청정한 환경을 지키고자 마을의 자원을 가꾸며 살아가는 마을이다. 
‘맑고 깨끗한 물’이라는 데서 붙여진 청수리는 제주시에서 서쪽으로 약 45㎞에 위치해 있으며, 북쪽은 한림읍, 서쪽은 낙천리, 남쪽은 산양리로 에워 싸여 있다. 친환경 농업경영과 곶자왈 보전 등 환경오염을 걱정하고 자연보호를 실천하고 있기 때문에 믿을 수 있는 농산물과 깨끗한 자연환경을 자랑하며, 이러한 자연자원과 역사문화자원을 바탕으로 다양한 프로그램들을 개발하여 농촌체험관광의 메카로 거듭나 도민은 물론 국내외 관광객의 방문이 끊이지 않고 있다.','제주특별자치도 제주시 한경면 대한로 1036',NULL,33.3175650318651,126.247673674219,NULL,'https://www.cheongsuri.kr/index.php','상시 개방','연중무휴',90,0,'2026-05-20 17:02:23'),
('50110','KTO_TOURAPI','2799740','ATTRACTION','비양도선착장','제주의 또 다른 섬으로 불리는 비양도는 날아온 섬이라는 뜻을 가지고 있으며, 우리나라에서 유일하게 탄생에 대한 역사적 문헌이 남아있다. 천년의 섬이라 불리는 비양도는 아름다운 자연경관과 무한한 관광자원을 가지고 있다. 본 섬의 한림항에서 비양도로 들어가는 배를 탈 수 있다. 하루에 4번 정도 들어오고 나가는 배편이 있고, 한림항에서 15분 정도 소요된다. 기상에 따른 스케줄 변동이 있을 수 있기 때문에 미리 유선으로 확인하고 가는 편이 좋다. 섬 안의 해안 도로를 따라 걷다 보면 기암괴석을 볼 수 있는데, 애기업은돌과 코끼리 바위가 대표적이다. 또 뭍에서는 보기 드문 바닷물로 된 염습지 필랑못이 있으며, 작은 섬이기 때문에 트래킹 명소로도 주목받고 있다. 주로 두 가지 코스가 있는데, 비양도항에서 비양봉을 돌고 나오는 비양 오름길, 비양도 한 바퀴를 전부 둘러보는 비양도 한 바퀴 일주 코스로 나뉜다.','제주특별자치도 제주시 한림읍 한림해안로 192',NULL,33.4190599358847,126.262561589665,NULL,NULL,'- 비양도호 한림항 출발 09:20 / 11:20 / 13:20 / 15:20- 비양도호 비양도 출발 09:35 / 11:35 / 13:35 / 15:35- 2천년호 한림항 출발 09:00 / 12:00 / 14:00 / 15:30- 2천년호 비양도 출발 09:15 / 12:15 / 14:15 / 15:45※ 자세한 사항은 전화 문의 요망','연중무휴',90,0,'2026-05-12 11:26:39'),
('50110','KTO_TOURAPI','4063148','ATTRACTION','수산저수지','수산저수지는 수산봉 기슭에 자리 잡고 있는 제주에서 보기 드문 큰 면적의 인공 저수지이다. 올레길 16코스를 따라 수산봉을 지나 저수지 방향으로 걷다 보면 수산리를 지키는 천연기념물 곰솔나무가 있는데, 400여 년이나 지난 이 곰솔은 마을의 수호목으로 주민들이 적극 보호하는 등 문화적 가치가 매우 높다. 저수지의 수면에 닿을 듯 말 듯한 모습이 독특하고 멋스러운 자태를 뽐낸다. 또한 곰솔의 상부에 눈이 덮이면 마치 백곰이 저수지의 물을 마시는 모습을 연상케 하기도 한다. 곰솔나무를 지나면 30,000평이 넘는 수산 저수지가 멋진 풍광을 자랑하고 있으며, 아름다운 경치를 보기 위해 올레꾼들이 꾸준히 찾아와 둑길에 앉아 휴식을 취하기도 한다. 또한 낚시를 즐기는 사람들은 낮이나 밤에 찾아와 이곳에서 붕어나 잉어를 낚시한다. 듬직한 수호목이 반기는 수산저수지에서 제주바다와는 다른 색다른 매력이 있다.

(출처 : 비짓제주)','제주특별자치도 제주시 애월읍 수산리',NULL,33.471222,126.387528,NULL,'https://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-05-08 16:23:35'),
('50110','KTO_TOURAPI','4061120','ATTRACTION','아라동 치유의 숲','아라동 치유의 숲은 제주대학교에서 관음사로 가는 길목에 위치해 있다. 또한 아라동 문화역사 탐방로 2코스의 일부이며 소산오름 자락에서 마주할 수 있는 곳이다. 산림욕을 하며 피톤치드를 마실 수도 있고, 조용히 걷기도 좋다. 특히 건강에 좋은 맨발 걷기를 하는 사람도 많다. 이곳에서는 흡연, 야영, 취사가 불가하다.','제주특별자치도 제주시 아라일동 산31-8',NULL,33.443987,126.555575,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-04-29 13:46:31'),
('50110','KTO_TOURAPI','3057286','ATTRACTION','함덕잠수함','함덕잠수함은 잠수함과 요트를 한꺼번에 이용할 수 있도록 배 아래에 투명창을 설치하여 수중 세계를 볼 수 있도록 설계된 선박이다. 함덕잠수함은 타 잠수함과 달리, 몇 개의 계단만 내려가면 멋진 수중 세계를 볼 수 있고 위로 올라오면 요트 체험을 할 수 있다. 자유롭게 수중과 수상을 이동할 수 있으며 한 배에 한 그룹만 탑승하기 때문에 방해 없이 조용하게 체험을 즐길 수 있다. 함덕잠수함은 제주도에서도 가장 물이 깨끗한 에메랄드빛 함덕 바다에서 운항하며 탁 트인 바다 풍경이 아름답고 물속 관찰이 용이하며, 가끔은 돌고래 떼도 볼 수 있다. 바다 위에서 물고기 밥 주기 체험도 같이할 수 있어 특별한 경험을 만들 수 있다.','제주특별자치도 제주시 조천읍 조함해안로 378',NULL,33.54780234884782,126.65681931018375,NULL,NULL,'09:30~18:00','연중무휴',90,0,'2026-04-28 09:56:46'),
('50110','KTO_TOURAPI','3530351','ATTRACTION','샛도리물','제주 삼양해수욕장에서 산책로를 따라 동쪽으로 걸으면 담수와 바닷물이 만나는 천연 풀장 샛도리물이 나타난다. 나쁜 기운과 잡귀를 상징하는 까마귀를 쫓아내는 샛도림(새쫒음) 굿을 할 때 이 물을 길어다 쓴 데서 유래해 샛도리물이라는 독특한 이름을 붙였다. 신성한 의식에 사용된 물답게 맑고 깨끗한 수질을 자랑하며, 포구 안쪽에는 차가운 용천수가 흐른다. 또한 포구 바깥쪽에는 바닷물이 흐르는 샛도리물은 물때에 따라 모습을 바뀐다. 간조 때는 수심이 얕은 대신 차가운 용천수가 무더위를 식혀주고 만조 때는 바닷물과 용천수가 만나 수온이 오르는 대신 수심이 깊어져 물놀이를 즐기기 좋다. 샛도리물 바로 옆에 자리한 삼양해수욕장은 검은 모래사장으로 유명해 함께 방문하기 좋다.','제주특별자치도 제주시 삼양일동','1938-9',33.5291,126.5892,NULL,'https://www.visitjeju.net','10:00~22:00※ 운영 시간 외 입수 및 음주, 텐트 설치 금지','연중무휴',90,0,'2026-04-15 14:33:57'),
('50110','KTO_TOURAPI','2773755','ATTRACTION','제주에너지누리마당','제주에너지누리마당은 미래의 에너지 자원으로 꼽히는 신재생에너지를 배우는 전시·학습 공간이다. 제주도에서 시행 중인 신재생에너지 정책과 미래형 에너지 도시 모델도 미리 만나볼 수 있다. 전시관은 2층에 위치한다. 먼저 터널 형식인 산업혁명관을 지나면 곧바로 기후위기관으로 이어진다. 우리나라를 비롯해 대륙별로 감지되는 이상기후 현황과 피해 사례가 전시되어 있다. 또한 국내 최초 ‘탄소 없는 섬(CFI; Carbon Free Island)’ 시범 모델인 가파도의 마이크로그리드 시스템도 자세히 살펴볼 수 있다.','제주특별자치도 제주시 구좌읍 해맞이해안로 712-3',NULL,33.559311665911,126.818655162866,NULL,NULL,'10:00~17:00 (휴게시간 12:00~13:00)','매주 토요일, 일요일 / 공휴일 / 명절 연휴 / 4·3기념일',90,0,'2026-04-10 17:50:45'),
('50110','KTO_TOURAPI','3038062','ATTRACTION','제주이호랜드','제주이호랜드는 제주올레길 17코스로 이호 테우해변과 인접한, 야자나무가 아름다운 공원이다. 라벤더, 수국, 버베나, 코스모스 등 다양한 꽃들이 시기마다 피어나고 곧게 뻗은 야자수는 이국적인 풍경을 만들어낸다. 제주공항에서 아주 가까워서 낮게 나는 비행기와 함께 사진을 찍을 수도 있고, 제주바다와 이호 테우 말 등대를 배경으로 이국적인 풍경도 즐길 수 있는 공원이다. 이호랜드 옆에는 이호 테우해변이 있어 바다에서 놀거나 해변 옆 깊은 소나무 숲길도 산책해 볼 수 있다.','제주특별자치도 제주시 이호일동','374-1',33.499659,126.455058,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-04-10 16:59:36'),
('50110','KTO_TOURAPI','3080405','ATTRACTION','캔디원','캔디원은 조천읍에 있는 수제캔디 전문점으로 ‘SWEET TO EVERYONE(모두에게 달콤한)’을 모토로 수제캔디를 통해 달콤한 행복을 주기 위해 2014년 문을 열었다. 수제캔디 전문점으로는 세계에서 가장 큰 규모이이다. 오래전부터 사용하던 사탕기계와 다양한 사진전시물을 통해 사탕의 유래를 한눈에 볼 수 있고 전 세계 다양하고 신기한 사탕들이 전시되어 있어 사탕에 관한 신비한 볼거리가 많다. 아이들이 체험을 즐길 수 있도록 캔디체험학습장을 보유하여 만들어진 수제캔디를 직접 잘라보고 다양한 색의 롤리팝 캔디를 우리 아이들의 손으로 직접 만들어보는 체험을 즐길 수 있다. 캔디열판이 뜨겁기 때문에 캔디 만들기 체험은 기본적으로 키가 120㎝ 이상이 되어야 안전하게 체험할 수 있으며 키가 되지 않은 5살 이상 미취학 아동은 부모와 함께 캔디 컷팅체험을 할 수 있다. 판매장에서는 시중에서는 볼 수 없는 다양한 모양의 수제캔디와 젤리, 그 외에도 선물이나 기념품으로 구매할 만한 굿즈들을 구매할 수 있다.','제주특별자치도 제주시 조천읍 선교로 384',NULL,33.47129448253796,126.70775177421912,NULL,'http://candyone.co.kr','09:00~18:00※ 동절기·하절기 마감 시간이 상이할 수 있으므로 홈페이지 참조 및 전화 문의 요망','연중무휴',90,0,'2026-04-10 15:17:25'),
('50110','KTO_TOURAPI','3071816','ATTRACTION','오저여','해안경관이 아름다운 오저여는 제주시 구좌읍 행원리에 위치한 일몰 명소로 월정리 해수욕장에서 행원 해수욕장을 조금 지난 곳에 있다. 오저여는 제주어로 물새가 날아와서 새끼를 치는 바위 또는 작은 섬을 뜻한다. 오저여는 제주 동쪽 해안가에 위치하고 있으며, 푸른 바다와 풍력발전단지의 풍경을 감상할 수 있는 곳이다. 해 질 무렵 오묘한 붉은빛의 일몰이 아름다워 여행객과 사진작가들 사이에 알음알음 입소문이 나면서 많은 사람들이 찾아오고 있는 곳이다. 오저여는 일몰 명소로 유명하지만, 일출 명소로도 유명한 곳이다. 바닷가 주변으로 해녀상과 돌하르방 등 다양한 석상을 둘러보는 재미도 쏠쏠하고 바닷가 정자에서 잠시 휴식을 취해도 좋으며 해맞이 해안도로를 달리다가 잠시 차를 세워 둘러보는 것도 좋다. 오저여에서는 운이 좋다면 가끔 제주 남방 돌고래를 볼 수 있는 곳으로도 알려져 있다.','제주특별자치도 제주시 구좌읍 행원리',NULL,33.561454,126.814276,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-04-10 14:53:51'),
('50110','KTO_TOURAPI','3037603','ATTRACTION','맛동산 감귤체험농장','애월읍에 위치한 맛동산 감귤체험농장은 2019년 농림축산식품부 지정 인증을 받은 농장으로 안전하고 건강한 감귤을 재배하고 있다. 맛동산 감귤체험농장에서는 다양한 감귤 체험 프로그램과 직접 수확한 감귤로 감귤청을 만드는 체험을 진행하며 농장에서 재배하는 풋귤, 하우스귤, 타이백귤, 사백향을 수확할 수 있다. 감귤수확체험은 시기별로 품종과 체험비가 다르니 사전에 전화로 문의하거나 네이버 예약사이트를 이용하기를 추천한다. 감귤 따기 체험을 예약한 인원만 입장가능 하며 만 36개월 미만 소아의 경우 부모와 동반 입장 가능하다. 귤 수확방법도 어렵지 않고, 싱싱한 귤도 실컷 먹을 수 있어 가족단위 여행객이나 친구·연인 등 남녀노소 재미있게 즐길 수 있는 제주 체험이다. 따기 체험을 하면서 감귤을 먹는 것은 무제한이며 체험이 끝나고 수확한 귤 무게를 잰 후에 추가 요금이 발생할 수 있으니 체험 시 참조하면 된다. 체험을 마무리한 후 농장에서 직접 만든 귤청으로 만든 귤차와 귤마들렌을 맛볼 수 있으며 농장에 조성된 포토존에서 귤밭을 배경으로 사진을 찍을 수도 있다.','제주특별자치도 제주시 애월읍 광령2길 62-1',NULL,33.45476723766368,126.42985216031016,NULL,'https://blog.naver.com/moonhj8030','※ 시기에 따라 변동되므로 자세한 사항은 홈페이지 참조 및 전화 문의 요망','매주 월요일',90,0,'2026-04-10 13:59:15'),
('50110','KTO_TOURAPI','3038479','ATTRACTION','장생의숲길','제주 절물자연휴양림 안에 있는 장생의숲길은 제주시 숨은 비경 31에서 선정된 곳 중 하나이다. 흙 그대로의 길로 낙엽이 쌓여 폭신폭신하기까지 하다. 자연스러운 걸음은 흙으로 흡수되어 발목이나 무릎에 오는 충격이 약하다. 길에 있는 울퉁불퉁한 돌과 송이는 오히려 발을 자극하여 지압 효과까지 나서 기분도 좋아진다. 자연적인 오르막길과 내리막길이 형성되어 있고 길 양쪽으로 각종 식물들이 자라고 있어 기분도 좋으며 쉽게 지루해지지 않고 피곤함도 적다. 나무와 식물들의 신비로운 모습을 볼 수 있으며 여름에는 습도가 높아 다양한 버섯들과 초록색의 이끼들을 보며 걸을 수 있다. 장생의숲길은 오후 16시 이후에는 일몰시간으로 출입을 금하며, 흙길이 많기 때문에 비가 많이 내린 다음날에는 출입통제를 하는 경우도 있으니 미리 연락을 취해 알아보고 가는 것이 좋다.','제주특별자치도 제주시 명림로 584 (봉개동)',NULL,33.439737252689625,126.63036259117361,NULL,NULL,'07:00~17:00','연중무휴',90,0,'2026-04-10 13:09:59'),
('50110','KTO_TOURAPI','3071875','ATTRACTION','제주송정농원','제주송정농원은 제주국제공항에서 차량으로 15분 거리에 위치해 뚜벅이 여행자들도 체험이 용이한 감귤 농장이다. 이곳에서는 감귤 따기 체험과 함께 한라봉, 천혜향, 레드향, 황금향 등 다양한 종류의 감귤을 구입할 수 있다. 또한, 송정농원의 건물과 농장 주변을 배경으로 사진을 찍을 수 있으며 즐거운 사진 찍기를 위한 주황색, 노란색 감귤모자와 선글라스 등 사진 찍을 때 활용하기 좋은 소품들을 무료로 이용할 수 있다. 감귤체험은 10월부터 소진 시까지 진행되며 대체로 레드향은 1월부터, 천혜향은 2월부터 진행되며 조기 마감될 수 있으니 일정에 참조하면 된다. 귤 따기 체험은 하루 13회 진행하며 30분 단위로 운영되고 있으며 귤 따기 체험을 하면서 시식은 무제한으로 가능하다. 정해진 통 안에만 넣어 오면 가져갈 수 있어서 푸근한 제주의 인심을 느낄 수 있는 가성비 감귤체험 농장이다.','제주특별자치도 제주시 영평동','2470-5',33.48018,126.564215,NULL,'https://blog.naver.com/kto6360','10:00~17:00 (입장 마감 16:00) ※ 체험 시즌 종료 후 휴장함으로 홈페이지 참조 및 전화 문의 요망','※ 체험 시즌 종료 후 휴장함으로 홈페이지 참조 및 전화 문의 요망',90,0,'2026-04-09 17:36:44'),
('50110','KTO_TOURAPI','3303346','ATTRACTION','하우스오브레퓨즈','1800평 규모의 제주의 복합문화공간, 하우스오브레퓨즈는 1층에는 10미터의 대리석바와 크고 시원한 파란색의 미술작품이 있는 곳이다. 그리고 500여 평으로 뒷마당에 펼쳐진 소나무숲과 잔디밭이 특징적인 카페 ’더 커미서리’를 운영 중이다. 제주산 바나나 푸딩, 제주 누보 논알코올 생맥주, 필터 커피 등 특색 있는 대표 메뉴가 있다. 전시, 공연, 파티 등 다양한 글로벌 이벤트를 진행할 제주의 새로운 랜드마크로서 현재 개관 전시로 한국 애니메이션 역사상 최초의 아카데미상 후보작이었던 애니메이션 ‘오페라’를 비롯한 픽사 출신 감독 ‘에릭오’의 작품세계에 흠뻑 빠져들 수 있는 대형 미디어 체험상설전도 열리고 있다.','제주특별자치도 제주시 애월읍 하소로 735',NULL,33.41928303869619,126.39600577939106,NULL,'https://www.instagram.com/hofrefuge','10:00~19:00 (입장 마감 18:30)','연중무휴',90,0,'2026-04-06 10:53:40'),
('50110','KTO_TOURAPI','3061575','ATTRACTION','흑돼지거리','제주항 탑동광장 부근에 조성된 제주 흑돼지 거리는 제주의 특산물인 흑돼지 전문점이 모여 있는 골목으로, 흑돼지를 맛보고 싶다면 방문하는 것을 추천한다. 흑돼지 거리는 오랜 전통을 자랑하고 있으며, 초입에는 흑돼지 거리 간판 조형물과 돼지 동상 조형물이 설치되어 있어 단번에 흑돼지 거리임을 알 수 있게 해주고 있다. 흑돼지는 일반 돼지고기에 비해 쫄깃하고 영양도 많다고 알려져 있으며, 흑돼지고기를 구워 꽃멸치 젓갈에 찍어 먹으면 그 맛이 담백하고 고소하여 씹을수록 입맛을 돋게 한다. 주변에는 칠성로 쇼핑거리, 동문재래시장, 생태하천 산지천, 산지 등대, 탑동광장 등 여러 관광지가 있는 제주 특화 거리이다.','제주특별자치도 제주시 일도일동',NULL,33.515417,126.526861,NULL,'https://www.visitjeju.net/','※ 점포별 상이함','※ 점포별 상이함',90,0,'2026-04-06 09:42:39'),
('50110','KTO_TOURAPI','3061701','ATTRACTION','용두암해안도로','용두암 해안도로는 용두암에서부터 도두봉까지 제주공항 북쪽의 해안을 따라 이어지는 해안도로로, 제주도민들과 관광객들이 즐겨 찾는 드라이브 코스이다. 밤에는 호텔, 카페, 횟집, 상가에서 흘러나오는 화려한 불빛을 받아 아름다운 야경을 연출하며, 야간 경관 조명 등도 설치되어 있어 야경 명소로 알려져 있다. 제주 올레길 제17코스 중 일부이며, 정식 명칭은 서해안로이지만, 제주의 유명 관광지인 용두암과 가까이 있어 용두암 해안도로 또는 용담 해안도로로 불리고 있다. 해안도로 곳곳에는 차를 대어 놓고 바다를 조망할 수 있는 공원이 조성되어 있고, 노을 명소로 유명한 도두봉 오름도 있다.','제주특별자치도 제주시 서해안로 687-8 (용담이동)',NULL,33.515548807796954,126.51209310788026,NULL,'https://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-04-06 09:42:39'),
('50110','KTO_TOURAPI','3061738','ATTRACTION','산지항로표지관리소','제주항을 바라보는 사라봉 정상에는 해양수산부 제주해양수산관리단 산지항로표지관리사무소에서 무인으로 운영하는 산지 등대가 있다. 산지 등대는 제주항 및 부근 해역을 항해하는 선박의 안전 운항을 위하여 1916년 10월 무인 등대를 설치하여 84년간 운영하였으나, 노후되어 1999년 12월 폐지하고, 역사적 가치를 인정받아 원형 형태로 영구 보존하게 된 등대이다. 1917년 유인등대로 변경하여 운영하다가, 1999년 12월 등대 옆에 모양이 비슷한 등대를 새로 세워 무인으로 운영하고 있다. 산지항로표지관리소로 올라가는 담벼락에는 우도등대, 마라도등대, 영도등대 등 우리나라의 아름다운 등대 16경에 대한 전경과 설명문이 비치되어 있어 등대의 역사를 알 수 있도록 운영되고 있다.','제주특별자치도 제주시 사라봉동길 108-1 (건입동)',NULL,33.52120444391013,126.5455560998841,NULL,'https://www.visitjeju.net/','[하절기] 09:00~19:30[동절기] 09:00~18:00※ 안전상의 이유로 이용시간 외 출입불가','연중무휴',90,0,'2026-04-06 09:42:39'),
('50110','KTO_TOURAPI','3110802','ATTRACTION','씬오브제주','씬오브제주는 제주도 애월읍에 위치한 천연염색 브랜드로 제주의 자연 재료를 활용한 친환경적인 염색 제품과 체험 프로그램을 제공하는 곳이다. 주요 특징은 제주에서 자란 꽃, 나뭇잎, 양파 껍질 등 자연 재료를 사용해 의류와 소품을 염색하는 것이다. 또한 방문객들을 위한 자연 염색 클래스를 운영하며 플라워 다잉, 나뭇잎 염색, 양파 껍질 염색 등 다양한 기법을 배울 수 있다. 제주 로컬 음식점 ‘카레 현’과 협업하여 버려지는 양파 껍질을 재활용하고 있다.
애월읍 금성리와 협력하여 마을 알리기 프로젝트를 진행하는 등 지역 발전에 기여하고 있으며, 씬오브제주는 단순한 염색 브랜드를 넘어 제주의 자연과 문화를 체험하고 힐링할 수 있는 공간으로 지속 가능한 관광과 로컬 비즈니스의 좋은 사례로 평가받고 있는 곳이다.','제주특별자치도 제주시 애월읍 금성3길 21',NULL,33.44605117498354,126.300416650902,NULL,NULL,'11:00~17:00','매주 화요일~목요일',90,0,'2026-04-06 09:42:39'),
('50110','KTO_TOURAPI','3329719','ATTRACTION','제주안전체험관','제주안전체험관은 2020년 11월 3일 개관하여 제주도민을 비롯한 국내외 제주 방문객들의 안전문화 정착을 목표로 설립된 전국 8번째 안전체험관이다. 지상 3층, 연면적 5,427.63㎡의 규모로 누구나 쉽게 재난을 경험하고 극복하는 방법을 배울 수 있도록 다양한 안전체험 프로그램을 갖추고 있다.','제주특별자치도 제주시 애월읍 평화로 1885',NULL,33.394132960406694,126.3734284420147,NULL,'https://www.jeju.go.kr/119safe/index.htm','09:00~18:00','매주 월요일(단, 월요일이 법정공휴일인 경우에는 그 다음날 휴관) / 1월 1일 / 설·추석 연휴',90,0,'2026-04-06 09:42:39'),
('50110','KTO_TOURAPI','3061637','ATTRACTION','렛츠런팜','렛츠런팜은 한국마사회가 운영하는 종마를 관리하는 목장이다. 종마란 ‘씨수말’이라는 뜻이다. ​​렛츠런팜에는 200만㎡가 넘는 면적에 씨수말 마사, 동물병원, 씨수말 초지, 실내마장, 말수영장, 실내 원형 마장, 야외 주로 등 말과 관련한 모든 시설들을 운영하고 있다. 관광객들을 위하여 목장 구석구석을 둘러볼 수 있는 트랙터 마차 체험이 3월부터 10월까지 매 주말마다 목장 내 주요시설을 둘러보는 트랙터 마차 투어가 운영되고 있다. 단, 교배시즌에는 전면 출입 금지라서 방문 전 문의가 필요하다. 현재 마사와, 씨수말 방목지, 동물병원 그리고 동백길(목장 올렛길)은 일반인 출입 금지다. 편자를 이용한 럭키 캐쳐 만들기 체험도 진행하고 있다. 잔디광장에 하트 조형물, 메니피 동상 등 이 있어 곳곳에서 사진을 찍을 수 있고 넓은 초지에서 놀고 있는 종마도 볼 수 있다. 여름에는 해바라기 꽃밭을 조성하여 관람할 수 있도록 하였으며 한라산과 붉은오름 등 많은 오름을 조망할 수 있는 한라산 전망대도 있다.','제주특별자치도 제주시 조천읍 남조로 1649-24',NULL,33.41304730702276,126.67552416119422,NULL,NULL,'- 09:00∼18:00[트랙터 마차투어(4월~11월)]- 매주 금요일~일요일 11:00~16:30','매주 월요일~화요일 / 법정공휴일',90,0,'2026-04-06 09:35:55'),
('50110','KTO_TOURAPI','3056625','ATTRACTION','애월한담공원','애월읍 애월리에 있는 애월한담공원은 바다를 조망할 수 있는 해안가 공원이다. 공원에는 1992년 8월에 설치한 물허벅여인상이 있고, 제주의 에메랄드빛 바다를 한눈에 담을 수 있다. 애월한담공원에는 무료 주차장이 설치되어 있어 편리하게 공원을 산책할 수 있으며, 공원 아래에는 애월 해안산책로가 잘 조성되어 있어 애월여행에서 빠질 수 없는 코스이다. 제주 올레길 15코스가 지나는 둘레길이 운영되고 있어 올레길 트레킹을 즐길 수 있으며, 공원이 애월 카페거리와 인접해 있어 산책 후 전망 좋은 카페에 들러 여유로운 시간을 보낼 수 있다.','제주특별자치도 제주시 애월읍 애월로 11',NULL,33.46002879059966,126.31126447797632,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-04-01 13:35:32'),
('50110','KTO_TOURAPI','3056401','ATTRACTION','감수굴 밭담길','평대리 중동에 위치한 감수굴 밭담길은 고즈넉한 마을의 옛 정취 그대로의 풍경을 즐기며 산책하기 좋은 길이다. 평대리 중동마을회관에서 출발한다. 밭담은 화산섬인 제주도에서 경작을 위해 밭을 개간하면서 흩어져 있는 돌들을 밭 옆에 쌓은 담으로, 밭담의 돌들이 얼기설기 물려있고, 틈새가 있어 태풍에도 무너지지 않으며, 바람으로부터 농작물을 보호하고, 가축의 침입을 예방하기 위하여 쌓았다. 감수굴 밭담길에는 감수굴 우물이 있다. 우물의 물맛이 좋아 감수라 이름이 붙었다고 한다. 감수굴 밭담길은 제주 돌담과 농촌의 문화, 환경을 체험하고, 지역홍보 활성화를 위해 난미 밭담길, 진빌레 밭담길, 물메 밭담길, 어멍아방 밭담길 등과 함께 제주 8대 밭담길로 지정되어 있다.','제주특별자치도 제주시 구좌읍 평대7길 34',NULL,33.53102682077065,126.84326807148297,NULL,'https://www.visitjeju.net/kr/','상시 개방','연중무휴',90,0,'2026-04-01 13:32:36'),
('50110','KTO_TOURAPI','3056135','ATTRACTION','호떡골목','1945년에 형성되어 제주에서 제일 크고 오래된 시장인 동문재래시장에는 그 세월만큼이나 오랜 시간 동안 자리를 지키고 있는 호떡 골목이 시장 안에 자리 잡고 있다. 제주 도민이라면 누구나 어린 시절 이곳에서 따뜻한 호떡을 먹은 추억 하나는 가지고 있을 것이다. 호떡 골목은 동문재래시장 1번 게이트 입구에서부터 왼쪽으로 길게 줄지어 가게들이 있어 쉽게 찾을 수 있다. 시장이 처음 생길 때부터 자리를 굳건하게 지키고 있는 가게부터, 빙떡, 쑥 호떡을 곁들여 파는 가게, 푸짐한 잡채가 한가득 들어간 잡채 호떡, 이색적인 다금바리 빵까지 조금씩 다른 콘셉트의 호떡으로 입맛 따라 취향 따라 맛보는 것을 추천한다.','제주특별자치도 제주시 동문로 16 (일도일동)',NULL,33.51279665661436,126.52831973043567,NULL,NULL,'점포 별로 상이함','점포 별로 상이함',90,0,'2026-04-01 13:21:14'),
('50110','KTO_TOURAPI','3056663','ATTRACTION','엉알해안산책로','제주 사투리로 엉은 벼랑과 절벽을 뜻하고, 알은 아래쪽이라는 의미를 가지고 있다. 엉알해안산책로는 절벽 아래에 자리 잡은 해안 산책로를 뜻한다. 제주시 숨은 비경 31곳에 선정된 엉알해안은 화산재가 쌓여 이루어진 지층이 바다와 어우러져 아름다운 절경을 자랑하며, 해안을 따라 한적한 엉알해안 산책로가 예쁘게 조성되어 있다. 엉알해안 산책로는 수월봉에서 자구내 포구까지 이어지는 해안 산책로로 올레길 12코스와 연결된다. 산책로의 시작점에 있는 수월봉은 화산재가 겹겹이 쌓여 생긴 오름이다. 산책로 코스에는 수월봉이 포함되지 않지만 수월봉 정상에 올라서면 엉알해변이 한눈에 들어오고 차귀도와 산방산, 한라산까지 조망할 수 있다. 엉알해안산책로를 걷는 동안 해안 절벽 곳곳에 있는 다양한 화산암괴와 지층이 휘어진 탄낭구조를 볼 수 있으며 엉알해안과 고산리 선사유적을 지나면 자구내 포구에 도착하는데 자구내 포구는 낙조가 아름답기로 유명하다.','제주특별자치도 제주시 한경면 노을해안로 1143',NULL,33.30805442882491,126.16412263702532,NULL,'https://www.visitjeju.net/kr/','상시 개방','연중무휴',90,0,'2026-04-01 13:08:41'),
('50110','KTO_TOURAPI','3057412','ATTRACTION','보메와산감귤체험농장','보메와산 감귤체험농장은 조천읍 와산리에 있는 감귤 따기 체험농장이다. 감귤 따기는 8월부터 1월까지 체험할 수 있으며, 예약 없이 방문해도 체험할 수 있다. 감귤 따기 체험은 어린이와 어른 할 것 없이 즐거운 추억을 남길 수 있는 체험이다. 농장에서 직접 딴 감귤을 바로 먹어볼 수도 있고, 일정량을 가져갈 수도 있으며, 농장에서 재배한 신선한 감귤을 구입할 수도 있다. 보메와산 감귤 체험농장은 농장 곳곳에 포토존을 꾸며 놓았으며, 어린이들이 놀기 좋도록 놀이터도 운영한다. 건물 1층에는 체험 카페를 운영하고, 2층과 3층은 펜션으로 운영하고 있다. 체험 카페에서는 풋귤 청 담그기, 제주 백향과 청 만들기 등 체험을 진행하고 있으며 펜션 숙박객은 무료로 체험을 진행할 수 있다.','제주특별자치도 제주시 조천읍 미래로 53',NULL,33.48449858436093,126.68018591188707,NULL,'https://www.instagram.com/bomews','10:00~17:00※ 8월부터 체험 가능으로 자세한 사항은 전화 문의 요망','매주 월요일※ 감귤 체험 시즌 후 8월 체험 시즌 전까지 휴무이므로 자세한 사항은 홈페이지 참조 요망',90,0,'2026-04-01 12:05:36'),
('50110','KTO_TOURAPI','3056592','ATTRACTION','용담레포츠공원','용담 레포츠공원은 제주시민들의 건강한 레저와 스포츠, 여가활동을 위해 조성된 공원이다. 다양한 활동이 가능한 다목적 운동장, 족구장, 배구장, 롤러스케이트장, 농구장 등의 체육시설과 정자, 쉼터 등 편의시설이 잘 갖춰져 있어 운동이나 가벼운 산책하기에 좋은 공원이다. 제주공항과 가까워 항공기 소음이 들린다는 단점이 있지만, 최근에는 비행기 이착륙 장면을 공원에서 근접 촬영할 수 있어서 사진 촬영 명소로 유명해졌다. 해안가에 조성된 공원답게 해안 산책길이 있으며 공원 내에서 야영과 취사는 금지하고 있다.','제주특별자치도 제주시 서해안로 580 (용담삼동)',NULL,33.51823715798163,126.4994427069005,NULL,'https://www.visitjeju.net/kr/','상시 개방','연중무휴',90,0,'2026-04-01 10:55:50'),
('50110','KTO_TOURAPI','3057363','ATTRACTION','탐나는농장','탐나는농장은 애월읍 하가리에 있는 감귤 따기 체험농장이다. 감귤 따기 체험은 계절별, 시기별 상이하게 열리며, 예약 없이 방문하여도 언제든지 체험할 수 있다. 가족, 친구, 연인 누구와도 즐거운 시간을 보낼 수 있다. 농장에서 직접 딴 감귤을 바로 먹어볼 수도 있고, 일정량을 가져갈 수도 있으며, 농장에서 재배한 신선한 감귤을 구입할 수도 있다. 탐나는농장에는 농장 곳곳에 포토존을 꾸며 놓아 사진 촬영하기 좋으며, 농장에서 운영하는 펜션이 농장 바로 옆에 있어 숙박과 체험을 겸할 수 있는 관광지이다.','제주특별자치도 제주시 애월읍 오당빌레길 88',NULL,33.4480342148416,126.3585287584191,NULL,'https://blog.naver.com/tamnaneunfarm','10:00~17:30 (휴게시간 13:00~14:00)','연중무휴',90,0,'2026-04-01 10:54:22'),
('50110','KTO_TOURAPI','3056279','ATTRACTION','누웨마루거리','제주도에서 2010년 제주시 연동7길에 조성한 차 없는 거리이다. 조성 당시 이름은 로데오거리였다고 한다. 누웨마루거리라는 이름은 2017년 12월 명칭 공모를 통해 선정된 이름으로, 누웨는 누에의 제주도 방언이고 마루는 언덕을 가리키는 제주도 방언이다. 본래 누웨마루 거리가 조성된 제주시 연동 일대의 지형이 누에고치가 꿈틀대는 형상을 띠고 있어 지역의 인재를 배출하고 부자가 많이 나온다는 명당자리라 하여 붙여졌다. 누웨마루 거리에는 우리나라 유명 배우들의 핸드프린팅과 인물정보를 나열한 조형물이 있고, 쇼핑점, 음식점, 옷 가게 등이 많으며 지금까지도 중국인 관광객이 많이 찾고 있어 제주 속의 작은 중국이라는 별명도 있다.','제주특별자치도 제주시 신광로 47 (연동)',NULL,33.487754418626565,126.49029390914617,NULL,'https://www.visitjeju.net/kr/','상시 개방','연중무휴',90,0,'2026-04-01 10:50:48'),
('50110','KTO_TOURAPI','3057244','ATTRACTION','조천만세동산','조천읍 조천리에 있는 조천만세동산은 제주의 3대 항일운동 중 하나인 조천만세운동이 일어났던 장소에 세워진 기념공원이다. 조천만세동산에는 조국의 자주독립을 위해 목숨을 바친 분들을 추모하고, 평화를 염원하는 애국선열 추모탑, 만세운동의 뜻을 기억하고 기리기 위해 세워진 3·1 독립운동 기념탑, 항일운동 관련 역사 자료를 전시하는 항일기념관이 있다. 애국선열 추모탑은 제주 고유의 문인 정낭을 닮은 모양을 하고 있고 항일기념관은 독립운동에 대한 다양한 역사적 사실들을 배우고 그 뜻을 기리는 기회를 가질 수 있다. 제주 올레길 18코스의 종점이자, 19코스의 시작점이기도 하여 올레길 여행객들이 많이 방문하는 동산이다.','제주특별자치도 제주시 조천읍 조천리','1142-1',33.540496,126.642205,NULL,'https://www.visitjeju.net/kr/','상시 개방','연중무휴',90,0,'2026-04-01 09:44:30'),
('50110','KTO_TOURAPI','3056448','ATTRACTION','올레바당체험마을','올레바당체험마을은 한림읍 수원리 마을공동체에서 운영하는 마을기업이다. 관광객들에게 제주 바다의 아름다움을 알리고, 청정 제주 바다에서 누릴 수 있는 다양한 체험을 소개하기 위해 주민들의 뜻을 모아 운영되고 있다. 관광특화마을답게 제주 전통의 테우가두리낚시체험을 저렴한 가격으로 즐길 수 있다. 아이부터 어른까지 모두 즐겁게 체험이 가능하다. 테우란 전통적인 뗏목 형태의 낚싯배이며 테우가두리낚시체험은 약 1시간 정도 소요된다. 올레바당체험마을 인근에는 협재해수욕장, 평수포구, 한림항 등의 관광지가 있어 같이 둘러보기 좋다.','제주특별자치도 제주시 한림읍 한림해안로 267-6',NULL,33.42542169301652,126.26406290297412,NULL,'https://www.instagram.com/ollebadang_fishing','11:00~17:00 (휴게시간 12:00~13:30)','연중무휴',90,0,'2026-04-01 09:20:13'),
('50110','KTO_TOURAPI','3097805','ATTRACTION','떠오르길·김녕 바닷길','떠오르길은 에메랄드빛 바다 위 갈라진 초록 카펫의 바닷길에서 멋진 사진을 남길 수 있는 명소이다. 이 길은 제주도 해녀들이 물질을 쉽게 할 수 있도록 인공으로 만든 바닷길이라고 한다. 이곳은 간조 시간 때마다 생겨나는 곳으로 김녕 물때를 검색해서 간조 시간을 꼭 확인하고 가야 한다. 따로 주소가 등록되어 있지 않기 때문에 봉지동복지회관(제주시 구좌읍 김녕로 1길 51-3)으로 검색하여 찾아가면 된다. 바닷물이 완전히 빠져 있을 때 보다 살짝 찰랑거릴 때 바다로 걸어 들어가는 체험을 할 수 있다.

(출처 : 비짓제주)','제주특별자치도 제주시 구좌읍 김녕로1길 51-3',NULL,33.55789195458667,126.74888021379536,NULL,'https://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-03-31 23:01:33'),
('50110','KTO_TOURAPI','3057021','ATTRACTION','개똥이네농장','제주 조천읍에 있는 개똥이네 농장은 귤을 마음껏 따서 먹고 바구니 한가득 귤을 담아가는 체험농장이다. 8월부터 2월까지 감귤 체험을 운영하며, 계절별 꽃 농장을 운영하는데 핑크뮬리(9월 말~11월), 가을꽃(9월~11월), 동백정원(12월~1월), 수국정원(5월 말~7월 초)이 열린다. 또 알파카, 말, 염소에게 먹이를 주는 동물체험도 있다. 다양한 체험활동이 가능하다. 부대 시설로 카페를 운영하고 있어 체험이 끝난 후 차 한 잔 마시며 힐링하는 여유를 가질 수 있는 곳이다. 주변 관광지로는 함덕해수욕장, 삼양해수욕장, 너븐숭이 4·3기념관 등이 있다.','제주특별자치도 제주시 조천읍 종인내길 133',NULL,33.49488846768377,126.62278314549967,NULL,NULL,'09:00~18:00※ 전화 문의 후 방문 요망','연중무휴',90,0,'2026-03-31 13:48:01'),
('50110','KTO_TOURAPI','3080144','ATTRACTION','김경숙해바라기농장','제주시생활체육공원 인근에 있는 김경숙 해바라기 농장은 제주 최대 규모의 해바라기 재배 농장으로 약 1만 평에 75만 송이의 해바라기가 자라고 있다. 매년 해바라기가 피는 6월 중순부터 11월 말까지 관광객들이 많이 찾는 제주도 명소 중 하나이며 SNS에 여름철 사진 촬영 명소로 알려져 있다. 꽃이 만개하는 여름철에 방문하면 가장 좋은 풍경을 느껴볼 수 있으며 가을까지 관람할 수 있다.
제주시 시내와 가깝고 함덕해수욕장, 신흥해수욕장, 삼양해수욕장 등과 가까운 곳에 있어 해바라기 농장과 함께 둘러보면 좋은 추억을 남길 수 있다.','제주특별자치도 제주시 번영로 854-1 (회천동)',NULL,33.47770045117845,126.62792591776503,NULL,'https://www.visitjeju.net/kr/','09:00~19:00','연중무휴',90,0,'2026-03-31 13:46:24'),
('50110','KTO_TOURAPI','3057180','ATTRACTION','차귀도유람선','한경면 고산리에 있는 차귀도 유람선은 차귀도 둘레길 탐방과 경치 유람을 동시에 즐길 수 있는 관광 유람선이다. 둘레길을 비롯해 섬을 탐방한 후 유람선에 승선하여, 범바위, 장군바위, 쌍둥이바위, 병풍바위, 고래등바위, 매바위, 송이동산, 장군석바위, 해식동굴 등 아름다운 차귀도 주변의 절경을 둘러볼 수 있다. 정기노선이 아니기 때문에 유람선 관광을 하려면 사전 전화예약이 필수이다.
차귀도는 고산리 해안 자구내포구에서 약 2㎞ 떨어진 곳에 있는 무인도로 세계 유네스코 지질공원으로 등재된 섬이다. 수려한 자연경관과 깎아지른 듯한 해안 절벽, 기암괴석이 절경을 이루며 차귀도를 중심으로 죽도, 지실이섬, 와도 등 작은 부속 섬들이 있다.','제주특별자치도 제주시 한경면 노을해안로 1160',NULL,33.30892422479478,126.16489810263236,NULL,'http://www.chagwidocruise.co.kr/','09:00~18:00※ 기상 악화나 업체 사정에 의해 변동될 수 있으므로 홈페이지 참조 및 전화 문의 요망','연중무휴',90,0,'2026-03-31 13:36:57'),
('50110','KTO_TOURAPI','3056829','ATTRACTION','제주바다체험장','제주바다체험장은 2008년 10월 제주시 구좌읍 동복리에서 개장하였고 제주시 구좌읍 김녕리로 신축 이전하여 아쿠아리움 카페와 제주바다체험장을 오픈했다. 아이들에게 바다에 대한 추억을 심어줄 수 있는 체험장으로 실내에 있어 날씨와 상관없이 언제든 짜릿한 손맛을 느끼며 다양한 해산물을 직접 잡고 만질 수 있다. 바다지하수를 사용하여 평균 수온이 일정하며 여름에는 시원하고 겨울에는 따뜻하다. 낚시 방수복을 제공해 장비 없이 방문해도 체험이 가능하다. 체험장은 문어 잡기, 소라와 조개 잡기, 바구니로 고기 잡기, 상어 먹이 주기 등의 프로그램을 운영하며 실내 아쿠아리움에서는 씨워킹 스쿠버 잠수함 체험이 가능하다. 제주도 바닷가에서 살고 있는 바다 생명체들이 어떻게 생겼는지 직접 만져보고 눈으로 확인할 수 있는 특별한 체험의 현장이다.','제주특별자치도 제주시 구좌읍 일주동로 1921',NULL,33.55543573406823,126.73709456410437,NULL,'http://land201kr.alltheway.kr/','10:00~17:00 (입장 마감 16:00)','연중무휴',90,0,'2026-03-31 13:29:20'),
('50110','KTO_TOURAPI','3056151','ATTRACTION','제동목장 입구','제동목장은 한진그룹에서 운영하는 제주도 목장으로 한국마사회에서 운영하는 렛츠런팜 목장 인근에 자리 잡고 있다. 제동목장은 사유지이기 때문에 목장 출입은 불가능 하나, 최근 제동목장 진입도로가 제주도 결혼사진 촬영 명소로 널리 알려지면서 관광객들이 많이 찾는 인생사진 명당이 됐다. 제동목장 입구에는 거대한 삼나무가 도로 양쪽으로 빽빽하게 있어 드라이브 코스로 제격이고, 이국적인 풍경을 연출한다. 특히, 비 오는 날에도 이곳만의 특별한 분위기에서 기억에 남는 사진을 찍을 수 있다. 제동목장 입구는 주차 공간이 없기 때문에 삼다수숲길 공영주차장에 주차하고 걸어서 이동하는 것을 권장한다.','제주특별자치도 제주시 조천읍 교래7길 218',NULL,33.41950376280661,126.6969128618206,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-03-31 13:25:47'),
('50110','KTO_TOURAPI','3056519','ATTRACTION','귤의정원 바령','귤의정원 바령은 환경을 살리는 친환경 유기농법으로 감귤을 키우는 체험농장이다. 약 50년 동안 2대째 감귤을 재배하고 있는 농장이며 화학비료와 농약을 전혀 쓰지 않고 제주의 청정 바닷물과 미생물을 활용하여 싱그러운 자연의 맛을 담으려 정성껏 키우고 있다. 사시사철 아름다운 농장으로 방문객들이 한가롭고 편안하게 쉬었다 갈 수 있으며 체험농장도 운영하고 있다. 귤밭피크닉, 풋귤 따기 체험, 귤 따기 체험, 농장 둘러보기 등 다양한 체험이 있다. 주변에는 돌하르방 미술관, 함덕해수욕장, 제주올레길, 대명목장 등 관광지가 있다.','제주특별자치도 제주시 조천읍 선흘남3길 87',NULL,33.505387985002336,126.70604748291626,NULL,'https://blog.naver.com/aneesuk','10:00~17:00 (입장 마감 16:00)','매주 화요일~목요일',90,0,'2026-03-31 13:17:15'),
('50110','KTO_TOURAPI','3082301','ATTRACTION','감사공묘역','조천읍 함덕리에 있는 감사공묘역은 조선 초기 한림학사와 전라감사를 역임한 영암 강영 선생의 묘역이다. 강영은 태조 7년(1398) 이방원이 일으킨 왕자의 난 때 왕위 계승 문제로 신덕왕후 소생 이방번과 이방석이 화를 입자, 1402년 제주도로 피신한 후 조천읍 함덕리에 정착하여 한림학사의 해박한 지식으로 지역주민 교육과 후진 양성에 기여하다 생을 마쳤다. 묘역 안에는 조천서원, 개명당 등의 건물이 있으며 봄철 겹벚꽃이 아름다워 이를 보기 위해 관광객이 많이 찾는 곳이며, 스냅사진 촬영 장소로도 인기가 있다. 단, 제주도종친회 사유지로 벚꽃기간에만 개방한다.','제주특별자치도 제주시 조천읍 함대로 362',NULL,33.51296425339782,126.66113556108903,NULL,NULL,'※ 제주도종친회 사유지로 벚꽃 기간에만 개방','연중무휴',90,0,'2026-03-31 09:48:12'),
('50110','KTO_TOURAPI','2738712','ATTRACTION','큰노꼬메오름','제주시 서쪽 애월읍에 있는 큰노꼬메오름은 큰녹고메라고도 불린다. 자연경관이 뛰어나고 주변 궷물 오름으로 이어지는 산책로를 포함하고 있어 제주 서부지역 오름 중 관광객과 도민이 많이 찾는 곳 중 하나이다. 오름 정상은 가운데가 우묵져 남북으로 두 봉우리가 마주 보면서 북서쪽으로 말굽형 화구를 이루고 있다. 가파른 사면과 상당한 높이가 특징이다. 제주시에서는 탐방로 및 안내표지판 등의 정비 작업을 마쳤다. 데크로 잘 정돈된 정상 전망대에는 오랜 시간 머물며 노을을 관람하는 탐방객이 많다.','제주특별자치도 제주시 애월읍 유수암리','산138',33.38944,126.410403,NULL,'https://www.visitjeju.net','※ 일부 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2026-03-23 09:52:49'),
('50110','KTO_TOURAPI','3439423','ATTRACTION','아르떼 키즈파크 제주','2024년 4월 5일 오픈한 환상적인 자연 속에서의 즐거운 놀이 세상, 아르떼 키즈파크 제주(Arte kids park jeju)는 전 세계 육백만 명 이상이 관람한 아르떼뮤지엄(ARTEMUSEM)이 선보이는 체험형 미디어아트 놀이터이다. 아이들이 마음껏 뛰어놀 수 있는 16가지 놀이로 구성된 광장, 3종류의 미디어 체험놀이공간, 미디어아트를 관람할 수 있는 어른들을 위한 전시공간으로 구성되어 있다. 키즈파크 내부에는 아이들이 직접 체험할 수 있는 비누 만들기, 나만의 키링/지비츠 만들기 총 2개의 유료체험 프로그램이 마련되어 있다.','제주특별자치도 제주시 애월읍 월각로 929',NULL,33.3539454457208,126.358596923303,NULL,'https://www.artekidspark.com','10:00~19:00','연중무휴',90,0,'2026-03-23 09:52:49'),
('50110','KTO_TOURAPI','577461','ATTRACTION','다랑쉬오름(월랑봉)','다랑쉬오름은 지도상 거의 원형으로 된 밑지름과 큰 몸집에 사자체의 높이가 둥긋한 사면은 돌아가며 어느 쪽으로나 급경사를 이루고 있다. 산정부에는 크고 깊은 깔때기 모양의 원형 분화구가 움푹 패어있는데, 이 화구는 남북으로 긴 타원을 이루며 북쪽은 비교적 평탄하고 화구의 깊이는 한라산 백록담의 깊이와 똑같다고 한다. 대부분의 오름이 비대칭적인 경사를 가진데 비해 동심원적 등고선으로 가지런히 빨려진 원추체란 것이 흔하지 않은 형태이다. 빼어난 균제미에 있어서는 구좌읍 일대에서 단연 여왕의 자리를 차지한다. 화구 바닥은 잡풀이 무성하고 산정부 주변에는 듬성듬성 나무가 자라고 있으며 각 사면 기슭에는 삼나무가 조림되어 있고, 풀밭에는 시호 꽃, 송장 꽃, 섬잔대, 가재 쑥부쟁이 등이 식생 한다. 산봉우리의 분화구가 마치 달처럼 둥글게 보인다 하여 다랑쉬 또는 달랑쉬라고 부른다고 한다.','제주특별자치도 제주시 구좌읍 세화리 산6',NULL,33.4759678473848,126.822816539054,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-03-18 10:10:05'),
('50110','KTO_TOURAPI','3022258','ATTRACTION','제원하늘농원','제원하늘농원은 26,046㎡(8,500평) 규모의 노지와 하우스 시설을 갖추고 농림축산식품부의 무농약, GAP, 저탄소 인증을 받은 감귤농원이다. 4월 말에서 5월 초 감귤꽃을 시작으로 8월~9월 풋귤, 10월 노지귤, 12월~2월 황금향, 레드향, 천혜향 등을 만나볼 수 있다. 계절에 따라 감귤마말레이드, 감귤케이크, 풋귤청, 하귤청 등을 직접 만들어보는 푸드테라피 프로그램을 다양하게 진행하고 있으며, 감귤밭에서의 싱잉볼 명상과 소원을 담은 후우링 만들기 등의 소리치유를 통해 심신이 지친 이들을 위한 쉼과 휴식의 공간으로 열어가고 있다.','제주특별자치도 제주시 조천읍 대흘북길 72-5',NULL,33.502978324166364,126.6664495134059,NULL,'https://www.instagram.com/jewonhaneul/','09:00~18:00','연중무휴',90,0,'2026-03-11 10:03:40'),
('50110','KTO_TOURAPI','3559794','ATTRACTION','모진이몽돌해변','모래 없이 동글동글한 돌들로만 이루어진 해수욕장으로 밀려오는 파도 소리에 움직이는 몽돌 소리가 아름다운 곳이다. 한적한 몽돌해변의 편안함으로 관광객들이 많이 찾는 해변 중 하나이다. 또한 물이 맑고 깨끗하며 조약돌들이 햇빛에 반사되어 반짝이는 모습도 장관이다. 도심에서 바쁘게 삶을 영위하다 힐링하러 오는 사람들이 많다. 

(출처 : 비짓제주 홈페이지)','제주특별자치도 제주시 추자면 신양4길 18',NULL,33.9457,126.3346,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-03-11 10:03:40'),
('50110','KTO_TOURAPI','3557958','ATTRACTION','상추자항','추자도는 사람이 살고 있는 네 개의 섬과 겹겹이 겹쳐져 있는 서른여덟 개의 섬을 모두 포함해 추자도라고 부르며, 크게 상추자도 하추자도로 나뉜다. 그중 상추자도에 있는 제주올레 18-1코스의 시작점인 상추자항은 오목한 만으로 되어있고 올레길을 따라 걷다 보면 고려시대 명장이었던 최영장군의 사당과 추자도를 대표하는 풍경 명소인 나바론 절벽을 볼 수 있다. 또한 상추자항은 여객선 터미널이 있어 제주 본섬과 추자도를 잇는 해상 교통의 중심지 역할을 하며 등대전망대와 추자교 등 볼거리가 있다.','제주특별자치도 제주시 추자면 추자로 37',NULL,33.96267344496003,126.29562905541727,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-03-09 17:33:08'),
('50110','KTO_TOURAPI','129074','ATTRACTION','우도마을','우도는 소가 누워있는 모양을 닮았다고 해서 일찍부터 소섬 또는 쉐섬으로 불리웠다. 완만한 경사와 옥토, 풍부한 어장, 우도팔경 등 천혜의 자연조건을 갖춘 관광지로써 한해 약 200만 명의 관광객이 찾는 제주의 대표적인 부속섬이다. 물소가 머리를 내민 모양이라 우도라 부르는데, 우도8경 등 수려한 자연경관과 청정해역으로 많은 관광객들이 찾고 있는 곳이다. 또한 최근에 영화 \'시월애\'와 \'인어공주\' 등의 촬영지로 알려지면서 세인들의 관심이 더욱 높아지고 있다.','제주특별자치도 제주시 우도면 우도비양길 119',NULL,33.51192218763324,126.96480936059389,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-03-05 10:08:54'),
('50110','KTO_TOURAPI','598635','ATTRACTION','검멀레해변','검멀레 해수욕장은 제주도 동쪽 끝 성산포에서 북동쪽 해상에 위치한 화산섬 우도에 있는 유명한 해수욕장이다. 우도봉 아래에 협곡 속에 숨어있다. 폭 1백 여 미터의 작은 해변이지만 모래찜질을 겸한 해수욕을 할 수 있는 장소이다. 도로에서 해변은 계단으로 연결되어 있다. 검멀레의 검은 검다, 멀레는 모래라는 뜻으로, 검은 모래 해변을 뜻한다. 해변 끝에는 고래가 살았다는 전설이 전해지는 동굴이 있다. 동굴 내부는 관광객들이 쌓아 올린 작은 돌탑 등이 있으며, 안에서 작은 음악회가 열렸을 정도로 꽤 큰 규모다. 검은코꾸망을 지나면 또 하나의 동굴이 동안경굴이라고도 하는데 우도 팔경 중 하 나이다. 바다 쪽에서 우도의 비경을 보고 싶다면, 보트를 타고 검멀레 주변 한 바퀴를 돌아보는 것도 좋다.','제주 제주시 우도면 연평리',NULL,33.497279,126.967248,NULL,'http://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2026-03-05 09:58:51'),
('50110','KTO_TOURAPI','2767884','ATTRACTION','우도천진항','제주의 동쪽 끝, 해가 가장 먼저 떠오르는 섬이자 제주의 부속 섬 중 가장 큰 우도는 볼거리와 즐길 거리가 가득해 관광객들로 북적이는 여행지다. 걷기에는 섬 크기가 커서 자동차를 가지고 입도하거나 입도 후 전동 스쿠터나 소형 전기차, 버스로 여행하는 것이 좋다. 우도에는 2개의 선착장이 있는데, 천진항과 하우목동항이 바로 그곳이다. 천진항은 우도의 관문 항구이자 전동 스쿠터 등 대여 업체가 많아 보통 이곳에서 내리는 관광객이 많다. 성산항과 종달항에서 천진항까지는 10~15분 정도가 소요된다.','제주특별자치도 제주시 우도면 연평리 1737-15',NULL,33.4919930639295,126.950434879884,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-03-05 09:58:51'),
('50110','KTO_TOURAPI','3498094','ATTRACTION','세화리 농어촌체험휴양마을','제주특별자치도 제주시 구좌읍에 위치한 세화리 농어촌체험휴양마을은 2023년 세계관광기구 UNWTO에서 세계 관광 최우수 마을로 지정한 마을로, 세계인류무형문화유산인 해녀와 국가중요농업유산 밭담이 있는 마을이다. 세화마을 주민 494명이 조합원으로 가입한 대한민국 최대 규모의 세화마을협동조합 주최 하에 \'세계인류무형유산 해녀투어\', \'오름의 여왕 다랑쉬오름 웰니스 투어\', \'양PD와 함께하는 세화마을 투어\', \'해녀 바당식탁\', \'세화마을 3박 4일 살기 프로그램\' 등 다양한 프로그램이 진행되고 있는 곳이기도 하다. 특히, 세화마을은 질그랭이 거점 센터가 있어 워케이션의 성지로도 유명하며, 방문자를 위한 마을 호텔도 운영 중이다.','제주특별자치도 제주시 구좌읍 세평항로 46-9',NULL,33.526991970150945,126.85603220698485,NULL,'http://sehwamaeulcoop.com','09:00~17:00※ 프로그램별로 상이하므로 자세한 사항은 홈페이지 참조','매월 1일',90,0,'2026-03-04 10:04:26'),
('50110','KTO_TOURAPI','1874612','ATTRACTION','지속가능환경교육센터','지속가능환경교육센터는 자원 절약과 폐기물 자원화의 소중함을 알리고 자원 재활용을 시민 생활문화로 정착시키기 위해 설립됐다. 교육 프로그램의 개발 및 교육교재의 보급, 환경전문가를 양성하는 데 힘쓰고 있으며, 제주도민 및 국내외 제주 방문객에게 환경교육을 시행하고 있다. 교육프로그램으로는 3R센터 견학을 통해 쓰레기 분리배출놀이, 업사이클 만들기 등의 체험을 할 수 있다. 또한 교육과정도 유아, 청소년, 성인으로 나뉘어서 진행하고 있다. 유아과정은 생태탐방, 숲탐색하기, 숲속게임활동 등 자연과 친해질 수 있는 내용으로 구성되어 있고, 청소년과정은 일상생활에서 실천하는 친환경 행동 배우기, 푸드 마일리지에 대한 교육 등이 있으며, 성인과정으로는 미세플라스틱의 위험성에 대한 교육과 천연 멀티밤이나 폼클렌저 만들기 등 체험 프로그램이 있다.','제주특별자치도 제주시 송이길 226 (회천동)',NULL,33.462080972123374,126.62930257715661,NULL,'http://www.jejueco.or.kr','09:00~18:00 (준비시간 12:00~13:00)','매주 토요일, 일요일 / 법정공휴일',90,0,'2026-02-09 13:55:08'),
('50110','KTO_TOURAPI','930345','ATTRACTION','한수풀 해녀학교','한수풀 해녀학교는 해녀들의 고령화와 어족자원의 고갈, 작업여건의 어려움으로 점차 사라져가는 해녀문화를 젊은 세대에 전수하자는 취지에서 주민자치 특성화 사업으로 시작되었다. 그동안 미국, 캐나다, 일본등 외국 국적의 외국인을 비롯한 전국 각지에서 참여하고 있으며, 직업군 또한 공무원, 의사, 변호사, 대학교수, 작가, 기자, 약사, 통역사, 학생, 주부 등으로 다양한 분야에서 왕성하게 활동하고 있는 분들이 해녀양성 교육에 참여하여 졸업하였다.','제주특별자치도 제주시 한림읍 한림해안로 623-6',NULL,33.4430935099646,126.279165058509,NULL,'http://jejuhaenyeoschool.com','※ 자세한 사항은 전화문의 요망','※ 자세한 사항은 전화문의 요망',90,0,'2026-02-09 11:26:09'),
('50110','KTO_TOURAPI','1621059','ATTRACTION','구시물','구시는 나무와 돌로 수로[水路]를 파 만든 것을 말한다. 구시물은 성[城]동산 북쪽 기슭 샘물로 삼별초의 식수원이었다. 이 물을 보호하기 위하여 성[城]밖인데도, 외성[外城]을 쌓아 나무로 구시를 만들어, 깨끗이 관리하였고, 아무리 가뭄이 닥쳐도 마르지 않는 질 좋은 생수라서 콜레라가 유행할때도 고성은 한 사람도 희생자가 없었다고 한다.','제주특별자치도 제주시 애월읍 상귀리','884',33.456530549,126.4097117919,NULL,'https://jeju.grandculture.net/jeju/dir/GC00710184','상시 개방','연중무휴',90,0,'2025-12-24 11:21:33'),
('50110','KTO_TOURAPI','2792599','ATTRACTION','한림항','한림항은 한림에서 출발하여 비양도를 잇는 여객선이 있는 항구다. 비양도는 우리나라에서 유일하게 탄생에 대한 역사적 문헌이 남아있는 섬으로, ‘천년의 섬’이라고 불리며, 제주 본섬과는 불과 3㎞밖에 떨어지지 않은 섬이다. 비양도 항에서 배로 5분 정도만 가면 섬에 다다르는데, 오후 9시부터 오후 4시까지 하루에 4번만 운행하니 시간표를 반드시 확인하는 것이 좋다. 천혜의 자연경관을 고스란히 지닌 비양도를 산책할 수 있는 산책로가 잘 마련되어 있어 섬을 한 바퀴 여유롭게 돌아보는 것도 좋다.

◎ 한류의 매력을 만나는 여행 정보
한림항은 한류 드라마의 촬영지로도 주목받는 곳이다. ‘우리들의 블루스’ 1화에서는 경매 장면의 배경으로, ‘폭싹 속았수다’ 14화에서는 원양어선을 탄 은명을 애순과 관식이 데리러 오는 항구로 등장한다. 드라마 속에서도 관광지로도 자연경관과 함게 제주의 일상을 느껴볼 수 있는 특별한 장소이다.','제주특별자치도 제주시 한림읍 한림해안로 192',NULL,33.4190907055,126.2625726517,NULL,'https://www.visitjeju.net/kr/detail/view?contentsid=CNTS_000000000018421','상시 개방','연중무휴',90,0,'2025-12-16 16:52:22'),
('50110','KTO_TOURAPI','2767790','ATTRACTION','답다니탑망대','우도 해안도로를 따라 돌다 보면 유난히 돌탑을 많이 만난다. 거의 바위 크기로 쌓아 올린 탑으로 무척 이색적이다. 이런 돌탑들이 모인 것이 답다니탑망대인데 4·3 사건 당시에 제주도 본섬과 바다의 상황들을 알아보고자 쌓아 올린 초소의 역할을 했다고 한다. 바위 크기로 쌓아 올려 이색적인 경관을 자아내는 답다니탑망대는 돌탑으로 쌓아 올린 봉수대와 그 옆 하얀 등대가 자리하고 있다. 등대 바로 옆으로 하트 모양 원담이 있어 사진 촬영 장소로 유명하다.
(출처 : 제주 문화관광 홈페이지)','제주특별자치도 제주시 우도면 연평리',NULL,33.5249205816,126.9526464263,NULL,'https://www.visitjeju.net/kr/detail/view?contentsid=CNTS_000000000018497','상시 개방','연중무휴',90,0,'2025-11-26 10:44:06'),
('50110','KTO_TOURAPI','129384','ATTRACTION','제주성지','제주성지는 제주목의 치소를 둘러쌓았던 성터로, 오현단 남쪽에 일부가 복원되었고, 곳곳에 잔해가 남아있다. 제주성의 축성 연대는 정확히 알 수 없으나 탐라국 당시 쌓았던 것을 고려 때 왜구 방어용으로 보수하여 사용했던 것으로 추정되며, 현재는 일부인 남수각 부분이 150여 미터 정도 복원되어 있다. 역사가 깊고 제주도의 중심지역을 지켰던 이곳은 일제강점기인 1925년부터 1928년 사이에 건입동 포구 앞바다를 매립할 때 성곽의 돌을 매립골재로 사용하면서 크게 훼손되었다고 전해진다.
성곽 주위에는 귤과 유자나무가 많이 심어져 있어 가을철 귤이 익을 무렵이면 성 주위는 가을색으로 절정을 이루었다고 한다. 튼튼한 성을 쌓으며 왜침의 ‘바람’을 잠재우려 했던 선조들의 지혜를 느낄 수 있는 곳으로, 이러한 가치를 인정받아 1971년 8월 26일 제주특별차지도 기념물로 지정되었다.','제주특별자치도 제주시 오현길 61','(이도일동)',33.5102931048,126.5255810579,NULL,'https://www.visitjeju.net/kr/detail/view?contentsid=CONT_000000000500558','상시 개방','연중무휴',90,0,'2025-10-24 23:55:00'),
('50110','KTO_TOURAPI','2778905','ATTRACTION','해맞이해안로','제주 동쪽 해가 뜨는 방향의 해안도로라는 의미의 해맞이해안로는 제주시 구좌읍 김녕리에서 서귀포시 성산읍 오조리까지 해안을 따라 조성된 약 27.8㎞의 도로이다. 올레길 21코스에 포함되는 해맞이해안로를 가다 보면 해맞이 명소로 유명한 성산 일출봉이 있어 제주를 방문하는 여행객들이 꼭 지나가는 길이다. 김녕- 월정리 -세화 -하도 -종달리 -성산 일출봉까지 연결되어 있어 제주의 맛집, 카페, 명소 등을 중간중간 방문할 수 있어 접근성도 좋다. 제주에 오면 꼭 들러야 하는 해맞이해안로의 가장 큰 매력은 끝없이 펼쳐지는 제주 바다를 감상할 수 있다는 점이다.','제주특별자치도 제주시 구좌읍 김녕리',NULL,33.5504226979,126.7427251632,NULL,'https://www.visitjeju.net/kr/detail/view?contentsid=CNTS_000000000018371','상시 개방','연중무휴',90,0,'2025-10-24 13:07:25'),
('50110','KTO_TOURAPI','128796','ATTRACTION','별방진','별방성은 1973년 4월 13일에 제주도 기념물로 지정되어 보호되고 있다. 별방성에 대해 \'신증동국여지승람\' 제주목 관방조에는 ‘별방성은 돌로 쌓았는데 둘레가 2,390자이고 높이는 7자이다. 중종 5년(1510)에 장림 목사가 이 땅이 우도(牛島)로 왜선이 가까이 댈 수 있는 곳이라 하여 성을 쌓고 김녕방호소를 이곳으로 옮기어 별방(別防)이라 이름하였다.’라고 하였고, 김상헌의 \'남사록\'에는 ‘별방성은 동·서·남에 세문이 있고 성 안에는 우물이 있으나 맛이 짜다. 지명은 옛날에 하도의탄리라 하였다.’라고 하였으며 ‘탐라지\'에는 ‘북성에 대변청이 있고 중앙에는 객사(客舍), 별창(別倉), 군기고(軍器庫)가 있다.’라고 하였다. 박천형의 서계(書啓) 내용에는 ‘동쪽과 북쪽이 바다에 임하였고 성 안은 화북이나 조천에 비해 조금 넓으며 동·서·남에 세문과 성안에 두 우물이 있으나 포구의 공간이 몹시 좁고 뾰족 나온 돌모서리가 창 같이 날카로워 배를 정박할 수가 없다. 횃불을 비치해 경보하는 것이 좋을 듯하며 성을 설치하여 방어하는 데에는 적합한 곳이 아닌 듯하다.’라고 하였다. 헌종 14년(1848)에 장인식 목사가 이를 중수하였다.

◎ 한류의 매력을 만나는 여행 정보 - 
조선시대의 성곽에 ‘부’씨로 구성된 밴드와 함께 부승관이 올랐다. 제주를 개국했다는 고 씨, 양 씨, 부 씨 세 성씨 중 하나인 부 씨이다. 별방진이 위치한 제주도 구좌읍 하도리는 부 씨의 집성촌이다. 승관의 고향 제주에서도 의미 있는 지역이다. 별방진은 유채꽃 명소로, 이른 봄 노란 유채꽃과 어우러지는 검은 돌의 성곽이 매력적이다.','제주특별자치도 제주시 구좌읍 하도리 3354','(구좌읍)',33.5262082208,126.8843912035,NULL,'https://www.visitjeju.net/kr/detail/view?contentsid=CONT_000000000500244','상시 개방','연중무휴',90,0,'2025-10-23 14:30:00'),
('50110','KTO_TOURAPI','129699','ATTRACTION','금오름','서부 중산간 지역의 대표적인 오름 중의 하나이다. 산정부에 대형의 원형 분화구와 산정화구호(山頂火口湖)를 갖는 신기(新期)의 기생화산체이며, 남북으로 2개의 봉우리가 동서의 낮은 안부로 이어지며 원형의 분화구 (깊이 52m)를 이루고 있다. 분화구내의 산정화구호 (일명 今岳潭)는 예전에는 풍부한 수량을 갖고 있었으나 현재는 화구 바닥이 드러나 있다. ‘검, 감, 곰, 금’ 등은 어원상 신(神)이란 뜻인 ‘곰(고어)’과 상통하며, 동일한 뜻을 지닌 ‘곰’係語(계어)로서 고조선시대부터 쓰여 온 말이라고 한다. 즉 ‘금오름’은 神이란 뜻의 어원을 가진 호칭으로 해석되며, 옛날부터 신성시 되어 온 오름임을 알 수 있다. 해송, 삼나무, 찔레, 보리수, 윤노리나무 등 원형 분화구와 산정화구호이다. 
* 표고 427.5m, 비고 178m, 둘레 2,861m, 면적 613,966㎡, 저경 1,008m','제주특별자치도 제주시 한림읍 금악리','산1-1',33.3555289743,126.3059091921,NULL,'https://www.visitjeju.net/kr/detail/view?contentsid=CNTS_000000000019460','상시 개방','연중무휴',90,0,'2025-10-23 14:30:00'),
('50110','KTO_TOURAPI','2740133','ATTRACTION','아끈다랑쉬 오름','제주 동쪽에서 오름의 여왕이라 불리는 ‘다랑쉬오름’ 바로 맞은편에 자리하고 있다. 다랑쉬오름처럼 낮고 자그마한 원형 분화구를 이루고 있으며, 다랑쉬오름과 비슷한 모양을 띠고 있어 아끈다랑쉬라고 부른다. ‘아끈’이란 버금가는 것, 둘째 것이라는 뜻의 제주 방언이다. 아끈다랑쉬 오름은 가볍게 산책하듯이 오를 수 있어 어린이를 동반해도 좋다. 서사면으로 난 작은 길을 따라 10분 정도면 쉽게 오를 수 있고 억새의 물결이 이루는 가을에는 아름다운 풍경을 감상할 수 있다. 키 높이의 억새가 가득 차 있고, 특히 일출 무렵에는 바람에 따라 흔들리는 억새의 파도와 낮에는 햇빛을 받아 반짝이는 은빛 억새가 아름다운 경관을 연출한다. 또한 하얀 억새꽃들이 떨어진 겨울 억새밭은 또 다른 느낌으로 다가온다. 특히 바람이 많이 부는 날에 아끈다랑쉬를 찾으면 흔들리는 억새가 만들어낸 겨울 감성을 느낄 수 있다.','제주특별자치도 제주시 구좌읍 세화리 2593',NULL,33.4754212946,126.8302942866,NULL,'https://www.visitjeju.net/kr/detail/view?contentsid=CONT_000000000500406','※ 일부 통제될 수 있으므로 방문 시 전화문의 요망','연중무휴',90,0,'2025-08-28 09:36:00'),
('50110','KTO_TOURAPI','2638441','ATTRACTION','제주탐나라공화국','제주 서쪽 한림읍 금악리에 자리 잡은 탐나라공화국은 대한민국 안에 개국한 또 하나의 나라다.
정확하게는 가상국가형 테마파크이다. 이름부터 낯선 탐나라공화국은 제주의 옛 이름 ‘탐라’를 의미한다. 여권도 있고 이곳에서만 사용하는 화폐도 있다. 탐나라공화국에 도착해 처음 만나는 건 출입국관리소이다. 입구에 들어서 좌측 작은 카페(Lava)에서 입장료를 내고 비자를 발급 받아야 한다. 비자(티켓)의 형태는 일단위와 연간 단위가 있는데, 연 단위 티켓의 경우 여권형을 준다. 제주에는 지형 특성상 호수나 연못이 없는데 탐나라공화국에는 빗물을 받아 만든 인공 연못이 많이 있다. 크고 작은 연못 80여 개에 이 곳을 형성하면서 시간이 흐르며 물고기나 양서류 등 생명체가 탄생 중이다. 탐나라공화국에는 수많은 이야기들이 담겨 있다. 어떤 공간에는 고의로 만든 전설이 있기도 하고, ‘길이 없어 길을 내고, 산이 없어 산을 만들다’, ‘내일도 모레도 만나는 날은 오늘입니다’ 등등 의 글귀를 보며 명상에 잠길 수도 있다.

(출처 : 제주 문화관광 홈페이지)','제주특별자치도 제주시 한림읍 한창로 897',NULL,33.3345121647,126.3256857208,NULL,'http://www.jejutamnara.com','09:00~18:00

※ 사전 예약 방문','연중무휴',90,0,'2025-03-24 17:46:26'),
('50110','KTO_TOURAPI','126467','ATTRACTION','무수천','무수천은 한라산 고지대에서 발원하여 외도 앞바다로 흘러드는 약 25㎞의 긴 하천으로, 경관이 워낙 빼어나 계곡에 들어서면 모든 근심 걱정이 사라진다는 의미를 가지고 있다. 오래된 화산이 분출하면서 용암이 흘러간 자리가 그대로 협곡이 되어버린 무수천은 기묘한 여러 형상들이 눈길을 끈다. 무수천 8경을 선정할 정도로 오랜 세월 비경을 자랑하고 있으며, 계곡을 따라 하류로 내려가면 작은 폭포가 이어진다.','제주특별자치도 제주시 애월읍 무수천길','(애월읍) 일대',33.4627665614,126.4470472947,NULL,'https://www.visitjeju.net/kr/detail/view?contentsid=CONT_000000000500196#','상시 개방','연중무휴',90,0,'2025-03-24 14:26:00'),
('50110','KTO_TOURAPI','1351196','ATTRACTION','저지오름(닥몰오름,새오름)','한경면 저지리(옛 이름:닥몰) 저청 초등학교에서 북서쪽 수동으로 가는 도로 우측에 우뚝 선 오름으로, 산상의 분화구를 중심으로 어느 쪽 사면이나 경사와 거리가 비슷한 둥근 산체를 이루고 있으며, 둘레가 약 900m, 깊이가 약 60m쯤 되는 매우 가파른 깔때기형 산상 분화구를 갖고 있는 화산체이다. 오름 각 사면에는 해송이 주종을 이루며 잡목과 함께 울창한 숲을 이루고 있으며, 분화구 안에는 낙엽수림과 상록수림이 울창한 자연림 상태를 보이고 있으나 안사면으로 보리수나무, 찔레나무, 닥나무 등이 빽빽이 우거져 있어 화구 안으로의 접근이 매우 어렵다.

저지 오름(楮旨岳)이란 호칭은 마을 이름이 ‘저지’로 되면서부터 생긴 한자명이라 한다. 그전까지는 ‘닥몰 오름’이라 불렀으며, 저지의 옛 이름이 ‘닥모루’(닥몰)였다고 한다. 이는 닥나무(楮)가 많았다는 데서 연유한 것이고, 한자이름은 한자의 뜻을 빌려서 표기한 것이라고 한다.

* 2007년 제8회 아름다운 숲 전국대회에서 생명상(대상) 수상','제주특별자치도 제주시 한경면 중산간서로',NULL,33.3338221918,126.2517754921,NULL,'https://www.visitjeju.net/kr/detail/view?contentsid=CNTS_000000000020959',NULL,'연중무휴',90,0,'2025-03-24 13:18:09'),
('50110','KTO_TOURAPI','129148','ATTRACTION','산지 등대','산지등대는 제주 사라봉 북쪽 비탈면에 있는 등대이다. 일제강점기인 1916년 10월 무인 등대로 처음 설치했으며 1917년 3월 유인 등대로 변경되었고 1999년 12월에 새롭게 등탑을 신설했다. 100년 이상의 오랜 역사를 간직한 등대로 제주도를 대표한다. 산지라는 명칭은 조선 숙종 때 제작한 ‘탐라순력도’에 이곳이 산지촌으로 기록된 데서 유래했다. 처음에는 산저였다가 산지로 바뀌었다는 설도 있다. 
산지등대는 주변 경관이 뛰어나고 도심지와 가까운 위치에 있어 학생들의 등대 탐방 체험장소로도 인기가 있다. 일몰 때면 등대 앞쪽 바다에 수십 척의 고기잡이배들이 모여 수놓는 아름다운 야경도 볼 수 있다.','제주특별자치도 제주시 사라봉동길 108-1','(건입동)',33.5209144715,126.5456624039,NULL,'https://www.visitjeju.net/kr/detail/view?contentsid=CONT_000000000500290#','[하절기]
- 09:00~19:30
[동절기]
09:00~18:00','연중무휴',90,0,'2025-03-24 11:05:35'),
('50110','KTO_TOURAPI','127055','ATTRACTION','사라봉(모충사) 의병항쟁기념탑','제주항 위로 보이는 사라봉에 오르면 제주성내를 한눈에 굽어볼 수 있다. 남으로 한라산, 북으로 끝없이 펼쳐진 푸른빛 제주바다, 어느 방향으로나 조망이 아름다운 이 봉우리 아래에 제주 의병 항쟁 기념탑이 서 있다. 1909년 2월 25일 의병장 고사훈 등 10 명의 구국지사들이 발의하여, 1909년 3월 3일을 기해 관덕정 광장에 집결, 일본 관리를 축출하고 국권을 회복하고자 했으나 비밀이 탄로 나 실패로 끝나버린 제주 의병 운동을 기념하기 위해 세워졌다. 모충사 내에 하늘을 찌를 듯 우뚝 솟은 의병항쟁탑 앞에 서면, 일본 침략에 항거한 제주도민의 주체적 항쟁의지가 가슴에 와닿는다. 아래에 2기의 탑이 더 있는데, 하나는 1919년 7월 독립군 군자금 모금사건으로 체포되어 1920년 4월 대구형무소에서 옥사한 조봉호 순국 지사의 기념비이고, 또 하나는 1700년대 말, 제주도 구휼에 앞장섰던 김만덕 할머니의 추모비이다.

김만덕 할머니 (1739 ∼1812)는 가난한 선비의 딸로 태어나 40대에 이르러 큰 부자가 되었다. 1792년경 제주도에 큰 흉년이 들어 약 18,000명이 굶어 죽었는데 김만덕 할머니는 그때까지 번 돈으로 육지에서 식량을 사 와 사람들에게 나눠주었다. 할머니가 자식도 없이 74세로 죽자 나라에서는 벼슬을 내렸다. 추사 김정희는 그녀의 묘비에 찬양하는 글을 남겼으며, 당시 영의정 채제공은 전기를 기록하였다. 사라봉 공원 내에는 그의 묘비와 만덕관이 있다. 매년 한라문화제 때에는 모충사에서 의녀 김만덕 할머니를 기리는 ‘만덕제’가 거행되며 이때 제주도 일원에서 사회봉사에 공헌한 여성을 선정해 만덕봉사상을 수여하고 있다. 세 개의 탑 주위는 향나무, 소나무, 동백나무, 종려나무 등, 다양한 수종으로 아름답게 꾸며져 있어 사라봉과 함께 제주 시민의 소중한 휴식 공간으로 이용되고 있다.','제주특별자치도 제주시 사라봉길 75',NULL,33.5161733522,126.5470457247,NULL,'http://www.visitjeju.net/','상시 개방','연중무휴',90,0,'2025-03-24 10:40:37'),
('50110','KTO_TOURAPI','2738675','ATTRACTION','선운정사','제주의 정겨운 마을과 운치 있는 농촌 길을 걷다 보면 아름다운 모습을 한 선운정사를 마주할 수 있다. 이 사찰은 제주올레 15코스에 포함된 사찰이다. 불교문화의 전승뿐만 아니라 제주의 문화를 함께 보존하기 위해 노력하는 공간으로, 설문대할망과 오백장군 전각, 소원을 이루어주는 소원석 등 다양한 조형물을 볼 수 있다. 무엇보다 유명한 것은 바로 야경이다. 절터를 은은하게 수놓는 연꽃등과 멋진 야경을 무료로 즐길 수 있어 인기다. 해가 떨어지는 7시쯤부터 경내에 불이 하나 둘 들어오기 시작한다. 수백 개의 LED 연꽃등과 탑, 전각 등을 밝히는 조명이 경내를 채우는 차분한 경전 소리와 어우러진다. 또한 사찰 내에 제주특별자치도 문화유산자료로 지정된 ‘선운정사 석조약사여래좌상’이 있다. 선운정사 석조여래좌상은 조선시대 이래 유행한 약기인의 약사불상의 도상을 정확하게 보여주고 있으며, 통일신라시대부터 조선시대까지 시대의 복합상을 갖춘 불상이다.','제주특별자치도 제주시 애월읍 구몰동길 65',NULL,33.4293874894,126.3071574318,NULL,'https://www.visitjeju.net/kr/detail/view?contentsid=CNTS_000000000018362','상시 개방','연중무휴',90,0,'2025-03-24 10:30:01'),
('50110','KTO_TOURAPI','2742357','ATTRACTION','월령 선인장군락지','월령리의 선인장은 관상용으로 많은 종이 재배되고 있는 선인장류 중 유일한 자생종이다. 선인장이 이곳에서 자라게 된 것은 집에서 가꾸던 것에서 퍼졌다고 보는 견해와 해류를 타고 남방에서 밀려와 바닷가의 모래땅이나 바위틈에 기착한 것으로 보는 견해도 있다.
월령리에 있는 선인장은 월령리 자생종 선인장으로, 손바닥과 비슷하다고 하여 ‘손바닥 선인장’이라는 이름이 붙여졌다. 여름이 되면 까만 현무암 사이로 노란 꽃과 자색 열매를 맺으며 장관을 이룬다.
월령리 선인장 군락지는 해안선을 중심으로 나무 데크가 놓여 있어 보행하기에 수월한 편이다. 산책로가 끝날 즈음이면 마을 안으로 들어서는 골목길이 이어진다. 골목길의 검은 현무암 돌담 위로 선인장들이 얼굴을 내밀고 있다.','제주특별자치도 제주시 한림읍 월령리','359-3',33.3780278479,126.2157082002,NULL,'https://www.visitjeju.net/kr/detail/view?contentsid=CONT_000000000500494','상시 개방','연중무휴',90,0,'2025-03-24 10:21:44'),
('50110','KTO_TOURAPI','2602741','ATTRACTION','종달리 해안도로','종달리 해안도로는 광치기해변에서 시작하는 해맞이해안도로의 일부로 하도해변까지 이르는 길로 약 11.2㎞이다. 동쪽에 있는 해안도로라서 해맞이라는 이름이 붙었고, 해가 뜰 때도 물론 장관이지만 해가 질 무렵에도 아름다운 하늘과 바다의 색을 뽐낸다. 종달리해안에는 수국이 가득 심어져 있어 5월 말부터 6월 내내 활짝 핀 수국이 가득한 길을 지날 수 있다. 길이 구불구불하여 우도와 성산일출봉이 번갈아 보이며, 종달리 전망대에 올라 주변 풍경을 한눈에 담아보는 것도 좋다. 마지막 지점인 하도해변은 조용한 분위기에 에메랄드 빛을 띠고 있으며, 건너편의 철새 도래지를 바라보며 여유를 느끼기에 제격이다.','제주특별자치도 제주시 구좌읍 종달리','630-1',33.4829243983,126.901724033,NULL,'https://www.visitjeju.net/u/5j3','상시 개방','연중무휴',90,0,'2025-03-21 17:47:33'),
('50110','KTO_TOURAPI','3005374','CULTURE','아이바가든','아이바가든은 제주 최대 규모의 몰입형 미디어아트 전시관으로, 빛과 영상이 어우러진 9개의 테마 공간에서 오감을 활용한 특별한 체험을 즐길 수 있는 실내 관광지이다. 거대한 미디어아트 영상과 공간 연출을 통해 마치 작품 속에 들어온 듯한 몰입감 있는 경험을 선사하며, 다양한 테마 전시를 통해 신비로운 세계를 만날 수 있다. 제주공항에서 차량으로 약 20분 거리에 위치해 접근성이 좋고, 애월과 평화로 인근 관광지와 함께 둘러보기에도 편리하다. 또한 실내 전시관으로 운영되어 날씨의 영향을 받지 않아 비 오는 날에도 방문하기 좋은 제주 여행지이다.','제주특별자치도 제주시 애월읍 고성남서길 10',NULL,33.4336186579,126.4220642723,NULL,'https://ivarjeju.co.kr/','09:00~19:00 (입장 마감 18:00)','연중무휴',90,0,'2026-11-16 01:30:05'),
('50110','KTO_TOURAPI','2931932','CULTURE','아라리오뮤지엄 탑동시네마','국내 최고의 미술품 커렉터로 꼽히는 김창일 회장이 제주 탑동 인근 원도심에 버려진 건물을 이횽해 만든 현대미술 전시관이다. 오래된 건물을 크게 개조하지 않고 곳곳에 이전의 흔적을 남겨두어 현대 미술품 뿐만 아니라 원도심의 정취를 느낄 수 있다. 제주 여행 중 친구와 가족과 함께 방문해 여러 전시품을 보며 추억을 남기기에도 좋다.','제주특별자치도 제주시 탑동로 14 (삼도이동)',NULL,33.5174206183,126.5233924898,NULL,'http://www.arariomuseum.org','화요일~일요일 10:00~19:00','매주 월요일',90,0,'2026-11-15 01:30:00'),
('50110','KTO_TOURAPI','1939058','CULTURE','갓전시관','갓일은 옛날 양반들이 햇볕이나 비를 가리기 위하여 머리에 썼던 갓을 만드는 수공예 기술 또는 그 기술을 지닌 사람을 가리키며, 1964년 중요무형문화유산으로 지정되었다. 갓일은 갓의 테를 만드는 양태 작업과 말총으로 갓의 머리에 들어가는 부분을 엮는 총모자 작업 그리고 양태와 총모자를 조립하면서 명주를 입히고 옻칠을 하여 완제품으로 만드는 입자 작업 등 3 부분으로 분업화되어 이루어진다.
제주 지역은 조선시대 말기까지 갓 공예의 중심지로서 3단계 작업이 모두 이곳에서 이루어졌다. 이 전시관도 제주시 조천읍 조천리에 거주하는 갓일의 양태 기능보유자 장순자(張順子)가 전통문화를 후세에 전승하기 위하여 기부한 땅에 제주특별자치도가 건립한 것이다. 고구려 시대부터 시대별 흐름을 짚어볼 수 있는 다양한 갓들이 전시되어 있는 전시실, 갓일을 직접 체험해 볼 수 있는 체험실, 갓일 과정을 담은 영상물 등을 상영하는 영상실, 갓일 작업을 하는 공방 등으로 이루어져 있다.','제주특별자치도 제주시 조천읍 남조로 1904',NULL,33.4372087849,126.6708232117,NULL,NULL,'10:00~18:00','매주 일요일~월요일',90,0,'2026-11-13 09:23:08'),
('50110','KTO_TOURAPI','594065','CULTURE','방림원','방림원은 야생화의 천국으로 원장 방한숙 씨가 전 세계를 돌며 30년간 수집한 야생화를 테마별로 전시한 국내 최초 세계 야생화 전시관이자 테마그린파크이다. 세월과 정성으로 가꾸어진 방림원은 실내전시관, 야외정원, 동굴, 형제폭포, 기초공사 중 발견된 방림굴 등 다양한 볼거리가 있으며, 3천여 종의 살아있는 야생화들의 소박한 매력을 느낄 수 있다. 
방림원 곳곳에는 다양한 개구리 조형물이 있는데 방한숙 관장이 이곳을 만들며 힘이 들 때 함께 울어준 친구 개구리를 이곳의 마스코트로 삼았다는 비하인드 스토리가 있다. 숨은 개구리 조형물을 찾으며 산책로를 따라 한 바퀴 걷다 보면 저절로 자연 속에서 힐링하는 기분을 느낄 수 있을 것이다.','제주특별자치도 제주시 한경면 용금로 864',NULL,33.3372862174,126.2685850857,NULL,'http://www.banglimwon.com','[하절기 (3월~10월)]- 09:00~18:00- 입장 마감 17:00[동절기 (11월~2월)]- 09:00~17:00- 입장 마감 16:00','매주 월요일',90,0,'2026-11-11 08:48:03'),
('50110','KTO_TOURAPI','597562','CULTURE','제주현대미술관','제주현대미술관은 제주만의 독특한 문화예술실현의 일환으로 2007년 9월 1일 개관했다. 제주의 아름다운 자연환경이 잘 보전된 중산간 마을 저지리의 저지문화예술인마을 중심부에 입지 하여 관람객에게 문화예술과 자연의 아름다움을 선사한다. 한국 근현대 미술의 거목 김흥수 화백이 자신의 대표 작품을 무상으로 기증한 유일한 미술관이다. 
국제조각심포지엄 야외공원과 함께 1천여 명이 동시 관람할 수 있는 야외공연장과 특별전시실, 상설전시실, 기획전시실, 아트숍, 세미나실 등 문화 예술 복합 기능을 갖췄다. 미술관 주변으로 대한민국 원로 화백들이 다수 거주하며 저지문화예술마을이라는 거대 문화벨트를 조성하고 있다. 예술의 관심이 있다면, 다수의 갤러리와 전시관을 함께 둘러볼 수 있다. 제주현대미술관과 저지문화예술인마을은 공간적 분리감이 거의 없어 관람 후 편하게 둘러볼 수 있으나, 거주 공간인 만큼 관광 매너를 준수해야 한다.','제주특별자치도 제주시 한경면 저지14길 35',NULL,33.3398442069,126.2656603005,NULL,'https://www.jeju.go.kr/jejumuseum/','- 본관 09:00~18:00- 공공수장고 09:15~17:30※ 매표시간은 관람시간 종료 30분전까지','매주 월요일 / 1월 1일 / 설·추석 연휴 ※ 월요일이 공휴일(대체공휴일 포함)인 경우에는 그 다음의 첫 번째 비공휴일',90,0,'2026-11-11 08:48:03'),
('50110','KTO_TOURAPI','696841','CULTURE','테디베어하우스 테지움','테지움 사파리는 세계 최초로 야생동물과 수중동물 꽃과 새들을 모두 봉제인형으로 제작하여 전시되는 새로운 개념의 박물관이다. A동 1층의 야생동물존에는 호랑이, 코끼리, 사자 표범 등의 동물인형과 다양한 포즈의 실물크기의 테디베어와 함께 사진을 찍고 직접 만지고 느낄 수 있도록 전시되어 있고 2층에는 돌고래, 상어를 비롯하여 문어, 거북이 등 수중 동물인형과 홍학, 학, 오리 떼 등 다양한 인형들이 있다. 2층으로 넘어오게 되면 엎드린 모습의 테디베어에서 어린이들이 자유롭게 뛰어놀 수 있는 놀이터와 드라마 뉴하트에 등장했던 모든 테디베어와 테지움아트갤러리에는 영화패러디, 그리스신화 테디베어, 세계의상 테디베어들이 전시되어 있다. 물코너에서는 다양한 형태의 테디베어 소품들과 사랑스러운 여러 가지의 테디베어를 구매할 수 있다.','제주특별자치도 제주시 애월읍 평화로 2159',NULL,33.4120128335,126.3935717784,NULL,'http://www.teseum.net','[춘추절기(3월~6월, 9월~11월)] 09:00~19:00- 입장마감 18:00[하절기(7월~8월)] 08:30~19:00- 입장마감 18:30[동절기(12~2월)] 09:00~18:30- 입장마감 17:40','연중무휴',90,0,'2026-11-11 08:48:03'),
('50110','KTO_TOURAPI','759595','CULTURE','제주특별자치도립미술관','제주도립미술관은 아름답고 청정한 제주의 자연 속에 세워진 숲속의 미술관이다. 미술관에 제주의 전통문화에 바탕을 둔 문화 예술의 역사를 오롯이 담아내었다. 제주 미술사는 물론 세계 미술사, 세계 미술의 흐름까지 함께 조망해 볼 수 있도록 전시를 꾸몄다. 특히, 한국의 대표적인 화가 장리석 화백의 기증 작품을 감상할 수 있는 장리석 기념관을 비롯하여 상설 전시와 기획 전시, 장리석 전시실, 야외 전시실 등을 통하여 예술의 경지에 이르는 창의적이고 다양한 훌륭한 작품 세계를 감상할 수 있다. 또한, 다양한 문화 예술 프로그램을 기획, 진행해 나가고 있다.','제주특별자치도 제주시 1100로 2894-78',NULL,33.4525179848,126.4897396925,NULL,'https://www.jeju.go.kr','[하절기(7월~9월)]09:00~20:00 (입장 마감 19:30)[동절기(10월~6월)]09:00~18:00 (입장 마감 17:30)','매주 월요일 (단, 월요일이 공휴일인 경우 그 다음 첫 번째 비공휴일) / 1월 1일 / 설·추석',90,0,'2026-11-11 08:48:03'),
('50110','KTO_TOURAPI','129894','CULTURE','제주특별자치도 민속자연사박물관','민속자연사박물관은 제주의 대표 박물관으로, 화산섬 제주의 형성과정을 비롯해 자연자원과 제주 사람들의 생애, 민속문화를 종합적으로 관람할 수 있는 곳이다. 1984년 5월 24일 개관한 이래 실물 자료와 모형, 마네킹 등을 활용한 입체적인 전시를 통해 제주 문화를 보다 쉽게 이해할 수 있도록 하고 있다. 로비에 설치된 참고래 골격 표본과 제주의 신비로운 실감 영상은 제주가 지닌 가치를 한눈에 보여준다. 제주도 형성사와 다양한 암석, 한라산 식물의 수직분포도, 곤충, 포유류 등 제주의 형성과정과 자연생태를 살펴볼 수 있으며, 제주인의 일생과 생업, 의식주 등을 통해 과거 제주 사람들의 생활 모습도 접할 수 있다.','제주특별자치도 제주시 삼성로 40',NULL,33.5063901549,126.5313373721,NULL,'http://www.jeju.go.kr/museum','09:00~18:00 (입장 마감 17:30)','매주 월요일 (단, 월요일이 공휴일인 경우 그 다음 첫 번째 비공휴일) / 1월 1일 / 설·추석 / 훈증 소독기간',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','129895','CULTURE','제주 탑동해변공연장','아름다운 제주 해변 풍광과 함께 시원한 바다 내음을 맡으며 다양한 무대 공연을 관람할 수 있는 야외 공연장이다. 공연장의 구조를 갖춘 최초의 야외 공연장으로서 수준 높은 공연이 가능한 곳이다. 지상 3층의 공연장 건물과 노천 객석 2,500여석 규모로 전국 유일의 바닷가에 인접한 공연장으로 국내 최초의 야외 공연장이다. 주변에 조망할 수 있는 바다와 항구가 있고, 공연장 옆에는 광장이 있어서 다양한 여가 활동을 즐기는 제주 시민을 만날 수 있다. 

(출처 : 제주 문화 관광 홈페이지)','제주특별자치도 제주시 중앙로 2',NULL,33.517874815,126.524290543,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','130036','CULTURE','제주문화원','제주문화원은 탑동해변공연장 건물 2층에 위치한 문화원이다. 지역 고유의 문화계발, 연구, 조사 및 향토 문화의 발굴과 보존, 지역주민들에게 문화시민정신을 선양시키는 데 중점을 두고 있으며, 제주문화원은 제주시의 향토 사료 발간, 문화학교와 문화대학, 어르신 문화학교인 교육프로그램을 운영하고 있다. 문화학교에서 운영하는 여가문화 활동을 위한 교육 강좌로는 서예 교실, 민요 교실, 사진 교실, 한문 교실 등이 있으며, 문화대학에서 운영하는 제주의 역사, 자연, 민속, 문화 등 향토사 중심의 교육 강좌는 제주 신화, 제주 올래와 정낭, 제주 향토사 원로 특강 등이 있으며, 이는 변동될 수 있다.','제주특별자치도 제주시 중앙로 2','해변공연장 2층',33.517874815,126.524290543,NULL,'https://jejucc.kr','- 09:00~18:00- 휴게시간 11:40~13:20※ 강좌시간에 따라 변동 가능','매주 토요일~일요일 / 공휴일',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','130308','CULTURE','제주항일기념관','기미년 3·1독립만세운동은 제주지역까지 이어져 1919년 3월 21일부터 24일까지 조천읍 미밋동산(현 만세동산)과 조천장터 일대에서 전개되었다. 이러한 선열들의 뜻을 기리기 위해 조천만세동산 성역화 사업이 추진되었고, 1997년 8월 15일 광복절에 맞춰 기념관이 문을 열었다. 조천만세운동을 비롯해 법정사 항일운동, 해녀항일운동 등 제주 3대 항일운동과 제주에서 일어난 항일독립운동의 역사를 시대순으로 한눈에 볼 수 있다. 1층에는 항일운동사 연표와 법정사 항일운동 디오라마가, 2층에는 조천만세운동 디오라마와 해녀항일운동을 담은 매직비전 등이 전시되어 있다. 야외에는 애국선열추모탑과 위패를 모신 창열사, 3·1독립운동기념탑이 자리한 만세공원이 조성되어 있어, 선열들의 숭고한 희생정신을 되새기며 함께 둘러보기 좋다.','제주특별자치도 제주시 조천읍 신북로 303',NULL,33.5409795531,126.6407569556,NULL,'http://hangil.jeju.go.kr','09:00~18:00 (입장 마감 17:30)','1월1일 / 설날연휴(3일) / 추석연휴(3일)',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','130461','CULTURE','국립제주박물관','2001년 6월 15일 개관한 국립제주박물관은 제주의 역사와 문화유산을 체계적으로 전시·보존·연구하는 고고·역사박물관이다. 국립제주박물관에서는 제주의 여러 유적에서 출토된 유물과 역사적 문물들을 중심으로 선사시대부터 조선시대까지 시대별 각 유적과 유물이 갖는 역사·문화적인 의의를 전시물에 담았다. 탐라문화의 전시공간을 특성화하여 독특하고 고유한 탐라문화를 체계적으로 선보이는 한편, 해마다 다양한 주제의 특별전을 개최하고 있다. 그 외에도 다양한 사회교육 프로그램을 마련하는 등 제주를 찾는 국내·외 관광객에게 제주 토착문화의 전개 과정을 체계적으로 보여주는 문화공간이 되도록 노력하고 있다.','제주특별자치도 제주시 일주동로 17 (건입동)',NULL,33.513375,126.54886,NULL,'http://jeju.museum.go.kr','09:00~18:00 (입장 마감 17:30)','매주 월요일 / 1월 1일 / 설·추석 당일',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','130745','CULTURE','제주통일관','제주시 탐라자유회관 내에 소재해 있는 제주 통일관은 1993년에 개관되어 지상 2층, 지하 1층 건물로 건립되었다. 남북 교류 협력 시대에 대비하여 오늘의 북한 실상을 올바로 이해시키고, 민족 동질성 회복을 위한 실증적인 ‘통일교육장’으로 활용하기 위하여 설치하였다. 남북 관계 개선뿐만 아니라 한반도의 역사를 다시 한번 볼 수 있는 곳이다.','제주특별자치도 제주시 삼성로 46 (일도이동)',NULL,33.5068500833,126.530612725,NULL,'https://www.visitjeju.net','- 하절기(3월~10월) 10:00~17:00 - 동절기(11월~2월) 10:00~16:00','매주 일요일 / 설·추석 연휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','130857','CULTURE','제주해녀박물관','제주도에 위치한 제주해녀박물관은 제주의 상징인 해녀를 주제로 그들의 생활풍습, 무속신앙, 세시풍속, 해녀공동체뿐만 아니라 제주민의 역사, 생업, 경제, 해양, 연희 등 제주의 전통문화를 총망라하여 전시하고 있다. 박물관 안팎의 전시물들은 모두 해녀들이 기부한 것이며, 전시관 안에는 실제 해녀의 집도 기부받아 옮겨와 있다. 해녀박물관 앞의 정원은 해녀 항일 운동이자 국내 최대 규모의 여성 항일 운동 시위에 참여한 해녀들의 집결지였다. 그곳에는 해녀 항일 운동 정신을 기리고자 제주해녀항일운동비가 세워져 있어 제주 여성의 삶에 대한 강인한 의지를 느낄 수 있다.','제주특별자치도 제주시 구좌읍 해녀박물관길 26',NULL,33.5235518611,126.8634366646,NULL,'http://www.jeju.go.kr/haenyeo/','- 09:00~18:00- 매표 마감 17:00','매주 월요일 (단, 월요일이 공휴일인 경우 그 다음 첫 번째 비공휴일) / 1월 1일 / 설·추석 연휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','1544730','CULTURE','제주돌문화공원','제주돌문화공원은 돌의 고장 제주에 있는 돌문화를 종합적이고 체계적으로 보여주는 박물관이자 생태공원이다. 2020년까지 전체공원이 조성되었으며, 제1단계로 제주 돌 박물관, 제주 돌문화 전시관, 제주의 전통 초가 등의 전시관이 완공되어 공사가 시작된 지 7년 만인 2006년 6월 3일 문을 열었다. 
제주돌문화공원은 제주만의 독특한 자연유산인 오름 앞에 자리 잡고 있으며, 제주의 돌문화를 한곳에서 볼 수 있는 곳이다. 각종 돌 조형물들과 거석 사이를 통과하여 숲 속 오솔길을 따라가다 보면 박물관과 제주의 전통 초가들을 볼 수 있다. 야외 전시장에는 48기의 돌하르방, 사악한 기운과 액운을 몰아낸다는 방사탑, 도둑이 없어 대문도 없다는 제주의 상징인 정주석, 무덤 주위에 세워 망자의 한을 달래준다는 제주만의 내세관을 보여주는 동자석 등을 볼 수 있다. 제주의 역사와 전통 자연미를 함께 느낄 수 있는 자연과 문화의 쉼터이다. 

◎ 한류의 매력을 만나는 여행 정보 - 영화 
마녀 프로젝트를 진행하는 비밀연구소 아크의 배경이 된 장소는 돌문화공원 내에 있다. 공원 부지 100만 평 중 70%는 돌, 나무, 덩굴이 어우러진 곶자왈로 제주의 정체성과 예술성을 잘 담아낸 곳이다.','제주특별자치도 제주시 조천읍 남조로 2023',NULL,33.446621402,126.663992872,NULL,'http://www.jeju.go.kr/','09:00~18:00 (매표 마감 17:00)','매주 월요일 (단, 월요일이 공휴일인 경우 다음의 첫번째 비공휴일에 휴원) / 1월 1일 / 설날 및 추석 당일',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','1556005','CULTURE','그리스신화박물관','그리스신화박물관은 아름다운 섬 제주도에서 그리스 신화와 관련된 명화와 대리석을 눈으로 보고 손으로 만져볼 수 있는 체험형 박물관이다. 박물관은 루브르와 바티칸 박물관의 명화와 대리석 조각상 재현 작품을 전시한 공간과 관람객 모두 그리스인으로 변신하는 그리스 마을로 구성되어 있다. 창조관, 올림포스관, 신탁관, 영웅관, 휴먼관, 사랑관, 그리스 마을에서 기존 유물 중심의 수동적인 관람 방식에서 벗어나 전시물과 관람객이 교감할 수 있도록 다양한 체험형 전시를 제공한다. 대표 체험으로는 그리스의상 체험, 아테네 시민권 발급 체험, 올림포스 12신 가면 만들기 체험 등이 있다.','제주특별자치도 제주시 한림읍 광산로 942',NULL,33.348072482,126.3576543384,NULL,'http://www.greekmythology.co.kr','09:00~18:00 (입장 마감 17:00)','매주 월요일',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','1769266','CULTURE','제주 세계자연유산센터','거문오름에 위치한 제주세계자연유산센터는 유네스코 세계자연유산으로서 제주의 가치를 관리하고 보전하기 위한 시설로, 화산 활동을 통해 생성된 제주, 용암동굴, 한라산의 다양한 식생, 용암동굴, 미래의 자연유산 등 제주 자연의 숨결을 느끼고 경험해 볼 수 있다. 이곳의 주요 시설은 상설전시실, 기획전시실, 4D영상관, VR체험존이 있고 그 이외에도 전망대, 세미나실, 국제홍보관, 여행안내소 등이 있다. 센터에서 거문오름을 탐방할 수 있는 통로가 곧바로 연결되어 있어 이용자의 편의를 돕는다.','제주특별자치도 제주시 조천읍 선교로 569-36',NULL,33.4568849822,126.714718683,NULL,'https://www.jeju.go.kr/wnhcenter/','- 09:00~17:50- 매표 마감 17:20','매월 첫째주 화요일 / 설·추석 당일',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','1939078','CULTURE','조천읍도서관','조천읍도서관은 다양한 자료를 수집 및 제공함으로써 도민의 독서생활화에 기여하고 있는 공공도서관이다. 1999년에 개관하였으며, 현재는 제주시 문화관광체육국 산하 우당도서관에서 관리하고 있다. 다양한 계층별 독서문화 프로그램을 통해 도민들의 평생교육 실현에 앞장서고 있는 문화·소통의 복합공간을 위해 힘쓰고 있다. 지하 1층, 지상 2층 규모로 총 250석의 좌석을 갖춘 열람실과 서예실, 정보이용실, 다목적강당, 어린이자료실 등이 있다. 어린이자료실은 아이들이 자유롭게 앉고 기대거나 누워서 볼 수 있는 편안한 공간으로 마련되어 있다. 영유아를 위한 온돌방 형태의 공간도 갖추고 있어 부모와 자녀가 함께 책을 즐길 수 있다.','제주특별자치도 제주시 조천읍 일주동로 1189',NULL,33.5376775945,126.6676656403,NULL,'https://www.jeju.go.kr/','[종합자료실]- 평일 08:00~22:00- 주말/법정공휴일 09:00~18:00[열람석/디지털석]- 08:00~22:00[어린이자료실]- 09:00~18:00','매주 금요일 / 설·추석 연휴 / 대체 공휴일 / 12월 31일 / 1월 1일',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2031663','CULTURE','김만덕기념관','김만덕기념관은 나눔과 베풂을 몸소 실천하시어 이 땅의 대표적 의인의 표상이 되신 김만덕의 삶과 그 정신을 기리고 본받아 널리 전파하기 위한 곳이다. 김만덕의 근검절약정신, 나눔 정신, 개척과 개혁, 개방 정신, 도전정신 그리고 김만덕의 리더십과 경영철학을 배워서 나눔을 체험하고 실천하는 대한민국 최초의 나눔문화전시관이기도 하다.

(출처 : 김만덕기념관 홈페이지)','제주특별자치도 제주시 산지로 7',NULL,33.515875146,126.5304011313,NULL,NULL,'09:00~18:00','매주 월요일 (단, 월요일이 공휴일일 경우 그 다음 평일 휴관) / 1월 1일 / 설·추석 당일',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2660122','CULTURE','제주라프','제주시 조천읍에 위치한 제주라프(Jeju LAF)는 거문오름과 푸른 녹차밭의 자연 속에서 짚와이어, 힐링 족욕, 그리고 다채로운 문화, 예술, 야간 조명 작품을 감상할 수 있는 복합문화예술공간이다. 이름의 \'라프(LAF)\'는 \'Light Art Festa\'의 약자로, 제주를 찾는 여행객들에게 특별하고 감각적인 경험을 선사한다.
이곳에는 예술작품 갤러리를 비롯해 다양한 체험·편의 시설이 마련되어 있다. 짜릿한 액티비티인 \'라플라이(짚라인)\'는 유네스코 세계자연유산인 거문오름과 광활한 녹차밭 위를 가로지르며 역동적인 풍경을 만끽할 수 있는 야외 레포츠이다. 또한 \'라풋(아로마테라피 풋 스파)\'은 따뜻한 미온수에 발을 담그고 아로마 향 속에서 피로를 풀 수 있는 시설로, 미온수 족욕과 녹차 소금 스크럽, 스트레칭을 통해 온몸의 긴장을 부드럽게 이완시켜 준다. 이외에도 음료와 스낵을 즐길 수 있는 카페 등이 운영되고 있다.','제주특별자치도 제주시 조천읍 선교로 115-1',NULL,33.4868202622,126.7069548264,NULL,'http://www.jejulaf.com','- 라플라이 09:30~18:00- 라풋 09:00~18:00','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2713583','CULTURE','제주도립김창열미술관','제주도립 김창열미술관은 ‘물방울 화가’로 널리 알려진 김창열 화백의 주옥같은 작품을 만나 볼 수 있으며, 현대미술의 발전에 이바지하는 미술작품과 자료를 전시, 연구 수집하는 것을 목적을 가지고 있다. 김창열은 미술관 건립을 위해 주요 작품 220점을 기증했다. 홍재승 건축가가 설계한 미술관 하늘에서 보면 중정을 기준으로 거대한 큐브형 건물 8개가 둘러싸인 모습이다. 이는 김창열이 추구한 회귀의 철학을 건축적으로 표현한 것이다.','제주특별자치도 제주시 한림읍 용금로 883-5',NULL,33.3390713181,126.2686717213,NULL,NULL,'[하절기(7월~9월)] - 09:00~19:00[동절기(10월~6월)] - 09:00~18:00 ※ 운영 종료 30분 전 입장 마감','매주 월요일 (단, 월요일이 공휴일일 경우 익일 휴무) / 1월 1일 / 설·추석 당일',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2740014','CULTURE','노형수퍼마켙','노형수퍼마켙은 약 4000㎡(1200여 평)의 면적과 최대 높이 20m(6층 건물 높이)의 웅장하고 압도적인 규모의 미디어아트 테마파크이다.
‘일상과 비일상이 공존하는 공간 속에서 자신만의 아이덴티티를 발견하는 여정’이라는 스토리라인으로, 내부는 ‘노형수퍼마켙 프리쇼’, ‘베롱베롱’, ‘뭉테구름’, ‘와랑와랑’, ‘곱을락’ 등 미디어아트 영상 공간을 중심으로 한 총 5개의 전시 공간으로 구성되어 있다. 내부 카페인 ‘노형다방’에서는 흑백 콘셉트의 다양한 음료 및 디저트를 즐길 수 있으며, 기념품 샵인 ‘노형잡화점’에서는 노형수퍼마켙 고유의 패턴이 들어간 특별한 기념품들을 만나볼 수 있다.','제주특별자치도 제주시 노형로 89',NULL,33.4649770932,126.4552065105,NULL,'http://nohyung-supermarket.com/','09:00~19:00 (입장 마감 18:00)','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2811110','CULTURE','훈데르트바서파크','훈데르트바서파크는 제주시 우도에 위치한 문화예술공간으로 훈데르트바서의 건축물과 예술 작품을 감상하며 색다른 경험을 할 수 있는 곳이다. 오스트리아의 화가이자 건축가인 프리덴슈타인 훈데르트바서의 작품과 건축 철학을 바탕으로 조성되었다. 훈데르트바서는 자연과 조화를 이루는 건축을 추구한 것으로 유명하다. 훈데르트바서파크 또한 우도의 자연환경과 조화를 이루는 독특한 건축물로 이루어져 있다. 파크는 크게 훈데르트바서뮤지엄, 우도갤러리, 파크 굿즈샵으로 구성되어 있다. 훈데르트바서뮤지엄은 훈데르트바서의 일생과 작품을 전시하는 곳으로 그의 회화 작품, 건축 작품, 조각 작품 등을 감상할 수 있다. 우도갤러리는 신진 작가들의 작품을 전시하는 곳으로 제주를 주제로 한 다양한 작품들을 감상할 수 있다. 파크 굿즈샵에서는 티셔츠, 머그컵, 에코백 등훈데르트바서파크의 다양한 오리지널 굿즈를 판매하고 있다.','제주특별자치도 제주시 우도면 우도해안길 32-12',NULL,33.4930106317,126.9549299785,NULL,'http://www.hundertwasserpark.co.kr','09:30~18:00 (입장 마감 17:00)','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2852695','CULTURE','예술공간 이아','예술공간 이아는 예전 제주대학교 병원 건물의 골조를 그대로 살린 채 리모델링하여 만든 복합문화공간으로 1년 내내 다양한 전시가 있어지는 곳이다. 전시장과 연습 공간 운영 및 창의적 문화 예술교육 프로그램 등을 통해 예술창작의 거점을 마련해 도민들의 문화향유 기회를 확대하고, 지역과의 긴밀한 연계를 통해 원도심 활성화에 함께한다.','제주특별자치도 제주시 중앙로14길 21 (삼도이동)',NULL,33.5111557521,126.5220988994,NULL,'https://www.jfac.kr/','[전시실]10:00~18:00 (입장 마감 17:30)[3층/4층]09:30~18:00','매주 월요일 / 법정공휴일 / 노동절(5월 1일)',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2905116','CULTURE','제주과학탐구체험관','제주과학 탐구체험관은 제주시 오라동 제주 미래 교육연구원에 위치하고 있다. 다양한 과학 체험을 할 수 있는 곳으로 1층 역동의 큐브는 물리, 역학적인 체험 전시물, 2층 발견의 큐브는 도입수학, 생명과학, 지구과학, 3층 도약의 큐브는 드론, 우주, 로봇, 스마트, 에너지, 시공간과 관련된 체험 전시물로 구성되어 있다. 이 외에도 유아 체험관, 3D 영상관과 천체투영실, 물품 보관함, 도서관을 갖추고 있으며 시설 사용료는 무료이다.','제주특별자치도 제주시 산록북로 421-1 (오라이동)',NULL,33.4266199751,126.5314445431,NULL,'https://org.jje.go.kr/cisecenter/','10:00~17:00 (입장 마감 16:00)','매주 월요일 / 1월 1일 / 설·추석 연휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2933508','CULTURE','유동룡미술관','유동룡미술관은 제주를 사랑한 세계적인 건축가 유동룡의 건축 철학과 예술 세계를 조명하는 공간이다. 재일한국인으로 태어나 이타미 준이라는 이름으로 활동한 유동룡은 건축과 예술의 경계를 넘나들며 독자적인 작품 세계를 구축한 건축가이자 종합예술가이다. 제주에는 방주교회, 수풍석뮤지엄, 포도호텔, 비오토피아 등 여러 건축 작품을 남긴 인물로 잘 알려져 있다. 미술관은 유동룡이 추구한 공간 철학을 바탕으로 그의 딸인 유이화가 설계하였으며, 자연과 조화를 이루는 건축과 지역의 풍토, 전통, 역사에 기반한 건축 철학을 담고 있다. 전시뿐 아니라 향과 음악, 티 서비스 등을 통해 건축가 유동룡의 사상과 예술 세계를 보다 깊이 이해할 수 있는 공간이다.','제주특별자치도 제주시 용금로 906-10',NULL,33.340585868,126.2707792522,NULL,'https://itamijunmuseum.com/','10:00~18:00 (입장 마감 17:00)','매주 월요일 / 1월1일※ 내부 사정에 따라 변동될 수 있으므로 전화문의 요망',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2833763','CULTURE','산지천갤러리','산지천 갤러리는 녹수장, 금성장이라는 이름의 여관 건물을 재생하여 만든 문화공간이다. 원도심 활성화를 위해 추진된 산지천 복원과 탐라문화광장 조성사업으로 노후 건물들의 철거가 진행되었으나, 산지천 갤러리가 들어선 건물을 포함하여 고씨가옥, 유성식품 등 다섯 곳은 기존 원도심의 풍경을 담고 있는 가치를 인정받아 보존 건축물로 지정되었다. 이 건물들에 대한 많은 사람들의 관심과 애정 어린 목소리를 통해 산지천 갤러리라는 전시공간으로 새롭게 탄생하였다. 산지천 갤러리는 전문전시공간으로서 다양한 문화예술콘텐츠를 제공함과 동시에 원도심 지역 문화 관광 활성화에 기여하고자 한다.','제주특별자치도 제주시 중앙로3길 36',NULL,33.5151474198,126.528331896,NULL,'https://www.jfac.kr/','- 10:00~18:00- 입장 마감 17:30','매주 월요일 / 설·추석 연휴 / 공휴일',90,0,'2026-11-05 14:32:04'),
('50110','KTO_TOURAPI','2858291','CULTURE','어리목탐방안내소','한라산 어리목탐방안내소는 한라산 어리목 탐방로 주차장, 어승생악 입구 옆에 있다. 한라산 탐방 정보와 한라산의 탄생, 역사, 지질, 전설, 생태 등 이해를 돕기 위한 전시공간으로 이루어져 있다. 1~3전시실과 함께 어린이 체험학습장, 영상실, 포토존 등이 있다. 영상실에서는 한라산 및 제주 세계자연유산 홍보영상을 관람할 수 있고 탐방로 입구, 한라산 탐방로, 어리목 등에 설치된 실시간 CCTV 장면도 확인할 수 있다. 한라산 탐방로 가이드와 산행 안전 수칙, 한라산 보호 활동 등 등반과 환경 활동에 필요한 정보를 얻을 수 있어 산행 전 둘러보기 좋다.','제주특별자치도 제주시 1100로 2070-61 (해안동)',NULL,33.392979,126.495379,NULL,NULL,'09:00~17:00','연중무휴',90,0,'2026-11-05 14:02:28'),
('50110','KTO_TOURAPI','130856','CULTURE','제주돌마을공원','제주돌마을공원 수석전시관은 30여 년 동안 수집해 온 제주의 수석, 자연석, 화산석 등을 전시해 놓은 곳이다. 자연석으로만 꾸며져 있으며 제주의 신비한 자연석을 각기 다른 테마로 구성해 전시했다. 화산 폭발과 용암의 흐름 등으로 각양각색으로 만들어진 자연석들이 있으며 전시관은 암반을 따라 테마별 수석 코너를 관람하도록 조성했다. 수석의 개수는 총 5,000여 점으로 코너별 테마는 동물 형상석, 제주도 생성 비밀을 간직한 화산탄, 자연물이나 생명체를 닮은 경석, 사람 얼굴을 빼닮은 두상석 등이 있고 캐릭터를 설정해 인간의 사랑과 일생을 형상석에 대입해 보여주는 코너가 있어 재미를 더한다. 368개 수석으로 오름을 형상화한 제주도 테마 코너도 볼거리가 많다.','제주특별자치도 제주시 한림읍 금능남로 421','(한림읍)',33.3537479564,126.2537416535,NULL,NULL,'[하절기] 09:00~18:00[동절기] 09:00~17:00','연중무휴',90,0,'2026-10-16 16:00:53'),
('50110','KTO_TOURAPI','3066924','CULTURE','제주웰컴센터','제주관광공사에서 운영하는 제주웰컴센터는 제주특별자치도, 제주관광공사, 제주특별자치도 관광협회, 제주컨벤션뷰 등으로 이원화되어 있던 관광 운영체계를 단일화한 안내소이다. 종합관광안내, 환전소, 관광기념품 전시장 등 관광객 편의시설을 갖추고 있으며 사진 스튜디오, 영상 스튜디오, 통계 자료실, 비즈니스 라운지, 회의실, 교육 시설, 세미나 및 강연을 위한 다목적 홀(240석)이 있다.','제주특별자치도 제주시 선덕로 23 (연동)',NULL,33.4857267441,126.4991792621,NULL,NULL,'09:00~18:00','연중무휴',90,0,'2026-10-06 17:31:17'),
('50110','KTO_TOURAPI','2834656','CULTURE','아라리오뮤지엄 동문모텔2','아라리오뮤지엄의 다섯 번째 전시공간 아라리오뮤지엄 동문모텔 II는 동문모텔 I과 더불어 제주 구도심의 최대 번화가였던 동문재래시장과 제주의 역사를 안고 흐르는 산지천 사이에 자리하였던 모텔들을 인수하여 문화시설로 개축한 현대미술관이다. 산지천은 물이 귀한 제주에서 가장 큰 용천수가 솟아나는 하천이자 항만물류의 중심으로 주택과 상가들이 조밀하게 모여있는 지역이었다. 바다에서 항구로 들어오면 바로 마주하게 되는 동문모텔 II는 건물이 밀집된 지역의 자투리 땅을 활용하기 위해 삼각형으로 지어졌다. 그러나 신도심 개발과 항공교통의 발달로 인해 산지천 일대를 찾는 사람들의 발길이 줄어들자 효용가치가 낮아 지난 10여 년간 방치되어 있었다. 동문모텔 I과 동문모텔 II는 산지천의 옛 기억이 묻어있는 기존 건물의 흔적들을 보존함과 동시에 현대적인 미술작품을 감상할 수 있는 곳으로 새롭게 태어났다. 과거 여정에 지친 사람들의 휴식처였던 모텔들은 이제 새로운 예술적 경험을 선사하는 공간으로 탈바꿈되어 산지천 일대에 새로운 문화적 활기를 불어넣을 것이다.','제주특별자치도 제주시 산지로 23',NULL,33.5149530146,126.5293623601,NULL,'http://www.arariomuseum.org/','10:00~19:00','매주 월요일',90,0,'2026-10-06 14:56:59'),
('50110','KTO_TOURAPI','2986689','CULTURE','제주고산리유적안내센터','우리나라에서 가장 오래된 신석기 유적인 제주 고산리 유적을 알리고 보존하기 위해 2016년 건립한 안내센터다. 고산리 유적은 1987년 마을 주민이 뗀석기와 덧무늬토기를 발견해 신고하면서 세상에 알려졌고, 여러 차례의 발굴 조사를 거쳐 1998년 국가 사적으로 지정되었다. 후기 구석기 최말기에서 신석기 초기로 넘어가는 전환기의 모습을 보여주는 유적으로, 우리나라 최초의 토기로 꼽히는 고산리식 토기와 양면떼기 방식의 찌르개, 화살촉, 갈돌 등이 출토되었다. 안내센터에서는 유적의 역사와 발굴 과정을 전시와 해설로 살펴볼 수 있으며, 토기와 석기 만들기 등 신석기 문화를 쉽고 흥미롭게 이해할 수 있는 체험과 교육 프로그램도 무료로 운영한다. 수월봉 앞 해안 대지에 자리해 있어 인근 수월봉과 함께 둘러보며 1만 년 전 제주의 시간을 가까이 만나기 좋다.','제주특별자치도 제주시 한경면 노을해안로 1100',NULL,33.3041190488,126.1662116405,NULL,'http://www.gosanriyujeok.co.kr/','09:00~17:00','매주 월요일 / 법정공휴일',90,0,'2026-09-30 15:56:06'),
('50110','KTO_TOURAPI','130088','CULTURE','제주교육박물관','제주교육박물관은 우리 주변에 사라지거나 잊혀가는 소중한 교육자료를 수집하여 보존하고, 학생들에게 전통문화의 체험 기회 확대와 제주교육문화의 진흥을 위해 1995년 4월 29일 개관한 교육 특화 박물관이다. 4개의 상설 전시장과 기획 및 체험전시실, 야외전시장으로 구성되어 있다. 제주교육에 관한 교과서, 서장, 교구, 문서 등을 수집하고, 선사시대부터 현대에 이르기까지 시대별로 특징을 담아 자료를 전시했다. 개체 전시, 생동감 있는 영상 전시, 그리고 교육 현장을 축소한 디오라마 전시기법을 통해 제주교육의 과거, 현재, 미래를 제시하고 있다. 제주교육의 흐름과 옛 교육의 생활 및 놀이를 엿보고 체험도 하며 즐거운 관람을 할 수 있다. 무료 전시해설 프로그램이 있어 관람 이해를 돕고 있다.','제주특별자치도 제주시 오복4길 25','(이도이동)',33.4946138543,126.5379120297,NULL,'https://org.jje.go.kr/','09:00~18:00','매주 월요일 / 1월 1일 / 설·추석 당일 / 임시 공휴일',90,0,'2026-09-28 09:48:53'),
('50110','KTO_TOURAPI','2798027','CULTURE','전이수갤러리 걸어가는늑대들','전이수갤러리 걸어가는늑대들은 제주도에 사는 꼬마 화가이자 동화 작가가 운영하는 곳이다. SBS ‘영재 발굴단’ 방송 출연으로 알려진 전이수는 개성 있는 그림체와 어려운 환경에 있는 사람들에게 기부를 하는 선한 영향력을 펼치고 있는 작가다. 전시 입장료의 수익은 제주 미혼모 보호시설과 국경 없는 의사회, 아프리카 친구들을 위해 쓰인다. 갤러리 입구에는 전이수 작가와 동생 전우태 작가의 작품이 담긴 굿즈 상품과 책, 팬시 용품 등을 판매하고 있다. 사회의 아픔과 세계 곳곳 어려운 이웃에 대한 마음을 순순하고 특유의 감성으로 풀어내는 전이수 갤러리는 전시를 보는 내내 마음의 힐링뿐 아니라 기부도 함께 할 수 있는 뜻깊은 공간이다.','제주특별자치도 제주시 연북로 707 (이도이동)','1-2',33.4950007521,126.5513080694,NULL,'https://www.walkingwolves.com/','10:00~19:00 (입장 마감 18:00)','연중무휴',90,0,'2026-09-23 14:24:31'),
('50110','KTO_TOURAPI','4108669','CULTURE','책약방','조용한 초등학교 앞 정겨운 골목길을 천천히 걷다 보면 동화 속에서 튀어나온 듯 아기자기한 외관의 작은 책방이 여행자의 발길을 붙잡는다. 이곳은 쓴 약 대신 달콤한 그림책으로 일상에 지친 사람들의 마음을 따스하게 다독이고자 문을 연 이색적인 무인 서점이다. 주인 없이 이십사 시간 내내 언제나 활짝 열려 있는 아담한 실내로 들어서면 누군가의 정성스러운 손길로 채워진 포근한 서가가 방문객을 반갑게 맞이한다. 책장에는 아이들의 순수한 상상력을 자극하는 도서부터 어른의 내면을 다정하게 위로해 주는 그림책과 산문집까지 다채로운 읽을거리가 정갈하게 꽂혀 있다. 그 밖에도 먼저 다녀간 여행자들이 정성껏 남겨 놓은 방명록의 흔적을 찬찬히 읽어보며 나만의 온전한 휴식 시간을 누릴 수 있는 것이 이곳만의 특별한 매력이다.','제주특별자치도 제주시 구좌읍 종달로5길 11',NULL,33.4929547105,126.8976924481,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-09-14 09:02:39'),
('50110','KTO_TOURAPI','1755806','CULTURE','제주아트센터','2010년 5월에 개관한 제주아트센터는 총 1,184석의 객석과 첨단 시설을 갖춘 다목적 공연장이다. 오케스트라 피트가 준비되어 있어 정통 클래식 공연에 오케스트라와 협연을 통한 최고의 공연을 보여줄 수 있으며 최신 음향, 조명, 무대 시스템을 갖추고 있어 뮤지컬, 연극, 무용 등 다양한 장르의 공연을 소화할 수 있다. 관람에 최적인 경사로를 선택하여 어느 좌석에서 앉아도 동일하고 쾌적한 음이 전달되는 최고의 관람 환경을 제공한다.','제주특별자치도 제주시 오남로 231 제주아트센터',NULL,33.4750796592,126.515520114,NULL,'http://www.jejusi.go.kr','공연 별로 상이함','공연 별로 상이함',90,0,'2026-09-10 11:03:02'),
('50110','KTO_TOURAPI','2778915','CULTURE','나이롱책방','제주시와 가까운 삼양의 어느 골목길에 나이롱책방이 자리한다. 나이롱은 ‘어떤 이로운 장난’을 의미한다고 한다. 보통 책방에 들르면 어떤 책을 골라야 할지 고민스럽기 마련이다. 책을 고르는 데 도움이 되도록 각각의 책마다 어떤 내용을 담고 있는지 정성스러운 손 글씨로 적혀 있다. 책은 주제별로 구분되어 있는데 제주와 관련된 서적부터 독립출판물, 다양한 해외 서적까지 만나볼 수 있다. 읽은 이의 흔적이 고스란히 남은 중고 책도 함께 판매한다. 책과 커피를 함께 즐길 수 있는데 책은 구매 후에 테이블에서 여유롭게 읽을 수 있다. 한쪽에는 그동안 책방을 다녀간 이들의 발자취를 더듬어볼 수 있는 그림 방명록을 비치해 구경하는 재미를 더한다.','제주특별자치도 제주시 관덕로8길 17 (이도일동)',NULL,33.5116662086,126.5234377233,NULL,NULL,'- 목요일~월요일 10:00~20:00- 화요일 10:00~16:00','매주 수요일',90,0,'2026-08-07 08:56:07'),
('50110','KTO_TOURAPI','2778939','CULTURE','밤수지맨드라미','비행기를 타고 제주에 가서, 또 배를 타고 섬에서 섬으로 들어가면 만날 수 있는 제주 우도의 유일한 독립서점인 밤수지맨드라미이다. 전형적인 제주 돌담으로 둘러싸인 건물 입구엔 책이라고 적힌 간판이 이곳이 책방이라는 걸 알려준다. 밤수지맨드라미는 제주 바닷속에 사는 멸종 위기 산호로, 책이 사라져 가는 현실이 산호꽃과 닮은 것 같다고 생각해 책방 이름을 지었다고 한다. 책방 내부엔 독립 서적이나 드로잉북, 채식 관련 책들이 구비되어 있다 책방 창문 너머로는 햇살이 쏟아지는 바다도 눈에 들어온다. 이곳 책방만의 개성을 담은 굿즈들도 판매하고 있으며 공간 한쪽은 카페처럼 운영돼 구매한 책을 여유롭게 읽어볼 수도 있다.','제주특별자치도 제주시 우도면 우도해안길 530',NULL,33.5207140039,126.9484786287,NULL,'http://www.instagram.com/bamsuzymandramy.bookstore/','10:00~17:00','연중무휴※ 비정기적 휴무가 있을 수 있으므로 홈페이지 참조 및 전화 문의 요망',90,0,'2026-08-07 08:53:48'),
('50110','KTO_TOURAPI','2798046','CULTURE','김택화 미술관','김택화 미술관은 2019년 12월에 개관한 미술관으로 일평생 제주의 풍경을 그렸던 화가 김택화(1940~2006)의 예술 세계와 삶의 여정을 담아낸 공간이다. 김택화 화가는 한라산 소주의 ‘하얀색’ 패키지 그림의 원화를 그리기도 했다. 미술관은 자료실, 제1전시실, 제2 전시실, 아트숍을 지나 2창 카페로 구성되어 있으며 전시실에는 생전에 그렸던 김택화 화가의 유화 작품 122점이 전시되어 있다. 이곳에서 옛 제주의 풍경을 그림으로 만날 수 있다. 2층은 화실로 꾸며진 카페가 있고 통유리 창으로 탁 트인 풍경을 감상할 수 있다.','제주특별자치도 제주시 조천읍 신흥로 1',NULL,33.5437572078,126.6531779586,NULL,'https://kimtekhwa.com/','10:00~18:00','매주 목요일 / 1월 1일',90,0,'2026-08-04 15:03:29'),
('50110','KTO_TOURAPI','4057731','CULTURE','제주책방·사랑방','제주사랑방은 일제 강점기에 지어진 일본식과 제주식 건축양식이 혼재된 가옥이다. 고씨 아저씨가 거주하시던 공간이라 ‘고씨주택’으로도 불리고 있다. 안거리와 밖거리, 작은 마당이 있는 아기자기한 공간을 제주책방, 제주사랑방으로 재탄생하였다. 제주책방에서는 제주의 문화, 역사, 자연을 주제로 수집된 제주 관련 희귀 자료들을 열람할 수 있고, 제주 이야기를 담은 그림책도 많아서 아이들과 방문하는 것도 추천한다.','제주특별자치도 제주시 관덕로17길 27-1 (일도일동)',NULL,33.5149162874,126.5283194776,NULL,NULL,'- 평일 10:00~18:00 - 주말 10:00~20:00※ 7월~8월은 주말 야간 운영','매주 목요일 / 설날·추석 연휴',90,0,'2026-06-30 11:26:57'),
('50110','KTO_TOURAPI','4060957','CULTURE','하리보 해피월드','하리보 해피월드는 100여년이 넘는 역사, 120개국 이상에서 사랑받고 있는 ‘HARIBO’를 천혜의 섬 제주에서 만나볼 수 있는 전시관이다. 알록달록 다양한 젤리들과 HARIBO의 역사, 그리고 제작 과정까지 HARIBO의 모든 것을 미디어 아트와 미디어 게임으로 만나볼 수 있으며, 전시관 곳곳에 가득한 포토존에서 추억을 만들 수 있는 곳이다. 어린이들에게는 상상력과 모험을, 어른들에게는 동심을 선사하는 환상적인 공간을 지향하고 있으며 2층의 아트샵에서는 전세계의 다양한 젤리들과 사랑스런 굿즈들을 만나 볼 수 있다.','제주특별자치도 제주시 아연로 444-1 (오등동)',NULL,33.4738817185569,126.528770546154,NULL,'https://haribohappyworldjeju.com/','10:00~19:00 (입장 마감 18:00)',NULL,90,0,'2026-04-28 16:54:04'),
('50110','KTO_TOURAPI','3546163','CULTURE','김영수도서관','제주북초 20회 졸업생인 故 김영수 선생님이 기증하신 학교도서관이다. 아이들이 책을 가까이하고 마음껏 상상할 수 있는 공간을 만들기 위하여 2018년 도시재생사업을 통해 학교와 지역공동체의 의견을 수렴한 결과, 현재 본교 학생과 지역주민이 함께 이용할 수 있는 학교도서관이자 마을도서관으로 새롭게 탄생하여 독서문화의 장으로 활발히 운영되고 있다.','제주특별자치도 제주시 중앙로8길 18 (삼도이동)',NULL,33.5149928252347,126.52138373358315,NULL,'https://school.jje.go.kr/jejubuk/main.do','[학교도서관]- 평일 08:30~16:30[마을도서관]- 평일 17:00~21:00- 주말 10:00~18:00※ 재학생과 지역주민의 이용시간이 상이하므로 방문 전 확인 필요','[학교도서관]- 주말 / 법정공휴일[마을도서관]- 매주 화요일 / 법정공휴일',90,0,'2026-04-21 17:26:37'),
('50110','KTO_TOURAPI','3061676','CULTURE','너븐숭이 4.3기념관','너븐숭이 4.3기념관은 2009년 조천읍 북촌리에 건립된 기념관으로, 제주 4.3 희생자들을 위로하고 교육장으로 활용하기 위해 조성되었다. 북쪽에는 위령비가 자리하고 있는데, 위령비 앞면에는 북촌리 원혼 위령비라는 글자가 새겨져 있고, 뒷면에는 희생자 명단이 새겨져 있다. 너븐숭이 4.3기념관에는 강요배 화백의 젖먹이를 비롯하여, 북촌리의 비극을 배경으로 한 현기영 작가의 순이 삼촌 초판본 등이 전시되어 있고, 북촌리 주민 대학살의 진상과 관련된 역사 자료들을 전시하고 있다. 기념관은 전시관, 탐구관, 묵상의 방, 영상실, 사무실로 구성되어 있으며, 너븐숭이 애기무덤 등 당시의 상황을 고스란히 느낄 수 있는 흔적들이 남아있다.','제주특별자치도 제주시 조천읍 북촌3길 3',NULL,33.546012249070245,126.68865605865707,NULL,'https://www.visitjeju.net/','09:00~18:00 (입장 마감 17:00)','매월 둘째주, 넷째주 월요일 / 1월 1일 / 설·추석 연휴',90,0,'2026-04-20 09:21:14'),
('50110','KTO_TOURAPI','4057922','CULTURE','건입박물관','제주시 건입동에 위치한 건입박물관은 마을 주민들이 전시 물품을 기증해 만든 작은 박물관이다. 이 때문에 소소한 볼거리들이 많다. 과거에 유행했던 제주 산호 기념품이나 직접 쓰던 돌절구, 다리미, 물허벅, 해녀물품 등 마치 타임머신을 타고 떠난 느낌을 받을 수 있는 곳이다.','제주특별자치도 제주시 산지로 5-14 (건입동)',NULL,33.5159813698533,126.530845054356,NULL,NULL,'09:00~18:00','매주 토요일, 일요일',90,0,'2026-04-17 09:35:49'),
('50110','KTO_TOURAPI','4057941','CULTURE','제주물사랑홍보관','제주에 위치한 제주물사랑홍보관은 건입박물관 후문으로 나서면 잘 꾸며진 생태 공원과 함께 위치해 있다. 과거 제주도는 물이 귀하고 부족해 조선시대에는 최악의 유배지로 여겨지던 곳이었다. 기술이 발달해 지하수를 퍼올리게 되면서 지금은 삼다수를 수출까지 하는 시대가 되었다. 물사랑홍보관에서는 이런 이야기들을 자세히 들을 수 있다.','제주특별자치도 제주시 산지로 5-16 (건입동)',NULL,33.5155645236088,126.531024685825,NULL,NULL,'09:00~18:00','매주 월요일',90,0,'2026-04-17 09:31:26'),
('50110','KTO_TOURAPI','3083715','CULTURE','제주홀릭뮤지엄','제주홀릭뮤지엄은 과거 50년 전에 지어진 요양병원을 업사이클링 하여 만들어진 전시관이며, 제주도를 재해석한 내용들로 이루어진 5개의 공간에서 제주에 대해 몰랐던 새로운 이야기가 펼쳐지는 신비로운 전시다.
제주홀릭뮤지엄은 ‘제주, 빛으로 말하다’, ‘상상제주’, ‘유색유취’, ‘경험의 자유’, ‘일상의 비움’ 등 제주도 콘텐츠를 바탕으로 컨셉이 이루어진 5개의 공간으로 구성되어 있으며, 제주에 관한 새로운 이야기를 쉽게 알 수 있도록 다양한 작품들이 설치되어 있는 체험형 전시다.','제주특별자치도 제주시 애월읍 평화로 2835',NULL,33.45646869202743,126.44162522614434,NULL,'https://www.jejuholicmuseum.com','09:30~18:00 (관람 마감 19:00)','연중무휴',90,0,'2026-04-14 15:01:36'),
('50110','KTO_TOURAPI','3386123','CULTURE','주정공장수용소 4·3역사관','주정공장수용소 4.3역사관은 일제강점기 시절 동양척식회사가 운영하던 큰 규모의 주정공장이 있었던 곳으로, 바로 앞에 항구가 있어 생산된 주정을 바로 내보낼 수 있었다. 태평양전쟁 때에는 제주도 전역에서 수확한 고구마를 이용해 주정을 생산하였다. 이 곳에서 생산한 알코올은 일본군의 연료로 사용되었고, 해방 이후에도 4.3 당시 주정공장이 보유한 창고들이 민간인 수용소로 이용되었다. 그 당시 행방불명된 희생자들을 기리기 위한 역사관이다.','제주특별자치도 제주시 임항로 98 (건입동)',NULL,33.51810710408291,126.53480935519346,NULL,NULL,'09:00 ~18:00 (입장 마감 17:00)','매달 둘째, 넷째 월요일 / 1월 1일 / 설·추석 연휴',90,0,'2026-04-14 11:01:35'),
('50110','KTO_TOURAPI','3037623','CULTURE','제주 스카이워터쇼','제주 스카이워터쇼는 구좌읍에 위치한 실내 공연장에서 상연되는 워터쇼이다. 대형 분수쇼와 고난도 다이빙쇼가 어우러지는 역동적이고 신기한 워터쇼로 외줄 타기 공연은 물론이고 고공낙하쇼 그리고 분수쇼까지 화려한 퍼포먼스와 환상적인 무대는 긴장감을 놓을 수 없는 재미를 선사한다. 또한, 물과 빛이 아름답게 어우러지는 국내 최초의 스카이 워터쇼로 손꼽힌다. 필리핀공연단, 러시아, 우즈베키스탄, 우크라이나 세계대회 우승 다이버 등 여러 나라의 공연단들과 함께 대형 분수쇼, 화려한 공중 퍼포먼스와 코믹하고 멋진 다이빙 쇼를 동시에 선보이고 있다. 공연이 끝나면 공연단들과 함께 사진 촬영도 가능하다. 아이가 있는 가족여행객뿐 아니라 부모님도 만족하는 공연으로 온 가족이 함께 즐기기 좋은 제주도 실내관광지이다. 주변으로 산굼부리분화구와 에코랜드가 있어 연계해서 방문해 보는 것도 좋다.','제주특별자치도 제주시 구좌읍 번영로 2172-80',NULL,33.42422382472475,126.7442727110463,NULL,'http://www.skywatershow.co.kr/','- 09:30~14:30 (휴게시간 12:00~13:00)- 공연 시간(3회차) 09:30 / 11:00 / 14:30','연중무휴',90,0,'2026-04-10 15:01:02'),
('50110','KTO_TOURAPI','3545735','CULTURE','만춘서점','만춘서점은 2016년에 시작한 제주 함덕의 독립서점이다. 여행자와 일상인 모두에게 열린 이 공간은 책을 통해 잠시 머물고 쉬어갈 수 있는 여유를 선사한다. 제주 감성이 깃든 책들과 소품이 어우러져 따뜻한 분위기를 자아내며, 바다와 가까운 위치 덕분에 산책길에 들르기 좋은 곳이다. 1호점과 2호점이 나란히 옆으로 자리하고 있다.','제주특별자치도 제주시 조천읍 함덕로 9',NULL,33.54072434423091,126.67343088634944,NULL,NULL,'11:00~18:00','연중무휴',90,0,'2026-04-06 17:04:27'),
('50110','KTO_TOURAPI','3112168','CULTURE','아우아우','제주 동쪽 숲 속에 위치한 마음을 치유하는 안식처, 제주도 내 유일 한옥 스타일의 반려동물 복합문화공간이다. 아우아우는 1천여 평의 공간으로 실내·외 공간 모두 보유하고 있어 날씨에 구애받지 않고 반려견과 함께할 수 있는 공간으로 반려견이 눈치 보지 않고 뛰어놀 수 있는 천연 잔디 운동장을 비롯한 제주 화산송이 운동장, 실내 반려견 전용 공간을 보유하고 있다. 반려동물을 위한 제주 특산품으로 만든 화식과 간식부터 반려인의 입맛을 사로잡을 메뉴까지 준비되어 있다. 여행의 추억을 위해 반려견과 함께하실 수 있는 사진 공간도 별도로 보유하고 있으며 시즌마다 바뀌는 포토존과 맞춤 이벤트, 다양한 반려견 의상도 체험할 수 있다.','제주특별자치도 제주시 조천읍 와산3길 13-105',NULL,33.48783967329499,126.69318766424067,NULL,'https://www.instagram.com/awooawoo.jeju','12:00~19:00','매주 수요일~목요일',90,0,'2026-04-06 09:42:39'),
('50110','KTO_TOURAPI','3063420','CULTURE','디앤디파트먼트','D&DEPARTMENT JEJU는 ‘LONG LIFE DESIGN’ 철학을 바탕으로 제주의 일상과 오래된 것의 가치를 새롭게 조명한다. 이곳은 단순히 소비를 위한 장소가 아니라 지역성과 지속 가능성을 바탕으로 오래 사용할 수 있는 물건과 지속가능성에 대한 가치를 공유하는 것을 목표로 한다. 1층은 d카페로 운영되어 제주산 재료를 활용한 음료와 디저트, 브런치를 맛볼 수 있고 제주 생산자들의 생산품도 함께 판매한다. 2층은 d스토어로, 제주의 공예품과 생활용품은 물론 D&DEPARTMENT에서 엄선한 롱라이프디자인 상품도 함께 선보인다. 이곳에서는 가구, 식기, 서적, 패션 등 일상 속에서 오래도록 사용할 수 있는 제품을 판매하며 한국과 일본, 그리고 지역다운 제주 생산자들의 상품들을 한곳에서 만날 수 있다. D&DEPARTMENT JEJU는 소비 욕구를 부추기는 상품이 아닌 계속해서 사용하고 싶은 물건, 오래 지속될 수 있도록 응원하고 싶은 상품을 찾아 판매하고 그 물건이 탄생한 지역과 생산자의 이야기를 함께 손님에게 전하고 있다.','제주특별자치도 제주시 탑동로2길 3 (삼도이동)',NULL,33.51770459484915,126.52331515099465,NULL,NULL,'10:30~18:30','매주 수요일',90,0,'2026-03-31 09:41:13'),
('50110','KTO_TOURAPI','1937744','CULTURE','소심한 책방','소심한 책방은 제주 동쪽 끝자락에 자리한 작은 마을, 종달리에 위치한 아담하고 따뜻한 분위기의 독립 서점이다. 이곳은 조용하고 아늑한 공간에서 책을 고르고 읽고 머무를 수 있다. 여행서적을 비롯해 문학·예술·철학 등 다양한 장르의 책들이 고르게 비치되어 있어 각자의 취향에 맞는 책을 발견하는 즐거움을 느낄 수 있다. 따뜻한 분위기와 편안한 좌석은 책과 함께하는 고요한 시간을 만들어준다. 제주의 감성을 느끼며 책을 즐길 수 있는 공간이다. 제주 여행 중 책과 여유, 그리고 조용한 시간을 원하는 이들에게 진심으로 추천하는 장소다.','제주특별자치도 제주시 구좌읍 종달동길 36-10',NULL,33.490276261417776,126.90265167417601,NULL,'https://www.sosimbook.com/','10:00~18:00','연중무휴',90,0,'2026-03-11 10:03:40'),
('50110','KTO_TOURAPI','2949573','CULTURE','제주문학관','제주문학관은 제주문학의 역사를 기록하고, 지역문학 활성화 및 도민 문학향유를 위하여 2021년 10월 23일에 개관하였다. 지하 1층, 지상 4층 규모로, 1층은 로비 및 기획전시실, 2층은 상설전시실과 수장고, 3층은 세미나실‧창작공간‧소모임공간‧문학살롱, 4층은 대강당 등으로 구성되어 있다. 창작 활성화를 위해 작가들에게 창작 공간을 지원하고 있으며, 세미나실 및 소모임 공간, 대강당에서는 다양한 문학 행사를 진행하고 있다.','제주특별자치도 제주시 연북로 339 (도남동)',NULL,33.4813850713,126.5178573851,NULL,'https://www.jeju.go.kr/liter/index.htm','09:00~18:00 (입장 마감 17:30)','매주 월요일 / 1월 1일 / 설·추석 당일',90,0,'2025-09-05 10:09:41'),
('50110','KTO_TOURAPI','2752772','CULTURE','성김대건신부표착기념관','이 곳은 한국 최초로 천주교를 널리 알리고자 했던 김대건신부의 의지가 담아 기념할 수 있게 만든 곳이다. 한적한 해안가 마을 용수리에 위치한 성김대건신부 표착기념관은 우리나라의 첫 신부인 성 김대건신부와 제주 천주교 교회의 역사를 엿볼 수 있는 곳이다. 성 김대건신부는 라파엘호를 타고 중국에서 우리나라에 천주교를 전파하러 오던 중 풍랑을 만나 제주도 용수리 해안에 표착하게 되었는데 그곳에서 한국 최초로 미사와 성체 성사를 한 신부이다. 기념관은 총 2층과 옥상전망대로 이루어져 있고 1층에는 영상이나 이미지를 볼 수 있는 공간, 2층에는 김대건 신부님의 업적 등을 소개하고 천주교가 들어오기까지의 험난한 과정을 알게 해주는 전시품들, 억압 당시 사용되었던 도구 등이 전시되어 있다. 건물의 가장 위층 옥상전망대에서는 멀리 차귀도가 보이고 용수리의 아담한 마을 풍경과 제주올레 12코스와 13코스를 잇는 용수포구가 한눈에 내려다 보인다. 기념관 옆에 작은 성당은 성 김대건 신부가 사제 서품을 받은 김가항 성당 모습을 재현했고, 지붕은 파도와 라파엘호를 형상화했다. 성당은 미사 시간을 제외하고는 누구나 자유롭게 관람이 가능하다.

(출처 : 제주 문화관광 홈페이지)','제주특별자치도 제주시 한경면 용수1길 108',NULL,33.3228915301,126.1677385965,NULL,'https://www.visitjeju.net/u/EnR','09:00~18:00 (미사 시간 별도)','연중무휴',90,0,'2025-03-24 14:39:49'),
('50110','KTO_TOURAPI','2609373','LEISURE','9.81 파크 제주','9.81 파크는 제주도 애월에 위치한 친환경 레이싱 테마파크로, 중력을 이용하여 속도를 낸다. 제주 바다를 바라보며 중력가속도만으로 스피드를 즐기는 다운힐 레이싱, 한라산 방향을 바라보며 자동회차로 여유롭게 즐기는 업힐 레이싱이 있다. 총 4개의 코스 10개의 트랙에서 자체 기술력으로 개발된 차량과 그래비티 레이싱에 최적화된 편경사와 커브 구간이 반영된 트랙에서 레이싱을 즐길 수 있으며, 아이와 함께 탑승할 수 있는 카트도 있어 가족과의 추억도 함께 남길 수 있다. 그래비티 레이싱을 비롯한 다양한 액티비티를 체험할 수 있는 무동력 레이싱 테마파크에서 제주 여행을 한층 더 즐길 수 있다.

◎ 한류의 매력을 만나는 여행 정보 - 예능 
창진, 다혜가 박진감 넘치는 서바이벌과 알콩달콩한 스포츠 게임을 즐기며 데이트한 장소다. 무동력 레이싱이 메인 어트랙션이지만, 두 사람이 참여한 레이저 태그 등 실내에서 즐길 수 있는 게임도 많다.','제주특별자치도 제주시 애월읍 천덕로 880-24',NULL,33.3900344063,126.3665081254,NULL,'https://www.981park.com/','09:00~18:20','연중무휴',90,0,'2026-11-16 18:01:27'),
('50110','KTO_TOURAPI','2864448','LEISURE','옹포천어울공원수영장','옹포천어울공원수영장은 제주도 서쪽 지역에 위치한 여름철 한정 무료 수영장으로, 매년 7월에서 8월 사이에 개장한다. 수영장은 제주 서부 지역의 주요 상수원 중 하나인 옹포천의 깨끗한 물을 사용하며, 용천수이기 때문에 물이 차갑고 시원한 것이 특징이다. 어린아이도 안전하게 물놀이를 즐길 수 있도록 조성되어 있다. 수영장 내에는 족욕장과 간단히 몸을 씻을 수 있는 샤워실, 탈의실 등의 편의시설도 무료로 이용할 수 있어 이용객들의 만족도가 높다. 단, 평상과 튜브 등 일부 편의 용품은 유료로 대여할 수 있으며, 반려동물과 음식물 반입은 안전과 위생상의 이유로 금지되어 있다.','제주특별자치도 제주시 한림읍 옹포리 21',NULL,33.4040334456,126.2595113441,NULL,NULL,'10:00~19:00','매주 수요일',90,0,'2026-11-16 10:19:49'),
('50110','KTO_TOURAPI','989242','LEISURE','에버리스골프리조트','기나긴 세월의 흐름이 빚어낸 우대한 자연과 인간의 무한도전이 어우러진 정통 골프장이 바로 에버리스골프리조트이다. 오름, 바다, 돌, 바람, 억새 등 제주의 자연을 담아 코스에 상징성을 부여했으며 구릉지 특성과 계절에 따른 변화무쌍한 수종들로 식재한 조경은 마치 별천지에서 라운딩하는 듯한 플레이의 묘미와 감동을 선사한다.동쪽으로는 멀리 한라산이 조망되고 서쪽으로는 광활한 목초지와 바다가 그림처럼 펼쳐진다. 남쪽으로는 다양한 형태의 오름이 제주 특유의 지형적 특성을 뽐내고 가미된 이국적인 정취는 에버리스 CC만의 비경으로 자리하게 된다.','제주특별자치도 제주시 애월읍 평화로 1693-75',NULL,33.3782245996,126.3620921357,NULL,'http://www.everis.co.kr','※ 자세한 사항은 전화문의 요망','연중무휴',90,0,'2026-11-11 08:48:03'),
('50110','KTO_TOURAPI','131222','LEISURE','제주청소년수련원','제주청소년수련원은 청소년들의 건강한 성장과 다양한 체험을 위한 시설이다. 이곳은 자연과 어우러진 넓은 공간에서 체육 활동, 문화 프로그램, 캠프 등 다양한 프로그램을 제공하며, 청소년들에게 자기 개발과 사회적 경험을 쌓을 기회를 준다. 제주청소년수련원은 안전하고 교육적인 환경에서 친구들과 함께 즐겁고 의미 있는 시간을 보낼 수 있는 장소이다.','제주특별자치도 제주시 한림읍 금능남로 128',NULL,33.377583796,126.2363232962,NULL,NULL,'상시 개방※ 자세한 안내는 전화 문의 요망',NULL,90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','131268','LEISURE','골프존카운티 오라','골프존카운티 오라는 영주십경중의 하나인 한라산 영구춘화 계곡을 따라 그림처럼 펼쳐지는 2,018,369㎡의 대자연 위에 국제수준의 36홀 코스를 갖춘 제주도의 대표적인 골프장이다. 쾌적하고 다양한 부대시설을 갖추어 365일 연중무휴로 푸른 잔디 위에서 라운딩이 가능하며, One Caddie One Bag System 운영과 차별화된 고객서비스를 제공한다.','제주특별자치도 제주시 오라남로 130-16 (오라이동)',NULL,33.4482225483,126.5131904451,NULL,'https://www.golfzoncounty.com/','※ 자세한 사항은 홈페이지 참조 및 전화 문의 요망','※ 자세한 사항은 홈페이지 참조 및 전화 문의 요망',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','131649','LEISURE','크라운컨트리클럽','제주도의 이국적인 분위기를 즐길 수 있는 곳 크라운컨트리클럽은 1998년 골프장을 개장하였다. 공항에서 25분 거리로 접근성이 뛰어나며, 제주 골프장 중에서 해발이 가장 낮은 곳에 위치하여 지리적 입지조건은 좋기 때문에 연중무휴 라운딩이 가능하다. 최근 이용객의 보다 쾌적한 골프 환경을 제공하기 위하여 과감한 투자를 시행, 31실 규모의 골프빌리지를 완공하였고 클럽하우스 및 코스는 리노베이션 공사를 통하여 새 단장하여 양질의 서비스를 제공하기 위해 노력하고 있다.

(출처 : 크라운컨트리클럽)','제주특별자치도 제주시 조천읍 북선로 125',NULL,33.5283874551,126.6952021831,NULL,'http://www.jejucrowncc.co.kr','06:00~19:00','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','1064572','LEISURE','김녕요트투어','김녕 일대는 돌고래 서식지로 돌고래와 요트가 함께 유영하는 장관을 연출한다. 알루미늄 제작으로 고가의 친환경 세일요트 BONA520과 돌고래가 함께 유영하는 모습은 제주관광의 또다른 볼거리를 제공한다. 30년 요트경력의 운영진과 최고의 럭셔리 52피트 요트 보나, 김녕 해녀의 손에 건져진 전복, 소라, 미역, 문어, 자연산 회 등의 바다 해산물로 만들어진 격조 높은 다이닝까지 또 다른 행복의 세계로 초대한다.','제주특별자치도 제주시 구좌읍 구좌해안로 229-16',NULL,33.5582318814,126.7371753694,NULL,'http://www.gnytour.com/','10:00~18:00','연중무휴※ 기상 악화 시 운항 중단으로 방문 시 전화문의 요망',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','1839801','LEISURE','[제주올레 14코스] 저지-한림 올레','제주올레 14코스는 아늑한 초록빛 숲길과 시원한 푸른 바다를 함께 만날 수 있는 길이다. 제주 농촌의 정취가 느껴지는 밭길을 지나면 곶자왈을 떠올리게 하는 울창한 숲이 이어지고, 숲을 빠져나와 물이 마른 하천을 따라 걷다 보면 어느새 바다와 마주하게 된다. 돌담길과 밭길, 숲길, 하천길을 차례로 지나 나무 산책로가 놓인 해안 길과 자잘한 돌이 깔린 바닷길, 고운 모래사장과 마을 길까지 다양한 길이 이어져 걷는 재미를 더한다. 바닷길에서는 아름다운 섬 비양도를 가까이 바라보며 제주의 다채로운 자연 풍경을 만끽할 수 있다.

(출처 : 제주올레트레일 홈페이지)','제주특별자치도 제주시 한경면 중산간서로 3687','저지예술정보화마을~한림항',33.3336912174,126.2559673514,NULL,'http://www.jejuolle.org','상시 개방','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','1839866','LEISURE','[제주올레 17코스] 광령-김만덕기념관 올레','제주올레 17코스는 무수천을 따라 이어지는 숲길과 무수천이 바다와 만나는 물길을 지나 제주시 도심으로 들어서는 길이다. 제주 시내와 가까운 곳임에도 한적한 분위기를 간직한 외도의 월대와 내도의 알작지 해안을 만날 수 있다. 청보리가 펼쳐진 길과 이호테우해변, 여유로운 마을 길을 지나면 제주의 머리라 불리는 도두봉에 오른다. 해안 도로를 따라 걷다가 만나는 용두암과 용연다리 역시 빼놓을 수 없는 볼거리다. 이어 무근성과 목관아지를 지나 제주 시내를 걸으며 제주 사람들이 과거에 살아온 모습부터 오늘날의 일상까지 자연스럽게 마주할 수 있다.

(출처 : 제주올레트레일 홈페이지)','제주특별자치도 제주시 애월읍 광성로 242-1','호끌락키즈북카페~김만덕 기념관',33.459554279,126.4334141393,NULL,'http://www.jejuolle.org','상시 개방','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2705373','LEISURE','제주레일바이크','제주레일바이크는 바퀴가 4개 달린 자전거를 타고 철로를 달리며, 경관을 즐기는 레저 관광 중 하나다. 구좌읍 주변의 오름과 우도, 성산일출봉 등을 조망할 수 있을 뿐 아니라, 목장을 함께 운영하고 있어 방목된 100여 마리의 소를 감상할 수 있다. 매 정시부터 30분 사이에 운행하며 트레일 완주는 약 35분 정도 소요된다. 직접 페달을 움직이지 않고, 전기모터를 이용하여 자동으로 앞으로 나아가는 형식이기 때문에 힘들이지 않고 탈 수 있다. 풍우막이 있어 우천 시에도 아늑하게 탑승할 수 있다. 레일바이크 코스는 상도리 공동 목장에서 출발해 산담, 밭담을 거쳐 우도와 성산일출봉을 지나 수산풍력단지, 용눈이오름, 다랑쉬오름으로 마무리된다. 

(출처 : 비짓제주)','제주특별자치도 제주시 구좌읍 용눈이오름로 641',NULL,33.4643277588,126.8366127501,NULL,'http://www.jejurailpark.com/','- 하절기(3월~10월) 09:00~17:30- 동절기(11월~2월) 09:00~17:00※ 기상악화 시 전화문의 요망','연중무휴',90,0,'2026-11-11 08:48:02'),
('50110','KTO_TOURAPI','2907715','LEISURE','금능해수욕장 야영장','금능해수욕장은 협재해수욕장과 바로 이어져 있다. 금능해수욕장 야영장은 높이 20~30m의 야자수 숲 아래 위치하고 있다. 야영장 구역 내 자유롭게 캠핑이 가능하며 아름다운 제주 바다를 보며 이용할 수 있다는 특징이 있다. 소박하고 여유로운 분위기를 품고 있어, 진정한 제주의 자연을 가까이서 즐기고 싶은 캠퍼들에게 인기가 높다.','제주특별자치도 제주시 한림읍 금능길 119-10',NULL,33.3912509636,126.2359199635,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-11-05 14:38:11'),
('50110','KTO_TOURAPI','2726675','LEISURE','관음사야영장','한라산 관음사 지구 야영장은 제주시 북쪽 아라동에 위치하고 있다. 제주시 시내에서 가까운 거리에 위치하고 있다. 제주대학교를 거쳐 도로를 지나면 관음사 초입에 다다르고, 곧이어 관음사 지구 야영장이 나온다. 해발 620m에 자리 잡고 있어 제주시 도심 인근에서 한라산 품에 안겨 캠핑을 즐길 수 있으며 백록담까지는 8.7㎞ 코스로 계곡이 깊고 산세가 웅장한 한라산의 진면목을 볼 수 있다.','제주특별자치도 제주시 산록북로 588 (오등동)',NULL,33.4219399,126.5505904,NULL,'https://visithalla.jeju.go.kr/contents','상시 개방','연중무휴※ 한라산 기상 상황에 따라 전면 통제될 수 있으니 방문 전 홈페이지 통제여부 확인 요망',90,0,'2026-11-05 14:33:47'),
('50110','KTO_TOURAPI','131546','LEISURE','어승생승마장','어승생 승마장은 제주시에 위치해 있고 승마와 목장체험을 동시에 즐길 수 있는 복합레저단지이다. 미국 서부를 테마로 한 공간이며 10만평 규모의 넓은 초지가 있어, 말을 타고 초원을 달릴 수 있다. 외승을 나가지 않더라도 구보로 400m 이상을 쉬지 않고 전력질주를 할 수 있다. 또한 말에 처음 오르는 초보자도 교관의 도움을 받아 평보부터 속보, 경속보, 구보까지 원스텝으로 경험할 수 있는 프로그램이 있다. 날씨가 좋은 날에는 에메랄드빛 제주바다를 볼 수 있고 웅장한 한라산까지 조망이 가능하다.','제주특별자치도 제주시 1100로 2659',NULL,33.4257572217,126.4904069057,NULL,'http://www.jejuhorse.com','[하절기(3월~10월)]- 09:00~19:00- 준비시간 13:00~14:00- 마지막 출발 18:30[동절기(11월~2월)]- 09:00~17:00- 준비시간 13:00~14:00- 마지막 출발 16:30','연중무휴',90,0,'2026-11-05 14:00:02'),
('50110','KTO_TOURAPI','653140','LEISURE','엘리시안 제주 컨트리클럽','제주시 애월읍에 위치한 엘리시안 제주 컨트리클럽은 한라산 경관과 한림 앞바다를 조망하는 라운딩을 즐길 수 있는 골프장이다. 자연이 주는 장엄한 아름다움을 4개 코스에 고스란히 담아 라운딩의 재미를 극대화 시켜준다. 엘리시안 컨트리클럽은 라운딩만을 즐기는 공간이 아닌, 기업의 세미나, 각종 행사와 호텔급 숙박까지 가능한 종합 골프 리조트이다.','제주특별자치도 제주시 애월읍 평화로 1738-116',NULL,33.37249,126.381153,NULL,'http://www.elysian.co.kr/main_jeju.asp','- 일출 20분 이전~일몰 20분 이후(※ 계절 및 클럽 사정에 따라 개장시간 변동 가능)','연중무휴',90,0,'2026-11-05 13:58:53'),
('50110','KTO_TOURAPI','1952520','LEISURE','차귀도요트','제주 서부 해역에 자리 잡은 요트 수상레저사업장으로 세일링요트와 파워낚시보트를 보유하고 있으며 별도의 구조선과 안전요원이 항시 대기 중으로 안전하고 여유롭게 이용 가능하다. 운항 코스는 이국적인 자연 경관을 배경으로 당산봉 해안절벽과 차귀도를 최대한 근접하여 운항할 뿐만 아니라 어족자원이 풍부한 포인트에서 손맛을 바로 느낄 수 있는 체험낚시와 열대어들과 함께 노닐 수 있는 스노클링도 함께 즐길 수 있으며, 남방 큰 돌고래와 함께 운항도 할 수 있다.','제주특별자치도 제주시 한경면 한경해안로 156',NULL,33.3239750414,126.1660310357,NULL,NULL,'10:00~19:00','연중무휴 (기상상황에 따라 변동 가능)',90,0,'2026-11-05 13:26:35'),
('50110','KTO_TOURAPI','2746268','LEISURE','삼다수숲길','삼다수숲길은 지역 주민들이 오가던 임도를 정비해 만든 비교적 최근에 조성된 탐방로이다. 원래 이 지역은 말 방목터이자 사냥터였는데 1970년대 심은 삼나무들이 거목으로 성장해 빼곡하게 숲을 메웠다. 삼다수를 생산하는 제주특별자치도 개발공사와 교래리 주민들은 숲 사이에 길을 닦아 ‘삼다수숲길’이란 이름을 붙여 2010년 개장했는데, 지난 2018년 교래 삼다수마을이 제주도의 13번째 지질공원 명소로 지정되면서 지질트레일로 관리, 운영되고 있다. 이곳은 생태적 측면에서 삼나무 싶길을 중심으로 희귀식물 군락지가 있으며, 다양한 생물들이 공존하고 있다.','제주특별자치도 제주시 조천읍 교래리','산70-24',33.420904,126.66661,NULL,'https://www.visitjeju.net/','[하절기(3월~10월)]10:00~17:00[동절기(11월~2월)]10:00~16:00※ 자세한 사항은 전화문의 요망','연중무휴',90,0,'2026-11-05 13:19:21'),
('50110','KTO_TOURAPI','131106','LEISURE','제주항 서부두방파제','연안낚시터로서 계절과 시간을 가리지 않고 조황이 좋아 늘 꾼들이 붐빈다. 테트러포스에서 던질낚시를 하면 스릴있는 손맛을 즐길 수 있다. 인근에 연안낚시터로 감성돔과 농어, 참돔이 많이 올라오는 용두암 일대를 들 수 있다. 최근 8월~10월 사이에 농어 밤낚시로 자리가 없을 때가 많다. 또한, 이곳에서는 매년 \'전국바다낚시대회\'가 개최되어 많은 관광객들이 참여한다.','제주특별자치도 제주시 서부두길 22',NULL,33.5181304078,126.5284679262,NULL,'https://www.visitjeju.net/kr','상시 개방','연중무휴',90,0,'2026-11-04 11:15:13'),
('50110','KTO_TOURAPI','131107','LEISURE','차귀도 바다낚시','차귀도는 제주의 여러 섬 중에서 빼어난 절경을 자랑하는 섬이다. 제주시 한경면 고산리 자구내포구에서 뱃길로 10분 거리에 있다. 차귀도 주변 바다는 수심이 깊고 참돔, 돌돔, 흑돔, 벤자리, 자바리 등의 다양한 어종이 잡힌다. 특히 1~3월 사이 낚시꾼이 많이 몰린다. 차귀도 주위를 한 바퀴 돌아볼 수 있는 쾌속정이 수시로 운항하며, 낚시할 도구가 없을 경우에도 낚시도구가 갖추어진 소형어선을 빌려 배낚시가 가능하다. 어족이 풍부하여 낚시 경험이 없는 초보자도 고기가 잘 잡힌다. 배에는 약 15명 내외 인원이 탑승이 가능하기 때문에 함께 온 친구나 연인, 가족들과 함께 낚시를 즐길 수 있다. 워낙 입질이 잦기 때문에 낚싯줄을 던지자마자 물고기가 잡히는 경우도 있다.','제주특별자치도 제주시 한경면 고산리 125-1',NULL,33.3010493518,126.2053535404,NULL,'https://www.visitjeju.net/','※ 업체마다 상이하므로 전화문의 요망','※ 업체마다 상이하므로 전화문의 요망',90,0,'2026-11-04 11:12:35'),
('50110','KTO_TOURAPI','131103','LEISURE','추자군도','목포에서 직선거리 93km, 제주에서는 53km 북쪽에 위치한 이 섬은 추자도라 부르기보다는 추자군도로 부름이 타당할 만큼 49개에 이르는 대소 부속 도서들을 거느리고 있는 갯바위 일급 지역이다. 이 추자도는 본섬인 상·하추자도가 다리로 연결되어 있다. 추자도는 수심이 깊고, 먼바다에 떨어져 앉은 원도에 해당하므로 바람이 조금만 불어도 심한 파도로 배낚시는 거의 불가능해지기 때문에 갯바위 낚시가 기본이 된다. 추자도의 낚시 포인트는 전 섬 모두 해당한다. 그만큼 크고 작은 각 섬마다 포인트가 형성되어 있고 낚시가 시도되지 않은 곳이 없을 만큼 거의 전 지역이 낚시터로 개발되어 있다. 따라서 낚시터 선정에 있어서는 물 때만 맞춘다면 각자 개개인의 경험과 판단에 따라 어느 곳에서 낚시해도 무난하다.','제주특별자치도 제주시 추자면 추자로',NULL,33.9500958551,126.3095173205,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-11-04 11:04:37'),
('50110','KTO_TOURAPI','824619','LEISURE','한라산 트레킹','한라산은 화산분 출로 생성된 산이어서 육지 산과는 다른 독특한 지형을 가지고 있다. 한반도의 대부분의 산들이 능선과 골짜기로 이루어진 반면 한라산은 양변의 기울기가 다소 완만한 삼각형 모양의 단면(순상화산)을 이룬다. 이 경사면을 따라 4개의 등산로가 있는데, 동쪽의 성판악 코스와 서쪽의 영실, 어리목 코스, 북쪽의 관음사 코스, 남쪽의 돈내코 코스가 있다.
한라산은 등산로가 10㎞ 이내로 거리가 짧아, 정상까지 당일 등, 하산이 가능하다. 또한 등산로가 잘 정비되어 있어 길을 잃거나 조난당할 우려는 적다. 그러나 기상변화가 심하고 바람이 세어서, 장비 없이 무작정 산행에 나섰다가 낭패를 보는 경우가 많다. 관음사 지구 야영장을 제외하고 모든 등산로에서는 취사와 야영이 금지되어 있다. 당일 등산을 원칙으로 하기 때문에 계절별로 일몰시간을 기준으로 입산통제가 이루어지므로 미리 입산 시간을 확인하는 것이 좋다.
1988년부터 한라산에서는 ‘자기 쓰레기 되가져오기 운동’을 전개하여서 등산객들도 깨끗한 한라산 만들기에 동참하고 있다.','제주특별자치도 제주시 1100로 2070-61',NULL,33.3927000285,126.4948600202,NULL,'http://www.jeju.go.kr','※ 이용시간 상이 홈페이지 및 전화문의','연중무휴※ 기상악화의 경우 입산 불가',90,0,'2026-11-04 09:59:58'),
('50110','KTO_TOURAPI','782905','LEISURE','한라산컨트리클럽','한라산 CC에는 은하수에 닿을 만큼 높은 한라산의 푸른 기상과 600년 넘게 한결같이 제주를 지켜온 산천단 곰솔의 굳은 의지가 담겨 있다. 600년 넘게 지켜온 곰솔의 푸르름과 곧은 기상이 살아있는 한라산 중턱 해발 400m 고지, 제주를 가장 잘 아는 제주 토박이의 한 사람으로서 아껴두고 싶고 또한 자랑하고 싶은 곳에 한라산 컨트리클럽을 지었다. 뒤로는 한라산의 절경이 든든하고 앞으로는 푸른 남해의 수평선이 시원하게 펼쳐진 이곳에 한겨울에도 기온과 바람 걱정이 없는 골프장을 만들기 위해 10여 년 연구와 노력을 아끼지 않았다. 하늘을 받치듯 곧게 뻗은 곰솔과 다정스레 모여 앉은 돌무지 하나까지 제주의 참모습을 그대로 살린 자연주의 골프클럽 한라산 컨트리클럽은 살아 숨 쉬는 대자연의 한가운데에 생동감 넘치는 그린을 더한 최고의 골프클럽임을 자부한다. 세계 100대 골프장으로 선정된 나인브릿지CC의 설계 디자이너 데이비드 데일과 역시 세계 100대 골프장으로 선정된 핀크스 골프클럽의 건설사 부건 종합건설(주)가 만나 최고의 기술과 노하우로 탄생하였다.','제주특별자치도 제주시 선돌목동길 56-46 (오등동)',NULL,33.4441227029,126.5447100287,NULL,'http://www.hallasancc.co.kr','홈페이지 참조','연중무휴',90,0,'2026-10-26 15:20:19'),
('50110','KTO_TOURAPI','2755469','LEISURE','에코그린캠핑장','에코그린캠핑장은 제주특별자치도 제주시 애월읍에 위치하고 있다. 제주공항 20㎞, 제주항 22㎞, 제주 시내권 15분 거리, 제주 캠핑에 최적화된 캠핑장이다. 6X7 넓은 데크사이트, 카라반과 캠핑카 수용이 가능하며 12X8 넓은 자갈 사이트가 제주에서 가장 넓은 사이트를 자랑한다. 한 텐트 규모에 따라 사이트 내 사이드 주차로 편안한 오토캠핑을 즐길 수 있다. 최대 수용 인원이 사용하여도 여유롭고, 청결한 시설로 캠퍼 분들에 만족도를 높였다. 캠핑장 전체를 감싸고 있는 돌담과 관리동 건물에 쌓아진 돌담이 제주 감성을 더 한다.','제주특별자치도 제주시 애월읍 중산간서로 5587',NULL,33.4442451755,126.3335249838,NULL,'https://www.instagram.com/ecogreencamping','- 입실 14:00- 퇴실 11:00','연중무휴',90,0,'2026-10-21 11:23:42'),
('50110','KTO_TOURAPI','3464225','LEISURE','제주 서핑도 실내서핑장','제주 서핑도는 제주도 최초 실내서핑장으로 변화무쌍한 제주도 날씨에 구애받지 않고 남녀노소 누구나 365일 온수풀로 실내에서 액티비티 서핑 체험을 즐길 수 있는 경험을 제공하며 인공 파도를 지속적으로 만들어 냄으로서 쉬지 않고 다수의 인원이 동시에 서핑을 즐길 수 있는 워터 익스트림 스포츠이다. 실내서핑장 바닥은 트램폴린 재질이여서 넘어져도 큰 타격감이 없어 누구나 안전하게 서핑 체험 즐길 수 있다.경험 많고 자격증 보유의 전문 강사들이 배치되어 안전 하고 즐겁게 체험을 즐길 수 있다.','제주특별자치도 제주시 애월읍 광령평화3길 21',NULL,33.4472921592,126.4325584457,NULL,'https://blog.naver.com/jeju_surfing-do','09:00~21:00 (준비시간 12:00~13:00)','※ 전화 문의 요망',90,0,'2026-10-20 13:30:27'),
('50110','KTO_TOURAPI','2752761','LEISURE','별헤는밤글램핑','별헤는밤글램핑은 애월읍 유수암리 해발 200m에 위치해 있다. 5개 동의 글램핑과, 2개 동의 카라반 구성으로 되어 있으며 가까운 곳에 제주공항, 곽지해변, 협재해변, 이호테우해변이 있고 해안도로를 따라 대형마트도 이용할 수 있다. 제주 서부권의 유명 여행지를 잇는 교통 요지에 위치해 있어 캠핑과 관광을 동시에 즐길 수 있다. 카라반 내부는 침대를 비롯해 TV, 에어컨, 냉장고, 테이블, 소파가 있고 주방용품도 잘 갖춰 놓았다. 화장실과 샤워실도 내부에 있으며 넓은 공간을 자랑하는 돔 형태의 글램핑에는 침대, 에어컨, TV, 화장실, 샤워실 등이 있다. 아침이면 캠핑장 내 휴게실에서 조식을 무료로 제공해 주는 것도 장점이다. 밤이면 별이 쏟아지는 광경을 육안으로 감상할 수 있고 한치잡이 배의 불빛과 밤바다를 마음껏 즐길 수 있다.','제주특별자치도 제주시 애월읍 광상로 348',NULL,33.4432720141,126.3965462756,NULL,NULL,'- 입실 15:00- 퇴실 11:00',NULL,90,0,'2026-10-07 13:46:58'),
('50110','KTO_TOURAPI','2734909','LEISURE','귤빛캠핑장','귤빛캠핑장은 제주 제주시 조천읍 대흘리에 위치하고 있으며 파쇄석 사이트가 총 35개로 구성되어 있고, 전기, 온수, 화장실, 샤워실, 취사장 등의 편의시설을 이용할 수 있다. 텐트가 없을 시에는 4인용 작은 텐트와 카라반, 내추럴하우스, 독채펜션을 예약하여 이용하면 된다. 텐트를 소지하고 있다면 사이트만 대여하여 캠핑을 즐길 수 있다. 인근에 가볼 만한 관광지는 펀테마파크, 선녀와 나무꾼 테마공원, 다희연이 있다.','제주특별자치도 제주시 조천읍 함와로 428',NULL,33.5039316233,126.6737908478,NULL,'http://www.jeju-camping.com','- 입실 14:00- 퇴실 12:00','연중무휴',90,0,'2026-10-07 10:41:54'),
('50110','KTO_TOURAPI','2498698','LEISURE','제주빅볼랜드','빅볼 체험은 큰 공(ZORB)에 사람이 들어가 언덕과 비탈길을 구르면 경사면을 내려오는 유쾌한 익스트림 스포츠이다. 빅볼랜드의 빅볼 체험 코스는 약 300m로 아시아 최초 세계 최장 거리이다. 특별한 강습이 필요하지 않아 누구나 즐길 수 있다. 빅볼랜드 코스는 최대 3-4인이 물이 들어간 공안에 들어가 약 300m를 굴러 내려가는 빅볼(BIG BALL) 코스와, 물 없이 기본 2인이 동승해 170m를 굴러내려 가는 조브(ZORB) 코스가 있다. 난이도는 빅볼보다, 조브 코스가 높은 편이며, 빅볼은 물이 들어가는 워터타입이라는 차이점이 있고, 조브 코스에는 300m 굴러내려 가는 빅조브(BIG ZORB) 코스도 있다.

(출처 : 제주 문화관광 홈페이지)','제주특별자치도 제주시 구좌읍 금백조로 951',NULL,33.4430807213,126.7757004482,NULL,NULL,'10:00~17:00※ 기상여건 영향을 많이 받으므로 전화문의 후 방문 요망','연중무휴',90,0,'2026-10-06 17:24:37'),
('50110','KTO_TOURAPI','2710165','LEISURE','[제주올레 15-B코스] 한림-고내 올레','제주올레 15-B코스는 한담 해안산책로를 포함한 곽지-애월의 해안을 두루 볼 수 있는 코스이다. 곽지 과물 해수욕장의 투명한 쪽빛 바다와 부드러운 모래가 인상적으로, 한담 해안산책로는 해안절경의 수려함과 석양에 눈을 뗄 수 없게 한다. 구불구불하게 이어진 해안선을 따라 조성된 산책로에서는 애월 환해장성도 만날 수 있어 신구의 매력이 공존하며 색다른 조화를 이룬다.

(출처 : 제주올레트레일 홈페이지)','제주특별자치도 제주시 한림읍 한림해안로 196','한림항~고내포구',33.4192876866,126.2625254768,NULL,'http://www.jejuolle.org','상시 개방','연중무휴',90,0,'2026-09-11 13:05:38'),
('50110','KTO_TOURAPI','131596','LEISURE','송당승마장','제주 여행에서 빠질 수 없는 승마를 즐길 수 있는 송당승마장은 단거리코스부터 산책코스까지 다양한 승마 코스가 있으며 1시간 자유승마도 가능하다. 남녀노소 모든 연령이 즐길 수 있으며 처음 승마를 접하는 초보자들도 교관들의 친절한 지도하에 쉽고 즐겁게 승마를 배울 수 있다.','제주특별자치도 제주시 구좌읍 번영로 2015',NULL,33.4364488497,126.7381780858,NULL,'https://www.instagram.com/jeju_songdang_horse_riding','09:00~17:00','연중무휴',90,0,'2026-09-10 17:54:12'),
('50110','KTO_TOURAPI','1755101','LEISURE','제주승마공원','애월읍 유수암리에 위치한 제주승마공원은 제주의 아름다운 중산간 초원을 말과 함께 즐길 수 있는 곳이다. 말과 함께 펼치는 기승쇼, 부부 승마 아카데미, 어린이 승마 캠프, 기업체 승마 워크숍 등 승마 레저 스포츠 프로그램을 운영하고 있으며 최장 거리의 승마 트레킹 코스를 갖춰 원하는 코스를 다양하게 선택할 수 있다. 또한 최고의 강사진이 철저한 안전 관리 등으로 편안하고 안전하게 승마를 즐길 수 있어 초보자도 쉽게 승마를 접할 수 있다. 사전에 신청하면 승마 스냅사진을 찍고 특별한 추억도 남길 수 있다.','제주특별자치도 제주시 애월읍 녹고메길 152-1',NULL,33.4051126503,126.406064378,NULL,'https://jhrpjhrp.imweb.me','- 09:30~17:00- 휴게시간 12:30~13:30- 입장 마감 16:30','매주 화요일',90,0,'2026-09-10 14:33:19'),
('50110','KTO_TOURAPI','1755350','LEISURE','탑 승마클럽','탑 승마클럽은 제주도 자연 속에서 승마체험을 즐길 수 있는 승마장이다. 세계자연유산, 지질공원, 생물권 보전지역 유네스코 3관왕 달성과 세계 7대 자연경관에 선정된 제주도의 중산간에 위치해 있다. 천혜의 자연환경을 갖고 있어 깨끗한 공기와 아름다운 오름을 감상하며 승마를 즐길 수 있다. 초보자를 위한 승마 프로그램도 운영하고 있어 숙련자 및 초보자 등 누구나 승마를 체험할 수 있다. 또한 주변에 절물자연휴양림, 노루생태관찰원, 4·3평화공원 및 민오름, 절물 오름 등 관광명소가 많아 승마와 함께 제주의 역사 및 오름 트레킹 등을 즐길 수 있다.','제주특별자치도 제주시 명림로 278 (봉개동)',NULL,33.4627301141,126.6118198072,NULL,'https://www.instagram.com/jeju_top_horse/','※ 전화 문의 후 방문 요망','※ 전화 문의 후 방문 요망',90,0,'2026-09-10 13:31:54'),
('50110','KTO_TOURAPI','2752733','LEISURE','제라진어드벤쳐','제주의 말들과 노루, 꿩이 자유롭게 뛰어노는 429,752㎡(13만 평) 규모의 초원과 숲에서 자연 그대로의 제주를 느낄 수 있는 국내 유일의 오프로드 투어를 제공한다. 스릴 넘치는 오프로드 투어부터 RC카를 통한 미니멀한 제주 투어까지, 오직 제주에서만 가능한 순간들을 경험할 수 있다. 제주 오프로드 코스 설계의 특별한 점은, 세계 자연유산에 인접한 원시 자연 그대로를 재현했다는 것이다. 가급적 ‘말이 다녔던 길을 따라’ 체험코스를 설계했다. 완만한 능선과 골짜기가 중첩된 지형은 액티비티를 만끽할 최적의 조건이며, 6.5km에 달하는 다이내믹한 코스는 특별한 체험의 시간을 선사한다. 또한 체험 코스 중간에서 포토타임을 가질 수 있어 잊지 못할 추억을 남길 수 있다. ‘바퀴 달린 집’ 촬영 이후 더 유명해졌다.','제주특별자치도 제주시 조천읍 선교로 33',NULL,33.4871759221,126.7159706472,NULL,'https://jejuoffroad.kr/About','10:00~18:00 ※ 상황에 따라 투어 시간 변동될 수 있음','연중무휴',90,0,'2026-09-10 09:55:40'),
('50110','KTO_TOURAPI','1839784','LEISURE','[제주올레 13코스] 용수-저지 올레','제주올레 13코스는 해안 길 중심으로 이어지던 올레길이 중산간으로 들어서는 시작점과 같은 코스이다. 용수포구에서 잠시 바다를 마주한 뒤 길은 내륙으로 방향을 틀어 중산간을 향한다. 용수저수지와 숲길을 지나 작은 마을 낙천리를 만나고, 다시 숲과 오름으로 이어지는 길을 걷는다. 50여 명의 특전사 대원들의 도움으로 복원된 숲길과 밭길, 울창한 숲을 품은 저지 오름이 이 코스의 매력적인 풍경을 더한다.

(출처 : 제주올레트레일 홈페이지)','제주특별자치도 제주시 한경면 용수리 4241-7','용수포구~저지예술정보화마을',33.3238222818,126.1660504817,NULL,NULL,'상시 개방','연중무휴',90,0,'2026-09-09 15:30:16'),
('50110','KTO_TOURAPI','1839864','LEISURE','[제주올레 16코스] 고내-광령 올레','제주올레 16코스는 애월 바다의 소박한 풍경에서 시작해 중산간으로 이어지는 길이다. 고내에서 구엄까지 이어지는 쪽빛 바다를 비롯해 햇빛을 받아 하얗게 빛나는 소금빌레, 낚시꾼들이 여유롭게 시간을 보내는 잔잔한 저수지를 만날 수 있다. 키 큰 나무들이 시원한 그늘을 드리운 호젓한 숲길과 삼별초가 항전을 벌였던 옛 토성도 지나간다. 평화롭고 소박한 마을과 돌담을 두른 밭길까지, 제주의 바다와 자연, 역사와 일상을 한 길에서 두루 만날 수 있는 코스이다.

(출처 : 제주올레트레일 홈페이지)','제주특별자치도 제주시 애월읍 고내리 1111-2','고내포구~호끌락키즈북카페',33.4669000009,126.3378979411,NULL,'http://www.jejuolle.org','상시 개방','연중무휴',90,0,'2026-09-09 15:24:38'),
('50110','KTO_TOURAPI','1839833','LEISURE','[제주올레 15-A코스] 한림-고내 올레','제주올레 15-A코스는 난대림이 우거진 숲과 한적한 중산간 풍경을 따라 걷는 올레길이다. 중산간에 펼쳐진 드넓은 밭길을 비롯해 숲길과 흙길이 이어져 제주 특유의 자연을 느낄 수 있다. 특히 평범한 마을공원처럼 보이는 금산공원은 안으로 들어서면 깊고 울창한 숲길이 펼쳐져 색다른 분위기를 자아내는 이 코스의 숨은 명소다. 이후 곽지팔경 중 하나인 과오름의 세 봉우리와 도새기 숲길, 고내봉을 차례로 지나 고내포구에 닿는다.

(출처 : 제주올레트레일 홈페이지)','제주특별자치도 제주시 한림읍 한림해안로 192','한림항~고내포구',33.4190719416,126.2625564235,NULL,'http://www.jejuolle.org','상시 개방','연중무휴',90,0,'2026-09-09 15:08:15'),
('50110','KTO_TOURAPI','1840882','LEISURE','[제주올레 20코스] 김녕-하도 올레','제주 북동쪽 해안에 자리한 김녕서포구에서 시작하는 제주올레 20코스는 김녕을 지나 월정과 세화로 이어지는 바닷길을 따라 걷는 코스이다. 길을 걷는 동안 잔잔하게 일렁이는 쪽빛 바다가 곁을 따라 펼쳐지며, 물빛이 아름답고 수심이 비교적 고른 해변에서는 물놀이도 즐길 수 있다. 운이 좋다면 바다로 나서는 해녀들의 물질하는 모습을 마주하고, 물질을 마친 해녀들이 내뿜는 숨비소리도 들을 수 있다. 아름다운 해안 풍경과 함께 제주 고유의 해녀 문화를 가까이에서 느낄 수 있는 길이다.

(출처 : 제주올레트레일 홈페이지)


