INSERT INTO place (region_id, source_provider, source_place_id, place_type, name,
  description, address, address_detail, latitude, longitude, phone, homepage_url,
  opening_hours, closed_days, recommended_minutes, is_market, source_modified_at,
  last_synced_at, is_active, created_at, updated_at, verification_status)
SELECT r.region_id, s.source_provider, s.source_place_id, s.place_type, s.name,
  s.description, s.address, s.address_detail, s.latitude, s.longitude, s.phone, s.homepage_url,
  s.opening_hours, s.closed_days, s.recommended_minutes, s.is_market, s.source_modified_at,
  NOW(), TRUE, NOW(), NOW(), 'UNVERIFIED'
FROM place_seed_stage s JOIN region r ON r.region_code = s.region_code
ON DUPLICATE KEY UPDATE
  region_id=VALUES(region_id), name=VALUES(name), place_type=VALUES(place_type),
  description=COALESCE(VALUES(description), place.description),
  address=COALESCE(VALUES(address), place.address),
  address_detail=COALESCE(VALUES(address_detail), place.address_detail),
  latitude=COALESCE(VALUES(latitude), place.latitude),
  longitude=COALESCE(VALUES(longitude), place.longitude),
  phone=COALESCE(VALUES(phone), place.phone),
  homepage_url=COALESCE(VALUES(homepage_url), place.homepage_url),
  opening_hours=COALESCE(VALUES(opening_hours), place.opening_hours),
  closed_days=COALESCE(VALUES(closed_days), place.closed_days),
  recommended_minutes=COALESCE(VALUES(recommended_minutes), place.recommended_minutes),
  is_market=VALUES(is_market),
  source_modified_at=COALESCE(VALUES(source_modified_at), place.source_modified_at),
  is_active=TRUE, last_synced_at=NOW(), updated_at=NOW();
